CREATE OR REPLACE FUNCTION public.close_run_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  IF NEW.status IN('approved','closed','published') THEN
   RAISE EXCEPTION 'Create the close run and submit its current evidence through Flows before release.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.status='approved' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF OLD.status<>'review' OR NEW.approved_by IS NULL OR NEW.approved_at IS NULL
    OR NEW.approved_by IS DISTINCT FROM NEW.updated_by
    OR NOT public.flow_subject_decision_authorized(NEW.org_id,'close_run',NEW.id,NEW.approved_by,
      public.close_run_approval_fingerprint(OLD.org_id,OLD.id),'approved') THEN
   RAISE EXCEPTION 'Submit the close run and complete every configured Flow gate before approval.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status IN('approved','closed','published') AND (ROW(NEW.id,NEW.org_id,NEW.period_id,NEW.book_id,NEW.blueprint_id,NEW.scope,NEW.started_by)
    IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.period_id,OLD.book_id,OLD.blueprint_id,OLD.scope,OLD.started_by)
    OR NEW.status='approved' AND NEW.data_fingerprint IS DISTINCT FROM OLD.data_fingerprint) THEN
  RAISE EXCEPTION 'Revalidate the close run and submit its changed terms through Flows.' USING ERRCODE='23514';
 END IF;
 IF OLD.status='approved' AND NEW.status='approved' AND ROW(NEW.approved_by,NEW.approved_at)
    IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at) THEN
  RAISE EXCEPTION 'The recorded close decision retains its actual actor and timestamp.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='closed' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF OLD.status<>'approved' OR NEW.closed_by IS NULL OR NEW.closed_at IS NULL
    OR NEW.closed_by IS DISTINCT FROM NEW.updated_by
    OR NOT public.flow_subject_decision_authorized(OLD.org_id,'close_run',OLD.id,OLD.approved_by,
      public.close_run_approval_fingerprint(OLD.org_id,OLD.id),'approved') THEN
   RAISE EXCEPTION 'Lock only a close run with its retained current Flow approval.' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(NEW.scope->'subsidiaryIds')='array'
      AND jsonb_array_length(NEW.scope->'subsidiaryIds')>0 THEN NEW.scope->'subsidiaryIds' ELSE '[null]'::jsonb END) entity(id)
    CROSS JOIN unnest(ARRAY['ar','ap','banking','assets','tax','gl']) module(name)
    WHERE NOT EXISTS(SELECT 1 FROM public.period_locks l WHERE l.org_id=NEW.org_id AND l.period_id=NEW.period_id
      AND l.book_id=NEW.book_id AND l.subsidiary_id IS NOT DISTINCT FROM entity.id::uuid AND l.module=module.name
      AND l.state='closed' AND (l.reopen_expires_at IS NULL OR l.reopen_expires_at<=now()))) THEN
   RAISE EXCEPTION 'Close the run through its native command so every scoped subledger and GL lock seals atomically.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.status='published' AND OLD.status IS DISTINCT FROM NEW.status AND
    (OLD.status<>'closed' OR NEW.published_by IS NULL OR NEW.published_at IS NULL OR NEW.published_by IS DISTINCT FROM NEW.updated_by) THEN
  RAISE EXCEPTION 'Publish only the retained closed run through its native publication command.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.close_task_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE fingerprint text; receipt public.flow_submissions;
BEGIN
 IF TG_OP='INSERT' THEN
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  IF NEW.completion_mode='manual' AND NEW.status IN('submitted','complete','waived') THEN
   RAISE EXCEPTION 'Create the close task, then submit its current evidence through Flows.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.completion_mode='manual' AND OLD.status IN('complete','waived') AND NEW.status=OLD.status
  AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by']) THEN
  RAISE EXCEPTION 'Completed close task evidence is immutable; revalidate the close run for changed work.' USING ERRCODE='23514';
 END IF;
 IF OLD.task_type='approval' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN('complete','changes_requested') THEN
  SELECT * INTO receipt FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='close_run'
    AND s.subject_id=NEW.run_id ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
  IF NOT public.flow_subject_decision_authorized(NEW.org_id,'close_run',NEW.run_id,NEW.updated_by,
      public.close_run_approval_fingerprint(NEW.org_id,NEW.run_id),CASE WHEN NEW.status='complete' THEN 'approved' ELSE 'rejected' END)
    OR NOT EXISTS(SELECT 1 FROM public.close_runs r WHERE r.org_id=NEW.org_id AND r.id=NEW.run_id
      AND r.data_fingerprint=NEW.data_fingerprint AND r.status=CASE WHEN NEW.status='complete' THEN 'approved' ELSE 'in_progress' END)
    OR NEW.status='complete' AND (NEW.completed_at IS NULL OR NEW.completed_by IS DISTINCT FROM NEW.updated_by)
    OR receipt.policy->>'kind'='ungated' AND (NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL)
    OR receipt.policy->>'kind'='gated' AND (NEW.reviewed_by IS DISTINCT FROM NEW.updated_by OR NEW.reviewed_at IS NULL) THEN
   RAISE EXCEPTION 'Approval tasks retain the parent close run decision, current evidence and actual Flow reviewer.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.completion_mode='manual' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN('complete','waived','changes_requested') THEN
  fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD),public.close_task_approval_dependencies(OLD.org_id,OLD.id));
  IF NEW.status='changes_requested' THEN
   IF NOT public.flow_subject_decision_authorized(NEW.org_id,'close_task',NEW.id,NEW.updated_by,fingerprint,'rejected') THEN
    RAISE EXCEPTION 'Return the close task through its assigned current Flow gate.' USING ERRCODE='23514';
   END IF;
  ELSE
   IF NEW.completed_at IS NULL OR NOT public.flow_command_authorized(NEW.org_id,'close_task',NEW.id,NEW.updated_by,fingerprint,
     jsonb_build_object('action',CASE WHEN NEW.status='waived' THEN 'waive' ELSE 'complete' END)) THEN
    RAISE EXCEPTION 'Submit the close task and complete every configured Flow gate before release.' USING ERRCODE='23514';
   END IF;
   SELECT * INTO receipt FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='close_task' AND s.subject_id=NEW.id ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
   IF NEW.completed_by IS DISTINCT FROM receipt.actor_id
     OR receipt.policy->>'kind'='ungated' AND (NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL)
     OR receipt.policy->>'kind'='gated' AND (NEW.reviewed_by IS DISTINCT FROM NEW.updated_by OR NEW.reviewed_at IS NULL) THEN
    RAISE EXCEPTION 'Retain the close task preparer and actual native Flow decision identity.' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.compensation_cycle_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
