CREATE OR REPLACE FUNCTION public.compliance_certificate_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.verified_at IS NOT NULL OR NEW.verified_by IS NOT NULL OR NEW.verified_revision IS NOT NULL THEN
   RAISE EXCEPTION 'Record the certificate before submitting verification through Flows.';
  END IF;
  RETURN NEW;
 END IF;
 IF ROW(NEW.verified_at,NEW.verified_by,NEW.verified_revision) IS DISTINCT FROM ROW(OLD.verified_at,OLD.verified_by,OLD.verified_revision)
  AND NEW.verified_at IS NOT NULL THEN
  IF NEW.status<>'active' OR NEW.verified_revision IS DISTINCT FROM OLD.revision OR NEW.revision<>OLD.revision+1
    OR (to_jsonb(NEW)-ARRAY['status','verified_at','verified_by','verified_revision','revision','rejected_reason','updated_at','updated_by'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','verified_at','verified_by','verified_revision','revision','rejected_reason','updated_at','updated_by'])
    OR NOT public.flow_command_authorized(NEW.org_id,'compliance_certificate',NEW.id,NEW.verified_by,
      public.flow_command_record_fingerprint(to_jsonb(OLD)),jsonb_build_object('revision',OLD.revision)) THEN
   RAISE EXCEPTION 'Verify this exact certificate revision through its native Flow submission.';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.compliance_record_renewal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  successor public.compliance_records%ROWTYPE;
BEGIN
  IF OLD.status = 'superseded' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'a superseded compliance record cannot be reinstated'
      USING ERRCODE = '23514';
  END IF;

  -- A renewal is the only legal operation that fills superseded_by_id.  The
  -- UPDATE row lock serializes competing transactions on the predecessor; the
  -- second waiter then sees the committed superseded state and is rejected.
  IF NEW.superseded_by_id IS NOT DISTINCT FROM OLD.superseded_by_id THEN
    IF NEW.status = 'superseded' AND NEW.superseded_by_id IS NULL THEN
      RAISE EXCEPTION
        'a superseded compliance record must identify its pending successor'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.superseded_by_id IS NULL THEN
    RAISE EXCEPTION
      'a compliance record supersession pointer cannot be cleared'
      USING ERRCODE = '23514';
  END IF;

  IF OLD.status = 'superseded' OR OLD.superseded_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'compliance record % has already been superseded; renew the current record instead',
      OLD.id
      USING ERRCODE = '23505';
  END IF;

  IF NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'a compliance renewal must mark its predecessor superseded'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.superseded_by_id = NEW.id THEN
    RAISE EXCEPTION
      'a compliance record cannot supersede itself'
      USING ERRCODE = '23514';
  END IF;

  SELECT *
    INTO successor
    FROM public.compliance_records
   WHERE id = NEW.superseded_by_id
   FOR KEY SHARE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'compliance renewal successor % does not exist',
      NEW.superseded_by_id
      USING ERRCODE = '23503';
  END IF;

  IF successor.org_id IS DISTINCT FROM NEW.org_id
     OR successor.party_id IS DISTINCT FROM NEW.party_id
     OR successor.requirement_id IS DISTINCT FROM NEW.requirement_id
     OR successor.project_id IS DISTINCT FROM NEW.project_id
     OR successor.status <> 'pending_review'
     OR successor.superseded_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'compliance renewal successor % must be a pending record for the same organization, vendor, requirement, and project',
      NEW.superseded_by_id
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.compliance_waiver_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.approved_at IS NOT NULL OR NEW.approved_by IS NOT NULL THEN RAISE EXCEPTION 'File the exception before submitting it through Flows.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.approved_at IS NOT NULL AND (to_jsonb(NEW)-ARRAY['revoked_at','revoked_by','revoke_reason','updated_at','updated_by']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['revoked_at','revoked_by','revoke_reason','updated_at','updated_by']) THEN
  RAISE EXCEPTION 'An effective compliance exception is immutable; revoke it with a reason and submit a new exception.';
 END IF;
 IF OLD.approved_at IS NULL AND NEW.approved_at IS NOT NULL AND NOT public.flow_command_authorized(NEW.org_id,'compliance_waiver',NEW.id,NEW.approved_by,public.flow_command_record_fingerprint(to_jsonb(OLD))) THEN
  RAISE EXCEPTION 'Release this exception through its complete native Flow submission.';
 END IF;
 RETURN NEW;
END $function$

