CREATE OR REPLACE FUNCTION public.document_open_balance_amount(p_org uuid, p_entry uuid, p_currency text, p_status text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_count bigint;
  v_valid boolean;
  v_balance numeric;
BEGIN
  IF p_status = 'voided' OR p_entry IS NULL THEN RETURN NULL; END IF;
  SELECT count(jl.id),
         bool_and(jl.currency = p_currency),
         sum(abs(jl.txn_amount)) - coalesce(sum(ap.applied), 0)
    INTO v_count, v_valid, v_balance
    FROM public.journal_lines jl
    LEFT JOIN LATERAL (
      SELECT sum(CASE WHEN a.from_line_id = jl.id
                      THEN a.source_transaction_amount
                      ELSE a.target_transaction_amount END) AS applied
        FROM public.applications a
       WHERE a.org_id = p_org AND a.unapplied_at IS NULL
         AND (a.from_line_id = jl.id OR a.to_line_id = jl.id)
    ) ap ON true
   WHERE jl.entry_id = p_entry AND jl.org_id = p_org AND jl.is_open_item;
  IF v_count = 0 THEN RETURN NULL; END IF;
  IF v_valid IS NOT TRUE THEN
    RAISE EXCEPTION 'document open-item currency mismatch: org %, posted entry %, expected currency %',
      p_org, p_entry, p_currency
      USING ERRCODE = '23514';
  END IF;
  RETURN v_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.document_payment_terms_snapshot_for_clone(evidence jsonb, source_tenant uuid, source_party uuid, seed uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE result jsonb;
BEGIN
 IF evidence IS NULL THEN RETURN NULL; END IF;
 IF public.document_payment_terms_snapshot_valid(evidence) IS NOT TRUE OR seed IS NULL
  OR evidence->'partyId' IS DISTINCT FROM coalesce(to_jsonb(source_party), 'null'::jsonb) THEN
  RAISE EXCEPTION 'Cannot clone payment terms whose source document identity is missing or invalid.' USING ERRCODE='23514';
 END IF;
 IF source_party IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.parties WHERE org_id = source_tenant AND id = source_party
 ) THEN
  RAISE EXCEPTION 'Cannot clone payment terms whose party has no source-organization identity.' USING ERRCODE='23514';
 END IF;
 IF evidence->'terms' <> 'null'::jsonb AND NOT EXISTS (
  SELECT 1 FROM public.payment_terms WHERE org_id = source_tenant AND id = (evidence #>> '{terms,id}')::uuid
 ) THEN
  RAISE EXCEPTION 'Cannot clone retained payment terms whose policy identity is absent from the source organization.' USING ERRCODE='23514';
 END IF;
 result := jsonb_set(evidence, '{partyId}', coalesce(to_jsonb(public.ob_rebase(source_party, seed)::text), 'null'::jsonb), false);
 IF evidence->'terms' <> 'null'::jsonb THEN
  result := jsonb_set(result, '{terms,id}', to_jsonb(public.ob_rebase((evidence #>> '{terms,id}')::uuid, seed)::text), false);
 END IF;
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.document_payment_terms_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 -- Native financial-history cloning is an explicit paired transaction-local
 -- operation; its source evidence remains subject to the shape constraint.
 IF TG_OP = 'INSERT' AND coalesce(current_setting('openbooks.migration', true),'off') = 'on'
  AND coalesce(current_setting('openbooks.amend', true),'off') = 'on' THEN RETURN NEW; END IF;
 IF TG_OP = 'INSERT' THEN
  IF NEW.payment_terms_snapshot IS NOT NULL THEN
   RAISE EXCEPTION 'Payment terms are captured only by posting an approved document.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.payment_terms_snapshot IS NOT DISTINCT FROM OLD.payment_terms_snapshot THEN RETURN NEW; END IF;
 IF OLD.payment_terms_snapshot IS NOT NULL OR OLD.status <> 'approved' OR NEW.status <> 'posted' THEN
  RAISE EXCEPTION 'Posted payment terms are immutable; preserve the source and use a governed document correction.' USING ERRCODE='23514';
 END IF;
 IF NEW.payment_terms_snapshot->>'documentKind' IS DISTINCT FROM NEW.kind
  OR NEW.payment_terms_snapshot->'partyId' IS DISTINCT FROM coalesce(to_jsonb(NEW.party_id), 'null'::jsonb)
  OR NEW.payment_terms_snapshot->>'documentDate' IS DISTINCT FROM NEW.document_date::text THEN
  RAISE EXCEPTION 'Retained payment terms must belong to the posting document and vendor.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.document_payment_terms_snapshot_valid(evidence jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
 SET "DateStyle" TO 'ISO, YMD'
AS $function$
DECLARE terms jsonb; percentage numeric; has_discount boolean;
BEGIN
 IF evidence IS NULL THEN RETURN true; END IF;
 IF jsonb_typeof(evidence) <> 'object' OR (SELECT count(*) FROM jsonb_object_keys(evidence)) <> 7
  OR NOT evidence ?& ARRAY['version','mode','source','documentKind','partyId','documentDate','terms']
  OR evidence->'version' <> '1'::jsonb
  OR jsonb_typeof(evidence->'documentDate') <> 'string'
  OR (evidence->>'documentDate') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  OR (evidence->>'documentDate')::date::text <> evidence->>'documentDate'
  OR (evidence->>'documentDate')::date NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31'
 THEN RETURN false; END IF;
 IF evidence->>'mode' = 'not_applicable' THEN
  RETURN evidence->>'documentKind' = 'expense_report' AND evidence->>'source' = 'not_applicable'
   AND evidence->'terms' = 'null'::jsonb
   AND (evidence->'partyId' = 'null'::jsonb OR
    (jsonb_typeof(evidence->'partyId') = 'string' AND
     (evidence->>'partyId') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'));
 END IF;
 IF evidence->>'documentKind' <> 'vendor_bill' OR jsonb_typeof(evidence->'partyId') <> 'string'
  OR (evidence->>'partyId') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
 THEN RETURN false; END IF;
 IF evidence->>'source' = 'none' THEN
  RETURN evidence->>'mode' = 'no_discount' AND evidence->'terms' = 'null'::jsonb;
 END IF;
 terms := evidence->'terms';
 IF evidence->>'source' NOT IN ('vendor','company') OR jsonb_typeof(terms) <> 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(terms)) <> 6
  OR NOT terms ?& ARRAY['id','name','netDays','discountDays','discountPercent','revisionHash']
  OR jsonb_typeof(terms->'id') <> 'string'
  OR (terms->>'id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  OR jsonb_typeof(terms->'name') <> 'string' OR btrim(terms->>'name') = ''
  OR jsonb_typeof(terms->'revisionHash') <> 'string' OR (terms->>'revisionHash') !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(terms->'netDays') <> 'number' OR (terms->>'netDays') !~ '^[0-9]+$'
  OR (terms->>'netDays')::numeric > 3652058
 THEN RETURN false; END IF;
 IF (evidence->>'documentDate')::date + (terms->>'netDays')::integer > DATE '9999-12-31' THEN RETURN false; END IF;
 IF terms->'discountDays' <> 'null'::jsonb AND
  (jsonb_typeof(terms->'discountDays') <> 'number' OR (terms->>'discountDays') !~ '^[0-9]+$'
   OR (terms->>'discountDays')::numeric > 3652058)
 THEN RETURN false; END IF;
 IF terms->'discountPercent' = 'null'::jsonb THEN percentage := 0;
 ELSE
  IF jsonb_typeof(terms->'discountPercent') <> 'string'
   OR (terms->>'discountPercent') !~ '^[0-9]{1,15}(\.[0-9]{1,4})?$' THEN RETURN false; END IF;
  percentage := (terms->>'discountPercent')::numeric;
  IF percentage < 0 OR percentage >= 100 THEN RETURN false; END IF;
 END IF;
 has_discount := percentage > 0;
 IF has_discount AND terms->'discountDays' = 'null'::jsonb THEN RETURN false; END IF;
 IF has_discount AND (evidence->>'documentDate')::date + (terms->>'discountDays')::integer > DATE '9999-12-31' THEN RETURN false; END IF;
 RETURN evidence->>'mode' = CASE WHEN has_discount THEN 'discount' ELSE 'no_discount' END;
EXCEPTION WHEN OTHERS THEN RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.document_supply_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE document_state text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  SELECT d.status INTO document_state FROM public.documents d
    WHERE d.org_id = COALESCE(NEW.org_id, OLD.org_id)
      AND d.id = COALESCE(NEW.document_id, OLD.document_id);
  IF document_state IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'supply evidence is immutable once the document leaves draft; return the document to draft and recollect its evidence';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.document_tender_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_old_document_id uuid;
  v_new_document_id uuid;
  v_old_org_id uuid;
  v_new_org_id uuid;
  v_old_found boolean := false;
  v_new_found boolean := false;
  v_old_status text;
  v_new_status text;
  v_old_kind text;
  v_new_kind text;
  v_parent record;
  v_sandbox_wipe boolean;
  v_trusted_replay boolean;
  v_mint_fill boolean;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  v_old_document_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.document_id ELSE NULL END;
  v_new_document_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.document_id ELSE NULL END;
  v_old_org_id := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.org_id ELSE NULL END;
  v_new_org_id := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.org_id ELSE NULL END;

  v_sandbox_wipe :=
    TG_OP = 'DELETE'
    AND (v_old_org_id IS NULL OR public.openbooks_sandbox_wipe_allowed(v_old_org_id));
  IF v_sandbox_wipe THEN
    RETURN OLD;
  END IF;

  FOR v_parent IN
    SELECT d.id, d.org_id, d.status, d.kind
      FROM public.documents d
     WHERE d.id IN (v_old_document_id, v_new_document_id)
     ORDER BY d.id
     FOR UPDATE
  LOOP
    IF v_parent.id = v_old_document_id THEN
      v_old_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_old_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_old_document_id, v_old_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_old_status := v_parent.status;
      v_old_kind := v_parent.kind;
    END IF;
    IF v_parent.id = v_new_document_id THEN
      v_new_found := true;
      IF v_parent.org_id IS DISTINCT FROM v_new_org_id THEN
        RAISE EXCEPTION
          'document % does not exist in organization %',
          v_new_document_id, v_new_org_id
          USING ERRCODE = 'foreign_key_violation';
      END IF;
      v_new_status := v_parent.status;
      v_new_kind := v_parent.kind;
    END IF;
  END LOOP;

  IF v_old_document_id IS NOT NULL AND NOT v_old_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_old_document_id, v_old_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_new_document_id IS NOT NULL AND NOT v_new_found THEN
    RAISE EXCEPTION
      'document % does not exist in organization %',
      v_new_document_id, v_new_org_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  v_trusted_replay :=
    coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on';
  IF v_trusted_replay THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Mint-fill: the refund settle effect mints the store-credit account after
  -- posting and records it on the tender. Only this single-column fill passes
  -- on a non-draft parent; every other post-commit write is refused.
  v_mint_fill :=
    TG_OP = 'UPDATE'
    AND v_old_status IS DISTINCT FROM 'draft'
    AND OLD.kind = 'stored_value'
    AND OLD.stored_value_account_id IS NULL
    AND NEW.stored_value_account_id IS NOT NULL
    AND NEW.org_id IS NOT DISTINCT FROM OLD.org_id
    AND NEW.document_id IS NOT DISTINCT FROM OLD.document_id
    AND NEW.position IS NOT DISTINCT FROM OLD.position
    AND NEW.kind IS NOT DISTINCT FROM OLD.kind
    AND NEW.method_label IS NOT DISTINCT FROM OLD.method_label
    AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id
    AND NEW.amount_minor IS NOT DISTINCT FROM OLD.amount_minor
    AND NEW.currency IS NOT DISTINCT FROM OLD.currency
    AND NEW.reference IS NOT DISTINCT FROM OLD.reference
    AND NEW.external_ref IS NOT DISTINCT FROM OLD.external_ref;
  IF v_mint_fill THEN
    RETURN NEW;
  END IF;

  IF v_old_document_id IS NOT NULL AND v_old_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its tenders are immutable outside draft status',
      v_old_document_id, v_old_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF v_new_document_id IS NOT NULL AND v_new_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION
      'document % is % — its tenders are immutable outside draft status',
      v_new_document_id, v_new_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;

  -- A sale redeems an existing balance at posting, so the account must be
  -- resolved while the draft is still editable. A refund may mint the
  -- credit at settle instead.
  IF v_new_document_id IS NOT NULL AND TG_OP = 'INSERT'
     AND NEW.kind = 'stored_value' AND NEW.stored_value_account_id IS NULL
     AND v_new_kind = 'cash_sale' THEN
    RAISE EXCEPTION
      'cash sale tender % names no stored-value account — resolve the gift card or store credit being redeemed before posting',
      NEW.position
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.documents_total_line_tieout()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM public.assert_document_totals_match_lines(new.id, new.org_id);
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.drop_ship_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP<>'INSERT' THEN
    IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
      IF TG_OP='DELETE' THEN RETURN OLD; END IF;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'agency allocations are immutable; reverse and replace the document through its controlled workflow';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.financial_changes change JOIN public.document_lines line ON line.org_id=change.org_id AND line.id=NEW.document_line_id
    JOIN public.documents document ON document.org_id=line.org_id AND document.id=line.document_id
    WHERE change.id=NEW.change_id AND change.org_id=NEW.org_id AND change.domain='sales' AND change.subject_id=NEW.sales_order_line_id AND change.status='applied'
      AND change.payload->>'controlsBeforeTransfer'='false' AND document.id=NEW.document_id AND document.kind=NEW.kind AND document.subsidiary_id=change.subsidiary_id)
    THEN RAISE EXCEPTION 'agency allocation must bind to its approved control judgment and native document'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.dunning_log_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if public.app_bypass_rls_active() then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if TG_OP = 'DELETE' then
    raise exception 'dunning_log is append-only: DELETE is refused; a rung''s lifecycle moves forward through staged/sent/failed/suppressed transitions only';
  end if;
  if TG_OP = 'INSERT' then
    return new;
  end if;
  if old.status = 'sent' or old.status = 'skipped' then
    raise exception 'dunning_log % rows are terminal delivery evidence and cannot be updated; failed and suppressed rows re-arm to staged, sent rows never move', old.status;
  end if;
  if old.status = 'staged' and new.status in ('sent', 'failed', 'suppressed') then
    return new;
  end if;
  if (old.status = 'failed' or old.status = 'suppressed') and new.status = 'staged' then
    return new;
  end if;
  raise exception 'dunning_log transition % to % is refused: the send attempt may move staged to sent/failed/suppressed, and the runner may re-arm failed/suppressed to staged', old.status, new.status;
end;
$function$

