CREATE OR REPLACE FUNCTION public.entitlement_ledger_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'UPDATE' then
    raise exception
      'entitlement_ledger is append-only; correct a balance with an adjustment movement';
  end if;
  if openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if old.pay_run_document_id is not null and exists (
    select 1 from pay_runs r
     where r.document_id = old.pay_run_document_id
       and r.run_status <> 'committed'
  ) then
    return old;
  end if;
  if old.kind = 'opening' and old.pay_run_document_id is null then
    if exists (
      select 1 from pay_stubs s
        join pay_runs r on r.document_id = s.pay_run_document_id and r.org_id = s.org_id
       where s.org_id = old.org_id
         and s.employee_party_id = old.employee_party_id
         and r.run_status = 'committed'
         and s.pay_date >= old.movement_date
    ) then
      raise exception
        'entitlement_ledger opening carry-in has already been consumed by a committed pay run; void that run before changing it';
    end if;
    return old;
  end if;
  raise exception
    'entitlement_ledger movements cannot be deleted once their pay run is committed';
end $function$

CREATE OR REPLACE FUNCTION public.equity_action_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Equity action requests are retained history.' USING ERRCODE='23514';
 END IF;
 IF OLD.status <> 'pending_approval' OR NEW.status = 'pending_approval'
    OR (to_jsonb(NEW) - ARRAY['status','released_without_approval','decided_by','decided_at','decision_comment','result','applied_at'])
       <> (to_jsonb(OLD) - ARRAY['status','released_without_approval','decided_by','decided_at','decision_comment','result','applied_at']) THEN
  RAISE EXCEPTION 'An equity action request is decided once, from pending approval to applied or rejected.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.equity_copied_security(p_org uuid, p_identity uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE seeds uuid[] := '{}'; current_org uuid := p_org; source_org uuid; seed uuid; depth integer; step integer; candidate uuid;
BEGIN
 FOR depth IN 1..8 LOOP
  SELECT o.sandbox_seed, o.sandbox_of INTO seed, source_org FROM orgs o WHERE o.id = current_org;
  EXIT WHEN seed IS NULL;
  seeds := seeds || seed;
  EXIT WHEN source_org IS NULL;
  current_org := source_org;
 END LOOP;
 FOR depth IN 1..coalesce(array_length(seeds, 1), 0) LOOP
  candidate := p_identity;
  FOR step IN REVERSE depth..1 LOOP
   candidate := public.ob_rebase(candidate, seeds[step]);
  END LOOP;
  IF EXISTS (SELECT 1 FROM equity_securities s WHERE s.org_id = p_org AND s.id = candidate) THEN RETURN candidate; END IF;
 END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.equity_position_backfill(p_org uuid, p_subsidiary uuid, p_apply boolean)
 RETURNS TABLE(position_kind text, security_id uuid, plan_id uuid, effective_on date, shares_delta bigint, as_converted_delta bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE pos record; d date; shares bigint; converted bigint; prev_shares bigint; prev_converted bigint; r record; class_id uuid;
BEGIN
 IF p_apply AND EXISTS (SELECT 1 FROM equity_position_movements m WHERE m.org_id = p_org AND m.subsidiary_id = p_subsidiary) THEN
  RAISE EXCEPTION 'The position ledger of this legal entity already carries movements.' USING ERRCODE='23514';
 END IF;
 FOR pos IN
   SELECT CASE WHEN s.kind = 'share' THEN 'share' ELSE 'award' END AS kind, s.id AS sec, NULL::uuid AS plan, s.share_class_id AS cls, s.issue_date AS start_on
     FROM equity_securities s WHERE s.org_id = p_org AND s.subsidiary_id = p_subsidiary AND s.quantity IS NOT NULL AND s.share_class_id IS NOT NULL
   UNION ALL
   SELECT 'pool', NULL::uuid, p.id, p.share_class_id, p.effective_on
     FROM equity_plans p WHERE p.org_id = p_org AND p.subsidiary_id = p_subsidiary
   ORDER BY 5, 2, 3
 LOOP
  prev_shares := 0; prev_converted := 0;
  FOR d IN
    SELECT x.on_date FROM (
      SELECT issue_date AS on_date FROM equity_securities WHERE org_id = p_org AND subsidiary_id = p_subsidiary
      UNION SELECT e.effective_on FROM equity_security_events e WHERE e.org_id = p_org AND e.subsidiary_id = p_subsidiary
      UNION SELECT sp.effective_on FROM equity_splits sp WHERE sp.org_id = p_org AND sp.subsidiary_id = p_subsidiary
      UNION SELECT a.effective_on FROM equity_class_amendments a WHERE a.org_id = p_org AND a.subsidiary_id = p_subsidiary
      UNION SELECT c.effective_on FROM equity_plan_reserve_changes c WHERE c.org_id = p_org AND c.subsidiary_id = p_subsidiary
      UNION SELECT pl.effective_on FROM equity_plans pl WHERE pl.org_id = p_org AND pl.subsidiary_id = p_subsidiary
      UNION SELECT cl.effective_on FROM equity_share_classes cl WHERE cl.org_id = p_org AND cl.subsidiary_id = p_subsidiary
    ) x WHERE x.on_date >= pos.start_on ORDER BY 1
  LOOP
   IF pos.kind = 'pool' THEN shares := public.equity_position_pool(p_org, pos.plan, d);
   ELSE shares := public.equity_position_outstanding(p_org, pos.sec, d);
   END IF;
   IF shares = 0 THEN converted := 0;
   ELSE
    SELECT * INTO r FROM public.equity_position_ratio(p_org, pos.cls, d);
    converted := public.equity_position_floor(shares * r.num, r.den);
   END IF;
   IF shares <> prev_shares OR converted <> prev_converted THEN
    position_kind := pos.kind; security_id := pos.sec; plan_id := pos.plan; effective_on := d;
    shares_delta := shares - prev_shares; as_converted_delta := converted - prev_converted;
    IF p_apply THEN
     INSERT INTO equity_position_movements (org_id, subsidiary_id, position_kind, security_id, plan_id, effective_on, shares_delta, as_converted_delta)
     VALUES (p_org, p_subsidiary, pos.kind, pos.sec, pos.plan, d, shares - prev_shares, converted - prev_converted);
    END IF;
    RETURN NEXT;
    prev_shares := shares; prev_converted := converted;
   END IF;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.equity_position_conversion_class(p_org uuid, p_class uuid, p_on date)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE cls record; amendment record; target uuid; stated date;
BEGIN
 SELECT * INTO cls FROM equity_share_classes WHERE org_id = p_org AND id = p_class;
 IF cls.kind <> 'preferred' THEN RETURN NULL; END IF;
 target := cls.conversion_share_class_id; stated := cls.effective_on;
 FOR amendment IN SELECT * FROM equity_class_amendments WHERE org_id = p_org AND share_class_id = p_class
   AND kind = 'conversion_class' AND effective_on <= p_on ORDER BY created_at, id LOOP
  IF amendment.effective_on >= stated THEN target := amendment.conversion_share_class_id; stated := amendment.effective_on; END IF;
 END LOOP;
 RETURN target;
END $function$

CREATE OR REPLACE FUNCTION public.equity_position_outstanding(p_org uuid, p_security uuid, p_on date)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE sec record; ev record; f record; num numeric; den numeric; g numeric;
BEGIN
 SELECT * INTO sec FROM equity_securities WHERE org_id = p_org AND id = p_security;
 IF sec.quantity IS NULL OR sec.share_class_id IS NULL OR p_on < sec.issue_date THEN RETURN 0; END IF;
 IF EXISTS (SELECT 1 FROM equity_security_events WHERE org_id = p_org AND security_id = p_security AND kind = 'void' AND effective_on <= p_on) THEN RETURN 0; END IF;
 SELECT * INTO f FROM public.equity_position_split_factor(p_org, sec.share_class_id, sec.issue_date, p_on);
 num := sec.quantity * f.num; den := f.den;
 FOR ev IN SELECT e.* FROM equity_security_events e
   WHERE e.org_id = p_org AND e.security_id = p_security AND e.effective_on <= p_on AND e.quantity IS NOT NULL
     AND e.kind IN ('exercise', 'settle', 'forfeit', 'expire', 'cancel', 'repurchase', 'transfer', 'convert')
     AND NOT EXISTS (SELECT 1 FROM equity_security_events r WHERE r.org_id = p_org AND r.kind = 'reverse'
       AND r.reverses_event_id = e.id AND r.effective_on <= p_on)
     AND NOT (e.resulting_security_id IS NOT NULL AND EXISTS (SELECT 1 FROM equity_security_events v WHERE v.org_id = p_org
       AND v.kind = 'void' AND v.security_id = e.resulting_security_id AND v.effective_on <= p_on)) LOOP
  SELECT * INTO f FROM public.equity_position_split_factor(p_org, sec.share_class_id, ev.effective_on, p_on);
  num := num * f.den - ev.quantity * f.num * den;
  den := den * f.den;
  g := gcd(num, den); IF g > 1 THEN num := num / g; den := den / g; END IF;
 END LOOP;
 RETURN public.equity_position_floor(num, den);
END $function$

CREATE OR REPLACE FUNCTION public.equity_position_ratio(p_org uuid, p_class uuid, p_on date, OUT num numeric, OUT den numeric)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE cls record; amendment record; split record; price numeric; stated date; f_stated record; f_effective record; g numeric;
BEGIN
 SELECT * INTO cls FROM equity_share_classes WHERE org_id = p_org AND id = p_class;
 IF cls.kind = 'common' THEN num := 1; den := 1; RETURN; END IF;
 price := cls.initial_conversion_price; stated := cls.effective_on;
 FOR amendment IN SELECT * FROM equity_class_amendments WHERE org_id = p_org AND share_class_id = p_class
   AND kind = 'conversion_price' AND effective_on <= p_on ORDER BY created_at, id LOOP
  IF amendment.effective_on >= stated THEN price := amendment.conversion_price; stated := amendment.effective_on; END IF;
 END LOOP;
 SELECT * INTO f_stated FROM public.equity_position_split_factor(p_org, p_class, stated, p_on);
 SELECT * INTO f_effective FROM public.equity_position_split_factor(p_org, p_class, cls.effective_on, p_on);
 -- Prices carry ten places: scale them to whole numbers.
 num := (cls.original_issue_price * 10000000000) * f_stated.num * f_effective.den;
 den := (price * 10000000000) * f_stated.den * f_effective.num;
 IF cls.conversion_adjusts_for_splits THEN
  FOR split IN SELECT * FROM equity_splits WHERE org_id = p_org AND share_class_id <> p_class
    AND effective_on > stated AND effective_on <= p_on ORDER BY effective_on, created_at, id LOOP
   IF public.equity_position_conversion_class(p_org, p_class, split.effective_on) = split.share_class_id THEN
    num := num * split.ratio_numerator; den := den * split.ratio_denominator;
   END IF;
  END LOOP;
 END IF;
 g := gcd(num, den); num := num / g; den := den / g;
END $function$

CREATE OR REPLACE FUNCTION public.equity_record_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='equity_securities' AND (to_jsonb(NEW)-'holder_party_id')=(to_jsonb(OLD)-'holder_party_id') THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Equity records are retained history. Record a void, cancellation or amendment instead.' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public.extension_draft_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF (NEW.id,NEW.org_id,NEW.created_by,NEW.extension_key,NEW.bundle,NEW.content_hash,NEW.base_version_id,NEW.reason,NEW.created_at)
     IS DISTINCT FROM
     (OLD.id,OLD.org_id,OLD.created_by,OLD.extension_key,OLD.bundle,OLD.content_hash,OLD.base_version_id,OLD.reason,OLD.created_at) THEN
    RAISE EXCEPTION 'Extension draft revisions are immutable; create a new revision';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status='draft' AND NEW.status IN ('applied','discarded')) THEN
    RAISE EXCEPTION 'Invalid extension draft transition';
  END IF;
  IF (NEW.status='applied') IS DISTINCT FROM (NEW.applied_at IS NOT NULL) OR
     (OLD.status='applied' AND NEW.applied_at IS DISTINCT FROM OLD.applied_at) THEN
    RAISE EXCEPTION 'Invalid extension activation timestamp';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fair_value_used_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF EXISTS (SELECT 1 FROM public.performance_obligations o WHERE o.org_id=OLD.org_id AND o.allocation_basis->>'fairValuePriceId'=OLD.id::text) THEN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Used fair-value policy is retained; create a successor dated policy'; END IF;
    IF ROW(NEW.org_id,NEW.item_id,NEW.currency,NEW.unit_price,NEW.low_value,NEW.high_value,NEW.effective_from,NEW.calculation_method,NEW.formula_percent,NEW.list_price,NEW.unit_cost)
       IS DISTINCT FROM ROW(OLD.org_id,OLD.item_id,OLD.currency,OLD.unit_price,OLD.low_value,OLD.high_value,OLD.effective_from,OLD.calculation_method,OLD.formula_percent,OLD.list_price,OLD.unit_cost) THEN
      RAISE EXCEPTION 'Used fair-value terms are immutable; close this window and create a successor dated policy';
    END IF;
    IF NEW.effective_to IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.performance_obligations o JOIN public.document_lines dl ON dl.org_id=o.org_id AND dl.id=o.document_line_id
      JOIN public.documents d ON d.org_id=dl.org_id AND d.id=dl.document_id
      WHERE o.org_id=OLD.org_id AND o.allocation_basis->>'fairValuePriceId'=OLD.id::text AND d.document_date>NEW.effective_to
    ) THEN RAISE EXCEPTION 'A fair-value window cannot exclude an obligation already priced by it'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.field_ticket_evidence_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_row jsonb;
  v_org_id uuid;
  v_field_ticket_id uuid;
  v_evidence_id uuid;
BEGIN
  -- to_jsonb(NEW) is safe for either trigger relation.  Keep the casts here so
  -- malformed identifiers fail closed rather than being treated as absent.
  v_row := to_jsonb(NEW);
  v_org_id := (v_row ->> 'org_id')::uuid;
  v_field_ticket_id := (v_row ->> 'field_ticket_id')::uuid;

  IF NOT EXISTS (
    SELECT 1
      FROM public.field_tickets ft
     WHERE ft.document_id = v_field_ticket_id
       AND ft.org_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'field ticket evidence must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'field_ticket_signatures' THEN
    v_evidence_id := NULLIF(v_row ->> 'signature_file_id', '')::uuid;
    IF v_evidence_id IS NULL OR NOT EXISTS (
      SELECT 1
        FROM public.files f
       WHERE f.id = v_evidence_id
         AND f.org_id = v_org_id
    ) THEN
      RAISE EXCEPTION 'field ticket signature file must belong to the same organization'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'field_ticket_signature_requests' THEN
    v_evidence_id := NULLIF(v_row ->> 'email_log_id', '')::uuid;
    IF v_evidence_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
        FROM public.email_log e
       WHERE e.id = v_evidence_id
         AND e.org_id = v_org_id
    ) THEN
      RAISE EXCEPTION 'field ticket signature email evidence must belong to the same organization'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.field_ticket_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not exists (
    select 1 from documents d
     where d.id = new.document_id and d.org_id = new.org_id
       and d.kind = 'field_ticket'
  ) then
    raise exception 'field ticket header must extend a field_ticket document in the same organization'
      using errcode = '23514';
  end if;
  if new.foreman_party_id is not null and not exists (
    select 1 from parties p where p.id = new.foreman_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket foreman must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.charge_document_id is not null and not exists (
    select 1 from documents d where d.id = new.charge_document_id and d.org_id = new.org_id
  ) then
    raise exception 'field ticket charge document must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then
    raise exception 'field ticket submitter must belong to the same organization'
      using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.field_ticket_labor_snapshot_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM field_tickets ft
      JOIN documents d
        ON d.id = ft.document_id
       AND d.org_id = ft.org_id
       AND d.kind = 'field_ticket'
     WHERE ft.document_id = new.field_ticket_id
       AND ft.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'field ticket labor snapshot must belong to a Field Ticket in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.captured_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.captured_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.superseded_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot superseding actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_at IS NOT NULL AND new.superseded_at < new.captured_at THEN
    RAISE EXCEPTION 'field ticket labor snapshot cannot be superseded before capture'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END
$function$

CREATE OR REPLACE FUNCTION public.field_ticket_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.customer_party_id is not null and not exists (
    select 1 from parties p
     where p.id = new.customer_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket customer policy must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.project_id is not null and not exists (
    select 1 from projects p
     where p.id = new.project_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket project policy must belong to the same organization'
      using errcode = '23514';
  end if;
  -- Effective-window exclusivity is owned by the
  -- field_ticket_policies_no_active_overlap exclusion constraint (0051),
  -- which stays correct under concurrent READ COMMITTED writers.
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.field_ticket_signature_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' then
    raise exception 'field ticket signature requests are retained evidence';
  end if;
  if row(new.org_id, new.field_ticket_id, new.recipient, new.message,
         new.expires_at, new.token_digest, new.email_log_id,
         new.created_by, new.created_at)
     is distinct from
     row(old.org_id, old.field_ticket_id, old.recipient, old.message,
         old.expires_at, old.token_digest, old.email_log_id,
         old.created_by, old.created_at)
  then
    raise exception 'field ticket signature request evidence is immutable';
  end if;
  if old.responded_at is not null and new.responded_at is distinct from old.responded_at then
    raise exception 'field ticket signature response timestamp is immutable once set';
  end if;
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'field ticket signature revocation timestamp is immutable once set';
  end if;
  if old.sent_at is not null and new.sent_at is distinct from old.sent_at then
    raise exception 'field ticket signature delivery timestamp is immutable once set';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.field_ticket_source_certification_clone_evidence(value jsonb, seed uuid, field_name text, target_org uuid, masked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF field_name = 'source_row_snapshot' THEN
  RETURN CASE WHEN masked THEN public.production_mask_evidence(value) ELSE value END;
 END IF;
 IF masked AND field_name = 'native_point_in_time' THEN
  RETURN jsonb_build_object(
   'maskedEvidence', 'REDACTED',
   'fingerprintAttribution', 'native_fingerprint_sha256 retains the original source fingerprint; this masked copy carries no native point-in-time before-image');
 END IF;
 RETURN public.production_clone_safe_evidence(value, seed, field_name, target_org, masked);
END
$function$

CREATE OR REPLACE FUNCTION public.field_ticket_source_certification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP = 'INSERT' AND public.field_ticket_source_certifications_clone_matches(to_jsonb(NEW)) THEN
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
   RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Field Ticket source-identity certifications are append-only; a certification cannot be deleted'
   USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'UPDATE' THEN
  RAISE EXCEPTION 'Field Ticket source-identity certifications are append-only; a certification cannot be replaced'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.documents
   WHERE org_id = NEW.org_id AND id = NEW.native_document_id AND kind = 'field_ticket'
     AND document_number = NEW.native_document_number
     AND project_id = NEW.native_project_id
     AND subsidiary_id = NEW.native_subsidiary_id) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification requires the exact native ticket, number, project and legal entity in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.field_tickets
   WHERE org_id = NEW.org_id AND document_id = NEW.native_document_id) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification requires the native Field Ticket header in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF EXISTS (SELECT 1 FROM public.documents
   WHERE org_id = NEW.org_id AND kind = 'field_ticket' AND id <> NEW.native_document_id
     AND custom->'source'->>'system' = NEW.source_system
     AND custom->'source'->>'externalId' = NEW.source_external_id) THEN
  RAISE EXCEPTION 'This source ticket is already represented by another native Field Ticket; reconcile the duplicate source representation before certifying'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.files file
   JOIN public.file_versions version ON version.file_id = file.id
   WHERE file.org_id = NEW.org_id AND file.id = NEW.source_file_id AND NOT file.is_inactive
     AND version.id = NEW.source_version_id AND version.content_hash = NEW.source_file_sha256) THEN
  RAISE EXCEPTION 'A Field Ticket source-identity certification requires the exact active retained source file version and hash in this organization'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.field_ticket_source_certifications_clone_matches(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target record;
  original jsonb;
  expected jsonb;
  column_row record;
BEGIN
  IF NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
  SELECT org.sandbox_of, org.sandbox_seed, sandbox.masked
    INTO target
    FROM public.orgs org
    JOIN public.sandboxes sandbox
      ON sandbox.org_id = org.id AND sandbox.production_org_id = org.sandbox_of
    JOIN public.orgs production ON production.id = org.sandbox_of AND production.id <> org.id
   WHERE org.id = (candidate->>'org_id')::uuid
     AND org.env_kind = 'sandbox'
     AND org.sandbox_seed IS NOT NULL
     AND sandbox.status IN ('provisioning', 'refreshing');
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT to_jsonb(source)
    INTO original
    FROM public.field_ticket_source_certifications source
   WHERE source.org_id = target.sandbox_of
     AND public.ob_rebase(source.id, target.sandbox_seed) = (candidate->>'id')::uuid;
  IF original IS NULL THEN RETURN false; END IF;

  expected := original;
  FOR column_row IN
    SELECT attribute.attname, attribute.atttypid
      FROM pg_catalog.pg_attribute attribute
     WHERE attribute.attrelid = 'public.field_ticket_source_certifications'::regclass
       AND attribute.attnum > 0 AND NOT attribute.attisdropped
  LOOP
    IF column_row.attname = 'org_id' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb((candidate->>'org_id')::uuid));
    ELSIF column_row.atttypid = 'uuid'::regtype
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb(public.ob_rebase(
        (original->>column_row.attname)::uuid, target.sandbox_seed
      )));
    END IF;
  END LOOP;
  expected := jsonb_set(expected, '{source_row_snapshot}', public.field_ticket_source_certification_clone_evidence(
    original->'source_row_snapshot', target.sandbox_seed, 'source_row_snapshot',
    (candidate->>'org_id')::uuid, target.masked));
  expected := jsonb_set(expected, '{reference_map}', public.field_ticket_source_certification_clone_evidence(
    original->'reference_map', target.sandbox_seed, 'reference_map',
    (candidate->>'org_id')::uuid, target.masked));
  expected := jsonb_set(expected, '{native_point_in_time}', public.field_ticket_source_certification_clone_evidence(
    original->'native_point_in_time', target.sandbox_seed, 'native_point_in_time',
    (candidate->>'org_id')::uuid, target.masked));
  IF target.masked THEN
    expected := jsonb_set(expected, '{attestation}', to_jsonb('REDACTED'::text));
    expected := jsonb_set(expected, '{reason}', to_jsonb('REDACTED'::text));
  END IF;
  RETURN candidate = expected;
END
$function$

CREATE OR REPLACE FUNCTION public.field_ticket_source_projection_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
 old_system text;
 old_external text;
 new_system text;
 new_external text;
BEGIN
 IF NEW.kind <> 'field_ticket' AND OLD.kind <> 'field_ticket' THEN RETURN NEW; END IF;
 old_system := CASE WHEN jsonb_typeof(OLD.custom->'source') = 'object' THEN OLD.custom->'source'->>'system' END;
 old_external := CASE WHEN jsonb_typeof(OLD.custom->'source') = 'object' THEN OLD.custom->'source'->>'externalId' END;
 new_system := CASE WHEN jsonb_typeof(NEW.custom->'source') = 'object' THEN NEW.custom->'source'->>'system' END;
 new_external := CASE WHEN jsonb_typeof(NEW.custom->'source') = 'object' THEN NEW.custom->'source'->>'externalId' END;
 IF (new_system, new_external) IS NOT DISTINCT FROM (old_system, old_external) THEN RETURN NEW; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.field_ticket_source_certifications
   WHERE org_id = NEW.org_id AND native_document_id = NEW.id
     AND source_system = new_system AND source_external_id = new_external) THEN
  RAISE EXCEPTION 'Field Ticket source identity may be set only from its governed source-identity certification; certify the ticket through the native certification command before projecting a source marker'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.financial_change_clone_context(value jsonb, seed uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb:=value; identity_key text;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 FOREACH identity_key IN ARRAY ARRAY['id','subsidiaryId'] LOOP
  IF jsonb_typeof(result->identity_key)='string' THEN
   result:=jsonb_set(result,ARRAY[identity_key],to_jsonb(public.ob_rebase((result->>identity_key)::uuid,seed)::text));
  END IF;
 END LOOP;
 IF jsonb_typeof(result #> '{submissionPolicy,flowId}')='string' THEN
  result:=jsonb_set(result,'{submissionPolicy,flowId}',to_jsonb(public.ob_rebase((result #>> '{submissionPolicy,flowId}')::uuid,seed)::text));
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.financial_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  scrap_work_order_subsidiary_id uuid;
  scrap_posted_entry_id uuid;
  scrap_posted_journal_subsidiary_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP='DELETE' THEN
    IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'financial changes are immutable evidence; propose a correcting change';
  END IF;
  IF TG_OP='INSERT' AND NEW.submission_policy IS NOT NULL AND NOT public.openbooks_clone_authority() THEN
    RAISE EXCEPTION 'Submission routing evidence is captured only on submission.';
  END IF;
  IF TG_OP='UPDATE' AND NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
    IF OLD.status<>'draft' OR NEW.status<>'pending' OR OLD.submission_policy IS NOT NULL
      OR NOT public.flow_submission_policy_valid(NEW.org_id,'financial_change',NEW.id,NEW.submitted_by,NEW.submission_policy) THEN
      RAISE EXCEPTION 'The accounting event requires complete native Flow routing evidence, frozen on submission.';
    END IF;
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='draft' AND NEW.status='pending' AND NEW.submission_policy IS NULL THEN
    RAISE EXCEPTION 'Submit the accounting event through its native Flow routing.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM subsidiaries WHERE id=NEW.subsidiary_id AND org_id=NEW.org_id) THEN
    RAISE EXCEPTION 'financial change subsidiary must belong to the organization';
  END IF;
  IF TG_OP='INSERT' THEN
    IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
    IF NEW.status <> 'draft' THEN RAISE EXCEPTION 'financial changes must start as draft'; END IF;
  END IF;
  IF NEW.domain = 'manufacturing' AND (
       TG_OP = 'INSERT'
       OR (OLD.status = 'draft' AND NEW.status = 'pending')
       OR (OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected'))
       OR (OLD.status = 'approved' AND NEW.status = 'applied')) THEN
    IF NEW.operation = 'work_order_loss_disposition' THEN
      IF NEW.payload->>'workOrderId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR NEW.before_state->'order'->>'id' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.before_state->'order'->>'subsidiary_id' IS DISTINCT FROM NEW.subsidiary_id::text
        OR NEW.before_state->>'onDate' IS DISTINCT FROM NEW.effective_on::text
        OR NEW.before_state->>'quantity' IS DISTINCT FROM NEW.payload->'input'->>'quantity'
        OR coalesce(NEW.before_state->>'value','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR coalesce(NEW.before_state->>'quantity','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR jsonb_typeof(NEW.payload->'input'->'times') IS DISTINCT FROM 'array'
        OR NOT EXISTS(SELECT 1 FROM public.mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.subject_id AND subsidiary_id=NEW.subsidiary_id) THEN
        RAISE EXCEPTION 'Production loss approval must bind its work, actual discarded quantity, conversion time, WIP and booking entity.' USING ERRCODE='23514';
      END IF;
      IF (NEW.before_state->>'quantity')::numeric<=0 OR (NEW.before_state->>'value')::numeric>999999999999999.9999 THEN RAISE EXCEPTION 'Production loss quantities and values require exact supported precision.' USING ERRCODE='23514'; END IF;
    ELSIF NEW.operation = 'standard_cost_rollup' THEN
      IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object'
        OR NEW.payload->>'itemId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->>'subsidiaryId' IS DISTINCT FROM NEW.subsidiary_id::text
        OR NEW.payload->>'onDate' IS DISTINCT FROM NEW.effective_on::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR coalesce(NEW.payload->>'batchQuantity','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR coalesce(NEW.payload->>'standardCost','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR NOT EXISTS(SELECT 1 FROM public.item_inventory_profiles WHERE org_id=NEW.org_id AND item_id=NEW.subject_id AND costing_method='standard') THEN
        RAISE EXCEPTION 'Standard roll-up must bind a tenant standard-cost item, costing date, positive batch, standard, and booking entity.' USING ERRCODE='23514';
      END IF;
      IF (NEW.payload->>'batchQuantity')::numeric<=0 THEN RAISE EXCEPTION 'Standard roll-up batch must be positive.' USING ERRCODE='23514'; END IF;
    ELSIF NEW.operation = 'bom_revision_activation' THEN
      IF NEW.payload->>'assemblyItemId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR jsonb_typeof(NEW.payload->'components') IS DISTINCT FROM 'array'
        OR jsonb_typeof(NEW.before_state->'lines') IS DISTINCT FROM 'array'
        OR jsonb_array_length(NEW.payload->'components') NOT BETWEEN 1 AND 500
        OR NOT EXISTS(SELECT 1 FROM public.items WHERE org_id=NEW.org_id AND id=NEW.subject_id AND kind<>'kit') THEN
        RAISE EXCEPTION 'BOM approval must bind its tenant produced item, component revision and booking entity.' USING ERRCODE='23514';
      END IF;
    ELSIF NEW.operation = 'routing_revision_activation' THEN
      IF jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object'
        OR NEW.payload->>'routingId' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text)
        OR jsonb_typeof(NEW.payload->'supersedes') IS DISTINCT FROM 'array'
        OR NEW.before_state->'candidate'->>'id' IS DISTINCT FROM NEW.subject_id::text
        OR NEW.before_state->'candidate'->>'effectiveFrom' IS DISTINCT FROM NEW.effective_on::text
        OR NOT EXISTS(SELECT 1 FROM public.mfg_routings WHERE org_id=NEW.org_id AND id=NEW.subject_id) THEN
        RAISE EXCEPTION 'Routing approval must bind its tenant revision, effective date and governed prior windows.' USING ERRCODE='23514';
      END IF;
    ELSE
    IF NEW.operation <> 'scrap_snapshot_restatement' THEN
      RAISE EXCEPTION 'manufacturing financial changes admit only the scrap_snapshot_restatement operation, not %', NEW.operation;
    END IF;
    IF NEW.payload IS NULL OR jsonb_typeof(NEW.payload) <> 'object' THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must carry an object payload binding the event, work order, subsidiary, and approval flag';
    END IF;
    IF NOT (NEW.payload ? 'event_id')
      OR NOT (NEW.payload ? 'work_order_id')
      OR NOT (NEW.payload ? 'subsidiary_id')
      OR NOT (NEW.payload ? 'requiredSubsidiaryIds') THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must bind event_id, work_order_id, subsidiary_id, and requiredSubsidiaryIds in the payload';
    END IF;
    IF jsonb_typeof(NEW.payload -> 'requiredSubsidiaryIds') <> 'array'
      OR jsonb_typeof(NEW.payload -> 'approval_required') <> 'boolean' THEN
      RAISE EXCEPTION 'manufacturing scrap restatement proposals must bind requiredSubsidiaryIds as an array and the engine-derived approval_required as a boolean';
    END IF;
    IF (NEW.payload ->> 'event_id') <> NEW.subject_id::text THEN
      RAISE EXCEPTION 'manufacturing scrap restatement subject must be the bound event';
    END IF;
    SELECT work_order.subsidiary_id, scrap_event.posted_entry_id
      INTO scrap_work_order_subsidiary_id, scrap_posted_entry_id
      FROM public.mfg_scrap_events scrap_event
      JOIN public.mfg_work_orders work_order
        ON work_order.org_id = scrap_event.org_id
       AND work_order.id = scrap_event.work_order_id
     WHERE scrap_event.org_id = NEW.org_id
       AND scrap_event.id = NEW.subject_id
       AND scrap_event.work_order_id::text = (NEW.payload ->> 'work_order_id');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'manufacturing scrap restatement must bind the same-organization event, its work order, and that work order''s subsidiary';
    END IF;
    IF scrap_work_order_subsidiary_id IS NULL THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % is refused: work order % carries no subsidiary, and a restatement requires a non-null authoritative work-order subsidiary', NEW.subject_id, (NEW.payload ->> 'work_order_id');
    END IF;
    IF scrap_work_order_subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % must book the work order''s subsidiary %, not %', NEW.subject_id, scrap_work_order_subsidiary_id, NEW.subsidiary_id;
    END IF;
    IF (NEW.payload ->> 'subsidiary_id') IS DISTINCT FROM NEW.subsidiary_id::text THEN
      RAISE EXCEPTION 'manufacturing scrap restatement for event % payload subsidiary % must equal the booking subsidiary %', NEW.subject_id, (NEW.payload ->> 'subsidiary_id'), NEW.subsidiary_id;
    END IF;
    IF (NEW.payload -> 'requiredSubsidiaryIds') <> jsonb_build_array(NEW.subsidiary_id::text) THEN
      RAISE EXCEPTION 'manufacturing scrap restatement requiredSubsidiaryIds must be exactly the booking subsidiary';
    END IF;
    IF scrap_posted_entry_id IS NOT NULL THEN
      SELECT journal_entry.subsidiary_id
        INTO scrap_posted_journal_subsidiary_id
        FROM public.journal_entries journal_entry
       WHERE journal_entry.org_id = NEW.org_id
         AND journal_entry.id = scrap_posted_entry_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for event % references posted entry % which has no same-organization journal entry; reconcile the posted entry through the controlled accounting evidence correction workflow before retrying the restatement, without posting a duplicate entry, reversing the entry, rewriting the event, or fabricating journal evidence', NEW.subject_id, scrap_posted_entry_id;
      END IF;
      IF scrap_posted_journal_subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for event % posted entry % books subsidiary %, not the bound booking subsidiary %', NEW.subject_id, scrap_posted_entry_id, scrap_posted_journal_subsidiary_id, NEW.subsidiary_id;
      END IF;
    ELSE
      IF (NEW.payload ? 'posted_entry_id')
        OR (NEW.payload ? 'journal_entry_id')
        OR (NEW.payload ? 'entry_id') THEN
        RAISE EXCEPTION 'manufacturing scrap restatement for unposted event % must not carry journal evidence; payload keys posted_entry_id, journal_entry_id, and entry_id are refused', NEW.subject_id;
      END IF;
    END IF;
    END IF;
  END IF;
  IF TG_OP='INSERT' THEN
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - ARRAY['status','approved_by','approved_at','result','applied_by','applied_at','updated_at','updated_by','submission_policy'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['status','approved_by','approved_at','result','applied_by','applied_at','updated_at','updated_by','submission_policy']) THEN
    RAISE EXCEPTION 'financial change proposal is immutable; create a new proposal';
  END IF;
  IF NOT ((OLD.status='draft' AND NEW.status='pending') OR
          (OLD.status='pending' AND NEW.status IN ('approved','rejected')) OR
          (OLD.status='approved' AND NEW.status='applied')) THEN
    RAISE EXCEPTION 'invalid financial change transition % -> %', OLD.status, NEW.status;
  END IF;
  IF OLD.status <> 'pending' AND (NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN
    RAISE EXCEPTION 'financial change approval cannot be rewritten';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.financial_change_self_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NEW.approved_by=NEW.submitted_by AND NOT public.financial_change_self_decision_authorized(NEW.org_id,NEW.id,NEW.approved_by) THEN
  RAISE EXCEPTION 'Submit through Flows; release requires successful ungated routing or its retained gate decisions.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.financial_history_clone_scope(source_scope text, seed uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF source_scope='all' THEN RETURN source_scope; END IF;
 IF source_scope ~ '^period:[0-9a-f-]{36}$' THEN
  RETURN 'period:'||public.ob_rebase(split_part(source_scope,':',2)::uuid,seed);
 END IF;
 IF source_scope ~ '^year:[0-9a-f-]{36}:[0-9]+$' THEN
  RETURN 'year:'||public.ob_rebase(split_part(source_scope,':',2)::uuid,seed)||':'||split_part(source_scope,':',3);
 END IF;
 RAISE EXCEPTION 'The retained GL audit scope has no native period or fiscal-year identity.' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public.financial_history_native_clone_matches(relation regclass, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target record; original jsonb; expected jsonb; field record; reference record;
 parent_matches boolean; parent_predicate text; policy_prefix text; relation_name text;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN (
  'public.fx_rate_types'::regclass,'public.account_translation_policies'::regclass,
  'public.subsidiary_accounting_preferences'::regclass,'public.segment_balancing_policies'::regclass,
  'public.gl_audit_number_policies'::regclass,'public.gl_audit_number_assignments'::regclass,
  'public.journal_lines'::regclass,'public.rebate_agreements'::regclass) THEN RETURN false; END IF;
 SELECT destination.id,destination.sandbox_of,destination.sandbox_seed,control.masked INTO target
 FROM public.orgs destination JOIN public.sandboxes control
  ON control.org_id=destination.id AND control.production_org_id=destination.sandbox_of
 JOIN public.orgs source ON source.id=destination.sandbox_of AND source.id<>destination.id
 WHERE destination.id=(candidate->>'org_id')::uuid AND destination.env_kind='sandbox'
  AND destination.sandbox_seed IS NOT NULL AND control.status IN('provisioning','refreshing');
 IF NOT FOUND THEN RETURN false; END IF;
 EXECUTE format('SELECT to_jsonb(source) FROM %s source WHERE source.org_id=$1 AND public.ob_rebase(source.id,$2)=$3',relation)
 INTO original USING target.sandbox_of,target.sandbox_seed,(candidate->>'id')::uuid;
 IF original IS NULL THEN RETURN false; END IF;
 SELECT relname INTO relation_name FROM pg_catalog.pg_class WHERE oid=relation;
 expected:=original;
 FOR field IN SELECT attname,atttypid FROM pg_catalog.pg_attribute
  WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF field.attname='org_id' THEN
   expected:=jsonb_set(expected,ARRAY[field.attname],to_jsonb(target.id));
  ELSIF field.atttypid='uuid'::regtype AND jsonb_typeof(original->field.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[field.attname],to_jsonb(public.ob_rebase((original->>field.attname)::uuid,target.sandbox_seed)));
  END IF;
  IF target.masked AND field.attname IN('name','reason','memo') AND jsonb_typeof(original->field.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[field.attname],to_jsonb('REDACTED'::text));
  END IF;
 END LOOP;
 IF jsonb_typeof(expected->'extra_dims')='object' THEN
  expected:=jsonb_set(expected,'{extra_dims}',coalesce((SELECT jsonb_object_agg(dim.key,CASE
   WHEN jsonb_typeof(dim.value)='string' AND EXISTS(SELECT 1 FROM public.segment_values value_row
    WHERE value_row.org_id=target.sandbox_of AND value_row.id::text=dim.value #>> '{}')
   THEN to_jsonb(public.ob_rebase((dim.value #>> '{}')::uuid,target.sandbox_seed)::text) ELSE dim.value END)
   FROM jsonb_each(expected->'extra_dims') dim),'{}'::jsonb));
 END IF;
 IF relation='public.journal_lines'::regclass AND coalesce(original->'custom'->>'equitySecurityId','') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
  expected:=jsonb_set(expected,'{custom}',(CASE WHEN target.masked THEN '{}'::jsonb ELSE original->'custom' END)
   || jsonb_build_object('equitySecurityId',public.ob_rebase((original->'custom'->>'equitySecurityId')::uuid,target.sandbox_seed)::text,
      'equityRole',original->'custom'->'equityRole'));
 ELSIF relation='public.journal_lines'::regclass AND target.masked THEN
  expected:=jsonb_set(expected,'{custom}','{}'::jsonb);
 END IF;
 IF relation='public.gl_audit_number_assignments'::regclass THEN
  SELECT prefix INTO policy_prefix FROM public.gl_audit_number_policies
   WHERE org_id=target.sandbox_of AND id=(original->>'policy_id')::uuid;
  IF policy_prefix IS NULL THEN RETURN false; END IF;
  expected:=jsonb_set(expected,'{scope_key}',to_jsonb(public.financial_history_clone_scope(original->>'scope_key',target.sandbox_seed)));
  expected:=jsonb_set(expected,'{audit_number}',to_jsonb(policy_prefix||'-'||replace(expected->>'scope_key',':','-')||'-'||
   lpad(original->>'ordinal',greatest(6,length(original->>'ordinal')),'0')));
 END IF;
 IF candidate IS DISTINCT FROM expected THEN RETURN false; END IF;
 -- Validate the complete referenced parent identity, including composite tenant keys,
 -- before admitting a recorded fact under its sandbox counterpart.
 FOR reference IN SELECT con.oid,con.confrelid FROM pg_catalog.pg_constraint con
  WHERE con.conrelid=relation AND con.contype='f' LOOP
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_constraint con
   JOIN pg_catalog.pg_attribute a ON a.attrelid=con.conrelid AND a.attnum=ANY(con.conkey)
   WHERE con.oid=reference.oid AND (candidate->a.attname IS NULL OR candidate->a.attname='null'::jsonb)) THEN CONTINUE; END IF;
  SELECT string_agg(format('parent.%I=($1->>%L)::%s',parent_column.attname,source_column.attname,
    pg_catalog.format_type(source_column.atttypid,source_column.atttypmod)),' AND ' ORDER BY position)
   INTO parent_predicate FROM pg_catalog.pg_constraint con
   CROSS JOIN LATERAL generate_subscripts(con.conkey,1) position
   JOIN pg_catalog.pg_attribute source_column ON source_column.attrelid=con.conrelid AND source_column.attnum=con.conkey[position]
   JOIN pg_catalog.pg_attribute parent_column ON parent_column.attrelid=con.confrelid AND parent_column.attnum=con.confkey[position]
   WHERE con.oid=reference.oid;
  IF EXISTS(SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid=reference.confrelid AND attname='org_id' AND NOT attisdropped) THEN
   parent_predicate:=parent_predicate||' AND parent.org_id=($1->>''org_id'')::uuid';
  END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s parent WHERE %s)',reference.confrelid::regclass,parent_predicate)
   INTO parent_matches USING candidate;
  IF NOT parent_matches THEN RETURN false; END IF;
 END LOOP;
 -- Legacy policy actor columns predate their explicit foreign keys.
 IF relation_name IN('fx_rate_types','account_translation_policies','subsidiary_accounting_preferences','segment_balancing_policies','gl_audit_number_policies') THEN
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[candidate->>'created_by',candidate->>'updated_by']) actor(id)
   WHERE actor.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.users u WHERE u.org_id=target.id AND u.id=actor.id::uuid)) THEN RETURN false; END IF;
 END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.financial_preferences_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 IF TG_TABLE_NAME='account_translation_policies' THEN
  IF NOT EXISTS(SELECT 1 FROM accounts WHERE org_id=NEW.org_id AND id=NEW.account_id AND is_active AND NOT is_summary AND type<>'statistical') THEN
   RAISE EXCEPTION 'Choose an active monetary posting account for a translation policy.' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM journal_lines l JOIN journal_entries e ON e.org_id=l.org_id AND e.id=l.entry_id
    WHERE l.org_id=NEW.org_id AND l.account_id=NEW.account_id AND e.status IN('posted','reversed') AND e.posting_date>=NEW.effective_from) THEN
   RAISE EXCEPTION 'A translation policy cannot reinterpret posted activity. Start after the latest posting on this account.' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.fiscal_calendar_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fiscal_calendars WHERE org_id=NEW.org_id AND id=NEW.fiscal_calendar_id AND is_active) THEN
   RAISE EXCEPTION 'Choose an active fiscal calendar of this organization.' USING ERRCODE='23514'; END IF;
  IF coalesce(NEW.fiscal_calendar_id,(SELECT id FROM fiscal_calendars WHERE org_id=NEW.org_id AND is_default AND is_active)) IS DISTINCT FROM public.subsidiary_posting_calendar(NEW.org_id,NEW.subsidiary_id,NEW.effective_from-1) AND (
    NOT EXISTS(SELECT 1 FROM accounting_periods p WHERE p.org_id=NEW.org_id AND p.fiscal_calendar_id=coalesce(NEW.fiscal_calendar_id,(SELECT id FROM fiscal_calendars WHERE org_id=NEW.org_id AND is_default AND is_active)) AND NOT p.is_adjustment AND p.starts_on=NEW.effective_from)
    OR EXISTS(SELECT 1 FROM accounting_periods p WHERE p.org_id=NEW.org_id AND p.fiscal_calendar_id=public.subsidiary_posting_calendar(NEW.org_id,NEW.subsidiary_id,NEW.effective_from-1)
      AND NOT p.is_adjustment AND p.starts_on<NEW.effective_from AND p.ends_on>=NEW.effective_from)) THEN
   RAISE EXCEPTION 'Change fiscal calendars at a shared regular-period boundary. Generate the new calendar periods and choose the first day after the old period ends.' USING ERRCODE='23514'; END IF;
  IF NEW.default_journal_form_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM form_layouts WHERE org_id=NEW.org_id AND id=NEW.default_journal_form_id AND record_type='journal' AND is_active) THEN
   RAISE EXCEPTION 'Choose an active journal form of this organization.' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM fx_rate_types WHERE org_id=NEW.org_id AND key=NEW.posting_rate_type AND is_active) THEN
   RAISE EXCEPTION 'Choose an active posting exchange-rate type.' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM journal_lines l JOIN journal_entries e ON e.org_id=l.org_id AND e.id=l.entry_id
    WHERE l.org_id=NEW.org_id AND l.subsidiary_id=NEW.subsidiary_id AND e.status IN('posted','reversed') AND e.posting_date>=NEW.effective_from) THEN
   RAISE EXCEPTION 'An entity preference cannot reinterpret posted activity. Start after the latest posting for this entity.' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fixed_asset_capitalization_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on'
     OR coalesce(current_setting('openbooks.asset_cip_ledger', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IN ('construction', 'capitalized') THEN
      RAISE EXCEPTION 'create construction in progress from Fixed Assets → Construction in progress' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF (OLD.status IN ('construction', 'capitalized') OR NEW.status IN ('construction', 'capitalized'))
     AND (NEW.status IS DISTINCT FROM OLD.status
       OR NEW.acquisition_cost IS DISTINCT FROM OLD.acquisition_cost
       OR NEW.asset_account_id IS DISTINCT FROM OLD.asset_account_id
       OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id) THEN
    RAISE EXCEPTION 'construction-in-progress cost moves only through linked costs and governed capitalization' USING ERRCODE = '23514';
  END IF;
  IF (NEW.acquisition_cost IS DISTINCT FROM OLD.acquisition_cost
      OR NEW.category_id IS DISTINCT FROM OLD.category_id
      OR NEW.asset_account_id IS DISTINCT FROM OLD.asset_account_id
      OR NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id)
     AND (EXISTS (SELECT 1 FROM public.asset_proposal_allocations al
                    JOIN public.asset_proposal_acceptances ac ON ac.org_id = al.org_id AND ac.id = al.acceptance_id
                   WHERE al.org_id = OLD.org_id AND al.asset_id = OLD.id AND al.cip_cost_id IS NULL AND ac.status = 'posted')
       OR EXISTS (SELECT 1 FROM public.asset_cip_capitalization_lines cl
                    JOIN public.asset_cip_capitalizations k ON k.org_id = cl.org_id AND k.id = cl.capitalization_id
                   WHERE cl.org_id = OLD.org_id AND cl.asset_id = OLD.id AND k.status = 'posted')) THEN
    RAISE EXCEPTION 'this asset''s cost was capitalized from posted transactions; reverse the acceptance or capitalization to change its cost, category, account or legal entity' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fixed_asset_component_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  parent record;
BEGIN
  IF coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.parent_asset_id IS NOT NULL THEN
    SELECT p.id, p.subsidiary_id, p.parent_asset_id, p.status INTO parent
      FROM public.fixed_assets p
     WHERE p.org_id = NEW.org_id AND p.id = NEW.parent_asset_id
       FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'the parent asset does not exist in this organization' USING ERRCODE = '23503';
    END IF;
    IF parent.parent_asset_id IS NOT NULL THEN
      RAISE EXCEPTION 'a component cannot own components; attach it to the top-level parent asset' USING ERRCODE = '23514';
    END IF;
    IF parent.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
      RAISE EXCEPTION 'a component must belong to the same legal entity as its parent asset' USING ERRCODE = '23514';
    END IF;
    IF parent.status IN ('construction', 'capitalized') OR NEW.status IN ('construction', 'capitalized') THEN
      RAISE EXCEPTION 'construction-in-progress records cannot own or be components' USING ERRCODE = '23514';
    END IF;
    IF (TG_OP = 'INSERT' OR NEW.parent_asset_id IS DISTINCT FROM OLD.parent_asset_id)
       AND parent.status IN ('disposed', 'written_off') THEN
      RAISE EXCEPTION 'components cannot be added to a disposed or written-off asset' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.fixed_assets c WHERE c.org_id = NEW.org_id AND c.parent_asset_id = NEW.id) THEN
      RAISE EXCEPTION 'an asset that owns components cannot itself become a component' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id
     AND EXISTS (SELECT 1 FROM public.fixed_assets c WHERE c.org_id = NEW.org_id AND c.parent_asset_id = NEW.id) THEN
    RAISE EXCEPTION 'an asset with components cannot change legal entity; detach or transfer its components first' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fixed_asset_configuration_org_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  method_id uuid;
  account_ids uuid[];
begin
  if tg_table_name = 'asset_categories' then
    method_id := new.default_depreciation_method_id;
  elsif tg_table_name = 'fixed_assets' then
    method_id := new.depreciation_method_id;
    account_ids := array_remove(array[new.asset_account_id, new.accumulated_depreciation_account_id, new.depreciation_expense_account_id], null);
  elsif tg_table_name in ('depreciation_schedules', 'depreciation_book_policies') then
    method_id := new.depreciation_method_id;
  end if;
  if method_id is not null and not exists (
    select 1 from depreciation_methods m where m.id = method_id and m.org_id = new.org_id and m.is_active
  ) then
    raise exception 'depreciation method must be active and belong to the tenant';
  end if;
  if cardinality(account_ids) > 0 and exists (
    select 1 from unnest(account_ids) wanted(id)
     where not exists (select 1 from accounts a where a.id = wanted.id and a.org_id = new.org_id and a.is_active and not a.is_summary)
  ) then
    raise exception 'fixed asset account override must be an active postable account in the tenant';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.flow_clone_evidence(value jsonb, seed uuid, field_name text DEFAULT ''::text, target_org uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE result jsonb; item record; scalar text; identity_field boolean;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(value)='string' THEN
  scalar:=value#>>'{}';
  IF field_name='intent' THEN
   BEGIN RETURN to_jsonb(public.production_canonical_json(public.flow_clone_evidence(scalar::jsonb,seed,'',target_org)));
   EXCEPTION WHEN invalid_text_representation THEN RETURN value; END;
  END IF;
  identity_field:=field_name='id' OR field_name~'(Id|Ids|_id|_ids|By|_by)$'
    OR field_name IN('requestKey','subcontract_consumption_key');
  IF identity_field AND field_name NOT IN('nodeId','node_id')
    AND scalar~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   IF field_name IN('orgId','org_id') AND target_org IS NOT NULL THEN RETURN to_jsonb(target_org::text); END IF;
   RETURN to_jsonb(public.ob_rebase(scalar::uuid,seed)::text);
  END IF;
 ELSIF jsonb_typeof(value)='array' THEN
  SELECT coalesce(jsonb_agg(public.flow_clone_evidence(element,seed,field_name,target_org) ORDER BY ordinal),'[]'::jsonb)
    INTO result FROM jsonb_array_elements(value) WITH ORDINALITY entries(element,ordinal);
  RETURN result;
 ELSIF jsonb_typeof(value)='object' THEN
  result:='{}'::jsonb;
  FOR item IN SELECT key,entry FROM jsonb_each(value) entries(key,entry) LOOP
   result:=result||jsonb_build_object(CASE WHEN field_name='material_usage_variance_delta_by_component'
     AND item.key~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     THEN public.ob_rebase(item.key::uuid,seed)::text ELSE item.key END,CASE
    WHEN item.key IN('id','source','target') AND field_name IN('nodes','edges') THEN item.entry
    WHEN item.key='custom' THEN item.entry
    ELSE public.flow_clone_evidence(item.entry,seed,item.key,target_org) END);
  END LOOP;
  RETURN result;
 END IF;
 RETURN value;
END $function$

CREATE OR REPLACE FUNCTION public.flow_gate_escalation_lineage_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.org_id,NEW.flow_id,NEW.run_id,NEW.node_id,NEW.subject_kind,NEW.subject_id,
      NEW.group_key,NEW.quorum,NEW.signature_required,NEW.created_by,NEW.created_at,NEW.escalated_from_gate_id)
     IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.flow_id,OLD.run_id,OLD.node_id,OLD.subject_kind,OLD.subject_id,
      OLD.group_key,OLD.quorum,OLD.signature_required,OLD.created_by,OLD.created_at,OLD.escalated_from_gate_id) THEN
   RAISE EXCEPTION 'A gate retains its submitted policy, subject and escalation lineage.' USING ERRCODE='23514';
  END IF;
  IF OLD.decided_at IS NOT NULL AND ROW(NEW.status,NEW.decided_by,NEW.decided_at,NEW.signature,NEW.comment,NEW.on_behalf_of_user_id)
     IS DISTINCT FROM ROW(OLD.status,OLD.decided_by,OLD.decided_at,OLD.signature,OLD.comment,OLD.on_behalf_of_user_id) THEN
   RAISE EXCEPTION 'A recorded gate decision is immutable.' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.flow_runs r,
    LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(r.context #> '{submissionPolicy,graph,nodes}')='array'
      THEN r.context #> '{submissionPolicy,graph,nodes}' ELSE '[]'::jsonb END) node
   WHERE r.org_id=NEW.org_id AND r.id=NEW.run_id AND r.flow_id=NEW.flow_id
    AND r.subject_kind=NEW.subject_kind AND r.subject_id=NEW.subject_id
    AND r.context #>> '{submissionPolicy,flowId}'=r.flow_id::text
    AND node->>'id'=NEW.node_id AND node->'data'->>'kind'='gate'
    AND node #>> '{data,gate,mode}'=NEW.quorum
    AND coalesce((node #>> '{data,gate,signatureRequired}')::boolean,false)=NEW.signature_required
    AND NEW.group_key=NEW.run_id::text || ':' || NEW.node_id) THEN
  RAISE EXCEPTION 'The approval gate must match its frozen Flow policy and subject.' USING ERRCODE='23514';
 END IF;
 IF NEW.escalated_from_gate_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.flow_gates parent WHERE parent.org_id=NEW.org_id AND parent.id=NEW.escalated_from_gate_id
     AND parent.run_id=NEW.run_id AND parent.flow_id=NEW.flow_id AND parent.node_id=NEW.node_id
     AND parent.group_key=NEW.group_key AND parent.quorum=NEW.quorum AND parent.status='escalated') THEN
  RAISE EXCEPTION 'An escalation replacement must retain its native gate group and replaced decision.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.flow_submission_receipt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Flow submission evidence is immutable.';
 END IF;
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Flow submission evidence is immutable.'; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NEW.actor_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.users u WHERE u.org_id=NEW.org_id AND u.id=NEW.actor_id AND u.is_active) THEN
   IF coalesce(NEW.context->>'submissionActorHomeOrgId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'The Flow submission requires its established active acting identity.' USING ERRCODE='23514';
   END IF;
   PERFORM public.lock_actor_home_identity(NEW.org_id,NEW.actor_id,(NEW.context->>'submissionActorHomeOrgId')::uuid);
  END IF;
 END IF;
 IF (NEW.actor_id IS NULL AND NOT (
     NEW.context->>'event_source' IS NOT DISTINCT FROM 'schedule'
     OR (NEW.context->>'event_source' IS NOT DISTINCT FROM 'portal'
       AND NEW.subject_kind='rma' AND public.flow_portal_return_source_valid(NEW.org_id,NEW.subject_id,NEW.context->'portalRequest'))
     OR (NEW.context->>'event_source' IS NOT DISTINCT FROM 'sync'
       AND NEW.subject_kind IN ('cash_sale','cash_refund')
       AND EXISTS(SELECT 1 FROM public.documents d JOIN public.sales_channels c
         ON c.org_id=d.org_id AND c.id=d.source_channel_id AND c.kind=d.external_source
         WHERE d.org_id=NEW.org_id AND d.id=NEW.subject_id AND d.kind=NEW.subject_kind
           AND nullif(btrim(d.external_ref),'') IS NOT NULL AND c.status='active'))
   ))
   OR NOT public.flow_submission_policy_valid(NEW.org_id,NEW.subject_kind,NEW.subject_id,NEW.actor_id,NEW.policy)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.policy->'runIds') claimed(id)
     WHERE NOT EXISTS(SELECT 1 FROM public.flow_runs r,
       LATERAL jsonb_array_elements(NEW.graphs) snapshot
       WHERE r.org_id=NEW.org_id AND r.id::text=claimed.id
        AND r.context #>> '{submissionPolicy,flowId}'=r.flow_id::text
        AND snapshot->>'id'=r.flow_id::text
        AND snapshot->'graph'=r.context #> '{submissionPolicy,graph}'))
   OR NEW.graphs IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'graph',f.graph) ORDER BY f.id),'[]'::jsonb)
     FROM public.flows f WHERE f.org_id=NEW.org_id AND f.subject_kind=NEW.subject_kind AND f.enabled) THEN
  RAISE EXCEPTION 'The Flow submission requires complete routing evidence and the current graph snapshots.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fulfillment_documents_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  document_kind text;
  document_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    SELECT status INTO document_status
      FROM public.documents WHERE id = OLD.document_id AND org_id = OLD.org_id;
    IF document_status IS NULL OR document_status = 'draft' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'fulfilment detail of a % document cannot be deleted; void the document instead', document_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.stage = 'done' THEN
    RAISE EXCEPTION 'a completed pick list or shipment is final and cannot be changed'
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  SELECT kind INTO document_kind
    FROM public.documents WHERE id = NEW.document_id AND org_id = NEW.org_id;
  IF document_kind IS DISTINCT FROM 'pick_list' AND document_kind IS DISTINCT FROM 'shipment' THEN
    RAISE EXCEPTION 'fulfilment detail belongs to a pick list or shipment, not a %', coalesce(document_kind, 'missing document')
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'pick_list' AND (
       NEW.carrier_id IS NOT NULL OR NEW.carrier_service IS NOT NULL OR NEW.tracking_number IS NOT NULL
       OR NEW.ship_to_address IS NOT NULL OR NEW.sales_fulfillment_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a pick list carries no carrier, tracking, ship-to address or fulfilment; those belong to its shipment'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'shipment' AND NEW.stage = 'done' AND (
       NEW.carrier_id IS NULL OR NEW.carrier_service IS NULL OR NEW.sales_fulfillment_id IS NULL) THEN
    RAISE EXCEPTION 'a completed shipment names its carrier, service and sales fulfilment'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fulfillment_lines_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  line_document uuid;
  document_kind text;
  document_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    SELECT status INTO document_status
      FROM public.documents WHERE id = OLD.document_id AND org_id = OLD.org_id;
    IF document_status IS NULL OR document_status = 'draft'
       OR NOT EXISTS (SELECT 1 FROM public.document_lines WHERE id = OLD.line_id AND org_id = OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'fulfilment line detail of a % document cannot be deleted; void the document instead', document_status
      USING ERRCODE = 'object_not_in_prerequisite_state';
  END IF;
  SELECT d.kind, d.status INTO document_kind, document_status
    FROM public.documents d WHERE d.id = NEW.document_id AND d.org_id = NEW.org_id;
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.line_id, NEW.org_id, NEW.document_id, NEW.sales_order_line_id, NEW.pick_line_id, NEW.lot_id, NEW.serial_id)
       IS DISTINCT FROM
       (OLD.line_id, OLD.org_id, OLD.document_id, OLD.sales_order_line_id, OLD.pick_line_id, OLD.lot_id, OLD.serial_id) THEN
      RAISE EXCEPTION 'only the carton of a fulfilment line can change'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    IF NEW.carton IS DISTINCT FROM OLD.carton AND document_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'cartons can change only while the shipment is a draft'
        USING ERRCODE = 'object_not_in_prerequisite_state';
    END IF;
    RETURN NEW;
  END IF;
  SELECT document_id INTO line_document
    FROM public.document_lines WHERE id = NEW.line_id AND org_id = NEW.org_id;
  IF line_document IS DISTINCT FROM NEW.document_id THEN
    RAISE EXCEPTION 'fulfilment line detail must sit on the line''s own document'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'pick_list' AND (NEW.pick_line_id IS NOT NULL OR NEW.carton IS NOT NULL) THEN
    RAISE EXCEPTION 'a pick-list line names no pick line and no carton'
      USING ERRCODE = 'check_violation';
  END IF;
  IF document_kind = 'shipment' AND NEW.pick_line_id IS NULL THEN
    RAISE EXCEPTION 'a shipment line names the pick line it ships'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.funds_restriction_class_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_line_count bigint;
  v_code text;
begin
  if new.restriction_class is distinct from old.restriction_class then
    select count(*) into v_line_count
      from public.journal_lines l
      join public.journal_entries e on e.org_id = l.org_id and e.id = l.entry_id
     where l.org_id = old.org_id and l.extra_dims->>'fund' = old.id::text
       and e.status is distinct from 'draft';
    if v_line_count > 0 then
      select code into v_code from public.segment_values
       where org_id = old.org_id and id = old.id;
      raise exception 'fund % restriction class cannot change while % posted journal lines carry it',
        coalesce(v_code, old.id::text), v_line_count using errcode = '23514';
    end if;
  end if;
  return new;
end $function$

