CREATE OR REPLACE FUNCTION public.fx_revaluation_rate_evidence_clone_matches(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target record;
  original jsonb;
  expected jsonb;
  column_row record;
BEGIN
  IF NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
  SELECT org.sandbox_of, org.sandbox_seed, sandbox.masked
    INTO target
    FROM public.orgs org
    JOIN public.sandboxes sandbox
      ON sandbox.org_id = org.id AND sandbox.production_org_id = org.sandbox_of
    JOIN public.orgs production ON production.id = org.sandbox_of AND production.id <> org.id
   WHERE org.id = (candidate->>'org_id')::uuid
     AND org.env_kind = 'sandbox'
     AND org.sandbox_seed IS NOT NULL
     AND sandbox.status IN ('provisioning', 'refreshing');
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT to_jsonb(source)
    INTO original
    FROM public.fx_revaluation_rate_evidence source
   WHERE source.org_id = target.sandbox_of
     AND public.ob_rebase(source.id, target.sandbox_seed) = (candidate->>'id')::uuid;
  IF original IS NULL THEN RETURN false; END IF;

  expected := original;
  FOR column_row IN
    SELECT attribute.attname, attribute.atttypid
      FROM pg_catalog.pg_attribute attribute
     WHERE attribute.attrelid = 'public.fx_revaluation_rate_evidence'::regclass
       AND attribute.attnum > 0 AND NOT attribute.attisdropped
  LOOP
    IF column_row.attname = 'org_id' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb((candidate->>'org_id')::uuid));
    ELSIF column_row.atttypid = 'uuid'::regtype
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb(public.ob_rebase(
        (original->>column_row.attname)::uuid, target.sandbox_seed
      )));
    END IF;
    IF target.masked AND column_row.attname IN ('source', 'reason')
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb('REDACTED'::text));
    END IF;
  END LOOP;
  RETURN candidate = expected;
END
$function$

CREATE OR REPLACE FUNCTION public.fx_revaluation_rate_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
 period_row public.accounting_periods%ROWTYPE;
 predecessor public.fx_revaluation_rate_evidence%ROWTYPE;
 measured text;
BEGIN
 IF TG_OP = 'INSERT' AND public.fx_revaluation_rate_evidence_clone_matches(to_jsonb(NEW)) THEN
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
   RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Closing exchange rate evidence is append-only; record a successor version with its reason instead of deleting a quote'
   USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'UPDATE' THEN
  RAISE EXCEPTION 'Closing exchange rate evidence is append-only; record a successor version with its reason instead of replacing a quote'
   USING ERRCODE = '23514';
 END IF;
 -- One writer at a time per exact position, so root creation and successor
 -- appends cannot interleave into two current versions.
 PERFORM pg_advisory_xact_lock(hashtextextended(
  'fx-revaluation-evidence:' || NEW.org_id::text || ':' || NEW.book_id::text || ':'
  || NEW.subsidiary_id::text || ':' || NEW.period_id::text || ':' || NEW.account_id::text || ':'
  || NEW.transaction_currency, 0));
 IF NOT EXISTS (SELECT 1 FROM public.accounting_books
   WHERE org_id = NEW.org_id AND id = NEW.book_id AND is_active AND posts_gl) THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an active posting book in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.subsidiaries
   WHERE org_id = NEW.org_id AND id = NEW.subsidiary_id AND is_active AND NOT is_elimination) THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an active legal entity in this organization'
   USING ERRCODE = '23514';
 END IF;
 SELECT * INTO period_row FROM public.accounting_periods
  WHERE org_id = NEW.org_id AND id = NEW.period_id;
 IF period_row.id IS NULL THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an assigned accounting period in this organization'
   USING ERRCODE = '23514';
 END IF;
 IF period_row.ends_on IS DISTINCT FROM NEW.rate_date THEN
  RAISE EXCEPTION 'The closing exchange rate must be dated %, the final day of its assigned period', period_row.ends_on
   USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.accounts a
   WHERE a.org_id = NEW.org_id AND a.id = NEW.account_id AND a.is_active AND NOT a.is_summary
     AND (CASE
       WHEN a.monetary IS FALSE THEN false
       WHEN a.monetary IS TRUE THEN a.type NOT IN
         ('income', 'income_other', 'cogs', 'expense', 'expense_other', 'expense_deferred', 'equity')
       ELSE a.type IN ('asset_bank', 'asset_receivable', 'liability_payable')
     END)) THEN
  RAISE EXCEPTION 'Closing exchange rate evidence requires an active monetary account in this organization'
   USING ERRCODE = '23514';
 END IF;
 measured := public.accounting_book_currency(NEW.org_id, NEW.book_id, NEW.subsidiary_id);
 IF measured IS NULL OR measured IS DISTINCT FROM NEW.measurement_currency THEN
  RAISE EXCEPTION 'The closing exchange rate must convert into %, the currency this book measures the legal entity in', measured
   USING ERRCODE = '23514';
 END IF;
 IF NEW.supersedes_id IS NULL THEN
  IF EXISTS (SELECT 1 FROM public.fx_revaluation_rate_evidence
    WHERE org_id = NEW.org_id AND book_id = NEW.book_id AND subsidiary_id = NEW.subsidiary_id
      AND period_id = NEW.period_id AND account_id = NEW.account_id
      AND transaction_currency = NEW.transaction_currency) THEN
   RAISE EXCEPTION 'This closing position already has recorded rate evidence; append a successor to its current version'
    USING ERRCODE = '23514';
  END IF;
 ELSE
  SELECT * INTO predecessor FROM public.fx_revaluation_rate_evidence
   WHERE org_id = NEW.org_id AND id = NEW.supersedes_id;
  IF predecessor.id IS NULL
     OR (predecessor.book_id, predecessor.subsidiary_id, predecessor.period_id, predecessor.account_id,
         predecessor.transaction_currency)
        IS DISTINCT FROM
        (NEW.book_id, NEW.subsidiary_id, NEW.period_id, NEW.account_id,
         NEW.transaction_currency)
     OR NEW.version <> predecessor.version + 1 THEN
   RAISE EXCEPTION 'A successor closing rate must keep its predecessor''s exact book, legal entity, period, account and transaction currency, and add one version'
    USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.fx_revaluation_rate_evidence
    WHERE org_id = NEW.org_id AND supersedes_id = NEW.supersedes_id) THEN
   RAISE EXCEPTION 'This closing rate version already has a successor; append to the current version instead'
    USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.gl_audit_number_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE policy gl_audit_number_policies%ROWTYPE; period accounting_periods%ROWTYPE; expected_scope text;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM period_posting_fence(NEW.org_id,NEW.period_id,NEW.book_id);
 IF NOT public.period_module_blocks_write(NEW.org_id,NEW.period_id,NEW.book_id,NEW.subsidiary_id,'gl',false) THEN
  RAISE EXCEPTION 'GL audit numbers require a closed entity accounting period.' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT period FROM accounting_periods WHERE org_id=NEW.org_id AND id=NEW.period_id;
 SELECT * INTO policy FROM gl_audit_number_policies WHERE org_id=NEW.org_id AND subsidiary_id=NEW.subsidiary_id AND effective_from<=period.ends_on ORDER BY effective_from DESC LIMIT 1;
 expected_scope:=CASE policy.reset_rule WHEN 'period' THEN 'period:'||period.id WHEN 'fiscal_year' THEN 'year:'||period.fiscal_calendar_id||':'||period.fiscal_year ELSE 'all' END;
 IF policy.id IS NULL OR NEW.policy_id<>policy.id OR NEW.scope_key<>expected_scope OR
    NEW.audit_number<>policy.prefix||'-'||replace(expected_scope,':','-')||'-'||lpad(NEW.ordinal::text,greatest(6,length(NEW.ordinal::text)),'0') THEN
  RAISE EXCEPTION 'GL audit numbers retain the effective entity policy and canonical sequence format.' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('gl-audit:'||NEW.org_id||':'||NEW.book_id||':'||NEW.subsidiary_id||':'||expected_scope,0));
 IF NOT EXISTS(SELECT 1 FROM journal_entries e JOIN journal_lines l ON l.org_id=e.org_id AND l.entry_id=e.id
   WHERE e.org_id=NEW.org_id AND e.id=NEW.entry_id AND e.book_id=NEW.book_id AND e.status IN('posted','reversed')
    AND l.subsidiary_id=NEW.subsidiary_id AND coalesce(l.period_id,e.period_id)=NEW.period_id) THEN
  RAISE EXCEPTION 'An audit number must identify a posted entry in its own entity, period and book.' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM gl_audit_number_assignments WHERE org_id=NEW.org_id AND book_id=NEW.book_id
  AND subsidiary_id=NEW.subsidiary_id AND scope_key=NEW.scope_key AND ordinal>=NEW.ordinal) OR
  NEW.ordinal<>(SELECT coalesce(max(ordinal),0)+1 FROM gl_audit_number_assignments WHERE org_id=NEW.org_id AND book_id=NEW.book_id
   AND subsidiary_id=NEW.subsidiary_id AND scope_key=NEW.scope_key) THEN
  RAISE EXCEPTION 'GL audit numbers are allocated without gaps in their native sequence.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.gl_audit_number_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 IF EXISTS(SELECT 1 FROM gl_audit_number_assignments n JOIN accounting_periods p ON p.org_id=n.org_id AND p.id=n.period_id
   WHERE n.org_id=NEW.org_id AND n.subsidiary_id=NEW.subsidiary_id AND p.ends_on>=NEW.effective_from) THEN
  RAISE EXCEPTION 'Audit numbering policy changes start after the latest numbered period.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.goods_tax_registration_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF EXISTS(SELECT 1 FROM public.document_goods_tax_snapshots proof JOIN public.document_lines l ON l.org_id=proof.org_id AND l.id=proof.document_line_id
    JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
    WHERE proof.org_id=OLD.org_id AND proof.registration_ids ? OLD.id::text AND d.status IN('posted','voided')
      AND (TG_OP='DELETE' OR (NEW.org_id,NEW.subsidiary_id,NEW.jurisdiction_id,NEW.registration_number,NEW.effective_from)
        IS DISTINCT FROM (OLD.org_id,OLD.subsidiary_id,OLD.jurisdiction_id,OLD.registration_number,OLD.effective_from)
        OR (NEW.effective_to IS NOT NULL AND NEW.effective_to<d.document_date)))
    THEN RAISE EXCEPTION 'used tax registration identity and coverage are immutable; close its future effective window and create a new dated registration'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.goods_tax_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE document_state text; owner uuid; current_org uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'goods tax calculation evidence is immutable; replace the draft line through its native document editor'; END IF;
  IF TG_OP='DELETE' THEN
    SELECT d.status INTO document_state FROM public.document_lines l JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
      WHERE l.org_id=OLD.org_id AND l.id=OLD.document_line_id;
    IF document_state='draft' OR document_state IS NULL THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'posted goods tax evidence cannot be deleted; use the controlled document reversal workflow';
  END IF;
  SELECT d.status,d.subsidiary_id,d.org_id INTO document_state,owner,current_org FROM public.document_lines l JOIN public.documents d ON d.org_id=l.org_id AND d.id=l.document_id
    WHERE l.org_id=NEW.org_id AND l.id=NEW.document_line_id;
  IF document_state<>'draft' OR owner IS DISTINCT FROM NEW.subsidiary_id OR current_org IS DISTINCT FROM NEW.org_id
    OR NEW.snapshot->>'subsidiaryId'<>NEW.subsidiary_id::text OR NEW.snapshot->>'fingerprint'<>NEW.fingerprint
    OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.registration_ids) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM public.tax_registrations r
      WHERE r.org_id=NEW.org_id AND r.id=wanted.id::uuid AND r.subsidiary_id=NEW.subsidiary_id))
    THEN RAISE EXCEPTION 'native goods tax evidence must bind to its draft invoice, selling entity and registrations'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.handling_unit_content_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Assigned carton contents cannot be deleted'; END IF;
 IF OLD.confirmed_at IS NOT NULL OR (to_jsonb(NEW)-ARRAY['confirmed_at','confirmed_by','confirmation_task_id']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['confirmed_at','confirmed_by','confirmation_task_id']) OR NEW.confirmed_at IS NULL THEN
  RAISE EXCEPTION 'Carton content identity and confirmed history are immutable'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.handling_unit_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Handling-unit history cannot be deleted'; END IF;
 IF (to_jsonb(NEW)-ARRAY['status','current_stock_location_id','content_version','updated_at','updated_by']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['status','current_stock_location_id','content_version','updated_at','updated_by']) THEN
  RAISE EXCEPTION 'Handling-unit shipment, warehouse and identity are immutable'; END IF;
 IF OLD.status IN('shipped','voided') OR NOT((OLD.status=NEW.status) OR (OLD.status='open' AND NEW.status='packed')
   OR (OLD.status='packed' AND NEW.status='shipped') OR (OLD.status IN('open','packed') AND NEW.status='voided')) THEN RAISE EXCEPTION 'Handling-unit lifecycle transition is not supported'; END IF;
 IF NEW.current_stock_location_id IS DISTINCT FROM OLD.current_stock_location_id AND (OLD.status<>'packed' OR NEW.status<>'packed') THEN
  RAISE EXCEPTION 'Only a packed handling unit can move as one identity'; END IF;
 IF NEW.content_version<OLD.content_version OR NEW.content_version>OLD.content_version+1 THEN
  RAISE EXCEPTION 'Handling-unit content version must advance one confirmed operation at a time'; END IF;
 IF EXISTS(SELECT 1 FROM public.shipment_labels label WHERE label.org_id=OLD.org_id AND label.handling_unit_id=OLD.id AND label.status='purchased')
   AND (NEW.content_version,NEW.current_stock_location_id) IS DISTINCT FROM (OLD.content_version,OLD.current_stock_location_id) THEN
  RAISE EXCEPTION 'Void the handling-unit label before changing its physical contents or position'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.historical_translation_completeness()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 DECLARE target uuid; basis public.historical_translation_contributions%ROWTYPE; count_layers integer; total numeric; proposal public.financial_changes%ROWTYPE;
 BEGIN
  IF TG_TABLE_NAME='historical_translation_contributions' THEN target:=NEW.id; ELSE target:=NEW.basis_id; END IF;
  SELECT * INTO STRICT basis FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND id=target;
  SELECT count(*),sum(amount) INTO count_layers,total FROM public.historical_translation_layers WHERE org_id=NEW.org_id AND basis_id=target;
  SELECT * INTO STRICT proposal FROM public.financial_changes WHERE org_id=NEW.org_id AND id=basis.change_id;
  IF count_layers<>jsonb_array_length(basis.evidence->'instruction'->'layers') OR total IS DISTINCT FROM basis.source_amount
    OR proposal.status<>'applied' OR proposal.result IS DISTINCT FROM jsonb_build_object('basisId',basis.id::text) THEN
   RAISE EXCEPTION 'Record every exact approved historical layer and complete its native approval atomically.';
  END IF;
  RETURN NULL;
 END $function$

CREATE OR REPLACE FUNCTION public.historical_translation_file_retention()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 DECLARE source_org uuid; source_version uuid;
 BEGIN
  IF TG_TABLE_NAME='file_versions' THEN
   source_version:=OLD.id;
   SELECT org_id INTO source_org FROM public.files WHERE id=OLD.file_id;
  ELSE
   source_version:=OLD.version_id;
   SELECT file.org_id INTO source_org FROM public.file_versions version JOIN public.files file ON file.id=version.file_id
    WHERE version.id=source_version;
  END IF;
  IF EXISTS(SELECT 1 FROM public.historical_translation_layers WHERE org_id=source_org AND source_version_id=source_version) THEN
   IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(source_org)) THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'Retain the immutable Cabinet version and original bytes supporting approved historical contribution evidence.';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END $function$

CREATE OR REPLACE FUNCTION public.historical_translation_layer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 DECLARE basis public.historical_translation_contributions%ROWTYPE; original public.historical_translation_layers%ROWTYPE;
   original_basis public.historical_translation_contributions%ROWTYPE; approved_layer jsonb; retained jsonb; used numeric;
 BEGIN
  IF TG_OP<>'INSERT' THEN
   IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
   RAISE EXCEPTION 'Approved historical translation layers are immutable.';
  END IF;
  SELECT * INTO STRICT basis FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND id=NEW.basis_id FOR SHARE;
  approved_layer:=basis.evidence->'instruction'->'layers'->(NEW.layer_number-1);
  retained:=basis.evidence->'retainedSources'->(NEW.layer_number-1);
  IF approved_layer IS DISTINCT FROM jsonb_build_object('amount',NEW.amount::text,'rate',NEW.rate::text,
     'historicalDate',NEW.historical_date::text,'provenance',NEW.provenance,'originalLayerId',NEW.original_layer_id::text,
     'source',jsonb_build_object('fileId',NEW.source_file_id::text,'versionId',NEW.source_version_id::text,'contentHash',NEW.source_hash))
    OR retained IS DISTINCT FROM jsonb_build_object('fileId',NEW.source_file_id::text,'versionId',NEW.source_version_id::text,
      'contentHash',NEW.source_hash,'versionNumber',NEW.source_version_number)
    OR basis.evidence->'translatedAmounts'->>(NEW.layer_number-1) IS DISTINCT FROM NEW.translated_amount::text
    OR sign(NEW.amount)<>sign(basis.source_amount) OR NEW.historical_date>basis.posting_date
    OR (basis.measurement_currency=basis.presentation_currency AND NEW.rate<>1)
    OR (basis.kind='correction') IS DISTINCT FROM (NEW.original_layer_id IS NOT NULL)
    OR NOT EXISTS(SELECT 1 FROM public.files file JOIN public.file_versions version ON version.file_id=file.id
      WHERE file.org_id=NEW.org_id AND file.id=NEW.source_file_id AND version.id=NEW.source_version_id
        AND version.content_hash=NEW.source_hash AND version.version_number=NEW.source_version_number) THEN
   RAISE EXCEPTION 'Every historical layer must retain its exact approved amount, genuine rate, date, provenance and tenant-owned Cabinet version.';
  END IF;
  IF NEW.original_layer_id IS NOT NULL THEN
   SELECT * INTO STRICT original FROM public.historical_translation_layers WHERE org_id=NEW.org_id AND id=NEW.original_layer_id FOR UPDATE;
   SELECT * INTO STRICT original_basis FROM public.historical_translation_contributions WHERE org_id=NEW.org_id AND id=original.basis_id FOR SHARE;
   IF original_basis.posting_date>basis.posting_date OR original_basis.book_id<>basis.book_id OR original_basis.account_id<>basis.account_id
     OR original_basis.subsidiary_id<>basis.subsidiary_id OR original_basis.measurement_currency<>basis.measurement_currency
     OR original_basis.presentation_currency<>basis.presentation_currency OR original.rate<>NEW.rate
     OR original.historical_date<>NEW.historical_date OR original.provenance<>NEW.provenance
     OR original.source_file_id<>NEW.source_file_id OR original.source_version_id<>NEW.source_version_id
     OR original.source_hash<>NEW.source_hash OR original.source_version_number<>NEW.source_version_number
     OR sign(original.amount)=sign(NEW.amount)
     OR NOT EXISTS(SELECT 1 FROM public.financial_changes WHERE org_id=NEW.org_id AND id=original_basis.change_id AND status='applied')
     OR EXISTS(SELECT 1 FROM public.journal_entries entry WHERE entry.org_id=NEW.org_id AND entry.id=basis.source_entry_id
       AND entry.reverses_entry_id IS NOT NULL AND entry.reverses_entry_id<>original_basis.source_entry_id) THEN
    RAISE EXCEPTION 'A correction must explicitly bind an applied parent layer and preserve its genuine rate and source.';
   END IF;
   SELECT coalesce(sum(abs(amount)),0) INTO used FROM public.historical_translation_layers WHERE org_id=NEW.org_id AND original_layer_id=original.id;
   IF used+abs(NEW.amount)>abs(original.amount) THEN RAISE EXCEPTION 'Correction exceeds the remaining applied parent layer.'; END IF;
   IF basis.evidence->'originalLayerStates'->(NEW.layer_number-1) IS DISTINCT FROM
      jsonb_build_object('originalLayerId',original.id::text,'consumedAmount',used::numeric(19,4)::text)
     OR NEW.translated_amount IS DISTINCT FROM NEW.amount*NEW.rate THEN
    RAISE EXCEPTION 'Correction must retain its reviewed original allocation state and exact unrounded original-rate product.';
   END IF;
  ELSIF NEW.translated_amount IS DISTINCT FROM NEW.amount*NEW.rate THEN
   RAISE EXCEPTION 'A contribution layer must retain its exact genuine-rate translated amount.';
  END IF;
  RETURN NEW;
 END $function$

CREATE OR REPLACE FUNCTION public.historical_translation_source_retention()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 BEGIN
  IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF TG_TABLE_NAME='journal_lines' THEN
   IF EXISTS(SELECT 1 FROM public.historical_translation_contributions WHERE org_id=OLD.org_id AND source_line_id=OLD.id)
    AND (TG_OP='DELETE' OR ROW(NEW.org_id,NEW.id,NEW.entry_id,NEW.account_id,NEW.subsidiary_id,NEW.amount,NEW.currency,NEW.txn_amount,NEW.fx_rate)
     IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.entry_id,OLD.account_id,OLD.subsidiary_id,OLD.amount,OLD.currency,OLD.txn_amount,OLD.fx_rate)) THEN
    RAISE EXCEPTION 'Retain the physical historical contribution source; correct it through governed reversals.';
   END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM public.historical_translation_contributions WHERE org_id=OLD.org_id AND source_entry_id=OLD.id)
    AND (TG_OP='DELETE' OR ROW(NEW.org_id,NEW.id,NEW.book_id,NEW.posting_date,NEW.origin,NEW.reverses_entry_id)
     IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.book_id,OLD.posting_date,OLD.origin,OLD.reverses_entry_id)
     OR NEW.status NOT IN('posted','reversed')) THEN
    RAISE EXCEPTION 'Retain the posted historical contribution entry identity and measurement date.';
   END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
 END $function$

CREATE OR REPLACE FUNCTION public.holiday_clone_json(value jsonb, kind text, seed uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb:=value; paths jsonb; item jsonb; path text[]; entries jsonb;
BEGIN
 IF value IS NULL THEN RETURN NULL; END IF;
 CASE kind
 WHEN 'evidence' THEN paths:='[["instruction","employeePartyId"],["source","fileId"],["source","versionId"]]'::jsonb;
 WHEN 'payload' THEN
  paths:='[["employmentId"]]'::jsonb;
  IF result ? 'evidence' THEN result:=jsonb_set(result,'{evidence}',public.holiday_clone_json(result->'evidence','evidence',seed)); END IF;
  IF jsonb_typeof(result->'requiredSubsidiaryIds')='array' THEN
   SELECT coalesce(jsonb_agg(to_jsonb(public.ob_rebase(a.value::uuid,seed)::text) ORDER BY a.ordinal),'[]'::jsonb)
    INTO entries FROM jsonb_array_elements_text(result->'requiredSubsidiaryIds') WITH ORDINALITY AS a(value,ordinal);
   result:=jsonb_set(result,'{requiredSubsidiaryIds}',entries);
  END IF;
 WHEN 'before_state' THEN
  paths:='[["employment","id"],["employment","worker_party_id"],["employment","employer_subsidiary_id"],["profile","id"],["profile","employment_id"],["profile","pay_schedule_id"]]'::jsonb;
  IF jsonb_typeof(result->'datedEmployment')='array' THEN
   SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(a.value->'id')='string'
    THEN jsonb_set(a.value,'{id}',to_jsonb(public.ob_rebase((a.value->>'id')::uuid,seed)::text)) ELSE a.value END ORDER BY a.ordinal),'[]'::jsonb)
    INTO entries FROM jsonb_array_elements(result->'datedEmployment') WITH ORDINALITY AS a(value,ordinal);
   result:=jsonb_set(result,'{datedEmployment}',entries);
  END IF;
 WHEN 'result' THEN paths:='[["obligationId"]]'::jsonb;
 WHEN 'source_snapshot' THEN
  paths:='[["wage","source","id"],["wage","fx","id"]]'::jsonb;
  IF result ? 'obligation' THEN result:=jsonb_set(result,'{obligation}',public.holiday_clone_json(result->'obligation','evidence',seed)); END IF;
 ELSE RAISE EXCEPTION 'Unknown holiday evidence projection.';
 END CASE;
 FOR item IN SELECT jsonb_array_elements(paths) LOOP
  SELECT array_agg(v ORDER BY ord) INTO path FROM jsonb_array_elements_text(item) WITH ORDINALITY a(v,ord);
  IF jsonb_typeof(result #> path)='string' THEN
   result:=jsonb_set(result,path,to_jsonb(public.ob_rebase((result #>> path)::uuid,seed)::text));
  END IF;
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.holiday_historical_clone_matches(relation regclass, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target record; original jsonb; expected jsonb; column_row record; projection text;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN (
  'public.payroll_holiday_obligations'::regclass,'public.payroll_holiday_occurrences'::regclass,
  'public.pay_run_holiday_allocations'::regclass) THEN RETURN false; END IF;
 SELECT o.id,o.sandbox_of,o.sandbox_seed,s.masked INTO target FROM public.orgs o
 JOIN public.sandboxes s ON s.org_id=o.id AND s.production_org_id=o.sandbox_of
 WHERE o.id=(candidate->>'org_id')::uuid AND o.env_kind='sandbox' AND o.sandbox_seed IS NOT NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 IF relation='public.payroll_holiday_occurrences'::regclass THEN
  SELECT to_jsonb(source) INTO original FROM public.payroll_holiday_occurrences source
   WHERE source.org_id=target.sandbox_of AND public.ob_rebase(source.obligation_id,target.sandbox_seed)=(candidate->>'obligation_id')::uuid
    AND source.holiday_date=(candidate->>'holiday_date')::date;
 ELSE
  EXECUTE format('SELECT to_jsonb(source) FROM %s source WHERE source.org_id=$1 AND public.ob_rebase(source.id,$2)=$3',relation)
   INTO original USING target.sandbox_of,target.sandbox_seed,(candidate->>'id')::uuid;
 END IF;
 IF original IS NULL THEN RETURN false; END IF;
 expected:=original;
 FOR column_row IN SELECT attname,atttypid,attnotnull FROM pg_catalog.pg_attribute
  WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF column_row.attname='org_id' THEN expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(target.id));
  ELSIF column_row.atttypid='uuid'::regtype AND jsonb_typeof(original->column_row.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(public.ob_rebase((original->>column_row.attname)::uuid,target.sandbox_seed)));
  ELSIF (relation='public.payroll_holiday_obligations'::regclass AND column_row.attname='evidence') OR
        (relation='public.pay_run_holiday_allocations'::regclass AND column_row.attname='source_snapshot') THEN
   projection:=column_row.attname;
   expected:=jsonb_set(expected,ARRAY[projection],public.holiday_clone_json(original->projection,projection,target.sandbox_seed));
   IF target.masked AND EXISTS(SELECT 1 FROM public.masking_policies p WHERE p.org_id=target.sandbox_of
    AND p.table_name=CASE relation WHEN 'public.payroll_holiday_obligations'::regclass THEN 'payroll_holiday_obligations' ELSE 'pay_run_holiday_allocations' END
    AND p.column_name=projection AND p.is_active AND p.transform='null_out') THEN
    expected:=jsonb_set(expected,ARRAY[projection],'{}'::jsonb);
   END IF;
  END IF;
 END LOOP;
 RETURN candidate=expected;
END $function$

