  END IF;
  IF NEW.status = 'pending' AND OLD.status = 'voided' THEN
    RAISE EXCEPTION
      'HRM benefit payroll input % is voided and stays voided — regenerate the month for a revised amount.',
      OLD.id;
  END IF;
