 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE session_row public.hrm_training_sessions; course_row public.hrm_training_courses;
 author_person uuid; decision_person uuid; employer uuid; qualification_status text; passed boolean;
 validity integer; evidence_required boolean; qualification_issued date;
BEGIN
 IF TG_OP='DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Training history cannot be deleted; retire a course, cancel a session or void a participant outcome with a reason.';
 END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='hrm_training_feedback' THEN RAISE EXCEPTION 'Training feedback is immutable; append a corrected feedback entry with the previous entry as its predecessor.'; END IF;
  IF ROW(NEW.id,NEW.org_id,NEW.created_at,NEW.created_by,NEW.request_hash) IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.created_at,OLD.created_by,OLD.request_hash) THEN
   RAISE EXCEPTION 'Training ownership and creation evidence are immutable; create a successor record.';
  END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Training revision changed; reload the record before saving.'; END IF;
 END IF;
 IF TG_TABLE_NAME='hrm_training_courses' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'draft' THEN RAISE EXCEPTION 'Create a course draft before submission through Flows.'; END IF;
   SELECT party_id INTO author_person FROM public.users WHERE org_id=NEW.org_id AND id=NEW.created_by AND is_active;
   IF author_person IS NULL OR author_person IS DISTINCT FROM NEW.author_party_id THEN RAISE EXCEPTION 'Course authorship needs a native person identity; link the author to their person record before creating the course.'; END IF;
   IF NEW.qualification_type_id IS NOT NULL THEN
    SELECT validity_months,requires_evidence INTO validity,evidence_required FROM public.hrm_qualification_types WHERE org_id=NEW.org_id AND id=NEW.qualification_type_id AND is_active FOR SHARE;
    IF NOT FOUND OR NEW.qualification_validity_months IS DISTINCT FROM validity OR NEW.qualification_requires_evidence IS DISTINCT FROM evidence_required THEN
     RAISE EXCEPTION 'Qualification policy changed; reload the native qualification type before creating the course draft.';
    END IF;
   END IF;
  ELSE
   IF (to_jsonb(NEW)-ARRAY['status','decided_by','decided_at','revision','reason','updated_at','updated_by']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['status','decided_by','decided_at','revision','reason','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'A course definition is immutable; create an effective-dated successor version.';
   END IF;
   IF NOT ((OLD.status='draft' AND NEW.status IN ('approved','cancelled')) OR (OLD.status='approved' AND NEW.status='retired')) THEN
    RAISE EXCEPTION 'This course transition is unavailable; reload the course and choose an action for its current state.';
   END IF;
   IF NEW.status='approved' THEN
    IF NEW.decided_by IS DISTINCT FROM NEW.updated_by OR NOT public.flow_command_authorized(NEW.org_id,'training_course',NEW.id,NEW.decided_by,
      public.flow_command_record_fingerprint(to_jsonb(OLD)),jsonb_build_object('expectedRevision',OLD.revision,'reason',NEW.reason)) THEN
     RAISE EXCEPTION 'Release this course revision through its complete native tenant Flow submission.';
    END IF;
   ELSIF ROW(NEW.decided_by,NEW.decided_at) IS DISTINCT FROM ROW(OLD.decided_by,OLD.decided_at) THEN
    RAISE EXCEPTION 'Course approval evidence is immutable; create a successor course version.';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME='hrm_training_sessions' THEN
  SELECT * INTO course_row FROM public.hrm_training_courses WHERE org_id=NEW.org_id AND id=NEW.course_id FOR SHARE;
  IF NOT FOUND OR course_row.subsidiary_id<>NEW.subsidiary_id THEN RAISE EXCEPTION 'The course is unavailable for this employer; select an approved course in this employer scope.'; END IF;
  IF NEW.starts_on<>(NEW.starts_at AT TIME ZONE NEW.time_zone)::date OR NEW.ends_on<>(NEW.ends_at AT TIME ZONE NEW.time_zone)::date THEN
   RAISE EXCEPTION 'Session dates do not match their time zone; choose exact session times again.';
  END IF;
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'draft' OR course_row.status<>'approved' OR NEW.starts_on<course_row.effective_from OR (course_row.effective_to IS NOT NULL AND NEW.ends_on>course_row.effective_to) THEN
    RAISE EXCEPTION 'Create a draft session within an approved course effective window; select a matching course version.';
   END IF;
  ELSE
   IF (to_jsonb(NEW)-ARRAY['status','revision','reason','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','reason','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'Session delivery details are immutable; cancel it and create a corrected session.';
   END IF;
   IF NOT ((OLD.status='draft' AND NEW.status IN ('scheduled','cancelled')) OR (OLD.status='scheduled' AND NEW.status IN ('in_progress','cancelled')) OR (OLD.status='in_progress' AND NEW.status IN ('completed','cancelled'))) THEN
    RAISE EXCEPTION 'This session transition is unavailable; reload the session and choose an action for its current state.';
   END IF;
   IF NEW.status='scheduled' AND course_row.status<>'approved' THEN RAISE EXCEPTION 'The course is retired; cancel this draft and create a session for an approved successor.'; END IF;
   IF NEW.status='in_progress' AND NEW.starts_at>now() THEN RAISE EXCEPTION 'The scheduled session has not started; start it at or after its recorded start time.'; END IF;
   IF NEW.status='completed' AND NEW.ends_at>now() THEN RAISE EXCEPTION 'The session has not ended; record final delivery after its recorded end time.'; END IF;
   IF NEW.status='completed' AND EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.id AND status IN ('invited','accepted')) THEN
    RAISE EXCEPTION 'Participant outcomes are unfinished; record each result or decline/cancel the invitation before closing the session.';
   END IF;
   IF NEW.status='completed' AND NOT EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.id AND status IN ('completed','failed')) THEN
    RAISE EXCEPTION 'This session has no completed participant results; record a delivered result or cancel the unused session.';
   END IF;
   IF NEW.status='cancelled' AND EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.id AND status NOT IN ('declined','cancelled','voided')) THEN
    RAISE EXCEPTION 'Session participants still have active invitations or outcomes; cancel invitations and void outcomes before cancelling the session.';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME='hrm_training_participants' THEN
  SELECT * INTO session_row FROM public.hrm_training_sessions WHERE org_id=NEW.org_id AND id=NEW.session_id FOR UPDATE;
  IF NOT FOUND OR session_row.subsidiary_id<>NEW.subsidiary_id THEN RAISE EXCEPTION 'The training session is unavailable; choose a visible employer session.'; END IF;
  SELECT employer_subsidiary_id INTO employer FROM public.worker_employments WHERE org_id=NEW.org_id AND id=NEW.employment_id FOR UPDATE;
  IF TG_OP='INSERT' OR NEW.status IN ('completed','failed') THEN
   IF employer IS DISTINCT FROM NEW.subsidiary_id THEN RAISE EXCEPTION 'The participant employment belongs to a different employer; choose an employment for the session employer.'; END IF;
   IF NOT EXISTS(SELECT employment_id FROM public.worker_employment_versions WHERE org_id=NEW.org_id AND employment_id=NEW.employment_id AND recorded_until IS NULL AND status IN ('active','on_leave')
    GROUP BY employment_id HAVING range_agg(daterange(effective_from,effective_to,'[)')) @> daterange(session_row.starts_on,session_row.ends_on,'[]')) THEN
    RAISE EXCEPTION 'Employment history does not cover the session; choose a covered session or record verified employment history through its native workflow.';
   END IF;
  END IF;
  SELECT * INTO course_row FROM public.hrm_training_courses WHERE org_id=NEW.org_id AND id=session_row.course_id FOR SHARE;
  IF NEW.qualification_type_id IS DISTINCT FROM course_row.qualification_type_id THEN RAISE EXCEPTION 'Participant qualification policy differs from its approved course; reload the course definition.'; END IF;
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'invited' OR session_row.status<>'scheduled' THEN RAISE EXCEPTION 'Schedule the session before inviting participants.'; END IF;
   IF (SELECT count(*) FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND session_id=NEW.session_id AND status NOT IN ('declined','cancelled'))>=session_row.capacity THEN
    RAISE EXCEPTION 'The training session is full; choose another session or decline an unused invitation.';
   END IF;
  ELSE
   IF ROW(NEW.session_id,NEW.employment_id,NEW.subsidiary_id,NEW.qualification_type_id) IS DISTINCT FROM ROW(OLD.session_id,OLD.employment_id,OLD.subsidiary_id,OLD.qualification_type_id) THEN
    RAISE EXCEPTION 'Participant ownership is immutable; create a new invitation for the correct employment.';
   END IF;
   IF NOT ((OLD.status='invited' AND NEW.status IN ('accepted','declined','cancelled','completed','failed')) OR
    (OLD.status='accepted' AND NEW.status IN ('declined','cancelled','completed','failed')) OR
    (OLD.status IN ('completed','failed') AND NEW.status='voided')) THEN
    RAISE EXCEPTION 'This participant transition is unavailable; reload the participant and choose an action for its current state.';
   END IF;
   IF NEW.status IN ('completed','failed') THEN
    IF session_row.status<>'in_progress' THEN RAISE EXCEPTION 'Start the training session before recording participant results.'; END IF;
    IF session_row.ends_at>now() THEN RAISE EXCEPTION 'The session has not ended; record final attendance and assessment after its end time.'; END IF;
    IF NEW.attendance_seconds IS NULL OR NEW.attendance_seconds>session_row.duration_seconds OR
     ((course_row.passing_score IS NOT NULL)<>(NEW.score IS NOT NULL)) THEN RAISE EXCEPTION 'Attendance or assessment is incomplete; record valid attendance and the declared assessment score.'; END IF;
    passed := NEW.attendance_seconds::bigint*100>=session_row.duration_seconds::bigint*course_row.minimum_attendance_percent
     AND (course_row.passing_score IS NULL OR NEW.score>=course_row.passing_score);
    IF (NEW.status='completed')<>passed THEN RAISE EXCEPTION 'The outcome differs from the approved course thresholds; calculate the result from recorded attendance and assessment.'; END IF;
    IF NEW.status='completed' AND course_row.qualification_type_id IS NOT NULL AND NEW.qualification_id IS NULL THEN
     RAISE EXCEPTION 'A passing course outcome needs its native qualification evidence; record or link the matching qualification before completing.';
    END IF;
    IF NEW.qualification_id IS NOT NULL THEN
     SELECT issued_on,status INTO qualification_issued,qualification_status FROM public.hrm_worker_qualifications WHERE org_id=NEW.org_id AND id=NEW.qualification_id;
     IF qualification_issued IS DISTINCT FROM session_row.ends_on OR qualification_status='revoked' THEN RAISE EXCEPTION 'The qualification does not match the completion date or is revoked; choose matching non-revoked qualification evidence.'; END IF;
    END IF;
   ELSIF NEW.status='voided' THEN
    IF (to_jsonb(NEW)-ARRAY['status','revision','reason','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','reason','updated_at','updated_by']) THEN
     RAISE EXCEPTION 'Training results are immutable; void the unchanged outcome with a reason.';
    END IF;
    IF NEW.qualification_created THEN
     SELECT status INTO qualification_status FROM public.hrm_worker_qualifications WHERE org_id=NEW.org_id AND id=NEW.qualification_id;
     IF qualification_status IS DISTINCT FROM 'revoked' THEN RAISE EXCEPTION 'The training-issued qualification is still active; revoke it with the same correction reason before voiding the outcome.'; END IF;
    END IF;
   ELSE
    IF ROW(NEW.attendance_seconds,NEW.score,NEW.evidence_file_id,NEW.notes,NEW.qualification_id,NEW.qualification_created,NEW.completion_hash) IS DISTINCT FROM
       ROW(OLD.attendance_seconds,OLD.score,OLD.evidence_file_id,OLD.notes,OLD.qualification_id,OLD.qualification_created,OLD.completion_hash) THEN
     RAISE EXCEPTION 'Invitation changes cannot rewrite a training result; use the participant completion action.';
    END IF;
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME='hrm_training_feedback' THEN
  IF NOT EXISTS(SELECT 1 FROM public.hrm_training_participants WHERE org_id=NEW.org_id AND id=NEW.participant_id AND status IN ('completed','failed')) THEN
   RAISE EXCEPTION 'Training feedback needs a completed participant result; complete the participant before recording feedback.';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.initialize_payroll_compensation_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE previous_org text;
BEGIN
 -- Organization creation is authorized by its own policy; initialize the new
 -- tenant's derived counter under that tenant without weakening table isolation.
 previous_org := current_setting('app.current_org',true);
 PERFORM set_config('app.current_org',NEW.id::text,true);
 INSERT INTO public.payroll_compensation_configuration(org_id) VALUES(NEW.id);
 PERFORM set_config('app.current_org',coalesce(previous_org,''),true);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.intercompany_fulfillment_charge_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
     OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'cross-subsidiary fulfillment charges are append-only; a return records the reversal';
END;
$function$

CREATE OR REPLACE FUNCTION public.intercompany_fund_transfer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany fund transfers are retained; reverse a transfer instead';
  END IF;
  IF NOT (OLD.status = 'posted' AND NEW.status = 'reversed')
     OR to_jsonb(NEW) - 'status' - 'reversal_entry_id' - 'reversal_date' - 'reverse_reason' - 'reversed_by' - 'reversed_at' - 'updated_at'
        IS DISTINCT FROM
        to_jsonb(OLD) - 'status' - 'reversal_entry_id' - 'reversal_date' - 'reverse_reason' - 'reversed_by' - 'reversed_at' - 'updated_at' THEN
    RAISE EXCEPTION 'a posted intercompany fund transfer changes only by reversal';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.intercompany_netting_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany netting lines are retained with their run';
  END IF;
  SELECT r.status INTO v_status FROM public.intercompany_netting_runs r
   WHERE r.org_id = NEW.org_id AND r.id = NEW.run_id;
  IF TG_OP = 'INSERT' THEN
    IF v_status IS DISTINCT FROM 'proposed' THEN
      RAISE EXCEPTION 'intercompany netting lines are written with the run proposal';
    END IF;
    RETURN NEW;
  END IF;
  -- Settlement evidence is stamped once, while the run posts.
  IF to_jsonb(NEW) - 'settlement_entry_id' - 'settlement_line_id' - 'application_id'
     IS DISTINCT FROM to_jsonb(OLD) - 'settlement_entry_id' - 'settlement_line_id' - 'application_id'
     OR (OLD.settlement_entry_id IS NOT NULL AND NEW.settlement_entry_id IS DISTINCT FROM OLD.settlement_entry_id)
     OR (OLD.settlement_line_id IS NOT NULL AND NEW.settlement_line_id IS DISTINCT FROM OLD.settlement_line_id)
     OR (OLD.application_id IS NOT NULL AND NEW.application_id IS DISTINCT FROM OLD.application_id)
     OR v_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'intercompany netting lines are immutable; settlement evidence is recorded once when the run posts';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.intercompany_netting_run_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany netting runs are retained; cancel a proposal or reverse a posted run instead';
  END IF;
  IF (NEW.org_id, NEW.run_number, NEW.as_of_date, NEW.book_id, NEW.period_id, NEW.subsidiary_ids,
      NEW.settle_cash, NEW.bank_accounts, NEW.computation, NEW.fingerprint, NEW.reason,
      NEW.idempotency_key, NEW.proposed_by, NEW.proposed_at)
     IS DISTINCT FROM
     (OLD.org_id, OLD.run_number, OLD.as_of_date, OLD.book_id, OLD.period_id, OLD.subsidiary_ids,
      OLD.settle_cash, OLD.bank_accounts, OLD.computation, OLD.fingerprint, OLD.reason,
      OLD.idempotency_key, OLD.proposed_by, OLD.proposed_at) THEN
    RAISE EXCEPTION 'an intercompany netting run keeps the terms it was proposed with; cancel it and propose a new run';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'proposed' AND NEW.status IN ('pending_approval', 'approved', 'cancelled'))
    OR (OLD.status = 'pending_approval' AND NEW.status IN ('approved', 'rejected', 'cancelled'))
    OR (OLD.status = 'approved' AND NEW.status IN ('posted', 'cancelled'))
    OR (OLD.status = 'posted' AND NEW.status = 'reversed')
  ) THEN
    RAISE EXCEPTION 'an intercompany netting run cannot move from % to %', OLD.status, NEW.status;
  END IF;
  IF OLD.status IN ('posted', 'reversed', 'cancelled', 'rejected') AND NEW.status = OLD.status
     AND to_jsonb(NEW) - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'updated_at' THEN
    RAISE EXCEPTION 'a % intercompany netting run is closed history', OLD.status;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.intercompany_pair_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_from_type text;
  v_to_type text;
  v_control record;
begin
  if new.from_subsidiary_id = new.to_subsidiary_id then
    raise exception 'intercompany subsidiaries must be different' using errcode = '23514';
  end if;
  if (select count(*) from subsidiaries s
       where s.org_id = new.org_id and s.id in (new.from_subsidiary_id, new.to_subsidiary_id)
         and s.is_active and not s.is_elimination) <> 2 then
    raise exception 'intercompany subsidiaries are invalid' using errcode = '23514';
  end if;
  select type into v_from_type from accounts
   where id = new.due_from_account_id and org_id = new.org_id
     and is_active and not is_summary and eliminate;
  select type into v_to_type from accounts
   where id = new.due_to_account_id and org_id = new.org_id
     and is_active and not is_summary and eliminate;
  if v_from_type is null or v_from_type not like 'asset\_%' escape '\' then
    raise exception 'due-from account must be an eliminable asset' using errcode = '23514';
  end if;
  if v_to_type is null or v_to_type not like 'liability\_%' escape '\' then
    raise exception 'due-to account must be an eliminable liability' using errcode = '23514';
  end if;
  -- Intercompany receivable and payable control accounts are optional; when
  -- set they must be eliminated posting accounts of the control type.
  for v_control in
    select account_id, expected, label from (values
      (new.from_receivable_account_id, 'asset_receivable', 'from-side intercompany receivable'),
      (new.to_receivable_account_id, 'asset_receivable', 'to-side intercompany receivable'),
      (new.from_payable_account_id, 'liability_payable', 'from-side intercompany payable'),
      (new.to_payable_account_id, 'liability_payable', 'to-side intercompany payable')
    ) as controls(account_id, expected, label)
    where account_id is not null
  loop
    if not exists (
      select 1 from accounts a
       where a.org_id = new.org_id and a.id = v_control.account_id
         and a.is_active and not a.is_summary and a.eliminate and a.type = v_control.expected
    ) then
      raise exception '% account must be an active eliminated % account', v_control.label, v_control.expected
        using errcode = '23514';
    end if;
  end loop;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.intercompany_representing_party_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_root uuid;
  v_role record;
BEGIN
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF NOT NEW.is_active THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.subsidiary_id AND s.is_active AND NOT s.is_elimination
  ) THEN
    RAISE EXCEPTION 'a representing party must represent an active operating subsidiary' USING errcode = '23514';
  END IF;
  SELECT s.id INTO v_root FROM public.subsidiaries s WHERE s.org_id = NEW.org_id AND s.parent_id IS NULL;
  FOR v_role IN
    SELECT party_id, role FROM (VALUES (NEW.customer_party_id, 'customer'), (NEW.vendor_party_id, 'vendor')) AS r(party_id, role)
     WHERE party_id IS NOT NULL
  LOOP
    IF v_role.role = 'customer' AND NOT EXISTS (
      SELECT 1 FROM public.customer_roles r JOIN public.parties p ON p.org_id = r.org_id AND p.id = r.party_id
       WHERE r.org_id = NEW.org_id AND r.party_id = v_role.party_id AND r.is_active AND p.is_active
    ) THEN
      RAISE EXCEPTION 'the representing customer must be an active customer' USING errcode = '23514';
    END IF;
    IF v_role.role = 'vendor' AND NOT EXISTS (
      SELECT 1 FROM public.vendor_roles r JOIN public.parties p ON p.org_id = r.org_id AND p.id = r.party_id
       WHERE r.org_id = NEW.org_id AND r.party_id = v_role.party_id AND r.is_active AND p.is_active
    ) THEN
      RAISE EXCEPTION 'the representing vendor must be an active vendor' USING errcode = '23514';
    END IF;
    -- A subsidiary cannot trade with itself: the representing party must not
    -- transact with the entity it represents.
    IF EXISTS (
      SELECT 1 FROM public.parties p
       WHERE p.org_id = NEW.org_id AND p.id = v_role.party_id
         AND coalesce(p.subsidiary_id, v_root) = NEW.subsidiary_id
    ) OR EXISTS (
      SELECT 1 FROM public.party_subsidiaries ps
       WHERE ps.org_id = NEW.org_id AND ps.party_id = v_role.party_id AND ps.subsidiary_id = NEW.subsidiary_id
    ) THEN
      RAISE EXCEPTION 'the representing % transacts with the subsidiary it represents; a subsidiary cannot be its own customer or vendor', v_role.role
        USING errcode = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.intercompany_transaction_pair_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_root uuid;
  v_seller record;
  v_buyer record;
  v_seller_kind text;
  v_buyer_kind text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'intercompany pairing history is retained; unlink the pair instead';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NOT (OLD.status = 'linked' AND NEW.status = 'unlinked')
       OR to_jsonb(NEW) - 'status' - 'unlinked_by' - 'unlinked_at' - 'unlink_reason' - 'updated_at'
          IS DISTINCT FROM
          to_jsonb(OLD) - 'status' - 'unlinked_by' - 'unlinked_at' - 'unlink_reason' - 'updated_at' THEN
      RAISE EXCEPTION 'an intercompany pair changes only by unlinking it';
    END IF;
    RETURN NEW;
  END IF;
  IF public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  v_seller_kind := CASE NEW.pair_kind WHEN 'order' THEN 'sales_order' WHEN 'invoice' THEN 'customer_invoice' ELSE 'customer_credit' END;
  v_buyer_kind := CASE NEW.pair_kind WHEN 'order' THEN 'purchase_order' WHEN 'invoice' THEN 'vendor_bill' ELSE 'vendor_credit' END;
  SELECT s.id INTO v_root FROM public.subsidiaries s WHERE s.org_id = NEW.org_id AND s.parent_id IS NULL;
  SELECT d.kind, coalesce(d.subsidiary_id, v_root) AS subsidiary_id, d.status INTO v_seller
    FROM public.documents d WHERE d.org_id = NEW.org_id AND d.id = NEW.seller_document_id;
  SELECT d.kind, coalesce(d.subsidiary_id, v_root) AS subsidiary_id, d.status INTO v_buyer
    FROM public.documents d WHERE d.org_id = NEW.org_id AND d.id = NEW.buyer_document_id;
  IF v_seller.kind IS DISTINCT FROM v_seller_kind OR v_buyer.kind IS DISTINCT FROM v_buyer_kind THEN
    RAISE EXCEPTION 'an intercompany % pair links a % to a %', NEW.pair_kind, v_seller_kind, v_buyer_kind
      USING errcode = '23514';
  END IF;
  IF v_seller.subsidiary_id IS DISTINCT FROM NEW.seller_subsidiary_id
     OR v_buyer.subsidiary_id IS DISTINCT FROM NEW.buyer_subsidiary_id THEN
    RAISE EXCEPTION 'intercompany pair documents must belong to the pair''s selling and buying subsidiaries'
      USING errcode = '23514';
  END IF;
  IF v_seller.status = 'voided' OR v_buyer.status = 'voided' THEN
    RAISE EXCEPTION 'a voided document cannot be paired' USING errcode = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.intercompany_transfer_pricing_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_last date;
  v_account record;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
       OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    IF EXISTS (SELECT 1 FROM public.intercompany_fulfillment_charges c WHERE c.org_id = OLD.org_id AND c.policy_id = OLD.id) THEN
      RAISE EXCEPTION 'this transfer pricing policy has priced charges; end its window instead of deleting it';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    SELECT max(c.charge_date) INTO v_last FROM public.intercompany_fulfillment_charges c
     WHERE c.org_id = OLD.org_id AND c.policy_id = OLD.id;
    IF v_last IS NOT NULL THEN
      IF (NEW.code, NEW.seller_subsidiary_id, NEW.buyer_subsidiary_id, NEW.method, NEW.price_level_id,
          NEW.markup_percent, NEW.revenue_account_id, NEW.cost_account_id, NEW.effective_from)
         IS DISTINCT FROM
         (OLD.code, OLD.seller_subsidiary_id, OLD.buyer_subsidiary_id, OLD.method, OLD.price_level_id,
          OLD.markup_percent, OLD.revenue_account_id, OLD.cost_account_id, OLD.effective_from) THEN
        RAISE EXCEPTION 'this transfer pricing policy has priced charges and keeps its terms; end it and create a new dated policy';
      END IF;
      IF NEW.effective_to IS NOT NULL AND NEW.effective_to < v_last THEN
        RAISE EXCEPTION 'this transfer pricing policy priced a charge on %; its window cannot end before that date', v_last;
      END IF;
    END IF;
    -- Ending or deactivating a policy never re-validates terms it already holds.
    IF (NEW.seller_subsidiary_id, NEW.buyer_subsidiary_id, NEW.revenue_account_id, NEW.cost_account_id)
       IS NOT DISTINCT FROM
       (OLD.seller_subsidiary_id, OLD.buyer_subsidiary_id, OLD.revenue_account_id, OLD.cost_account_id) THEN
      RETURN NEW;
    END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.seller_subsidiary_id AND s.is_active AND NOT s.is_elimination
  ) OR (NEW.buyer_subsidiary_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.buyer_subsidiary_id AND s.is_active AND NOT s.is_elimination
  )) THEN
    RAISE EXCEPTION 'transfer pricing applies between active operating subsidiaries' USING errcode = '23514';
  END IF;
  FOR v_account IN
    SELECT account_id, types, label FROM (VALUES
      (NEW.revenue_account_id, ARRAY['income', 'income_other'], 'intercompany revenue'),
      (NEW.cost_account_id, ARRAY['cogs', 'expense', 'expense_other'], 'intercompany cost')
    ) AS a(account_id, types, label)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.accounts a
       WHERE a.org_id = NEW.org_id AND a.id = v_account.account_id
         AND a.is_active AND NOT a.is_summary AND a.eliminate AND a.type = ANY (v_account.types)
    ) THEN
      RAISE EXCEPTION 'the % account must be an active eliminated posting account of type %', v_account.label, array_to_string(v_account.types, ', ')
        USING errcode = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.internal_billing_rules_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on' THEN
   IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
   RAISE EXCEPTION 'Internal billing rule history is preserved; deactivate the version instead of deleting it in Setup → Internal billing'
   USING ERRCODE = '23514';
 END IF;
 IF ROW(OLD.org_id, OLD.id, OLD.code, OLD.method, OLD.debit_account_id, OLD.credit_account_id,
        OLD.effective_from, OLD.created_at, OLD.created_by)
    IS DISTINCT FROM
    ROW(NEW.org_id, NEW.id, NEW.code, NEW.method, NEW.debit_account_id, NEW.credit_account_id,
        NEW.effective_from, NEW.created_at, NEW.created_by) THEN
   RAISE EXCEPTION 'Internal billing rule versions keep their accounting treatment; close the window and add a new version in Setup → Internal billing'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inv_move_fill_subsidiary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT je.subsidiary_id INTO owner
    FROM public.journal_entries je
   WHERE je.id = NEW.journal_entry_id
     AND je.org_id = NEW.org_id;
  IF owner IS NULL THEN
    SELECT s.id INTO owner
      FROM public.subsidiaries s
     WHERE s.org_id = NEW.org_id
       AND s.parent_id IS NULL
     ORDER BY s.created_at
     LIMIT 1;
  END IF;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'inventory movement requires a legal-entity owner',
      DETAIL = 'No subsidiary could be derived from the movement''s journal entry or organization root.',
      HINT = 'Supply subsidiary_id explicitly or configure a root subsidiary first.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inv_move_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' then
    if old.status = 'posted' and not openbooks_sandbox_wipe_allowed(old.org_id) then
      raise exception 'inventory movement % is posted and cannot be deleted', old.id;
    end if;
    return old;
  end if;
  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'inventory movement % is posted and immutable', old.id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.inv_provisional_fill_subsidiary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.issue_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'inventory provisional cost requires the legal entity of its issue movement',
      DETAIL = 'The issue movement was not found, so ownership could not be derived.',
      HINT = 'Create the issue movement before recording its provisional cost.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.inventory_count_policy_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF OLD.effective_from<=current_date THEN
  IF TG_OP='UPDATE' AND (NEW.org_id,NEW.subsidiary_id,NEW.abc_class,NEW.interval_days,NEW.variance_tolerance,NEW.effective_from)
   IS NOT DISTINCT FROM (OLD.org_id,OLD.subsidiary_id,OLD.abc_class,OLD.interval_days,OLD.variance_tolerance,OLD.effective_from)
   AND NEW.effective_to IS NOT NULL AND NEW.effective_to>=current_date AND (OLD.effective_to IS NULL OR NEW.effective_to<=OLD.effective_to) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Effective cycle-count policies are immutable; close the policy and add a successor';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_inspection_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Inspection evidence is immutable.' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'pending' OR NEW.disposition IS NOT NULL OR NEW.inspected_by IS NOT NULL THEN RAISE EXCEPTION 'Inspections start pending.' USING ERRCODE='23514'; END IF;
  IF NEW.operation_id IS NOT NULL THEN
   PERFORM id FROM mfg_wo_operations WHERE org_id=NEW.org_id AND id=NEW.operation_id FOR UPDATE;
   SELECT coalesce(max(inspection_sequence),0)+1 INTO NEW.inspection_sequence FROM inventory_inspections WHERE org_id=NEW.org_id AND operation_id=NEW.operation_id;
  END IF;
  IF NEW.receipt_movement_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inventory_movements source WHERE source.org_id=NEW.org_id AND source.id=NEW.receipt_movement_id AND source.status='posted' AND source.reverses_movement_id IS NULL AND source.quantity=NEW.quantity AND source.quantity>0 AND source.item_id=NEW.item_id AND source.subsidiary_id=NEW.subsidiary_id AND source.stock_location_id=NEW.stock_location_id AND source.lot_id IS NOT DISTINCT FROM NEW.lot_id AND source.serial_id IS NOT DISTINCT FROM NEW.serial_id) THEN RAISE EXCEPTION 'Receipt inspection must bind its exact native stock receipt.' USING ERRCODE='23514'; END IF;
  IF NEW.operation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mfg_wo_operations operation JOIN mfg_work_orders work ON work.org_id=operation.org_id AND work.id=operation.work_order_id WHERE operation.org_id=NEW.org_id AND operation.id=NEW.operation_id AND work.id=NEW.work_order_id AND work.subsidiary_id=NEW.subsidiary_id AND work.produced_item_id=NEW.item_id AND operation.status IN('pending','running','paused') AND operation.inspection_plan_snapshot=NEW.plan_snapshot) THEN RAISE EXCEPTION 'Operation inspection must bind its released work and frozen plan.' USING ERRCODE='23514'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['quantity','lot_id','serial_id','status','measurements','reason','inspected_at','inspected_by','disposition','disposition_reason','disposition_result','disposed_at','disposed_by','rework_work_order_id','rework_operation_id','rework_completed_at','scrap_movement_id','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['quantity','lot_id','serial_id','status','measurements','reason','inspected_at','inspected_by','disposition','disposition_reason','disposition_result','disposed_at','disposed_by','rework_work_order_id','rework_operation_id','rework_completed_at','scrap_movement_id','updated_at','updated_by']) THEN RAISE EXCEPTION 'Inspection subject and plan are immutable.' USING ERRCODE='23514'; END IF;
  IF OLD.status<>'pending' AND (NEW.quantity,NEW.lot_id,NEW.serial_id,NEW.status,NEW.measurements,NEW.reason,NEW.inspected_at,NEW.inspected_by) IS DISTINCT FROM (OLD.quantity,OLD.lot_id,OLD.serial_id,OLD.status,OLD.measurements,OLD.reason,OLD.inspected_at,OLD.inspected_by) THEN RAISE EXCEPTION 'Recorded inspection results are immutable.' USING ERRCODE='23514'; END IF;
  IF NEW.receipt_movement_id IS NOT NULL AND NEW.quantity IS DISTINCT FROM OLD.quantity THEN RAISE EXCEPTION 'Receipt inspection quantity retains its stock source.' USING ERRCODE='23514'; END IF;
  IF OLD.status='pending' AND NEW.status NOT IN ('pending','pass','fail') THEN RAISE EXCEPTION 'Invalid inspection result.' USING ERRCODE='23514'; END IF;
  IF OLD.disposition IS NOT NULL AND (NEW.disposition,NEW.disposition_reason,NEW.disposition_result,NEW.disposed_at,NEW.disposed_by,NEW.rework_work_order_id,NEW.rework_operation_id,NEW.scrap_movement_id) IS DISTINCT FROM (OLD.disposition,OLD.disposition_reason,OLD.disposition_result,OLD.disposed_at,OLD.disposed_by,OLD.rework_work_order_id,OLD.rework_operation_id,OLD.scrap_movement_id) THEN RAISE EXCEPTION 'Recorded quality dispositions are immutable.' USING ERRCODE='23514'; END IF;
  IF OLD.scrap_movement_id IS NOT NULL AND NEW.scrap_movement_id IS DISTINCT FROM OLD.scrap_movement_id THEN RAISE EXCEPTION 'Quality scrap has one immutable inventory effect.' USING ERRCODE='23514'; END IF;
  IF OLD.rework_completed_at IS NOT NULL AND NEW.rework_completed_at IS DISTINCT FROM OLD.rework_completed_at THEN RAISE EXCEPTION 'Rework completion is immutable.' USING ERRCODE='23514'; END IF;
 END IF;
 IF (NEW.disposition='rework' AND NEW.receipt_movement_id IS NOT NULL) IS DISTINCT FROM (NEW.rework_work_order_id IS NOT NULL) AND NEW.disposition IS NOT NULL THEN RAISE EXCEPTION 'Receipt rework requires its native repair order.' USING ERRCODE='23514'; END IF;
 IF NEW.rework_work_order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mfg_work_orders repair WHERE repair.org_id=NEW.org_id AND repair.id=NEW.rework_work_order_id AND repair.receipt_rework_inspection_id=NEW.id) THEN RAISE EXCEPTION 'The repair order must retain this exact failed inspection.' USING ERRCODE='23514'; END IF;
 IF NEW.operation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mfg_wo_operations WHERE org_id=NEW.org_id AND id=NEW.operation_id AND work_order_id=NEW.work_order_id AND NEW.quantity<=quantity_planned) THEN RAISE EXCEPTION 'Operation inspection cannot exceed its released planned quantity.' USING ERRCODE='23514'; END IF;
 IF NEW.status<>'pending' THEN
  IF NEW.operation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM item_inventory_profiles profile WHERE profile.org_id=NEW.org_id AND profile.item_id=NEW.item_id AND
    ((profile.tracking='none' AND NEW.lot_id IS NULL AND NEW.serial_id IS NULL) OR (profile.tracking='lot' AND NEW.lot_id IS NOT NULL AND NEW.serial_id IS NULL) OR (profile.tracking='serial' AND NEW.serial_id IS NOT NULL AND NEW.lot_id IS NULL AND NEW.quantity=1) OR (profile.tracking='lot_serial' AND NEW.lot_id IS NOT NULL AND NEW.serial_id IS NOT NULL AND NEW.quantity=1))) THEN
    RAISE EXCEPTION 'Operation inspection identifiers must match the produced item tracking policy.' USING ERRCODE='23514';
  END IF;
  IF jsonb_typeof(NEW.measurements)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.measurements) supplied(key) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.plan_snapshot->'measures') measure WHERE measure->>'key'=supplied.key))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.plan_snapshot->'measures') measure WHERE (measure->>'required')::boolean AND coalesce(NEW.measurements->> (measure->>'key'),'')='')
   OR EXISTS(SELECT 1 FROM jsonb_each_text(NEW.measurements) reading WHERE reading.value<>'' AND reading.value !~ '^-?[0-9]+([.][0-9]{1,4})?$')
   OR EXISTS(SELECT 1 FROM jsonb_each_text(NEW.measurements) reading WHERE CASE WHEN reading.value ~ '^-?[0-9]+([.][0-9]{1,4})?$' THEN abs(reading.value::numeric)>999999999999999.9999 ELSE false END) THEN
   RAISE EXCEPTION 'Inspection result requires exact known measurements and every required reading.' USING ERRCODE='23514';
  END IF;
  IF NEW.status='pass' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.plan_snapshot->'measures') measure WHERE nullif(NEW.measurements->>(measure->>'key'),'') IS NOT NULL
    AND ((measure->>'minimum' IS NOT NULL AND (NEW.measurements->>(measure->>'key'))::numeric<(measure->>'minimum')::numeric)
      OR (measure->>'maximum' IS NOT NULL AND (NEW.measurements->>(measure->>'key'))::numeric>(measure->>'maximum')::numeric))) THEN
    RAISE EXCEPTION 'An out-of-range frozen measurement cannot pass inspection.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.lot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN RAISE EXCEPTION 'Inspection lot must identify its item.' USING ERRCODE='23514'; END IF;
 IF NEW.serial_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM serials WHERE org_id=NEW.org_id AND id=NEW.serial_id AND item_id=NEW.item_id AND (NEW.lot_id IS NULL OR lot_id IS NOT DISTINCT FROM NEW.lot_id)) THEN RAISE EXCEPTION 'Inspection serial must identify its item and lot.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_inspection_plan_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Inspection plans retain their history; end the effective window.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Inspection plan changes require the next revision.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND (EXISTS(SELECT 1 FROM inventory_inspections WHERE org_id=OLD.org_id AND plan_id=OLD.id) OR EXISTS(SELECT 1 FROM mfg_wo_operations WHERE org_id=OLD.org_id AND inspection_plan_snapshot->>'id'=OLD.id::text)) AND
  ((to_jsonb(NEW)-ARRAY['effective_to','revision','reason','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['effective_to','revision','reason','updated_at','updated_by']) OR NEW.effective_to IS NULL OR NEW.effective_to<(SELECT (now() AT TIME ZONE coalesce(nullif(settings->>'timeZone',''),'UTC'))::date FROM orgs WHERE id=NEW.org_id) OR (OLD.effective_to IS NOT NULL AND NEW.effective_to>OLD.effective_to)) THEN
  RAISE EXCEPTION 'Used inspection plans retain their content and historical effective window.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtext('inventory.inspection.plan'),hashtext(NEW.org_id::text||NEW.item_id::text||NEW.point||coalesce(NEW.operation_sequence::text,'')));
 IF EXISTS(SELECT 1 FROM inventory_inspection_plans WHERE org_id=NEW.org_id AND item_id=NEW.item_id AND point=NEW.point AND operation_sequence IS NOT DISTINCT FROM NEW.operation_sequence AND id<>NEW.id AND daterange(effective_from,effective_to,'[)') && daterange(NEW.effective_from,NEW.effective_to,'[)')) THEN
  RAISE EXCEPTION 'Inspection plan effective windows overlap.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_inspection_scrap_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE inspection inventory_inspections;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO inspection FROM inventory_inspections WHERE org_id=NEW.org_id AND id=NEW.id;
 IF inspection.scrap_movement_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inventory_movements movement JOIN journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id WHERE movement.org_id=inspection.org_id AND movement.id=inspection.scrap_movement_id AND movement.status='posted' AND entry.status='posted' AND movement.item_id=inspection.item_id AND movement.subsidiary_id=inspection.subsidiary_id AND movement.stock_location_id=inspection.stock_location_id AND movement.lot_id IS NOT DISTINCT FROM inspection.lot_id AND movement.serial_id IS NOT DISTINCT FROM inspection.serial_id AND movement.quantity=-inspection.quantity AND inspection.disposition='scrap' AND inspection.disposition_result->>'movementId'=movement.id::text) THEN RAISE EXCEPTION 'Quality scrap requires its exact posted inventory disposition.' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_lot_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'lot identity and recall evidence cannot be deleted';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.item_id IS DISTINCT FROM OLD.item_id
     OR NEW.lot_number IS DISTINCT FROM OLD.lot_number
     OR (OLD.expires_on IS NOT NULL
         AND NEW.expires_on IS DISTINCT FROM OLD.expires_on) THEN
    RAISE EXCEPTION 'lot identity is immutable; only a missing expiry may be completed';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.inventory_movement_tracking_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE tracking_mode text; serial_lot uuid;
BEGIN
 SELECT tracking INTO tracking_mode FROM public.item_inventory_profiles WHERE org_id=NEW.org_id AND item_id=NEW.item_id;
 IF tracking_mode IS NULL OR tracking_mode NOT IN('none','lot','serial','lot_serial') THEN
  RAISE EXCEPTION 'Inventory movement requires a supported tenant-owned profile' USING ERRCODE='23514';
 END IF;
 IF tracking_mode='none' AND num_nonnulls(NEW.lot_id,NEW.serial_id)>0 THEN
  RAISE EXCEPTION 'Untracked stock cannot carry identifiers' USING ERRCODE='23514';
 END IF;
 IF tracking_mode IN('lot','lot_serial') THEN
  IF NEW.lot_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN
   RAISE EXCEPTION 'Lot tracking requires the item and tenant lot' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.lot_id IS NOT NULL THEN RAISE EXCEPTION 'This profile does not track lots' USING ERRCODE='23514'; END IF;
 IF tracking_mode IN('serial','lot_serial') THEN
  IF NEW.serial_id IS NULL OR abs(NEW.quantity)<>1 OR NOT EXISTS(SELECT 1 FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id AND item_id=NEW.item_id) THEN
   RAISE EXCEPTION 'Serial tracking requires exactly one unit of the item and tenant serial' USING ERRCODE='23514';
  END IF;
  SELECT lot_id INTO serial_lot FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id;
  IF tracking_mode='lot_serial' AND serial_lot IS DISTINCT FROM NEW.lot_id THEN
   RAISE EXCEPTION 'Serial must belong to the movement lot' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.serial_id IS NOT NULL THEN RAISE EXCEPTION 'This profile does not track serials' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_owned_position_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE ownership text;
BEGIN
 SELECT inventory_ownership INTO ownership FROM public.stock_locations WHERE org_id=NEW.org_id AND id=NEW.stock_location_id FOR SHARE;
 IF ownership IS DISTINCT FROM 'owned' THEN RAISE EXCEPTION 'Valued inventory requires an owned stock location; use the custody command'; END IF;
 IF NEW.serial_id IS NOT NULL THEN
  PERFORM id FROM public.serials WHERE org_id=NEW.org_id AND id=NEW.serial_id FOR UPDATE;
  IF NEW.quantity>0 AND EXISTS(SELECT 1 FROM public.consignment_stock WHERE org_id=NEW.org_id AND serial_id=NEW.serial_id AND remaining_quantity>0) THEN
   RAISE EXCEPTION 'Serial is externally owned; take ownership through the custody command';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_provisional_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'inventory provisional evidence is immutable';
end $function$

CREATE OR REPLACE FUNCTION public.inventory_serial_count_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF OLD.serial_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.stock_counts count
   WHERE count.org_id=OLD.org_id AND count.id=OLD.stock_count_id AND count.status='posted') THEN
  RAISE EXCEPTION 'Posted serial count observations and movement associations are immutable; record a new count';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_serial_count_marker_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.current_missing_count_movement_id IS NULL OR public.inventory_serial_count_clone_marker_matches(NEW) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Serial missing-count identity requires its native posted transition';
 END IF;
 IF NEW.current_missing_count_movement_id IS DISTINCT FROM OLD.current_missing_count_movement_id
    AND NEW.current_missing_count_movement_id IS NOT NULL THEN
  IF OLD.status='in_stock' AND NEW.status='shipped' AND NEW.current_stock_location_id IS NULL AND EXISTS(
   SELECT 1 FROM public.stock_count_lines line JOIN public.inventory_movements movement
    ON movement.org_id=line.org_id AND movement.id=line.adjustment_movement_id
   WHERE line.org_id=NEW.org_id AND movement.id=NEW.current_missing_count_movement_id
    AND movement.kind='issue' AND movement.serial_id=NEW.id AND movement.item_id=NEW.item_id
    AND movement.stock_location_id=OLD.current_stock_location_id AND movement.lot_id IS NOT DISTINCT FROM NEW.lot_id
    AND public.inventory_serial_count_line_matches(NEW.org_id,line.id,movement.id,false)
  ) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Serial missing-count identity must match its exact current count issue';
 END IF;
 IF (NEW.status,NEW.current_stock_location_id) IS DISTINCT FROM (OLD.status,OLD.current_stock_location_id) THEN
  NEW.current_missing_count_movement_id=NULL;
  RETURN NEW;
 END IF;
 IF NEW.current_missing_count_movement_id IS DISTINCT FROM OLD.current_missing_count_movement_id THEN
  RAISE EXCEPTION 'Serial missing-count identity cannot change without its lifecycle transition';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_serial_count_posted_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF NEW.serial_id IS NULL OR NEW.adjustment_movement_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.inventory_serial_count_clone_line_matches(NEW) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Copied serial count evidence must retain its exact registered source identity and observations';
 END IF;
 IF TG_OP='UPDATE' AND NEW.adjustment_movement_id IS NOT DISTINCT FROM OLD.adjustment_movement_id THEN RETURN NEW; END IF;
 IF NOT public.inventory_serial_count_line_matches(NEW.org_id,NEW.id,NEW.adjustment_movement_id,true)
    OR NOT EXISTS(
     SELECT 1 FROM public.stock_count_lines line
     JOIN public.stock_counts count ON count.org_id=line.org_id AND count.id=line.stock_count_id
     JOIN public.inventory_movements movement ON movement.org_id=line.org_id AND movement.id=line.adjustment_movement_id
     JOIN public.audit_log audit ON audit.org_id=count.org_id AND audit.table_name='stock_counts' AND audit.row_id=count.id
     WHERE line.org_id=NEW.org_id AND line.id=NEW.id AND movement.id=NEW.adjustment_movement_id
      AND movement.xmin=(pg_current_xact_id()::text::bigint % 4294967296)::text::xid
      AND audit.xmin=movement.xmin AND audit.changes->>'operation'='post'
      AND audit.actor_id=movement.created_by AND audit.changes->'review'->>'postedBy'=audit.actor_id::text
      AND count.updated_by=audit.actor_id AND count.review_released
      AND audit.changes->'review'->'policy'=count.submission_policy
      AND EXISTS(SELECT 1 FROM public.flow_submissions submission
        WHERE submission.org_id=count.org_id AND submission.subject_kind='stock_count'
          AND submission.subject_id=count.id AND submission.policy=count.submission_policy
          AND ((submission.policy->>'kind'='ungated' AND
            public.flow_ungated_submission_authorized(submission.org_id,submission.subject_kind,submission.subject_id,count.submitted_by))
           OR (submission.policy->>'kind'='gated' AND
            public.flow_submission_approved(submission.org_id,submission.subject_kind,submission.subject_id,submission.id))))
    ) THEN
  RAISE EXCEPTION 'Serial count adjustment requires exact posted count, journal and tenant Flow review evidence';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.inventory_serial_lot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND OLD.lot_id IS NOT NULL AND NEW.lot_id IS DISTINCT FROM OLD.lot_id THEN RAISE EXCEPTION 'Serial lot identity is immutable'; END IF;
 IF NEW.lot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.lots WHERE org_id=NEW.org_id AND id=NEW.lot_id AND item_id=NEW.item_id) THEN RAISE EXCEPTION 'Serial lot must belong to its item and tenant'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.item_pricing_customer_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customer_roles role
     WHERE role.org_id = NEW.org_id AND role.party_id = NEW.customer_id AND role.is_active
  ) THEN
    RAISE EXCEPTION 'Pricing customer % is not an active customer in this organization', NEW.customer_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.item_pricing_level_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.price_level_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.price_levels level
     WHERE level.org_id = NEW.org_id AND level.id = NEW.price_level_id AND level.is_active
  ) THEN
    RAISE EXCEPTION 'Pricing level % is not active in this organization', NEW.price_level_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.je_check_adjustment_period_date()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_window record;
begin
  if TG_OP = 'INSERT' and public.openbooks_clone_authority() then return new; end if;
  select * into v_window
    from public.accounting_period_posting_window(new.org_id, new.period_id);
  if not found or not v_window.is_adjustment then return new; end if;
  if new.posting_date < v_window.window_start or new.posting_date > v_window.window_end then
    raise exception 'journal entry % is dated % but names adjustment period "%" of fiscal year % (% to %): an adjustment period takes postings dated inside its own fiscal year; date the entry inside that year or post it to the period that covers %',
      new.entry_number, new.posting_date, v_window.period_name, v_window.fiscal_year,
      v_window.window_start, v_window.window_end, new.posting_date
      using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.je_check_posted_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ 
declare
  v_sum numeric(19,4);
  v_bad record;
  v_fx record;
begin
  if new.status <> 'posted' then return null; end if;
  select coalesce(sum(amount), 0) into v_sum
    from journal_lines
   where entry_id = new.id and org_id = new.org_id;
  if v_sum <> 0 then
    raise exception 'posted journal entry % does not balance (sum = %)', new.id, v_sum
      using errcode = '23514';
  end if;
  select subsidiary_id, sum(amount) as total into v_bad
    from journal_lines
   where entry_id = new.id and org_id = new.org_id
   group by subsidiary_id having sum(amount) <> 0 limit 1;
  if found then
    raise exception 'posted journal entry % does not balance for subsidiary % (sum = %)',
      new.id, v_bad.subsidiary_id, v_bad.total using errcode = '23514';
  end if;
  select subsidiary_id,
         sum(case when is_currency_adjustment then 0 else abs(amount - round(txn_amount * fx_rate, 4)) end) as deviation,
         count(*) as lines,
         count(*) * 0.00005 as bound into v_fx
    from journal_lines
   where entry_id = new.id and org_id = new.org_id
   group by subsidiary_id
  having sum(case when is_currency_adjustment then 0 else abs(amount - round(txn_amount * fx_rate, 4)) end) > count(*) * 0.00005 limit 1;
  -- This gate fires when an entry becomes posted: inserted posted, or a
  -- draft flipped to posted. Either way nothing has been posted yet.
  if found then
    raise exception 'posted journal entry % exceeds the per-entry FX rounding bound for subsidiary % (stored deviation % over % lines, bound %): nothing was posted; correct the line exchange rates or functional amounts so each amount is its transaction amount times its rate, then post again',
      new.id, v_fx.subsidiary_id, v_fx.deviation, v_fx.lines, v_fx.bound using errcode = '23514';
  end if;
  if (select count(*) from journal_lines where entry_id = new.id and org_id = new.org_id) < 2
     and not exists(select 1 from journal_lines l join accounts a on a.org_id=l.org_id and a.id=l.account_id where l.org_id=new.org_id and l.entry_id=new.id and a.type='statistical' and l.quantity<>0 and length(btrim(l.unit))>0) then
    raise exception 'posted journal entry % must contain at least two lines', new.id
      using errcode = '23514';
  end if;
  return null;
end  $function$

CREATE OR REPLACE FUNCTION public.je_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_module text;
  v_replay_auth uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'journal entry % is % and cannot be deleted', old.id, old.status;
    end if;
    perform period_posting_fence(old.org_id, old.period_id, old.book_id);
    if period_module_blocks_write(old.org_id, old.period_id, old.book_id,
         nullif(to_jsonb(old)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
      raise exception 'period is closed for GL posting';
    end if;
    return old;
  end if;

  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'journal entry % is posted and immutable: corrections append a reversal through the ledger API instead of editing history', old.id;
  end if;
  if old.status = 'posted' and new.status <> 'reversed' then
    raise exception 'journal entry % is posted and can only be reversed, not set to %', old.id, new.status;
  end if;
  if old.status = 'posted' and new.status = 'reversed' then
    if to_jsonb(old) - 'status' - 'updated_at' - 'updated_by' - 'posted_at'
       is distinct from
       to_jsonb(new) - 'status' - 'updated_at' - 'updated_by' - 'posted_at' then
      raise exception 'journal entry % is posted and can only be reversed without other changes', old.id;
    end if;
    if not exists (
      select 1
        from journal_entries reversal
       where reversal.org_id = old.org_id
         and reversal.book_id = old.book_id
         and reversal.reverses_entry_id = old.id
         and reversal.status = 'posted'
         and public.openbooks_reversal_mirrors(old.org_id, old.id, reversal.id)
    ) then
      raise exception 'journal entry % cannot be reversed without a posted mirror reversal in the same book', old.id;
    end if;
    return new;
  end if;
  if old.status = 'reversed' then
    raise exception 'journal entry % is reversed and immutable', old.id;
  end if;

  if old.status = 'draft' and new.status = 'posted' then
    perform period_posting_fence(new.org_id, new.period_id, new.book_id);
    if period_module_blocks_write(new.org_id, new.period_id, new.book_id,
         nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       or exists (
         select 1 from journal_lines l
          where l.entry_id = new.id
            and l.org_id = new.org_id
            and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
              nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, 'gl',
              coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       ) then
      begin
        v_replay_auth := nullif(current_setting('openbooks.connector_replay_authorization', true), '')::uuid;
      exception when invalid_text_representation then
        v_replay_auth := null;
      end;
      if not public.openbooks_connector_replay_authorized(new.org_id, v_replay_auth, new.period_id) then
        raise exception 'period is closed for GL posting';
      end if;
    end if;
    if new.source_document_id is not null then
      select public.document_close_module(d.kind) into v_module
        from public.documents d
       where d.id = new.source_document_id;
      if v_module is not null and v_module <> 'gl'
         and (period_module_blocks_write(new.org_id, new.period_id, new.book_id,
                nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, v_module,
                coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
              or exists (
                select 1 from journal_lines l
                 where l.entry_id = new.id
                   and l.org_id = new.org_id
                   and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
                     nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, v_module,
                     coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
              )) then
        begin
          v_replay_auth := nullif(current_setting('openbooks.connector_replay_authorization', true), '')::uuid;
        exception when invalid_text_representation then
          v_replay_auth := null;
        end;
        if not public.openbooks_connector_replay_authorized(new.org_id, v_replay_auth, new.period_id)
           or not public.connector_historical_replay_authorized(new.org_id) then
          raise exception 'period is closed for % posting', upper(v_module);
        end if;
      end if;
    end if;
    new.posted_at := now();
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.jl_check_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_summary boolean;
  v_active boolean;
  v_ccy text;
  v_merged_into uuid;
begin
  -- Evidence-only stamps (0236) are not postings. The line satisfied the
  -- posting rules below when it was posted; recording cleared/reconciled
  -- evidence changes no posting-relevant field, so the question is not
  -- re-opened. The column set matches jl_guard() exactly: any UPDATE that
  -- touches anything else falls through to the full checks. Whether the
  -- stamp itself is a legal append-only transition stays jl_guard's call.
  if tg_op = 'UPDATE'
     and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
       = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
  then
    return new;
  end if;
  select is_summary, is_active, currency_restriction, merged_into_id
    into v_summary, v_active, v_ccy, v_merged_into
   from accounts
   where id = new.account_id and org_id = new.org_id
     for share;
  if not found then
    raise exception 'account % does not exist in organization %', new.account_id, new.org_id
      using errcode = '23503';
  end if;
  if v_summary then
    raise exception 'account % is a summary account and cannot be posted to', new.account_id;
  end if;
  if v_merged_into is not null then
    raise exception 'account % was merged into account % — post to the surviving account instead', new.account_id, v_merged_into
      using errcode = '23514';
  end if;
  if not v_active and coalesce(current_setting('openbooks.migration', true), 'off') <> 'on' then
    raise exception 'account % is inactive — reactivate the account or map the posting to an active account instead of posting to a deactivated one', new.account_id;
  end if;
  if v_ccy is not null and new.currency <> v_ccy then
    raise exception 'account % only accepts % postings', new.account_id, v_ccy;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.jl_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_status text;
  v_org uuid;
  v_period uuid;
  v_book uuid;
  v_old_status text;
  v_old_org uuid;
  v_old_period uuid;
  v_old_book uuid;
  v_line_org uuid;
  v_entry uuid;
  v_recon_same boolean;
  v_recon_statement_stamp boolean;
  v_recon_source_stamp boolean;
  v_source_same boolean;
  v_source_stamp boolean;
  v_recon_withdrawal boolean;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  -- Tenant coherence (restored from 0038 in 0159): a line may only ever
  -- reference a journal entry of its OWN organization. On UPDATE the
  -- ORIGINAL parent is resolved too: the destination alone cannot vouch for
  -- the history the line leaves behind. A miss raises the foreign-key class
  -- error the ledger guards and the kernel-constraints canary rely on.
  if tg_op = 'DELETE' then
    v_line_org := old.org_id;
    v_entry := old.entry_id;
  else
    v_line_org := new.org_id;
    v_entry := new.entry_id;
  end if;
  select status, org_id, period_id, book_id
    into v_status, v_org, v_period, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if not found then
    raise exception 'journal entry % does not exist in organization %', v_entry, v_line_org
      using errcode = '23503';
  end if;
  if tg_op = 'UPDATE' then
    select status, org_id, period_id, book_id
      into v_old_status, v_old_org, v_old_period, v_old_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if not found then
      raise exception 'journal entry % does not exist in organization %', old.entry_id, old.org_id
        using errcode = '23503';
    end if;
    -- Original-parent immutability (0165, hardened in 0380): a line that
    -- leaves posted or reversed history for a different entry or
    -- organization is refused, with no session-flag escape. Evidence-only
    -- stamps never move lines, so any such move is a history rewrite.
    if v_old_status is distinct from 'draft'
       and (new.entry_id is distinct from old.entry_id
            or new.org_id is distinct from old.org_id) then
      raise exception 'lines of a % journal entry are immutable', v_old_status;
    end if;
  end if;
  if v_status is distinct from 'draft' then
    -- Branch: clone-authority-insert (0316, restored in 0400). The
    -- deterministic clone replays posted history verbatim into target
    -- periods that may already be closed there; the immutability raise
    -- below would refuse the copy even though the history was valid where
    -- it was written. Under the clone authority an INSERT carries that
    -- history across, still subject to the tenant-coherent parent lookup
    -- above and to every balance and account guard. UPDATE and DELETE fall
    -- through and stay blocked exactly as before. This needs no amend
    -- escape: the authority is the conjunction of four GUCs only the clone
    -- transaction holds.
    if tg_op = 'INSERT' and public.openbooks_clone_authority() then
      return new;
    end if;
    -- Bank-reconciliation sign-off stamps reconciled_at / reconciliation_id
    -- on posted lines. That is bookkeeping metadata, but it is still
    -- financial-control evidence: it may transition from entirely unset to an
    -- extant unsigned reconciliation that already claims the line, and clear
    -- only through the governed sign-off withdrawal below. Retargeting or
    -- partially stamping the evidence is forbidden.
    -- Source-cleared evidence (0158) follows the same append-only rule: the
    -- mirror records the source system's cleared marker once, and a
    -- source-evidenced sign-off stamps only lines already carrying it.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
         = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id' - 'source_cleared_date' - 'source_cleared_connector'
    then
      v_recon_same := new.reconciled_at is not distinct from old.reconciled_at
        and new.reconciliation_id is not distinct from old.reconciliation_id;
      v_source_same := new.source_cleared_date is not distinct from old.source_cleared_date
        and new.source_cleared_connector is not distinct from old.source_cleared_connector;
      if v_recon_same and v_source_same then
        return new;
      end if;
      v_recon_statement_stamp :=
        old.reconciled_at is null
        and old.reconciliation_id is null
        and new.reconciled_at is not null
        and new.reconciliation_id is not null
        and exists (
          select 1
            from reconciliations r
           where r.id = new.reconciliation_id
             and r.org_id = new.org_id
             and r.status <> 'signed_off'
        )
        and exists (
          select 1
            from reconciliation_matches m
           where m.reconciliation_id = new.reconciliation_id
             and m.journal_line_id = new.id
             and m.org_id = new.org_id
        );
      v_recon_source_stamp :=
        old.reconciled_at is null
        and old.reconciliation_id is null
        and new.reconciled_at is not null
        and new.reconciliation_id is not null
        and new.source_cleared_date is not null
        and exists (
          select 1
            from reconciliations r
           where r.id = new.reconciliation_id
             and r.org_id = new.org_id
             and r.status <> 'signed_off'
             and r.evidence_kind = 'source'
        );
      v_source_stamp :=
        old.source_cleared_date is null
        and old.source_cleared_connector is null
        and new.source_cleared_date is not null
        and new.source_cleared_connector is not null
        and length(btrim(new.source_cleared_connector)) > 0;
      -- Governed sign-off withdrawal (0669): the engine has already returned
      -- the reconciliation to an unsigned state under the account lock and
      -- names it in a transaction-scoped marker. Only that reconciliation's
      -- stamp may clear, wholly, and the audit row lands in the same
      -- transaction.
      v_recon_withdrawal :=
        old.reconciled_at is not null
        and old.reconciliation_id is not null
        and new.reconciled_at is null
        and new.reconciliation_id is null
        and current_setting('app.reconciliation_withdrawal', true) = old.reconciliation_id::text
        and exists (
          select 1
            from reconciliations r
           where r.id = old.reconciliation_id
             and r.org_id = old.org_id
             and r.status <> 'signed_off'
        );
      if (v_recon_same or v_recon_statement_stamp or v_recon_source_stamp or v_recon_withdrawal)
         and (v_source_same or v_source_stamp) then
        return new;
      end if;
      raise exception 'journal-line reconciliation evidence is append-only';
    end if;
    -- Party-attribution moves (0380): the governed party-merge path
    -- re-points an absorbed party on posted lines. That changes NO amount,
    -- account, subsidiary, currency, or memo — party_id is the only column
    -- that may differ — and the move is refused when the period is closed
    -- for GL posting. There is no session-flag escape.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'party_id' = to_jsonb(old) - 'party_id'
       and new.party_id is distinct from old.party_id
    then
      if period_module_blocks_write(v_org, v_period, v_book,
           nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
           coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
        raise exception 'period is closed for GL posting';
      end if;
      return new;
    end if;
    -- Append-only (0380): the amend re-materialization branch is gone. A
    -- posted or reversed line admits clone replay, reconciliation-evidence
    -- stamps and party-attribution moves above; everything else is immutable.
    raise exception 'lines of a % journal entry are immutable', v_status;
  end if;
  return coalesce(new, old);
end $function$

CREATE OR REPLACE FUNCTION public.journal_entity_period_post_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE leg record; source_module text;
BEGIN
 IF NEW.status<>'posted' OR OLD.status='posted' THEN RETURN NEW; END IF;
 SELECT public.document_close_module(kind) INTO source_module FROM documents WHERE org_id=NEW.org_id AND id=NEW.source_document_id;
 FOR leg IN SELECT DISTINCT subsidiary_id,coalesce(period_id,NEW.period_id) as period_id FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=NEW.id LOOP
  PERFORM period_posting_fence(NEW.org_id,leg.period_id,NEW.book_id);
  IF period_module_blocks_write(NEW.org_id,leg.period_id,NEW.book_id,leg.subsidiary_id,'gl',public.connector_historical_replay_authorized(NEW.org_id))
   OR (source_module IS NOT NULL AND source_module<>'gl' AND period_module_blocks_write(NEW.org_id,leg.period_id,NEW.book_id,leg.subsidiary_id,source_module,public.connector_historical_replay_authorized(NEW.org_id))) THEN
   RAISE EXCEPTION 'The entity accounting period is closed for this posting module.' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.journal_generic_segment_balance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE bad record;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.id AND status IN('posted','reversed')) THEN RETURN NULL; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 SELECT d.key,l.subsidiary_id,sum(l.amount) AS total INTO bad FROM journal_lines l
 JOIN segment_definitions d ON d.org_id=l.org_id AND d.is_active AND d.is_balancing
 WHERE l.org_id=NEW.org_id AND l.entry_id=NEW.id
 GROUP BY d.key,l.subsidiary_id,CASE d.storage_column WHEN 'subsidiary_id' THEN l.subsidiary_id::text
  WHEN 'department_id' THEN l.department_id::text WHEN 'project_id' THEN l.project_id::text
  WHEN 'location_id' THEN l.location_id::text WHEN 'class_id' THEN l.class_id::text ELSE l.extra_dims->>d.key END
 HAVING sum(l.amount)<>0 LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION 'The journal must balance per entity and value of balancing segment %.',bad.key USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.journal_instruction_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
<<instruction_line>>
DECLARE head journal_entries%ROWTYPE; chosen_calendar uuid; chosen_period uuid; v_book_currency text; reversal_line journal_lines%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 SELECT * INTO STRICT head FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.entry_id;
 IF public.connector_historical_replay_authorized(NEW.org_id) THEN
  NEW.period_id:=head.period_id;
 ELSE
 chosen_calendar:=public.subsidiary_posting_calendar(NEW.org_id,NEW.subsidiary_id,head.posting_date);
 SELECT id INTO chosen_period FROM accounting_periods WHERE org_id=NEW.org_id AND id=head.period_id AND fiscal_calendar_id=chosen_calendar;
 IF chosen_period IS NULL THEN SELECT id INTO chosen_period FROM accounting_periods WHERE org_id=NEW.org_id AND fiscal_calendar_id=chosen_calendar
  AND NOT is_adjustment AND starts_on<=head.posting_date AND ends_on>=head.posting_date ORDER BY starts_on,ends_on,id LIMIT 1; END IF;
 IF chosen_period IS NULL THEN RAISE EXCEPTION 'Generate the entity accounting period covering this posting date.' USING ERRCODE='23514'; END IF;
 IF NEW.period_id IS NOT NULL AND NEW.period_id<>chosen_period THEN RAISE EXCEPTION 'A journal line must use its entity accounting period.' USING ERRCODE='23514'; END IF;
 NEW.period_id:=chosen_period;
 END IF;
 IF EXISTS(SELECT 1 FROM accounts WHERE org_id=NEW.org_id AND id=NEW.account_id AND type='statistical') THEN
  IF NEW.amount<>0 OR NEW.txn_amount<>0 OR NEW.quantity IS NULL OR NEW.quantity=0 OR coalesce(length(btrim(NEW.unit)),0)=0 OR NEW.is_open_item OR NEW.is_currency_adjustment THEN
   RAISE EXCEPTION 'Statistical accounts carry nonzero quantities with a unit and zero money.' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.is_currency_adjustment THEN
  IF NEW.txn_amount<>0 OR NEW.amount=0 OR NEW.is_open_item OR head.origin<>'currency_adjustment' THEN
   RAISE EXCEPTION 'Typed currency adjustments carry only a base amount and zero foreign transaction value.' USING ERRCODE='23514'; END IF;
  IF head.reverses_entry_id IS NOT NULL THEN
   SELECT * INTO reversal_line FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=head.reverses_entry_id AND line_number=NEW.line_number;
   IF NOT FOUND OR NOT reversal_line.is_currency_adjustment OR reversal_line.account_id<>NEW.account_id OR reversal_line.subsidiary_id<>NEW.subsidiary_id OR reversal_line.amount<>-NEW.amount OR reversal_line.currency<>NEW.currency OR reversal_line.fx_rate<>NEW.fx_rate OR reversal_line.txn_amount<>-NEW.txn_amount THEN
    RAISE EXCEPTION 'A currency adjustment reversal must mirror its original recorded line.' USING ERRCODE='23514'; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM documents WHERE org_id=NEW.org_id AND id=head.source_document_id AND kind='journal' AND journal_mode='currency_adjustment') THEN
   RAISE EXCEPTION 'A currency adjustment requires its native governed journal instruction.' USING ERRCODE='23514';
  END IF;
  IF head.reverses_entry_id IS NULL THEN
   PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:' || NEW.org_id::text,0));
   v_book_currency:=public.accounting_book_currency(NEW.org_id,head.book_id,NEW.subsidiary_id);
   IF NEW.currency=instruction_line.v_book_currency OR NOT EXISTS(SELECT 1 FROM journal_lines f JOIN journal_entries e ON e.org_id=f.org_id AND e.id=f.entry_id
      WHERE f.org_id=NEW.org_id AND e.book_id=head.book_id AND e.status IN('posted','reversed') AND e.posting_date<=head.posting_date
      AND f.subsidiary_id=NEW.subsidiary_id AND f.account_id=NEW.account_id AND f.currency=NEW.currency) OR EXISTS(SELECT 1 FROM journal_lines f JOIN journal_entries e ON e.org_id=f.org_id AND e.id=f.entry_id
    WHERE f.org_id=NEW.org_id AND e.book_id=head.book_id AND e.status IN('posted','reversed') AND e.posting_date<=head.posting_date
      AND f.subsidiary_id=NEW.subsidiary_id AND f.account_id=NEW.account_id AND f.currency<>instruction_line.v_book_currency
    GROUP BY f.currency HAVING sum(f.txn_amount)<>0) OR
    NEW.amount<>-(SELECT coalesce(sum(f.amount),0) FROM journal_lines f JOIN journal_entries e ON e.org_id=f.org_id AND e.id=f.entry_id
      WHERE f.org_id=NEW.org_id AND e.book_id=head.book_id AND e.status IN('posted','reversed') AND e.posting_date<=head.posting_date
      AND f.subsidiary_id=NEW.subsidiary_id AND f.account_id=NEW.account_id) THEN
    RAISE EXCEPTION 'A currency adjustment clears the exact book residual only after every foreign currency balance is zero.' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.journal_line_measurement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE account_type text;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 SELECT a.type INTO account_type FROM accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.account_id;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Choose a posting account owned by the journal organization.' USING ERRCODE='23514';
 END IF;
 IF account_type='statistical' THEN
  IF NEW.amount<>0 OR NEW.txn_amount<>0 OR NEW.quantity IS NULL OR NEW.quantity=0 OR NEW.quantity<>trunc(NEW.quantity,4) OR
    coalesce(length(btrim(NEW.unit)),0)=0 OR NEW.is_open_item OR NEW.is_currency_adjustment THEN
   RAISE EXCEPTION 'Statistical accounts carry nonzero quantities with a unit and zero money.' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.amount=0 THEN
  RAISE EXCEPTION 'Zero-money journal lines require a statistical account with a nonzero quantity and unit.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.journal_lines_lock_nonprofit_framework()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if coalesce(new.extra_dims, '{}'::jsonb) ? 'fund' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || new.org_id::text, 0)
    );
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.journal_primary_book_history_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  primary_ids uuid[];
BEGIN
  IF coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN new;
  END IF;
  SELECT array_agg(id) INTO primary_ids FROM (
    SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
      ORDER BY id FOR SHARE
  ) authority;
  -- A concurrent empty-org promotion can demote the row seen by the first
  -- statement while its lock waits. Take a fresh READ COMMITTED snapshot to
  -- resolve the successor, instead of proceeding without an authority fence.
  IF coalesce(cardinality(primary_ids), 0) = 0 THEN
    SELECT array_agg(id) INTO primary_ids FROM (
      SELECT id FROM public.accounting_books WHERE org_id = new.org_id AND is_primary
        ORDER BY id FOR SHARE
    ) authority;
  END IF;
  IF coalesce(cardinality(primary_ids), 0) <> 1 THEN
    RAISE EXCEPTION 'accounting history creation requires exactly one primary accounting book'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.journal_reversal_instruction_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Scheduled reversal instructions are retained history.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-ARRAY['status','reversal_entry_id','last_error','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','reversal_entry_id','last_error','updated_at','updated_by']) OR OLD.status IN('completed','cancelled')) THEN
  RAISE EXCEPTION 'An approved reversal instruction retains its source, actor and date; only its execution state can advance.' USING ERRCODE='23514'; END IF;
 IF NEW.status='completed' AND NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.reversal_entry_id
   AND status='posted' AND reverses_entry_id=NEW.source_entry_id AND posting_date=NEW.reverse_on) THEN
  RAISE EXCEPTION 'Completion identifies the exact posted reversal of the approved instruction.' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM documents d JOIN journal_entries e ON e.org_id=d.org_id AND e.source_document_id=d.id
  WHERE d.org_id=NEW.org_id AND d.id=NEW.document_id AND e.id=NEW.source_entry_id AND d.kind='journal' AND d.journal_reverse_on=NEW.reverse_on AND NEW.reverse_on>e.posting_date) THEN
  RAISE EXCEPTION 'A scheduled reversal must match its posted journal instruction.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.landed_cost_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'landed-cost allocation evidence is append-only';
  END IF;
  IF OLD.journal_entry_id IS NULL
     AND NEW.journal_entry_id IS NOT NULL
     AND (to_jsonb(NEW) - 'journal_entry_id' - 'updated_at' - 'updated_by')
       = (to_jsonb(OLD) - 'journal_entry_id' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'landed-cost allocation evidence is immutable';
END
$function$

CREATE OR REPLACE FUNCTION public.landed_cost_voucher_target_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent_status text;
  parent_org uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT status, org_id
    INTO parent_status, parent_org
    FROM landed_cost_vouchers
   WHERE id = coalesce(NEW.voucher_id, OLD.voucher_id);
  IF TG_OP = 'DELETE' AND parent_status IS NULL THEN RETURN OLD; END IF;
  IF parent_status IS NULL
     OR parent_org IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'landed-cost target must reference a tenant-owned voucher';
  END IF;
  IF parent_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of a posted landed-cost voucher are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.layer_consumption_fill_subsidiary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner uuid;
BEGIN
  IF NEW.subsidiary_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT m.subsidiary_id INTO owner
    FROM public.inventory_movements m
   WHERE m.id = NEW.issue_movement_id
     AND m.org_id = NEW.org_id;
  IF owner IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'check_violation',
      MESSAGE = 'cost layer consumption requires the legal entity of its issue movement',
      DETAIL = 'The issue movement was not found, so ownership could not be derived.',
      HINT = 'Create the issue movement before recording its consumptions.';
  END IF;
  NEW.subsidiary_id := owner;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lease_agreement_revision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.status<>'draft' THEN RAISE EXCEPTION 'commenced lease agreements are retained; use a termination or correcting change'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.org_id<>NEW.org_id OR OLD.subsidiary_id<>NEW.subsidiary_id OR OLD.id<>NEW.id THEN
    RAISE EXCEPTION 'lease organization and legal entity are immutable';
  END IF;
  IF OLD.status='draft' THEN RETURN NEW; END IF;
  IF (to_jsonb(NEW)-ARRAY['description','custom','updated_at','updated_by']) IS NOT DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['description','custom','updated_at','updated_by']) THEN RETURN NEW; END IF;
  IF NEW.revision<>OLD.revision+1 OR NEW.last_change_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM financial_changes c WHERE c.id=NEW.last_change_id AND c.org_id=NEW.org_id
      AND c.domain='lease' AND c.subject_id=NEW.id AND c.status='approved') THEN
    RAISE EXCEPTION 'changing a commenced lease requires an approved accounting change and a new revision';
  END IF;
  IF NEW.initial_liability IS DISTINCT FROM OLD.initial_liability OR NEW.initial_rou_asset IS DISTINCT FROM OLD.initial_rou_asset
     OR NEW.commencement_entry_id IS DISTINCT FROM OLD.commencement_entry_id OR NEW.commencement_on<>OLD.commencement_on
     OR NEW.book_id IS DISTINCT FROM OLD.book_id OR NEW.currency IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION 'lease commencement history is immutable';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.lease_schedule_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'lease schedules are retained; supersede future rows through an approved change'; END IF;
  IF (to_jsonb(NEW) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by'])
     IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['payment_entry_id','amortization_entry_id','posted_at','payment_posted_at','accrual_posted_at','superseded_by_change_id','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'lease schedule measurements are immutable; append a revision';
  END IF;
  IF NEW.superseded_by_change_id IS DISTINCT FROM OLD.superseded_by_change_id THEN
    IF OLD.accrual_posted_at IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM financial_changes c WHERE c.id=NEW.superseded_by_change_id AND c.org_id=OLD.org_id
        AND c.subject_id=OLD.lease_id AND c.domain='lease' AND c.status='approved') THEN
      RAISE EXCEPTION 'only unaccrued rows may be superseded by an approved change to this lease';
    END IF;
  END IF;
  IF (OLD.payment_posted_at IS NOT NULL AND (NEW.payment_posted_at IS DISTINCT FROM OLD.payment_posted_at OR NEW.payment_entry_id IS DISTINCT FROM OLD.payment_entry_id))
    OR (OLD.accrual_posted_at IS NOT NULL AND (NEW.accrual_posted_at IS DISTINCT FROM OLD.accrual_posted_at OR NEW.amortization_entry_id IS DISTINCT FROM OLD.amortization_entry_id))
    OR (OLD.superseded_by_change_id IS NOT NULL AND NEW IS DISTINCT FROM OLD) THEN
    RAISE EXCEPTION 'completed lease events cannot be changed';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.lock_actor_home_identity(p_org uuid, p_actor uuid, p_home uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  original_scope text := current_setting('app.current_org', true);
  target_member boolean;
  locked public.users%rowtype;
BEGIN
  IF p_org IS NULL OR original_scope IS DISTINCT FROM p_org::text OR p_actor IS NULL OR p_home IS NULL THEN
    RAISE EXCEPTION 'Actor command tenant scope does not match its organization';
  END IF;
  PERFORM a.id FROM public.role_assignments a
    JOIN public.app_roles r ON r.org_id=a.org_id AND r.id=a.role_id
    WHERE a.org_id=p_org AND a.user_id=p_actor
    ORDER BY a.id FOR SHARE OF a,r;
  target_member := FOUND;
  BEGIN
    PERFORM set_config('app.current_org', p_home::text, true);
    SELECT u.* INTO locked FROM public.users u
      WHERE u.id=p_actor AND u.org_id=p_home FOR SHARE;
    IF NOT FOUND OR NOT locked.is_active OR (NOT locked.is_super_admin AND NOT target_member) THEN
      RAISE EXCEPTION 'Actor is not eligible to command this organization';
    END IF;
    PERFORM set_config('app.current_org', original_scope, true);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.current_org', original_scope, true);
    RAISE;
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.manufacturing_completion_trace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE work_number text; source_quantity numeric; assigned_quantity numeric;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Completion trace evidence is immutable; reverse its receipt to correct the batch.' USING ERRCODE='23514'; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 SELECT number INTO work_number FROM mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.work_order_id FOR SHARE;
 IF work_number IS NULL OR NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.completion_entry_id AND origin='manufacturing' AND status='posted' AND reverses_entry_id IS NULL AND custom->>'work_order_number'=work_number AND custom ? 'completion_quantity') THEN
  RAISE EXCEPTION 'Completion evidence requires the posted receipt of its work order.' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='mfg_completion_batches' THEN
  IF NOT EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND id=NEW.completion_entry_id AND (custom->>'completion_quantity')::numeric=NEW.quantity) THEN RAISE EXCEPTION 'Batch quantity must match its native receipt.' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT -movement.quantity INTO source_quantity FROM inventory_movements movement JOIN journal_entries entry ON entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id
   WHERE movement.org_id=NEW.org_id AND movement.id=NEW.input_movement_id AND movement.kind='assembly_consume' AND movement.status='posted' AND movement.reverses_movement_id IS NULL
    AND entry.origin='manufacturing' AND entry.status='posted' AND entry.custom->>'work_order_number'=work_number
    AND NOT EXISTS(SELECT 1 FROM inventory_movements reversal WHERE reversal.org_id=movement.org_id AND reversal.reverses_movement_id=movement.id AND reversal.status='posted') FOR UPDATE OF movement;
  SELECT coalesce(sum(allocation.quantity),0) INTO assigned_quantity FROM mfg_completion_inputs allocation JOIN journal_entries receipt ON receipt.org_id=allocation.org_id AND receipt.id=allocation.completion_entry_id
   WHERE allocation.org_id=NEW.org_id AND allocation.input_movement_id=NEW.input_movement_id AND receipt.status='posted' AND receipt.reverses_entry_id IS NULL;
  IF source_quantity IS NULL OR NEW.quantity+assigned_quantity>source_quantity THEN RAISE EXCEPTION 'Completion inputs must use unassigned native issues from the same work order.' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.manufacturing_inspected_output_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE movement inventory_movements; work mfg_work_orders; operation mfg_wo_operations; accepted inventory_inspections; total_goods numeric; identifier_goods numeric;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO movement FROM inventory_movements WHERE org_id=NEW.org_id AND id=NEW.id;
 IF movement.kind<>'assembly_build' OR movement.quantity<=0 OR movement.status<>'posted' OR movement.reverses_movement_id IS NOT NULL THEN RETURN NULL; END IF;
 SELECT order_row.* INTO work FROM mfg_work_orders order_row JOIN journal_entries entry
   ON entry.org_id=order_row.org_id AND entry.custom->>'work_order_number'=order_row.number
   WHERE entry.org_id=movement.org_id AND entry.id=movement.journal_entry_id AND entry.origin='manufacturing'
     AND entry.status='posted' AND entry.reverses_entry_id IS NULL AND order_row.produced_item_id=movement.item_id;
 IF work.id IS NULL THEN RETURN NULL; END IF;
 SELECT coalesce(sum(receipt.quantity),0),coalesce(sum(receipt.quantity) FILTER(WHERE receipt.lot_id IS NOT DISTINCT FROM movement.lot_id AND receipt.serial_id IS NOT DISTINCT FROM movement.serial_id),0)
   INTO total_goods,identifier_goods FROM inventory_movements receipt JOIN journal_entries entry ON entry.org_id=receipt.org_id AND entry.id=receipt.journal_entry_id
   WHERE receipt.org_id=work.org_id AND receipt.item_id=work.produced_item_id AND receipt.kind='assembly_build' AND receipt.quantity>0
     AND receipt.status='posted' AND receipt.reverses_movement_id IS NULL AND entry.origin='manufacturing' AND entry.status='posted'
     AND entry.reverses_entry_id IS NULL AND entry.custom->>'work_order_number'=work.number;
 FOR operation IN SELECT * FROM mfg_wo_operations WHERE org_id=work.org_id AND work_order_id=work.id AND inspection_plan_snapshot IS NOT NULL LOOP
  IF operation.status<>'done' OR total_goods>operation.quantity_done OR EXISTS(SELECT 1 FROM inventory_inspections inspection
    WHERE inspection.org_id=work.org_id AND inspection.operation_id=operation.id AND (inspection.status='pending'
      OR inspection.status='fail' AND (inspection.disposition IS NULL OR inspection.disposition='rework' AND inspection.rework_completed_at IS NULL))) THEN
   RAISE EXCEPTION 'Finished output requires completed operations and resolved inspections covering its quantity.' USING ERRCODE='23514';
  END IF;
  SELECT * INTO accepted FROM inventory_inspections inspection WHERE inspection.org_id=work.org_id AND inspection.operation_id=operation.id
    AND inspection.lot_id IS NOT DISTINCT FROM movement.lot_id AND inspection.serial_id IS NOT DISTINCT FROM movement.serial_id
    ORDER BY inspection.inspection_sequence DESC LIMIT 1;
  IF accepted.id IS NULL OR identifier_goods>accepted.quantity OR NOT coalesce(accepted.status='pass' OR accepted.disposition='use_as_is' OR accepted.disposition='rework' AND accepted.rework_completed_at IS NOT NULL,false) THEN
   RAISE EXCEPTION 'Finished output identifiers and quantity must match accepted operation inspections.' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.manufacturing_loss_completion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE event mfg_scrap_events; change financial_changes; work mfg_work_orders; balance numeric;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO event FROM mfg_scrap_events WHERE org_id=NEW.org_id AND id=NEW.id;
 IF event.disposition_change_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO change FROM financial_changes WHERE org_id=event.org_id AND id=event.disposition_change_id;
 SELECT * INTO work FROM mfg_work_orders WHERE org_id=event.org_id AND id=event.work_order_id;
 SELECT coalesce(sum(line.amount),0) INTO balance FROM journal_lines line JOIN journal_entries entry ON entry.org_id=line.org_id AND entry.id=line.entry_id WHERE line.org_id=event.org_id AND line.account_id::text=change.before_state->>'wipAccountId' AND entry.origin='manufacturing' AND entry.custom->>'work_order_number'=work.number AND entry.status IN('posted','reversed');
 IF change.status IS DISTINCT FROM 'applied' OR change.result->>'eventId' IS DISTINCT FROM event.id::text OR change.result->>'entryId' IS DISTINCT FROM event.posted_entry_id::text OR work.loss_change_id IS DISTINCT FROM change.id OR work.status<>'cancelled' OR work.quantity_completed<>0 OR balance<>0 THEN
  RAISE EXCEPTION 'Loss disposition must finish its governed order, exact journal and zero remaining WIP atomically.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.manufacturing_loss_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE change financial_changes; work mfg_work_orders; balance numeric;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.disposition_change_id IS NOT NULL THEN RAISE EXCEPTION 'Approved loss evidence is immutable.' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.disposition_change_id IS DISTINCT FROM OLD.disposition_change_id OR (OLD.disposition_change_id IS NOT NULL AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by'])) THEN RAISE EXCEPTION 'Approved loss evidence is immutable.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.disposition_change_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO change FROM financial_changes WHERE org_id=NEW.org_id AND id=NEW.disposition_change_id FOR SHARE;
 SELECT * INTO work FROM mfg_work_orders WHERE org_id=NEW.org_id AND id=NEW.work_order_id FOR UPDATE;
 IF change.id IS NULL OR work.id IS NULL OR change.domain<>'manufacturing' OR change.operation<>'work_order_loss_disposition' OR change.status<>'approved'
   OR change.subject_id<>work.id OR change.subsidiary_id IS DISTINCT FROM work.subsidiary_id OR work.status<>'on_hold' OR work.quantity_completed<>0
   OR NEW.classification<>'abnormal' OR NEW.treatment<>'operation' OR NEW.approval_required IS DISTINCT FROM true
   OR NEW.quantity<=0 OR NEW.quantity>work.quantity_ordered-work.quantity_scrapped
   OR NEW.quantity IS DISTINCT FROM (change.before_state->>'quantity')::numeric OR NEW.frozen_value IS DISTINCT FROM (change.before_state->>'value')::numeric
   OR NEW.frozen_unit_cost IS DISTINCT FROM round(NEW.frozen_value/NEW.quantity,4)
   OR NEW.operation_id::text IS DISTINCT FROM change.payload->'input'->>'operationId' OR NEW.reason_id::text IS DISTINCT FROM change.payload->'input'->>'reasonId'
   OR (NEW.frozen_value=0) IS DISTINCT FROM (NEW.posted_entry_id IS NULL)
   OR change.approved_by IS NULL OR NOT(change.approved_by<>change.submitted_by OR public.financial_change_self_decision_authorized(change.org_id,change.id,change.submitted_by)) THEN
   RAISE EXCEPTION 'Loss evidence requires its exact approved work, quantity, value and independent decision.' USING ERRCODE='23514';
 END IF;
 SELECT coalesce(sum(line.amount),0) INTO balance FROM journal_lines line JOIN journal_entries entry ON entry.org_id=line.org_id AND entry.id=line.entry_id
   WHERE line.org_id=NEW.org_id AND line.account_id::text=change.before_state->>'wipAccountId' AND entry.origin='manufacturing'
     AND entry.custom->>'work_order_number'=work.number AND entry.status IN('posted','reversed') AND entry.id IS DISTINCT FROM NEW.posted_entry_id;
 IF balance IS DISTINCT FROM NEW.frozen_value THEN RAISE EXCEPTION 'Loss recognizes all actual remaining WIP, including consumed conversion.' USING ERRCODE='23514'; END IF;
 IF NEW.posted_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM journal_entries entry WHERE entry.org_id=NEW.org_id AND entry.id=NEW.posted_entry_id AND entry.status='posted'
   AND entry.origin='manufacturing' AND entry.subsidiary_id=work.subsidiary_id AND entry.custom->>'loss_change_id'=change.id::text AND entry.custom->>'scrap_event_id'=NEW.id::text
   AND (SELECT coalesce(sum(amount),0) FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=entry.id AND account_id::text=change.before_state->>'wipAccountId')=-NEW.frozen_value
   AND (SELECT coalesce(sum(amount),0) FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=entry.id AND account_id::text=change.before_state->>'lossAccountId')=NEW.frozen_value
   AND (SELECT count(*) FROM journal_lines WHERE org_id=NEW.org_id AND entry_id=entry.id)=2) THEN
   RAISE EXCEPTION 'Loss requires its exact balanced native write-off journal.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.manufacturing_loss_journal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status IS DISTINCT FROM OLD.status AND EXISTS(SELECT 1 FROM mfg_work_orders work WHERE work.org_id=OLD.org_id AND work.number=OLD.custom->>'work_order_number' AND work.loss_change_id IS NOT NULL) THEN
  RAISE EXCEPTION 'A disposed production loss retains its journal. Record an approved adjusting journal for a financial correction; discarded stock and work cannot be recreated by reversal.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND NEW.reverses_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM journal_entries source JOIN mfg_work_orders work ON work.org_id=source.org_id AND work.number=source.custom->>'work_order_number' WHERE source.org_id=NEW.org_id AND source.id=NEW.reverses_entry_id AND work.loss_change_id IS NOT NULL) THEN
  RAISE EXCEPTION 'A disposed production loss requires an adjusting journal rather than a reversal that would recreate WIP.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.manufacturing_loss_order_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.loss_change_id IS NOT NULL THEN RAISE EXCEPTION 'A production order starts without a loss disposition.' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.loss_change_id IS NOT NULL THEN
  IF (NEW.status,NEW.quantity_completed,NEW.quantity_scrapped,NEW.loss_change_id,NEW.cancel_reason) IS DISTINCT FROM (OLD.status,OLD.quantity_completed,OLD.quantity_scrapped,OLD.loss_change_id,OLD.cancel_reason) THEN RAISE EXCEPTION 'A disposed order retains its terminal loss evidence.' USING ERRCODE='23514'; END IF;
 ELSIF NEW.loss_change_id IS NOT NULL THEN
  IF OLD.status<>'on_hold' OR NEW.status<>'cancelled' OR NEW.quantity_completed<>0 OR NOT EXISTS(SELECT 1 FROM financial_changes change JOIN mfg_scrap_events event ON event.org_id=change.org_id AND event.disposition_change_id=change.id
   WHERE change.org_id=NEW.org_id AND change.id=NEW.loss_change_id AND change.subject_id=NEW.id AND change.domain='manufacturing' AND change.operation='work_order_loss_disposition' AND change.status='approved'
   AND event.work_order_id=NEW.id AND event.quantity=NEW.quantity_scrapped-OLD.quantity_scrapped AND NEW.cancel_reason=change.reason) THEN
   RAISE EXCEPTION 'Closing as loss requires its approved actual scrap and WIP evidence.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

