CREATE OR REPLACE FUNCTION public.native_command_approval_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE dependencies jsonb; command jsonb; fingerprint text; approval_statuses text[]:=string_to_array(TG_ARGV[1],'|'); subject_kind text:=TG_ARGV[0]; released_fields text[]:=ARRAY['status','updated_at','updated_by','approved_at','approved_by'];
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF (to_jsonb(NEW)->>'status')=ANY(approval_statuses) THEN RAISE EXCEPTION 'Create a native draft before submitting its approval command through Flows.'; END IF;
  RETURN NEW;
 END IF;
 IF NOT coalesce((to_jsonb(NEW)->>'status')=ANY(approval_statuses),false) OR coalesce((to_jsonb(OLD)->>'status')=ANY(approval_statuses),false) THEN RETURN NEW; END IF;
 -- Restoring a settled claim retains its original approval and immutable stamp.
 IF TG_ARGV[0]='rebate_claim' AND to_jsonb(OLD)->>'status'='settled'
  AND to_jsonb(OLD)->>'approved_at' IS NOT NULL AND jsonb_build_array(to_jsonb(NEW)->'approved_at',to_jsonb(NEW)->'approved_by') IS NOT DISTINCT FROM jsonb_build_array(to_jsonb(OLD)->'approved_at',to_jsonb(OLD)->'approved_by') THEN RETURN NEW; END IF;
 IF TG_ARGV[0] IN('customer_change_order','subcontract_change_order') THEN released_fields:=released_fields||ARRAY['approved_on']; END IF;
 IF TG_ARGV[0]='bank_reconciliation_sign_off' THEN released_fields:=released_fields||ARRAY['signed_off_at','signed_off_by']; END IF;
 IF TG_ARGV[0]='headcount_plan_line' THEN released_fields:=released_fields||ARRAY['revision','requisition_id','reason']; END IF;
 IF TG_ARGV[0]='headcount_plan' THEN released_fields:=released_fields||ARRAY['revision']; END IF;
 IF TG_ARGV[0]='compensation_cycle_line' THEN released_fields:=released_fields||ARRAY['revision','approver_party_id','decided_at','reason']; END IF;
 -- Stored generated projections are computed after BEFORE triggers. Their
 -- base columns remain sealed; derived values cannot be supplied by a write.
 SELECT released_fields||coalesce(array_agg(a.attname::text),ARRAY[]::text[])
   INTO released_fields FROM pg_catalog.pg_attribute a
  WHERE a.attrelid=TG_RELID AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated<>'';
 -- Releasing a generated bill or invoice restores the existing approved
 -- economic terms; it neither makes a new decision nor changes its evidence.
 IF subject_kind IN('customer_pay_application','vendor_pay_application')
  AND to_jsonb(NEW)->>'status'='approved'
  AND to_jsonb(OLD)->>'status'=ANY(CASE WHEN subject_kind='customer_pay_application' THEN ARRAY['invoiced','posted'] ELSE ARRAY['billed'] END) THEN
  DECLARE document_column text:=CASE WHEN subject_kind='customer_pay_application' THEN 'invoice_document_id' ELSE 'vendor_bill_document_id' END;
          source_document uuid; original_decider uuid;
  BEGIN
   source_document:=(to_jsonb(OLD)->>document_column)::uuid;
   original_decider:=(to_jsonb(OLD)->>'approved_by')::uuid;
   IF source_document IS NULL OR original_decider IS NULL OR to_jsonb(OLD)->>'approved_at' IS NULL
    OR to_jsonb(NEW)->>document_column IS NOT NULL OR to_jsonb(NEW)->>'updated_by' IS NULL
    OR (to_jsonb(NEW)-ARRAY['status','updated_at','updated_by',document_column])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at','updated_by',document_column]) THEN
    RAISE EXCEPTION 'Releasing billing cannot change approved payment application terms. Review the current application and submit changed terms through Flows.' USING ERRCODE='23514';
   END IF;
   IF NOT EXISTS(SELECT 1 FROM public.documents d WHERE d.org_id=OLD.org_id AND d.id=source_document
     AND d.kind=CASE WHEN subject_kind='customer_pay_application' THEN 'customer_invoice' ELSE 'vendor_bill' END
     AND ((d.status='draft' AND d.posted_entry_id IS NULL)
       OR (d.status='posted' AND d.void_requested_at IS NOT NULL AND d.void_reason IS NOT NULL
         AND d.void_requested_by::text=to_jsonb(NEW)->>'updated_by'
         AND EXISTS(SELECT 1 FROM public.journal_entries original WHERE original.org_id=d.org_id
           AND original.id=d.posted_entry_id AND original.status='reversed'
           AND EXISTS(SELECT 1 FROM public.journal_entries reversal WHERE reversal.org_id=original.org_id
             AND reversal.reverses_entry_id=original.id AND reversal.status='posted'))))) THEN
    RAISE EXCEPTION 'Discard the draft or complete the native invoice or bill reversal before releasing its payment application.' USING ERRCODE='23514';
   END IF;
   IF subject_kind='customer_pay_application' THEN
    SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM public.pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
   ELSE
    SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM public.vendor_pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
   END IF;
   fingerprint:=public.flow_command_record_fingerprint(to_jsonb(NEW),dependencies);
   IF NOT public.flow_subject_decision_authorized(NEW.org_id,subject_kind,NEW.id,original_decider,fingerprint,'approved') THEN
    RAISE EXCEPTION 'The payment application has no retained approval for these exact terms. Review and resubmit it through Flows.' USING ERRCODE='23514';
   END IF;
   RETURN NEW;
  END;
 END IF;
 IF (to_jsonb(NEW)-released_fields) IS DISTINCT FROM (to_jsonb(OLD)-released_fields) THEN
  RAISE EXCEPTION 'A Flow decision cannot replace the submitted record terms.';
 END IF;
 CASE TG_ARGV[0]
  WHEN 'bank_reconciliation_sign_off' THEN dependencies:=public.reconciliation_approval_dependencies(OLD.org_id,OLD.id);
  WHEN 'customer_change_order' THEN
    SELECT jsonb_build_object('contractValue',(SELECT p.contract_value::text FROM projects p WHERE p.org_id=OLD.org_id AND p.id=OLD.project_id),
      'schedule',(SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) FROM sov_lines l WHERE l.org_id=OLD.org_id AND l.project_id=OLD.project_id)) INTO dependencies;
    command:=jsonb_build_object('approvedOn',NEW.approved_on::text);
  WHEN 'headcount_plan_line' THEN dependencies:=NULL;
  WHEN 'headcount_plan' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM hrm_headcount_plan_lines l WHERE l.org_id=OLD.org_id AND l.plan_id=OLD.id;
  WHEN 'compensation_cycle_line' THEN dependencies:=NULL;
  WHEN 'per_diem_entry' THEN dependencies:=NULL;
  WHEN 'travel_pay_entry' THEN dependencies:=NULL;
  WHEN 'sandbox_change_set' THEN SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.id),'[]'::jsonb) INTO dependencies FROM change_set_items i WHERE i.org_id=OLD.org_id AND i.change_set_id=OLD.id;
  WHEN 'rebate_agreement' THEN dependencies:=NULL;
  WHEN 'rebate_claim' THEN SELECT to_jsonb(a) INTO dependencies FROM rebate_agreements a WHERE a.org_id=OLD.org_id AND a.id=OLD.agreement_id;
  WHEN 'subcontract' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM subcontract_sov_lines l WHERE l.org_id=OLD.org_id AND l.subcontract_id=OLD.id;
  WHEN 'subcontract_change_order' THEN dependencies:=public.subcontract_change_approval_dependencies(OLD.org_id,OLD.subcontract_id);command:=jsonb_build_object('approvedOn',NEW.approved_on::text);
  WHEN 'vendor_pay_application' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM vendor_pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
  WHEN 'customer_pay_application' THEN SELECT coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]'::jsonb) INTO dependencies FROM pay_application_lines l WHERE l.org_id=OLD.org_id AND l.pay_application_id=OLD.id;
  ELSE RAISE EXCEPTION 'This native command has no registered approval evidence contract.';
 END CASE;
 IF subject_kind='rebate_agreement' THEN subject_kind:=OLD.side||'_rebate_agreement';
 ELSIF subject_kind='rebate_claim' THEN subject_kind:=(dependencies->>'side')||'_rebate_claim'; END IF;
 fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD),dependencies);
 IF NOT public.flow_command_authorized(NEW.org_id,subject_kind,NEW.id,coalesce(to_jsonb(NEW)->>'approved_by',to_jsonb(NEW)->>'updated_by')::uuid,fingerprint,command) THEN
  RAISE EXCEPTION 'Complete native tenant Flow routing for this exact record and command before release.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.native_command_pending_terms_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE before_row jsonb; after_row jsonb; candidate jsonb; subject_key uuid; organization uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN before_row:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN after_row:=to_jsonb(NEW); END IF;
 IF TG_OP='UPDATE' AND (after_row-ARRAY['updated_at','updated_by']) IS NOT DISTINCT FROM
   (before_row-ARRAY['updated_at','updated_by']) THEN RETURN NEW; END IF;
 -- Both old and new ownership matter when a child is moved between parents.
 FOR candidate IN SELECT value FROM jsonb_array_elements(jsonb_build_array(before_row,after_row)) WHERE value<>'null'::jsonb LOOP
  organization:=(candidate->>'org_id')::uuid;
  subject_key:=coalesce((candidate->>nullif(TG_ARGV[1],''))::uuid,(candidate->>'id')::uuid);
  IF EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=organization AND g.subject_kind=ANY(string_to_array(TG_ARGV[0],'|')) AND g.subject_id=subject_key
      AND r.context ? 'command' AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Recall the pending native Flow submission before changing these terms.';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.native_request_flow_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE kind text:=TG_ARGV[0];fingerprint text; allowed text[]:=ARRAY['status','flow_instance_id','decided_by','decided_at','decision_reason','decision_comment','updated_at','updated_by'];
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'draft' THEN RAISE EXCEPTION 'File a draft request before native submission.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status<>'draft' AND (to_jsonb(NEW)-allowed) IS DISTINCT FROM (to_jsonb(OLD)-allowed) THEN
  RAISE EXCEPTION 'Submitted request terms are immutable. Cancel or withdraw the request and file the replacement.';
 END IF;
 IF kind='hrm_leave_request' THEN fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD)-ARRAY['flow_instance_id','decided_by','decided_at','decision_reason']);
 ELSE fingerprint:=public.flow_command_record_fingerprint(to_jsonb(OLD)-ARRAY['flow_instance_id','decided_by','decided_at','decision_comment']); END IF;
 IF OLD.status='draft' AND NEW.status='submitted' THEN
  IF NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind=kind AND s.subject_id=NEW.id
    AND s.actor_id=NEW.updated_by AND s.context->>'approvalFingerprint'=fingerprint
    AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
      AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))) THEN
   RAISE EXCEPTION 'Submit the exact request through native Flow routing.';
  END IF;
 END IF;
 IF NEW.status IN('approved','rejected') AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF OLD.status<>'submitted' OR NOT public.flow_subject_decision_authorized(NEW.org_id,kind,NEW.id,NEW.updated_by,fingerprint,NEW.status) THEN
   RAISE EXCEPTION 'Complete this request through its current native Flow submission.';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.nonprofit_frameworks_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_line_count bigint;
  v_org_id uuid;
begin
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and pg_catalog.pg_trigger_depth() > 1 then
    return old;
  end if;

  v_org_id := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'UPDATE' and new.org_id is distinct from old.org_id then
    raise exception 'a nonprofit framework cannot be moved to another organization'
      using errcode = '23514';
  end if;

  -- Fund line inserts use the same transaction lock, so a framework change
  -- cannot pass its history check while a fund posting is still in flight.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('openbooks:nonprofit-framework:' || v_org_id::text, 0)
  );

  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and new.framework is distinct from old.framework) then
    select count(*) into v_line_count
      from public.journal_lines jl
      join public.journal_entries je
        on je.org_id = jl.org_id and je.id = jl.entry_id
     where jl.org_id = v_org_id
       and jl.extra_dims ? 'fund'
       and je.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'nonprofit framework cannot change or be removed while % posted fund-tagged journal lines exist; continue with the current framework or use a separate organization',
        v_line_count
        using errcode = '23514',
              constraint = 'nonprofit_frameworks_history_guard';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_rule_criteria_is_valid(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  account_id text;
BEGIN
  IF jsonb_typeof(value) <> 'object'
     OR value->>'version' <> '2'
     OR octet_length(value::text) > 100000
     OR NOT public.openbooks_bank_rule_group_is_valid(value->'match') THEN
    RETURN false;
  END IF;
  IF value ? 'accountScope' THEN
    IF jsonb_typeof(value->'accountScope') <> 'array' THEN
      RETURN false;
    END IF;
    FOR account_id IN SELECT entry FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)
    LOOP
      IF account_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF (SELECT count(*) <> count(DISTINCT entry) FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_rule_group_is_valid(value jsonb, depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  rule jsonb;
  field_name text;
  operator_name text;
  scalar_value text;
  numeric_value numeric;
  lower_bound numeric;
  upper_bound numeric;
BEGIN
  IF depth > 4
     OR jsonb_typeof(value) <> 'object'
     OR value->>'combinator' NOT IN ('and', 'or')
     OR jsonb_typeof(value->'rules') <> 'array'
     OR jsonb_array_length(value->'rules') NOT BETWEEN 1 AND 40 THEN
    RETURN false;
  END IF;

  FOR rule IN SELECT element FROM jsonb_array_elements(value->'rules') AS elements(element)
  LOOP
    IF jsonb_typeof(rule) <> 'object' THEN
      RETURN false;
    END IF;
    IF rule ? 'rules' THEN
      IF NOT public.openbooks_bank_rule_group_is_valid(rule, depth + 1) THEN
        RETURN false;
      END IF;
      CONTINUE;
    END IF;

    field_name := rule->>'field';
    operator_name := rule->>'op';
    scalar_value := rule->>'value';

    IF field_name IN ('description', 'payee', 'anyText', 'reference') THEN
      IF operator_name NOT IN ('contains', 'notContains', 'equals', 'startsWith', 'endsWith', 'isBlank')
         OR (operator_name <> 'isBlank' AND (jsonb_typeof(rule->'value') <> 'string' OR btrim(scalar_value) = '' OR length(scalar_value) > 200)) THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'flow' THEN
      IF operator_name <> 'is' OR scalar_value NOT IN ('in', 'out', 'any') THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'source' THEN
      IF operator_name <> 'equals' OR jsonb_typeof(rule->'value') <> 'string'
         OR btrim(scalar_value) = '' OR length(scalar_value) > 40 THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'amount' THEN
      IF operator_name NOT IN ('eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'between') THEN
        RETURN false;
      END IF;
      IF operator_name = 'between' THEN
        IF jsonb_typeof(rule->'value') <> 'array'
           OR jsonb_array_length(rule->'value') <> 2
           OR jsonb_typeof(rule->'value'->0) <> 'number'
           OR jsonb_typeof(rule->'value'->1) <> 'number' THEN
          RETURN false;
        END IF;
        lower_bound := (rule->'value'->>0)::numeric;
        upper_bound := (rule->'value'->>1)::numeric;
        IF lower_bound < 0 OR upper_bound < lower_bound THEN
          RETURN false;
        END IF;
      ELSE
        IF jsonb_typeof(rule->'value') <> 'number' THEN
          RETURN false;
        END IF;
        numeric_value := scalar_value::numeric;
        IF numeric_value < 0 THEN
          RETURN false;
        END IF;
      END IF;
    ELSIF field_name = 'date' THEN
      IF operator_name = 'withinDays' THEN
        IF jsonb_typeof(rule->'value') <> 'number' OR scalar_value::numeric <= 0 THEN
          RETURN false;
        END IF;
      ELSIF operator_name IN ('on', 'before', 'after') THEN
        IF jsonb_typeof(rule->'value') <> 'string'
           OR scalar_value !~ '^\d{4}-\d{2}-\d{2}$'
           OR to_char(scalar_value::date, 'YYYY-MM-DD') <> scalar_value THEN
          RETURN false;
        END IF;
      ELSE
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_rule_outcome_is_valid(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE
  line jsonb;
  portion jsonb;
  optional_id text;
  remainder_count integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object' OR octet_length(value::text) > 100000 THEN
    RETURN false;
  END IF;
  IF value->>'action' = 'exclude' THEN
    RETURN value = '{"action":"exclude"}'::jsonb;
  END IF;
  IF value->>'action' <> 'categorize'
     OR value->>'version' <> '2'
     OR value->>'mode' NOT IN ('auto', 'suggest')
     OR jsonb_typeof(value->'lines') <> 'array'
     OR jsonb_array_length(value->'lines') NOT BETWEEN 1 AND 20 THEN
    RETURN false;
  END IF;

  IF value ? 'partyId' AND coalesce(value->>'partyId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  IF value ? 'memo' AND (jsonb_typeof(value->'memo') <> 'string' OR btrim(value->>'memo') = '' OR length(value->>'memo') > 300) THEN
    RETURN false;
  END IF;

  FOR line IN SELECT element FROM jsonb_array_elements(value->'lines') AS elements(element)
  LOOP
    IF jsonb_typeof(line) <> 'object'
       OR coalesce(line->>'accountId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR jsonb_typeof(line->'portion') <> 'object' THEN
      RETURN false;
    END IF;
    portion := line->'portion';
    IF portion->>'kind' = 'remainder' THEN
      remainder_count := remainder_count + 1;
    ELSIF portion->>'kind' = 'percent' THEN
      IF jsonb_typeof(portion->'value') <> 'number'
         OR (portion->>'value')::numeric <= 0
         OR (portion->>'value')::numeric > 100 THEN
        RETURN false;
      END IF;
    ELSIF portion->>'kind' = 'fixed' THEN
      IF jsonb_typeof(portion->'value') <> 'number' OR (portion->>'value')::numeric <= 0 THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;

    FOREACH optional_id IN ARRAY ARRAY['partyId', 'departmentId', 'projectId', 'locationId', 'classId', 'taxCodeId']
    LOOP
      IF line ? optional_id
         AND coalesce(line->>optional_id, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF line ? 'description'
       AND (jsonb_typeof(line->'description') <> 'string' OR btrim(line->>'description') = '' OR length(line->>'description') > 200) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN remainder_count <= 1;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_bank_statement_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    -- Governed import deletion: the engine holds the account lock, rechecks
    -- the untouched-import fence, and writes the per-row and header audit in
    -- this same transaction.
    IF current_setting('app.statement_import_delete', true) = old.statement_id::text THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'imported bank statement lines are immutable';
  END IF;
  IF tg_op = 'INSERT' THEN
    RETURN new;
  END IF;
  IF to_jsonb(new)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by'
     <> to_jsonb(old)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'possible_duplicate_of'
       - 'updated_at' - 'updated_by' THEN
    -- Governed line correction: the engine holds the line lock, rechecks
    -- unmatched state and the signed-off cutoff, and writes the before/after
    -- audit row in this same transaction.
    IF current_setting('app.statement_correction_line', true) IS DISTINCT FROM old.id::text THEN
      RAISE EXCEPTION 'imported bank statement content is immutable';
    END IF;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM reconciliation_matches m
      JOIN reconciliations r ON r.id = m.reconciliation_id
     WHERE m.statement_line_id = old.id
       AND m.org_id = old.org_id
       AND r.status = 'signed_off'
  ) OR EXISTS (
    SELECT 1
      FROM reconciliations r
     WHERE r.org_id = old.org_id
       AND r.account_id = old.account_id
       AND r.currency = old.currency
       AND r.status = 'signed_off'
       AND r.through_date >= old.posted_on
       AND old.match_status = 'excluded'
  ) THEN
    RAISE EXCEPTION 'signed-off bank statement evidence is immutable';
  END IF;
  IF new.match_status = 'matched'
     AND NOT EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'matched bank statement line requires reconciliation-match evidence';
  END IF;
  IF new.match_status <> 'matched'
     AND EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'bank statement line with match evidence must remain matched';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.openbooks_gl_activity_entry()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_old_in boolean;
  v_new_in boolean;
  v_old_month date;
  v_new_month date;
  v_old_book uuid;
  v_new_book uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'INSERT' then
    if new.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(new.id, new.org_id, date_trunc('month', new.posting_date)::date, 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    if old.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(old.id, old.org_id, date_trunc('month', old.posting_date)::date, -1);
    end if;
    return null;
  end if;
  v_old_in := old.status in ('posted', 'reversed');
  v_new_in := new.status in ('posted', 'reversed');
  v_old_month := date_trunc('month', old.posting_date)::date;
  v_new_month := date_trunc('month', new.posting_date)::date;
  v_old_book := old.book_id;
  v_new_book := new.book_id;
  if v_old_in and not v_new_in then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1);
  elsif v_new_in and not v_old_in then
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  elsif v_old_in and v_new_in and (v_old_month <> v_new_month or v_old_book is distinct from v_new_book) then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1, v_old_book);
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.openbooks_gl_activity_line()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_status text;
  v_date date;
  v_org uuid;
  v_book uuid;
  v_month date;
  v_entry uuid;
  v_line_org uuid;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and public.openbooks_sandbox_wipe_allowed(old.org_id) then
    return null;
  end if;
  if tg_op = 'UPDATE'
     and (new.entry_id, new.org_id) is distinct from (old.entry_id, old.org_id) then
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = old.entry_id and org_id = old.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
        -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
    end if;
    select status, posting_date, org_id, book_id
      into v_status, v_date, v_org, v_book
      from journal_entries
     where id = new.entry_id and org_id = new.org_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
        greatest(new.amount, 0), greatest(-new.amount, 0), 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    v_entry := old.entry_id;
    v_line_org := old.org_id;
  else
    v_entry := new.entry_id;
    v_line_org := new.org_id;
  end if;
  select status, posting_date, org_id, book_id
    into v_status, v_date, v_org, v_book
    from journal_entries
   where id = v_entry and org_id = v_line_org;
  if v_status is null or v_status not in ('posted', 'reversed') then
    return null;
  end if;
  v_month := date_trunc('month', v_date)::date;
  if tg_op in ('UPDATE', 'DELETE') then
    perform openbooks_gl_activity_apply(v_org, old.account_id, v_book, v_month, old.subsidiary_id,
      -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform openbooks_gl_activity_apply(v_org, new.account_id, v_book, v_month, new.subsidiary_id,
      greatest(new.amount, 0), greatest(-new.amount, 0), 1);
  end if;
  return null;
end $function$

