CREATE OR REPLACE FUNCTION public.org_business_calendars_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;
   RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'Business calendar history is preserved; deactivate the version instead of deleting it in Setup → Company → Business calendars'
   USING ERRCODE = '23514';
 END IF;
 IF ROW(OLD.org_id, OLD.id, OLD.subsidiary_id, OLD.week_starts_on, OLD.weekend_days,
         OLD.holiday_country, OLD.holiday_region, OLD.effective_from,
         OLD.created_at, OLD.created_by)
    IS DISTINCT FROM
    ROW(NEW.org_id, NEW.id, NEW.subsidiary_id, NEW.week_starts_on, NEW.weekend_days,
        NEW.holiday_country, NEW.holiday_region, NEW.effective_from,
        NEW.created_at, NEW.created_by) THEN
   RAISE EXCEPTION 'Business calendar versions are immutable; close the window (set its effective-to) and create a new version in Setup → Company → Business calendars'
   USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.ownership_interest_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_parent uuid; bad_account boolean; approved_close boolean:=false;
BEGIN
 SELECT parent_id INTO actual_parent FROM subsidiaries WHERE id=NEW.subsidiary_id AND org_id=NEW.org_id AND is_active AND NOT is_elimination;
 IF actual_parent IS DISTINCT FROM NEW.parent_subsidiary_id OR NOT EXISTS(SELECT 1 FROM subsidiaries WHERE id=NEW.parent_subsidiary_id AND org_id=NEW.org_id AND is_active AND NOT is_elimination) THEN RAISE EXCEPTION 'ownership interest must follow the active tenant consolidation hierarchy'; END IF;
 SELECT EXISTS(SELECT 1 FROM unnest(array_remove(ARRAY[NEW.investment_account_id,NEW.equity_income_account_id,NEW.distribution_account_id,NEW.distribution_income_account_id,NEW.nci_equity_account_id,NEW.nci_income_account_id,NEW.goodwill_account_id,NEW.fair_value_adjustment_account_id],NULL)) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM accounts a WHERE a.id=wanted.id AND a.org_id=NEW.org_id AND a.is_active AND NOT a.is_summary)) INTO bad_account;
 IF bad_account THEN RAISE EXCEPTION 'ownership accounts must be active postable accounts in the tenant'; END IF;
 IF NEW.method='full' AND NEW.ownership_percent<100 AND (NEW.nci_equity_account_id IS NULL OR NEW.nci_income_account_id IS NULL) THEN RAISE EXCEPTION 'full consolidation below 100 percent requires NCI equity and income accounts'; END IF;
 IF NEW.method='full' AND (NEW.goodwill_account_id IS NULL OR NEW.fair_value_adjustment_account_id IS NULL) THEN RAISE EXCEPTION 'full consolidation requires goodwill and fair-value adjustment accounts'; END IF;
 IF NEW.distribution_account_id IS NOT NULL AND NEW.distribution_income_account_id IS NULL THEN RAISE EXCEPTION 'distribution income account is required when a distribution account is configured'; END IF;
 -- A new full policy alone does not book a new acquisition or reopen the
 -- disposed reporting window. Do not silently reconsolidate from stale basis.
 IF NEW.method='full' AND NEW.is_active AND EXISTS(SELECT 1 FROM consolidation_control_losses loss WHERE loss.org_id=NEW.org_id AND loss.subsidiary_id=NEW.subsidiary_id AND loss.reversed_by_change_id IS NULL AND NEW.effective_from>loss.effective_on) THEN RAISE EXCEPTION 'a full reacquisition requires new acquisition accounting; a policy-only change cannot reopen the disposed group. For an erroneous disposal use its approved correction in Accounting changes'; END IF;
 IF TG_OP='UPDATE' THEN
  approved_close:=NEW.effective_to IS NOT NULL AND NEW.effective_to>=OLD.effective_from AND (OLD.effective_to IS NULL OR NEW.effective_to<=OLD.effective_to) AND NEW.last_change_id IS DISTINCT FROM OLD.last_change_id AND EXISTS(SELECT 1 FROM financial_changes f WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.domain='consolidation' AND f.operation='loss_of_control' AND f.subject_id=OLD.id AND f.effective_on=NEW.effective_to AND f.status='approved') AND (to_jsonb(NEW)-ARRAY['effective_to','last_change_id','updated_at','updated_by']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['effective_to','last_change_id','updated_at','updated_by']);
  approved_close:=approved_close OR (NEW.last_change_id IS DISTINCT FROM OLD.last_change_id AND EXISTS(SELECT 1 FROM financial_changes f JOIN consolidation_control_losses loss ON loss.org_id=f.org_id AND loss.change_id::text=f.payload->>'sourceChangeId' WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.domain='consolidation' AND f.operation='reversal' AND f.status='approved' AND loss.interest_id=OLD.id AND loss.reversed_by_change_id=f.id AND NEW.effective_to IS NOT DISTINCT FROM (loss.measurement->>'originalEffectiveTo')::date) AND (to_jsonb(NEW)-ARRAY['effective_to','last_change_id','updated_at','updated_by']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['effective_to','last_change_id','updated_at','updated_by']));
  approved_close:=approved_close OR (OLD.is_active AND NOT NEW.is_active AND EXISTS(SELECT 1 FROM financial_changes f JOIN consolidation_control_losses loss ON loss.org_id=f.org_id AND loss.change_id::text=f.payload->>'sourceChangeId' WHERE f.org_id=OLD.org_id AND f.id=NEW.last_change_id AND f.domain='consolidation' AND f.operation='reversal' AND f.status='approved' AND loss.retained_interest_id=OLD.id AND loss.reversed_by_change_id=f.id) AND (to_jsonb(NEW)-ARRAY['is_active','last_change_id','updated_at','updated_by']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['is_active','last_change_id','updated_at','updated_by']));
  IF EXISTS(SELECT 1 FROM ownership_consolidation_entries WHERE interest_id=OLD.id) AND (to_jsonb(NEW)-ARRAY['updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','updated_by']) AND NOT approved_close THEN RAISE EXCEPTION 'used ownership policy is immutable; propose an approved loss-of-control change or retain the existing historical terms'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.party_subsidiary_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if not exists (select 1 from parties p where p.id = new.party_id and p.org_id = new.org_id) then
    raise exception 'party belongs to another organization' using errcode = '23514';
  end if;
  if not exists (
    select 1 from subsidiaries s
     where s.id = new.subsidiary_id and s.org_id = new.org_id and not s.is_elimination
  ) then
    raise exception 'party subsidiary is invalid' using errcode = '23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.pay_component_earning_classifications_prevent_orphan_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF EXISTS(SELECT 1 FROM public.pay_components WHERE org_id=OLD.org_id AND id=OLD.pay_component_id) THEN
  RAISE EXCEPTION 'Pay component classifications cannot be deleted independently; edit the native component classification instead.';
 END IF;
 RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION public.pay_component_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  -- Permit the owning tenant's cascade deletion, never an ordinary component
  -- deletion that would SET NULL on historical stub lines.
  IF TG_OP = 'DELETE' AND NOT EXISTS (
    SELECT 1 FROM public.orgs WHERE id = OLD.org_id
  ) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW IS DISTINCT FROM OLD THEN
      -- All component inputs participate in calculation freshness, including
      -- prospective flags whose monetary results are already snapshotted.
      NEW.updated_at := clock_timestamp();
    END IF;
    IF ROW(NEW.id, NEW.org_id, NEW.kind, NEW.system_key, NEW.country,
           NEW.taxable, NEW.tax_treatment)
       IS NOT DISTINCT FROM
       ROW(OLD.id, OLD.org_id, OLD.kind, OLD.system_key, OLD.country,
           OLD.taxable, OLD.tax_treatment) THEN
      RETURN NEW;
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pay_stub_lines l
    JOIN public.pay_stubs s ON s.org_id = l.org_id AND s.id = l.stub_id
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
     WHERE l.org_id = OLD.org_id AND l.component_id = OLD.id
       AND r.run_status IN ('committed', 'voided')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'pay_component_historical_policy',
      MESSAGE = 'Pay component tax classification is fixed after committed payroll. Preserve this component and use a new policy for future payroll; historical corrections require a controlled adjustment.';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  -- Raw SQL writers must also invalidate an existing calculation. A caller's
  -- old transaction timestamp must not hide a later policy edit.
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.pay_component_non_cash_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE offset_type text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.payment_kind IS DISTINCT FROM OLD.payment_kind AND EXISTS (
    SELECT 1 FROM public.hrm_benefit_programs p WHERE p.org_id = OLD.org_id AND p.pay_component_id = OLD.id
      AND (p.status = 'active' OR EXISTS (
        SELECT 1 FROM public.hrm_benefit_awards a WHERE a.org_id = p.org_id AND a.program_id = p.id
          AND a.status IN ('approved', 'queued', 'delivered')
      ))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'An active benefit program or approved benefit obligation uses this cash representation; preserve its component and create a new program and component for a different delivery policy.';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.payment_kind IS DISTINCT FROM OLD.payment_kind AND EXISTS (
    SELECT 1 FROM public.pay_stub_lines l JOIN public.pay_stubs s ON s.org_id = l.org_id AND s.id = l.stub_id
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
    WHERE l.org_id = OLD.org_id AND l.component_id = OLD.id AND r.run_status IN ('committed', 'voided')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A pay component cash representation is fixed after committed payroll; preserve this component and create a new component for future earnings.';
  END IF;
  IF NEW.payment_kind = 'non_cash' THEN
    SELECT a.type INTO offset_type FROM public.accounts a
     WHERE a.org_id = NEW.org_id AND a.id = NEW.non_cash_account_id AND a.is_active AND NOT a.is_summary;
    IF offset_type IS NULL OR offset_type NOT IN (
      'asset_current_other', 'asset_other', 'liability_current_other', 'liability_long_term',
      'cogs', 'expense', 'expense_other'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A non-cash earning requires an active posting prepaid asset, provider clearing liability, or contra-expense account as its offset.';
    END IF;
    IF offset_type IN ('cogs', 'expense', 'expense_other') AND NEW.non_cash_account_id = NEW.expense_account_id THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A contra-expense offset must be a different account from the earning''s expense account; posting both sides to one account records nothing.';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.pay_component_statutory_treatment_clone_matches(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target record;
  original jsonb;
  expected jsonb;
  column_row record;
BEGIN
  IF NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
  SELECT org.sandbox_of, org.sandbox_seed
    INTO target
    FROM public.orgs org
    JOIN public.sandboxes sandbox
      ON sandbox.org_id = org.id AND sandbox.production_org_id = org.sandbox_of
   WHERE org.id = (candidate->>'org_id')::uuid
     AND org.env_kind = 'sandbox'
     AND org.sandbox_seed IS NOT NULL;
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT to_jsonb(source)
    INTO original
    FROM public.pay_component_statutory_treatments source
   WHERE source.org_id = target.sandbox_of
     AND public.ob_rebase(source.id, target.sandbox_seed) = (candidate->>'id')::uuid;
  IF original IS NULL THEN RETURN false; END IF;

  expected := original;
  FOR column_row IN
    SELECT attribute.attname, attribute.atttypid
      FROM pg_catalog.pg_attribute attribute
     WHERE attribute.attrelid = 'public.pay_component_statutory_treatments'::regclass
       AND attribute.attnum > 0 AND NOT attribute.attisdropped
  LOOP
    IF column_row.attname = 'org_id' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb((candidate->>'org_id')::uuid));
    ELSIF column_row.atttypid = 'uuid'::regtype
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb(public.ob_rebase(
        (original->>column_row.attname)::uuid, target.sandbox_seed
      )));
    END IF;
  END LOOP;
  RETURN candidate = expected;
END
$function$

CREATE OR REPLACE FUNCTION public.pay_stub_filing_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.filing_account_source = 'unknown' THEN
      -- Old application writers still capture attribution at INSERT, before
      -- any subsequent profile/default edit. This is not a legacy backfill.
      SELECT coalesce(prof.filing_account_id,
        (SELECT fa.id FROM public.payroll_filing_accounts fa
          WHERE fa.org_id = NEW.org_id AND fa.country = NEW.country
            AND fa.is_active AND fa.is_default))
        INTO NEW.filing_account_id
        FROM public.employee_payroll_profiles prof
       WHERE prof.org_id = NEW.org_id AND prof.employee_party_id = NEW.employee_party_id;
      NEW.filing_account_source := 'insertion';
    END IF;
    IF NEW.filing_account_source NOT IN ('calculation', 'insertion') THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_historical_filing_account',
        MESSAGE = 'New payroll must capture its filing account at calculation or insertion.';
    END IF;
  ELSE
    IF ROW(NEW.org_id, NEW.filing_account_id, NEW.filing_account_source, NEW.filing_account_evidence)
       IS NOT DISTINCT FROM
       ROW(OLD.org_id, OLD.filing_account_id, OLD.filing_account_source, OLD.filing_account_evidence) THEN
      RETURN NEW;
    END IF;
    IF OLD.filing_account_source <> 'unknown' OR NEW.filing_account_source <> 'reconciled'
       OR NEW.updated_by IS NULL
       OR (to_jsonb(NEW) - ARRAY['filing_account_id','filing_account_source','filing_account_evidence','updated_at','updated_by'])
          IS DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['filing_account_id','filing_account_source','filing_account_evidence','updated_at','updated_by']) THEN
      RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_historical_filing_account',
        MESSAGE = 'Payroll filing attribution is immutable. Only unknown legacy attribution can be reconciled with original evidence, a reason, and an actor.';
    END IF;
    NEW.updated_at := clock_timestamp();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
    VALUES (NEW.org_id, 'pay_stubs', NEW.id, 'update',
      jsonb_build_object('operation', 'reconcile_filing_account', 'before', to_jsonb(OLD),
                        'after', to_jsonb(NEW), 'evidence', NEW.filing_account_evidence), NEW.updated_by);
  END IF;

  IF NEW.filing_account_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.payroll_filing_accounts fa
     WHERE fa.org_id = NEW.org_id AND fa.id = NEW.filing_account_id
       AND fa.country = NEW.country
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'pay_stub_filing_account_country',
      MESSAGE = 'Payroll filing account must belong to the stub organization and country.';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.pay_stub_line_derived_quantity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE run_state text;
BEGIN
  IF ROW(NEW.derived_quantity, NEW.derived_rule_code)
      IS NOT DISTINCT FROM ROW(OLD.derived_quantity, OLD.derived_rule_code) THEN
    RETURN NEW;
  END IF;
  SELECT r.run_status INTO run_state FROM public.pay_stubs s
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
    WHERE s.org_id = OLD.org_id AND s.id = OLD.stub_id FOR SHARE OF r;
  IF run_state IS NULL OR run_state NOT IN ('draft', 'calculated') THEN
    RAISE EXCEPTION 'Derived payroll quantity evidence is immutable after posting; use a governed payroll correction.';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.pay_stub_line_liability_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE committed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.liability_account_source = 'reconciled' THEN
      RAISE EXCEPTION 'Liability reconciliation must resolve an existing unknown payroll line.' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.org_id,NEW.liability_account_id,NEW.liability_account_source,NEW.liability_account_evidence)
     IS NOT DISTINCT FROM ROW(OLD.org_id,OLD.liability_account_id,OLD.liability_account_source,OLD.liability_account_evidence) THEN
    RETURN NEW;
  END IF;
  IF OLD.liability_account_source <> 'unknown' THEN
    RAISE EXCEPTION 'The liability account a committed payroll line accrued to is immutable.' USING ERRCODE='23514';
  END IF;
  SELECT r.run_status='committed' INTO committed FROM public.pay_stubs s
    JOIN public.pay_runs r ON r.org_id=s.org_id AND r.document_id=s.pay_run_document_id
   WHERE s.org_id=OLD.org_id AND s.id=OLD.stub_id;
  IF NEW.liability_account_source = 'commit' AND committed IS FALSE AND NEW.org_id=OLD.org_id THEN
    RETURN NEW; -- normal commit captures its account before marking the run committed
  END IF;
  IF NEW.liability_account_source <> 'reconciled' OR committed IS NOT TRUE OR NEW.updated_by IS NULL
     OR OLD.kind NOT IN ('deduction','employer_contribution')
     OR (to_jsonb(NEW) - ARRAY['liability_account_id','liability_account_source','liability_account_evidence','updated_at','updated_by'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['liability_account_id','liability_account_source','liability_account_evidence','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'Only unknown committed liabilities may be reconciled, with original evidence and without changing payroll amounts.' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.liability_account_id
    AND NOT a.is_summary AND a.type LIKE 'liability%') THEN
    RAISE EXCEPTION 'Historical payroll liability must reference a posting liability account in the same organization.' USING ERRCODE='23514';
  END IF;
  NEW.updated_at := clock_timestamp();
  INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
  VALUES(NEW.org_id,'pay_stub_lines',NEW.id,'update',jsonb_build_object(
    'operation','reconcile_liability_account','before',to_jsonb(OLD),'after',to_jsonb(NEW),
    'evidence',NEW.liability_account_evidence),NEW.updated_by);
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.pay_stub_line_payment_kind_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE component_payment_kind text; component_non_cash_account uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.kind = 'earning' AND NEW.component_id IS NOT NULL THEN
      SELECT payment_kind, non_cash_account_id INTO component_payment_kind, component_non_cash_account
        FROM public.pay_components WHERE org_id = NEW.org_id AND id = NEW.component_id;
      IF component_payment_kind IS NOT NULL AND (
        NEW.payment_kind IS DISTINCT FROM component_payment_kind OR
        (component_payment_kind = 'non_cash' AND NEW.non_cash_account_id IS DISTINCT FROM component_non_cash_account)
      ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'The calculated earning cash representation must match its configured component. Update the payroll application and recalculate; a non-cash benefit must never also be paid as cash.';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.payment_kind, NEW.non_cash_account_id) IS DISTINCT FROM ROW(OLD.payment_kind, OLD.non_cash_account_id)
     AND EXISTS (SELECT 1 FROM public.pay_stubs s JOIN public.pay_runs r
       ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
       WHERE s.org_id = OLD.org_id AND s.id = OLD.stub_id AND r.run_status IN ('committed', 'voided')) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'The cash representation and clearing account of a committed payroll line are immutable; use a correcting payroll run.';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.payment_acceptance_account_reference_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  account_row record;
  rule_row record;
BEGIN
  IF TG_TABLE_NAME = 'psp_provider_configs' THEN
    IF NEW.default_bank_account_id IS NOT NULL THEN
      SELECT org_id, type, is_active, is_summary
        INTO account_row
        FROM public.accounts
       WHERE id = NEW.default_bank_account_id;
      IF NOT FOUND OR account_row.org_id IS DISTINCT FROM NEW.org_id
         OR account_row.type IS DISTINCT FROM 'asset_bank'
         OR NOT account_row.is_active OR account_row.is_summary THEN
        RAISE EXCEPTION 'provider default bank account must be an active, postable asset_bank account owned by the provider organization'
          USING ERRCODE = '23514';
      END IF;
    END IF;
    IF NEW.surcharge_rule_id IS NOT NULL THEN
      SELECT org_id, is_active, provider
        INTO rule_row
        FROM public.payment_surcharge_rules
       WHERE id = NEW.surcharge_rule_id;
      IF NOT FOUND OR rule_row.org_id IS DISTINCT FROM NEW.org_id
         OR NOT rule_row.is_active
         OR (rule_row.provider IS NOT NULL AND rule_row.provider IS DISTINCT FROM NEW.provider) THEN
        RAISE EXCEPTION 'provider surcharge rule must be active, provider-compatible, and owned by the provider organization'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'payment_surcharge_rules' THEN
    SELECT org_id, type, is_active, is_summary
      INTO account_row
      FROM public.accounts
     WHERE id = NEW.fee_income_account_id;
    IF NOT FOUND OR account_row.org_id IS DISTINCT FROM NEW.org_id
       OR account_row.type NOT IN ('income', 'income_other')
       OR NOT account_row.is_active OR account_row.is_summary THEN
      RAISE EXCEPTION 'surcharge fee account must be an active, postable income account owned by the rule organization'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'payment_links' THEN
    SELECT org_id, type, is_active, is_summary
      INTO account_row
      FROM public.accounts
     WHERE id = NEW.bank_account_id;
    IF NOT FOUND OR account_row.org_id IS DISTINCT FROM NEW.org_id
       OR account_row.type IS DISTINCT FROM 'asset_bank'
       OR NOT account_row.is_active OR account_row.is_summary THEN
      RAISE EXCEPTION 'payment link bank account must be an active, postable asset_bank account owned by the link organization'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.payment_event_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'payment events are append-only';
end $function$

CREATE OR REPLACE FUNCTION public.payment_run_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_status text;
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  select status into v_status from payment_runs where id = coalesce(new.payment_run_id, old.payment_run_id);
  if tg_op = 'DELETE' and v_status not in ('draft', 'pending_approval')
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'payment run items are immutable once the run is approved';
  end if;
  if tg_op = 'UPDATE' and v_status not in ('draft', 'pending_approval') and (
     new.payment_run_id is distinct from old.payment_run_id
     or new.payment_instruction_id is distinct from old.payment_instruction_id
     or new.source_document_id is distinct from old.source_document_id
     or new.source_open_line_id is distinct from old.source_open_line_id
     or new.kind is distinct from old.kind
     or new.gross_amount is distinct from old.gross_amount
     or new.discount_amount is distinct from old.discount_amount
     or new.credit_amount is distinct from old.credit_amount
     or new.payment_amount is distinct from old.payment_amount
     or new.currency is distinct from old.currency
     or new.fx_rate is distinct from old.fx_rate) then
    raise exception 'payment run item composition is immutable once the run is approved';
  end if;
  return coalesce(new, old);
end $function$

CREATE OR REPLACE FUNCTION public.payroll_annual_period_bounds_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE period_opening record; amount record;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 FOR period_opening IN SELECT annual_bounds FROM public.payroll_period_openings
  WHERE org_id=OLD.org_id AND annual_opening_balance_id=OLD.id LOOP
  IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'Annual balances referenced by same-period payments must be retained; save explicit zero balances after clearing the unused period amounts.';
  END IF;
  FOR amount IN SELECT key,value FROM jsonb_each_text(period_opening.annual_bounds) LOOP
   IF amount.key LIKE 'program:%' THEN CONTINUE; END IF;
   IF (to_jsonb(NEW)->amount.key) IS NULL OR (to_jsonb(NEW)->>amount.key)::numeric<amount.value::numeric THEN
    RAISE EXCEPTION 'Annual opening balances cannot be reduced below their admitted period payments; correct the unused period amounts first.';
   END IF;
  END LOOP;
 END LOOP;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_ca_opening_reporting_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' OR (NEW.org_id,NEW.id,NEW.country,NEW.program_type,NEW.subsidiary_id,NEW.account_number)
    IS DISTINCT FROM (OLD.org_id,OLD.id,OLD.country,OLD.program_type,OLD.subsidiary_id,OLD.account_number) THEN
  IF EXISTS (SELECT 1 FROM public.payroll_ca_opening_reporting_allocations a WHERE a.org_id=OLD.org_id AND a.filing_account_id=OLD.id)
    OR EXISTS (SELECT 1 FROM public.payroll_ca_opening_reporting_authorities h
      CROSS JOIN LATERAL jsonb_array_elements(h.opening_children_snapshot->'accountBases') child(value)
      WHERE h.org_id=OLD.org_id AND child.value->>'filing_account_id'=OLD.id::text) THEN
   RAISE EXCEPTION 'Original Canadian reporting preserves its RP account and legal employer; create a distinct account for new identity' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_ca_opening_reporting_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE authority public.payroll_ca_opening_reporting_authorities%ROWTYPE; family text; child jsonb; amount_key text;
 child_identity jsonb; keys text[]; row_count integer;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Original Canadian reporting slices are immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO authority FROM public.payroll_ca_opening_reporting_authorities h WHERE h.org_id=NEW.org_id AND h.id=NEW.authority_id FOR UPDATE;
 IF authority.id IS NULL OR authority.sealed OR NEW.created_by<>authority.created_by
   OR NEW.first_covered_pay_date NOT BETWEEN authority.coverage_start AND authority.coverage_end THEN
   RAISE EXCEPTION 'Write source-attested slices within the original coverage before sealing the certificate' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.payroll_filing_accounts f WHERE f.org_id=NEW.org_id AND f.id=NEW.filing_account_id
   AND f.country='CA' AND f.program_type='ca_rp' AND f.subsidiary_id=authority.subsidiary_id FOR SHARE) THEN
   RAISE EXCEPTION 'Original RP must belong to the exact Canadian legal employer' USING ERRCODE='23514';
 END IF;
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(NEW.annual_amounts) key)
    IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(authority.annual_amounts) key)
   OR EXISTS (SELECT 1 FROM jsonb_each(NEW.annual_amounts) a WHERE jsonb_typeof(a.value)<>'string'
      OR (a.value#>>'{}') !~ '^(0|[1-9][0-9]*)(\.[0-9]{1,4})?$')
   OR (NEW.province<>'QC' AND EXISTS (SELECT 1 FROM jsonb_each_text(NEW.annual_amounts) a
     WHERE a.key IN ('qpip_ytd','qpip_employer_ytd','qc_tax_ytd','qc_csb_ytd','ca_avg_qpip','ca_avg_bonus_qpip') AND a.value::numeric<>0)) THEN
   RAISE EXCEPTION 'Declare all original annual fields as exact nonnegative decimals in their original jurisdiction' USING ERRCODE='23514';
 END IF;

 IF jsonb_typeof(NEW.reportable_bases) IS DISTINCT FROM 'object'
   OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(NEW.reportable_bases) key) IS DISTINCT FROM ARRAY['cpp','ei','qpip']::text[]
   OR EXISTS (SELECT 1 FROM jsonb_each(NEW.reportable_bases) r WHERE jsonb_typeof(r.value)<>'string' OR (r.value#>>'{}') !~ '^(0|[1-9][0-9]*)(\.[0-9]{1,4})?$')
   OR (NEW.reportable_bases->>'ei')::numeric>(NEW.annual_amounts->>'insurable_ytd')::numeric
   OR (NEW.reportable_bases->>'cpp')::numeric>(NEW.annual_amounts->>'pensionable_ytd')::numeric
   OR (NEW.reportable_bases->>'qpip')::numeric>coalesce((SELECT sum((r->>'insurable_ytd')::numeric) FROM jsonb_array_elements(NEW.children->'programBases') r WHERE r->>'program_key'='qpip'),0)
   OR NEW.province<>'QC' AND (NEW.reportable_bases->>'qpip')::numeric<>0 THEN
   RAISE EXCEPTION 'Declare exact source-attested reported bases within their allocated original earnings' USING ERRCODE='23514';
 END IF;
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(NEW.children) key)
    IS DISTINCT FROM ARRAY['accountBases','components','programBases','suiStates']::text[] THEN
   RAISE EXCEPTION 'Declare all four original opening child families' USING ERRCODE='23514';
 END IF;
 FOREACH family IN ARRAY ARRAY['components','programBases','accountBases','suiStates'] LOOP
   IF jsonb_typeof(NEW.children->family) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Declare original child arrays including explicit empty arrays' USING ERRCODE='23514'; END IF;
   amount_key := CASE WHEN family='components' THEN 'ytd_amount' ELSE 'insurable_ytd' END;
   keys := CASE family WHEN 'components' THEN ARRAY['component_id','ytd_amount']
      WHEN 'programBases' THEN ARRAY['insurable_ytd','program_key']
      WHEN 'accountBases' THEN ARRAY['filing_account_id','insurable_ytd','program_key','region'] ELSE ARRAY['insurable_ytd','state'] END;
   IF jsonb_array_length(NEW.children->family)<>jsonb_array_length(authority.opening_children_snapshot->family) THEN
    RAISE EXCEPTION 'Every slice requires all original child identities including zeros' USING ERRCODE='23514';
   END IF;
   FOR child IN SELECT value FROM jsonb_array_elements(NEW.children->family) LOOP
    IF jsonb_typeof(child)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(child) key) IS DISTINCT FROM keys
      OR jsonb_typeof(child->amount_key) IS DISTINCT FROM 'string' OR child->>amount_key !~ '^(0|[1-9][0-9]*)(\.[0-9]{1,4})?$' THEN
     RAISE EXCEPTION 'Original child slices require exact native identities and nonnegative decimal amounts' USING ERRCODE='23514';
    END IF;
    child_identity := public.payroll_ca_opening_reporting_child_identity(family,child);
    SELECT count(*) INTO row_count FROM jsonb_array_elements(NEW.children->family) r WHERE public.payroll_ca_opening_reporting_child_identity(family,r.value)=child_identity;
    IF row_count<>1 OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(authority.opening_children_snapshot->family) r
       WHERE public.payroll_ca_opening_reporting_child_identity(family,r.value)=child_identity) THEN
     RAISE EXCEPTION 'Reporting slices cannot omit, repeat or invent original child identities' USING ERRCODE='23514';
    END IF;
    IF family='components' AND NOT EXISTS (SELECT 1 FROM public.pay_components c
      WHERE c.org_id=NEW.org_id AND c.id=(child->>'component_id')::uuid AND (c.country IS NULL OR c.country='CA')) THEN
     RAISE EXCEPTION 'Original reporting component must be a native Canadian or common component' USING ERRCODE='23514';
    END IF;
    IF family IN ('programBases','accountBases') AND (child->>'program_key'<>'qpip'
       OR NEW.province<>'QC' AND (child->>amount_key)::numeric<>0) THEN
     RAISE EXCEPTION 'Original program base must resolve to the Canadian program and original jurisdiction' USING ERRCODE='23514';
    END IF;
    IF family='accountBases' AND ((child->'region'<>'null'::jsonb AND (jsonb_typeof(child->'region')<>'string'
       OR child->>'region' NOT IN ('AB','BC','MB','NB','NL','NS','NT','NU','ON','PE','QC','SK','YT','ZZ')))
      OR NOT EXISTS (SELECT 1 FROM public.payroll_filing_accounts f
      WHERE f.org_id=NEW.org_id AND f.id=(child->>'filing_account_id')::uuid AND f.country='CA' AND f.program_type='ca_rp'
       AND f.subsidiary_id=authority.subsidiary_id)
      OR (child->>amount_key)::numeric<>0 AND ((child->>'filing_account_id')::uuid<>NEW.filing_account_id
        OR child->>'region' IS NOT NULL AND child->>'region'<>NEW.province)) THEN
     RAISE EXCEPTION 'Original account bases cannot be moved between RP accounts or provinces' USING ERRCODE='23514';
    END IF;
    IF family='suiStates' AND (child->>amount_key)::numeric<>0 THEN RAISE EXCEPTION 'Canadian original reporting cannot contain US state unemployment wages' USING ERRCODE='23514'; END IF;
   END LOOP;
 END LOOP;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_ca_opening_reporting_authority_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
 levy public.payroll_opening_levy_source_authorities%ROWTYPE;
 employer public.payroll_opening_employer_authorities%ROWTYPE;
 retained jsonb; actual jsonb; family text; amount_key text; original_row jsonb; identity jsonb; original_value text;
 source_version uuid; allocated_total numeric; slice_count integer;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original Canadian opening reporting evidence is immutable' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-opening-source:'||NEW.org_id::text||':'||NEW.tax_year::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id::text||':'||NEW.employee_party_id::text||':'||NEW.tax_year::text,0));
 IF TG_OP='UPDATE' AND (OLD.sealed OR NOT NEW.sealed
   OR (to_jsonb(NEW)-ARRAY['sealed','allocation_snapshot','allocation_sha256'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['sealed','allocation_snapshot','allocation_sha256'])) THEN
   RAISE EXCEPTION 'Original Canadian opening reporting authority can only be sealed once' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND NEW.sealed THEN RAISE EXCEPTION 'Seal original reporting after writing its complete slices' USING ERRCODE='23514'; END IF;
 SELECT * INTO levy FROM public.payroll_opening_levy_source_authorities h
  WHERE h.org_id=NEW.org_id AND h.id=NEW.levy_authority_id AND h.sealed
    AND NOT EXISTS (SELECT 1 FROM public.payroll_opening_levy_source_authorities successor
      WHERE successor.org_id=h.org_id AND successor.supersedes_authority_id=h.id) FOR SHARE;
 SELECT * INTO employer FROM public.payroll_opening_employer_authorities e
  WHERE e.org_id=NEW.org_id AND e.id=NEW.employer_authority_id FOR SHARE;
 SELECT to_jsonb(b) INTO retained FROM public.payroll_opening_balances b
  WHERE b.org_id=NEW.org_id AND b.id=NEW.opening_balance_id FOR SHARE;
 IF levy.id IS NULL OR employer.id IS NULL OR retained IS NULL
   OR (levy.opening_balance_id,levy.employer_authority_id,levy.employee_party_id,levy.tax_year,levy.subsidiary_id,levy.original_country,levy.original_currency,levy.coverage_start,levy.coverage_end)
      IS DISTINCT FROM (NEW.opening_balance_id,NEW.employer_authority_id,NEW.employee_party_id,NEW.tax_year,NEW.subsidiary_id,NEW.original_country,NEW.original_currency,NEW.coverage_start,NEW.coverage_end)
   OR NOT levy.coverage_complete OR levy.allocation_sha256<>NEW.levy_allocation_sha256
   OR levy.allocation_sha256<>encode(public.digest(levy.allocation_snapshot::text,'sha256'),'hex')
   OR levy.allocation_snapshot IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_object(
      'programKey',a.program_key,'region',a.region,'subRegion',a.sub_region,'filingAccountId',a.filing_account_id,
      'federalAccountId',a.federal_account_id,'amount',a.amount::text)
      ORDER BY a.program_key,a.region,a.sub_region,a.filing_account_id NULLS FIRST,a.federal_account_id NULLS FIRST),'[]'::jsonb)
      FROM public.payroll_opening_levy_source_allocations a WHERE a.org_id=levy.org_id AND a.authority_id=levy.id)
   OR employer.opening_balance_id<>NEW.opening_balance_id OR employer.employee_party_id<>NEW.employee_party_id
   OR employer.tax_year<>NEW.tax_year OR employer.subsidiary_id<>NEW.subsidiary_id
   OR NEW.opening_snapshot IS DISTINCT FROM retained OR employer.opening_snapshot IS DISTINCT FROM retained
   OR NEW.opening_sha256<>encode(public.digest(retained::text,'sha256'),'hex')
   OR employer.opening_sha256<>NEW.opening_sha256 OR levy.opening_sha256<>NEW.opening_sha256
   OR NEW.annual_amounts IS DISTINCT FROM public.payroll_ca_opening_reporting_annual(retained)
   OR NEW.opening_children_snapshot IS DISTINCT FROM public.payroll_opening_source_children(NEW.org_id,NEW.opening_balance_id,NEW.employee_party_id,NEW.tax_year)
   OR levy.opening_children_snapshot IS DISTINCT FROM NEW.opening_children_snapshot
   OR NEW.opening_children_sha256<>encode(public.digest(NEW.opening_children_snapshot::text,'sha256'),'hex')
   OR levy.opening_children_sha256<>NEW.opening_children_sha256 THEN
   RAISE EXCEPTION 'Resolve the exact current Canadian levy certificate, original payer and unchanged annual and child history' USING ERRCODE='23514';
 END IF;
 IF (NEW.annual_amounts->>'fica_withheld_ytd')::numeric IS DISTINCT FROM 0 THEN
   RAISE EXCEPTION 'Original Canadian reporting cannot contain foreign statutory annual amounts' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
     WHERE f.org_id=levy.org_id AND f.id=levy.source_file_id AND v.id=levy.source_version_id AND v.content_hash=levy.source_sha256)
   OR NOT EXISTS (SELECT 1 FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
     WHERE f.org_id=employer.org_id AND f.id=employer.source_file_id AND v.id=employer.source_version_id AND v.content_hash=employer.source_sha256) THEN
   RAISE EXCEPTION 'Retained original levy and payer evidence is unavailable' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
   SELECT v.id INTO source_version FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
    WHERE f.org_id=NEW.org_id AND f.id=NEW.source_file_id AND f.current_version_id=NEW.source_version_id AND NOT f.is_inactive
      AND v.id=NEW.source_version_id AND v.content_hash=NEW.source_sha256 AND v.created_by=NEW.created_by FOR SHARE OF f,v;
   IF source_version IS NULL THEN RAISE EXCEPTION 'Select the current original Cabinet file version uploaded by this operator' USING ERRCODE='23514'; END IF;
   IF EXISTS (SELECT 1 FROM public.payroll_filing_submissions WHERE org_id=NEW.org_id AND tax_year=NEW.tax_year)
     OR EXISTS (SELECT 1 FROM public.pay_runs r JOIN public.documents d ON d.org_id=r.org_id AND d.id=r.document_id
       WHERE r.org_id=NEW.org_id AND r.tax_year=NEW.tax_year AND r.run_status='committed' AND d.status<>'voided'
       AND (d.subsidiary_id=NEW.subsidiary_id OR EXISTS (SELECT 1 FROM public.pay_stubs s
         WHERE s.org_id=r.org_id AND s.pay_run_document_id=r.document_id AND s.employee_party_id=NEW.employee_party_id))) THEN
     RAISE EXCEPTION 'Issued filings or committed payroll preserve this original source; original reporting adoption is unavailable' USING ERRCODE='23514';
   END IF;
   RETURN NEW;
 END IF;
 actual := public.payroll_ca_opening_reporting_allocations_snapshot(NEW.org_id,NEW.id);
 IF actual IS DISTINCT FROM NEW.allocation_snapshot OR jsonb_array_length(actual)=0
   OR NEW.allocation_sha256<>encode(public.digest(actual::text,'sha256'),'hex') THEN
   RAISE EXCEPTION 'Seal every exact Canadian reporting slice with its native allocation digest' USING ERRCODE='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM (SELECT first_covered_pay_date,
    lag(first_covered_pay_date) OVER (ORDER BY source_ordinal) AS previous_date
    FROM public.payroll_ca_opening_reporting_allocations WHERE org_id=NEW.org_id AND authority_id=NEW.id) ordered
    WHERE first_covered_pay_date<previous_date) THEN
   RAISE EXCEPTION 'Source ordinal must preserve original first covered pay date chronology' USING ERRCODE='23514';
 END IF;
 FOR original_row IN SELECT jsonb_build_object('key',key,'value',value) FROM jsonb_each(NEW.annual_amounts) LOOP
   SELECT sum((a.annual_amounts->>(original_row->>'key'))::numeric) INTO allocated_total
    FROM public.payroll_ca_opening_reporting_allocations a WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id;
   IF allocated_total IS DISTINCT FROM (original_row->>'value')::numeric THEN
    RAISE EXCEPTION 'Reporting annual slices must equal every exact original annual amount' USING ERRCODE='23514';
   END IF;
 END LOOP;

 IF NEW.tax_year<>2026 THEN RAISE EXCEPTION 'Original reporting year has no declared Canadian annual maxima' USING ERRCODE='23514'; END IF;
 IF (SELECT sum((a.reportable_bases->>'ei')::numeric) FROM public.payroll_ca_opening_reporting_allocations a WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id)
      IS DISTINCT FROM least((NEW.annual_amounts->>'insurable_ytd')::numeric,68900::numeric)
   OR (SELECT sum((a.reportable_bases->>'cpp')::numeric) FROM public.payroll_ca_opening_reporting_allocations a WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id)
      IS DISTINCT FROM least((NEW.annual_amounts->>'pensionable_ytd')::numeric,85000::numeric)
   OR (SELECT sum((a.reportable_bases->>'qpip')::numeric) FROM public.payroll_ca_opening_reporting_allocations a WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id)
      IS DISTINCT FROM least(coalesce((SELECT sum((r->>'insurable_ytd')::numeric) FROM jsonb_array_elements(NEW.opening_children_snapshot->'programBases') r WHERE r->>'program_key'='qpip'),0),103000::numeric) THEN
   RAISE EXCEPTION 'Original reported bases must reconcile exactly to annual maxima and unchanged original earnings' USING ERRCODE='23514';
 END IF;
 SELECT count(*) INTO slice_count FROM public.payroll_ca_opening_reporting_allocations a WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id;
 FOREACH family IN ARRAY ARRAY['components','programBases','accountBases','suiStates'] LOOP
   amount_key := CASE WHEN family='components' THEN 'ytd_amount' ELSE 'insurable_ytd' END;
   FOR original_row IN SELECT value FROM jsonb_array_elements(NEW.opening_children_snapshot->family) LOOP
    identity := public.payroll_ca_opening_reporting_child_identity(family,original_row);
    original_value := original_row->>amount_key;
    SELECT sum((child.value->>amount_key)::numeric) INTO allocated_total
     FROM public.payroll_ca_opening_reporting_allocations a CROSS JOIN LATERAL jsonb_array_elements(a.children->family) child(value)
     WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id
       AND public.payroll_ca_opening_reporting_child_identity(family,child.value)=identity;
    IF allocated_total IS DISTINCT FROM original_value::numeric OR
      (SELECT count(*) FROM public.payroll_ca_opening_reporting_allocations a CROSS JOIN LATERAL jsonb_array_elements(a.children->family) child(value)
       WHERE a.org_id=NEW.org_id AND a.authority_id=NEW.id
        AND public.payroll_ca_opening_reporting_child_identity(family,child.value)=identity)<>slice_count THEN
     RAISE EXCEPTION 'Reporting child slices must preserve each exact original identity and amount, including zeros' USING ERRCODE='23514';
    END IF;
   END LOOP;
 END LOOP;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_compensation_calculation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_org uuid; v_run uuid; v_status text;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 v_org := CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
 v_run := CASE WHEN TG_OP='DELETE' THEN OLD.pay_run_document_id ELSE NEW.pay_run_document_id END;
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(v_org) THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 SELECT run_status INTO v_status FROM public.pay_runs WHERE org_id=v_org AND document_id=v_run FOR UPDATE;
 IF v_status IS NULL OR v_status IN ('committed','voided') THEN RAISE EXCEPTION 'Compensation calculation evidence belongs to an editable native pay run; preserve posted evidence and use a controlled correction.'; END IF;
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Replace compensation calculation evidence only through native recalculation.'; END IF;
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public.payroll_compensation_assignments WHERE org_id=NEW.org_id AND id=NEW.assignment_id AND employment_id=NEW.employment_id AND status IN ('active','ended')) THEN
  RAISE EXCEPTION 'Compensation evidence needs the active native employment assignment used by this calculation.';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_compensation_configuration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE approver_party uuid; submitter_party uuid; author_party uuid; subject_party uuid; v_org uuid; self_decision_authorized boolean; approval_subject_kind text; ungated_submission boolean := false;
BEGIN
 IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
  RETURN OLD;
 END IF;
 v_org := CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(v_org) THEN
  UPDATE public.payroll_compensation_configuration SET revision=revision+1 WHERE org_id=v_org;
  RETURN OLD;
 END IF;
 UPDATE public.payroll_compensation_configuration SET revision=revision+1 WHERE org_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Compensation configuration is missing; complete the database upgrade before saving.'; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 -- Only tenant-reference rebasing is admitted after the controlled bulk copy.
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='payroll_compensation_versions' AND public.openbooks_clone_authority()
  AND (to_jsonb(NEW)-ARRAY['definition','definition_hash','authorship'])=(to_jsonb(OLD)-ARRAY['definition','definition_hash','authorship']) THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='payroll_compensation_assignments' AND public.openbooks_clone_authority()
  AND (to_jsonb(NEW)-'authorship')=(to_jsonb(OLD)-'authorship') THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Compensation configuration preserves approval history; retire the package or cancel an unused draft instead.'; END IF;
 IF TG_OP='INSERT' AND TG_TABLE_NAME<>'payroll_compensation_packages' AND NEW.status<>'draft' THEN
  RAISE EXCEPTION 'Create a compensation draft before submitting it through the tenant approval Flow.';
 END IF;
 IF TG_TABLE_NAME<>'payroll_compensation_packages' THEN
  IF TG_OP='INSERT' AND NEW.submission_policy IS NOT NULL THEN
   RAISE EXCEPTION 'Submission policy is recorded by the native compensation submission command.';
  END IF;
  IF TG_OP='UPDATE' THEN
   IF OLD.status='draft' AND NEW.status='submitted' THEN
    IF NEW.submission_policy IS DISTINCT FROM jsonb_build_object('version',1,'kind','flow','submittedRevision',NEW.revision) THEN
     RAISE EXCEPTION 'Compensation submission must bind its routing policy to the submitted revision.';
    END IF;
   ELSIF NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
    ungated_submission := OLD.status='submitted'
     AND NEW.status=CASE WHEN TG_TABLE_NAME='payroll_compensation_versions' THEN 'approved' ELSE 'active' END
     AND OLD.submission_policy=jsonb_build_object('version',1,'kind','flow','submittedRevision',OLD.revision)
     AND NEW.submission_policy=jsonb_build_object('version',1,'kind','ungated','submittedRevision',OLD.revision)
     AND NEW.decided_by=OLD.submitted_by AND NEW.updated_by=OLD.submitted_by
     AND public.compensation_ungated_submission_authorized(NEW.org_id,
      CASE WHEN TG_TABLE_NAME='payroll_compensation_versions' THEN 'compensation_package_version' ELSE 'compensation_package_assignment' END,
      NEW.id,NEW.package_id,OLD.revision,NEW.decided_by);
    IF ungated_submission IS NOT TRUE THEN
     RAISE EXCEPTION 'The submitted compensation policy is frozen; complete its native Flow or create a new draft.';
    END IF;
   END IF;
  END IF;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.org_id,NEW.id,NEW.created_at,NEW.created_by) IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.created_at,OLD.created_by) THEN
   RAISE EXCEPTION 'Compensation record ownership and creation evidence are immutable.';
  END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Compensation revision changed; reload the record before saving.'; END IF;
  IF TG_TABLE_NAME='payroll_compensation_packages' THEN
   IF ROW(NEW.subsidiary_id,NEW.code,NEW.country,NEW.currency) IS DISTINCT FROM ROW(OLD.subsidiary_id,OLD.code,OLD.country,OLD.currency) THEN
    RAISE EXCEPTION 'Package employer, code, country and currency are immutable; create a separate package.';
   END IF;
   IF OLD.status='retired' THEN RAISE EXCEPTION 'A retired compensation package is immutable; create a new package.'; END IF;
  ELSE
   IF NEW.package_id IS DISTINCT FROM OLD.package_id OR (TG_TABLE_NAME='payroll_compensation_versions' AND (to_jsonb(NEW)->'version') IS DISTINCT FROM (to_jsonb(OLD)->'version')) THEN
    RAISE EXCEPTION 'Compensation package ownership and version numbers are immutable; create a new draft.';
   END IF;
   IF OLD.status NOT IN ('draft','submitted') THEN
    IF TG_TABLE_NAME<>'payroll_compensation_assignments' OR OLD.status<>'active' OR NEW.status<>'ended' THEN
     RAISE EXCEPTION 'Approved compensation history is immutable; create an effective-dated successor.';
    END IF;
    IF (to_jsonb(NEW)-ARRAY['status','effective_to','revision','reason','updated_at','updated_by']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['status','effective_to','revision','reason','updated_at','updated_by'])
       OR NEW.effective_to IS NULL OR (OLD.effective_to IS NOT NULL AND NEW.effective_to>OLD.effective_to) THEN
     RAISE EXCEPTION 'Ending an assignment may only shorten its window; create an approved successor for changed terms.';
    END IF;
    IF EXISTS(SELECT 1 FROM public.payroll_compensation_calculations c JOIN public.pay_runs r ON r.org_id=c.org_id AND r.document_id=c.pay_run_document_id
      WHERE c.org_id=OLD.org_id AND c.assignment_id=OLD.id AND r.run_status IN ('committed','voided') AND r.period_end>NEW.effective_to) THEN
     RAISE EXCEPTION 'The assignment has payroll history after that end date; preserve the paid window and use a controlled payroll correction.';
    END IF;
   ELSIF OLD.status='submitted' THEN
    IF NEW.status NOT IN ('approved','active','rejected') OR
       (TG_TABLE_NAME='payroll_compensation_versions' AND NEW.status='active') OR
       (TG_TABLE_NAME='payroll_compensation_assignments' AND NEW.status='approved') OR
       (to_jsonb(NEW)-ARRAY['status','decided_by','decided_at','revision','reason','updated_at','updated_by']-
        CASE WHEN ungated_submission THEN 'submission_policy' ELSE '__no_policy_change__' END) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['status','decided_by','decided_at','revision','reason','updated_at','updated_by']-
        CASE WHEN ungated_submission THEN 'submission_policy' ELSE '__no_policy_change__' END) THEN
     RAISE EXCEPTION 'Submitted compensation terms are frozen; decide this proposal or create a new draft.';
    END IF;
   ELSIF NEW.status NOT IN ('draft','submitted','cancelled') OR (TG_TABLE_NAME='payroll_compensation_versions' AND NEW.status='cancelled') THEN
    RAISE EXCEPTION 'Submit the compensation draft before requesting its tenant Flow approval.';
   END IF;
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND OLD.status='submitted' THEN
  IF NEW.decided_by IS DISTINCT FROM NEW.updated_by THEN RAISE EXCEPTION 'The compensation decision must identify the actor making it.'; END IF;
  SELECT party_id INTO approver_party FROM public.users WHERE org_id=NEW.org_id AND id=NEW.decided_by AND is_active;
  SELECT party_id INTO submitter_party FROM public.users WHERE org_id=NEW.org_id AND id=NEW.submitted_by;
  SELECT party_id INTO author_party FROM public.users WHERE org_id=NEW.org_id AND id=NEW.created_by;
  approval_subject_kind := CASE WHEN TG_TABLE_NAME='payroll_compensation_versions' THEN 'compensation_package_version' ELSE 'compensation_package_assignment' END;
  self_decision_authorized := ungated_submission OR public.compensation_self_decision_authorized(NEW.org_id,approval_subject_kind,NEW.id,NEW.package_id,OLD.revision,
    CASE WHEN NEW.status='rejected' THEN 'rejected' ELSE 'approved' END,NEW.decided_by);
  IF approver_party IS NULL OR submitter_party IS NULL OR author_party IS NULL
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.authorship) a LEFT JOIN public.users u ON u.org_id=NEW.org_id AND u.id=(a->>'actorId')::uuid
    WHERE u.id IS NULL OR u.party_id IS NULL) THEN
   RAISE EXCEPTION 'Compensation decisions require resolved native person identities for the approver, submitter and authors.';
  END IF;
  IF NOT self_decision_authorized AND (NEW.decided_by IN (NEW.submitted_by,NEW.created_by) OR approver_party IS NOT DISTINCT FROM submitter_party OR approver_party IS NOT DISTINCT FROM author_party
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.authorship) a JOIN public.users u ON u.org_id=NEW.org_id AND u.id=(a->>'actorId')::uuid
    WHERE u.id=NEW.decided_by OR u.party_id=approver_party OR (a->>'partyId')::uuid=approver_party)
   OR EXISTS(SELECT 1 FROM public.audit_log a JOIN public.users u ON u.org_id=a.org_id AND u.id=a.actor_id
    WHERE a.org_id=NEW.org_id AND a.table_name=TG_TABLE_NAME AND a.row_id=NEW.id AND
     (u.id=NEW.decided_by OR u.party_id=approver_party OR (a.changes->>'actorPartyId')::uuid=approver_party))) THEN
   RAISE EXCEPTION 'The submitted native compensation Flow must explicitly authorize a self decision; otherwise use an independent approver.';
  END IF;
  IF TG_TABLE_NAME='payroll_compensation_assignments' THEN
   subject_party := NEW.employee_party_id;
   IF approver_party=subject_party AND NOT self_decision_authorized THEN RAISE EXCEPTION 'The submitted native compensation Flow must authorize the affected employee to decide this assignment.'; END IF;
  END IF;
 END IF;
 IF TG_TABLE_NAME<>'payroll_compensation_packages' THEN
  IF TG_OP='INSERT' THEN
   NEW.authorship := jsonb_build_array(jsonb_build_object('actorId',NEW.created_by,'partyId',(SELECT party_id FROM public.users WHERE org_id=NEW.org_id AND id=NEW.created_by)));
  ELSIF OLD.status='draft' THEN
   NEW.authorship := OLD.authorship;
   -- Submission records the submitting person's identity as well as draft authors.
   IF NEW.status IN ('draft','submitted') THEN
    SELECT jsonb_agg(value ORDER BY value->>'actorId',value->>'partyId') INTO NEW.authorship FROM
     (SELECT DISTINCT value FROM jsonb_array_elements(NEW.authorship || jsonb_build_array(jsonb_build_object('actorId',NEW.updated_by,'partyId',(SELECT party_id FROM public.users WHERE org_id=NEW.org_id AND id=NEW.updated_by))))) authors;
   END IF;
  END IF;
  IF jsonb_array_length(NEW.authorship)>128 THEN RAISE EXCEPTION 'A compensation draft has too many distinct authorship identities; create a new version for the next proposal.'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_employee_employer_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE employee_employer uuid; employee_country text; current_id uuid;
BEGIN
 IF TG_OP='DELETE' AND (public.openbooks_sandbox_wipe_allowed(OLD.org_id)
   OR tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() AND TG_OP<>'DELETE' THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Dated employer assignment evidence is immutable; retain the record and use a controlled payroll correction.';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id||':'||NEW.employee_party_id,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id||':'||NEW.employee_party_id||':'||NEW.tax_year,0));
 SELECT p.subsidiary_id,prof.country,prof.filing_account_id INTO employee_employer,employee_country,current_id
  FROM public.employee_payroll_profiles prof JOIN public.parties p ON p.org_id=prof.org_id AND p.id=prof.employee_party_id
  WHERE prof.org_id=NEW.org_id AND prof.employee_party_id=NEW.employee_party_id FOR UPDATE OF prof FOR SHARE OF p;
 IF NOT FOUND OR employee_employer IS DISTINCT FROM NEW.subsidiary_id THEN
  RAISE EXCEPTION 'Choose the saved payroll employee and their own legal employer before recording an assignment.';
 END IF;
 IF NEW.assignment_kind='filing_account' THEN
  PERFORM a.id FROM public.payroll_filing_accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.filing_account_id
    AND a.country=employee_country AND (a.subsidiary_id IS NULL OR a.subsidiary_id=employee_employer) AND a.is_active FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Choose an active filing account for the employee payroll country.'; END IF;
 ELSE
  PERFORM er.id FROM public.employee_roles er
   WHERE er.org_id=NEW.org_id AND er.party_id=NEW.employee_party_id AND er.is_active
   ORDER BY er.updated_at DESC,er.id LIMIT 1 FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Save an active employee role before recording a dated classification.'; END IF;
  current_id := public.payroll_worker_comp_group_at(NEW.org_id, NEW.employee_party_id, current_date);
  IF NEW.worker_comp_group_id IS NOT NULL THEN
   PERFORM g.id FROM public.worker_comp_groups g WHERE g.org_id=NEW.org_id AND g.id=NEW.worker_comp_group_id AND g.is_active FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Choose an active worker-compensation group for this dated classification.'; END IF;
  END IF;
 END IF;
 IF current_id IS DISTINCT FROM NEW.expected_current_id THEN
  RAISE EXCEPTION 'The current employer assignment changed; export and preview the dated assignment again.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.pay_runs r JOIN public.pay_stubs s ON s.org_id=r.org_id AND s.pay_run_document_id=r.document_id
   JOIN public.documents d ON d.org_id=r.org_id AND d.id=r.document_id
   WHERE r.org_id=NEW.org_id AND s.employee_party_id=NEW.employee_party_id AND r.run_status='committed' AND d.status<>'voided'
     AND r.pay_date BETWEEN NEW.effective_from AND NEW.effective_to) THEN
  RAISE EXCEPTION 'Committed payroll already used these dates; preserve its evidence and use a controlled correction run.';
 END IF;
 UPDATE public.employee_payroll_profiles SET updated_at=greatest(clock_timestamp(),updated_at+interval '1 microsecond'),updated_by=NEW.created_by
  WHERE org_id=NEW.org_id AND employee_party_id=NEW.employee_party_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'The payroll profile revision was not saved; reload the employee and preview again.'; END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.payroll_employment_coherence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE worker uuid;
BEGIN
  IF NEW.employment_id IS NULL THEN
    RETURN NEW;
  END IF;
  -- No person on the row (entitlement_plan_limits non-person scopes): there
  -- is nobody to compare the employment against, so this guard abstains and
  -- the scope CHECK owns the refusal with its precise message.
  IF NEW.employee_party_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT we.worker_party_id INTO worker
    FROM public.worker_employments we
   WHERE we.org_id = NEW.org_id AND we.id = NEW.employment_id;
  -- No row (yet): the composite FK refuses unknown/other-org ids at commit.
  -- This trigger owns only the cross-person refusal, which the FK cannot see.
  IF worker IS NULL THEN
    RETURN NEW;
  END IF;
  IF worker IS DISTINCT FROM NEW.employee_party_id THEN
    RAISE EXCEPTION
      '% employment_id % names an employment of worker %, not employee % — stamp the row with an employment of the row''s own worker',
      TG_TABLE_NAME, NEW.employment_id, worker, NEW.employee_party_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_holiday_allocation_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
  VALUES(OLD.org_id,'pay_run_holiday_allocations',OLD.id,'delete',jsonb_build_object('before',to_jsonb(OLD)),OLD.updated_by);
  RETURN OLD;
 END IF;
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
 VALUES(NEW.org_id,'pay_run_holiday_allocations',NEW.id,lower(TG_OP),jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,'after',to_jsonb(NEW)),NEW.updated_by);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_holiday_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.pay_runs%ROWTYPE; obligation public.payroll_holiday_obligations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='INSERT' AND public.holiday_historical_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO STRICT run_row FROM public.pay_runs WHERE org_id=NEW.org_id AND document_id=NEW.pay_run_document_id FOR SHARE;
  SELECT * INTO STRICT obligation FROM public.payroll_holiday_obligations WHERE org_id=NEW.org_id AND id=NEW.obligation_id FOR SHARE;
  IF NEW.status<>'calculated' OR run_row.run_status NOT IN('draft','calculated') OR run_row.run_type<>'regular'
    OR run_row.pay_date IS DISTINCT FROM obligation.payment_date
    OR NEW.hours::text::numeric IS DISTINCT FROM (obligation.evidence->'instruction'->>'hours')::numeric
    OR NEW.source_snapshot->'obligation' IS DISTINCT FROM obligation.evidence
    OR NOT EXISTS(SELECT 1 FROM public.documents d WHERE d.org_id=NEW.org_id AND d.id=NEW.pay_run_document_id
        AND d.subsidiary_id=obligation.subsidiary_id AND d.currency=NEW.currency)
    OR NOT EXISTS(SELECT 1 FROM public.financial_changes f WHERE f.org_id=obligation.org_id AND f.id=obligation.change_id AND f.status='applied')
    OR NOT EXISTS(SELECT 1 FROM public.pay_components c WHERE c.org_id=NEW.org_id AND c.id=NEW.component_id AND c.system_key='stat_holiday' AND c.kind='earning') THEN
   RAISE EXCEPTION 'Holiday settlement must claim an applied unpaid entitlement on its instructed regular pay date with exact source hours and the native holiday component.';
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT run_row FROM public.pay_runs WHERE org_id=OLD.org_id AND document_id=OLD.pay_run_document_id FOR SHARE;
 IF TG_OP='UPDATE' AND pg_trigger_depth()>1 AND
    ((OLD.status='calculated' AND NEW.status='committed' AND run_row.run_status='calculated') OR
     (OLD.status='committed' AND NEW.status='voided' AND run_row.run_status='committed')) AND
    (to_jsonb(NEW)-ARRAY['status','updated_at','updated_by'])=(to_jsonb(OLD)-ARRAY['status','updated_at','updated_by']) THEN RETURN NEW; END IF;
 IF OLD.status<>'calculated' OR run_row.run_status NOT IN('draft','calculated') THEN
  RAISE EXCEPTION 'Committed holiday settlement evidence is immutable; void its native payroll before releasing the claim.';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NEW.status<>'calculated' OR (to_jsonb(NEW)-ARRAY['pay_stub_line_id','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['pay_stub_line_id','updated_at','updated_by']) THEN
  RAISE EXCEPTION 'Calculated holiday pricing is frozen; recalculate the editable payroll instead of rewriting its claim.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_holiday_obligation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proposal public.financial_changes%ROWTYPE; obligation public.payroll_holiday_obligations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='INSERT' AND public.holiday_historical_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
 IF TG_OP<>'INSERT' THEN
  IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Approved holiday entitlement evidence is immutable; preserve it and use a governed correction.';
 END IF;
 IF TG_TABLE_NAME='payroll_holiday_occurrences' THEN
  SELECT * INTO STRICT obligation FROM public.payroll_holiday_obligations WHERE org_id=NEW.org_id AND id=NEW.obligation_id FOR SHARE;
  IF NOT coalesce(obligation.evidence->'instruction'->'holidayDates' ? NEW.holiday_date::text,false) THEN
   RAISE EXCEPTION 'A holiday occurrence must be named in its approved entitlement.';
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT proposal FROM public.financial_changes WHERE org_id=NEW.org_id AND id=NEW.change_id FOR SHARE;
 IF proposal.domain<>'payroll' OR proposal.operation<>'adjudicated_holiday_hours'
   OR proposal.status<>'approved' OR proposal.approved_by IS NULL
   OR (proposal.approved_by=proposal.submitted_by AND NOT public.financial_change_self_decision_authorized(proposal.org_id,proposal.id,proposal.approved_by))
   OR proposal.subject_id IS DISTINCT FROM NEW.employee_party_id
   OR proposal.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id
   OR proposal.effective_on IS DISTINCT FROM NEW.payment_date
   OR proposal.payload->>'employmentId' IS DISTINCT FROM NEW.employment_id::text
   OR proposal.payload->'evidence' IS DISTINCT FROM NEW.evidence
   OR proposal.payload->'requiredSubsidiaryIds' IS DISTINCT FROM jsonb_build_array(NEW.subsidiary_id::text) THEN
  RAISE EXCEPTION 'Unpaid holiday pay requires a policy-authorized proposal for this employee, employment, employer, payment date and exact source evidence.';
 END IF;
 IF NEW.evidence->'instruction'->>'employeePartyId' IS DISTINCT FROM NEW.employee_party_id::text
   OR NEW.evidence->'instruction'->>'paymentDate' IS DISTINCT FROM NEW.payment_date::text
   OR NEW.evidence->'source'->>'fileId' IS DISTINCT FROM NEW.source_file_id::text
   OR NEW.evidence->'source'->>'versionId' IS DISTINCT FROM NEW.source_version_id::text
   OR jsonb_typeof(NEW.evidence->'instruction'->'holidayDates') IS DISTINCT FROM 'array'
   OR NOT EXISTS(SELECT 1 FROM public.worker_employments e WHERE e.org_id=NEW.org_id AND e.id=NEW.employment_id
       AND e.worker_party_id=NEW.employee_party_id AND e.employer_subsidiary_id=NEW.subsidiary_id)
   OR NOT EXISTS(SELECT 1 FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
       WHERE f.org_id=NEW.org_id AND f.id=NEW.source_file_id AND v.id=NEW.source_version_id
         AND lower(v.content_hash)=NEW.evidence->'source'->>'contentHash'
         AND lower(v.content_hash)=NEW.evidence->'instruction'->>'sourceDigest'
         AND v.version_number::text=NEW.evidence->'source'->>'versionNumber') THEN
  RAISE EXCEPTION 'The holiday entitlement must retain its exact tenant-owned employee and File Cabinet source version.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_holiday_occurrence_completeness()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE obligation public.payroll_holiday_obligations%ROWTYPE; actual jsonb; target_id uuid; source_dates jsonb;
BEGIN
 IF TG_TABLE_NAME='payroll_holiday_obligations' THEN target_id:=NEW.id; ELSE target_id:=NEW.obligation_id; END IF;
 SELECT * INTO obligation FROM public.payroll_holiday_obligations
  WHERE org_id=NEW.org_id AND id=target_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT jsonb_agg(holiday_date::text ORDER BY holiday_date) INTO actual FROM public.payroll_holiday_occurrences
  WHERE org_id=obligation.org_id AND obligation_id=obligation.id;
 IF public.holiday_historical_clone_matches('public.payroll_holiday_obligations'::regclass,to_jsonb(obligation)) THEN
  SELECT jsonb_agg(source.holiday_date::text ORDER BY source.holiday_date) INTO source_dates
   FROM public.orgs target JOIN public.payroll_holiday_occurrences source ON source.org_id=target.sandbox_of
    AND public.ob_rebase(source.obligation_id,target.sandbox_seed)=obligation.id WHERE target.id=obligation.org_id;
  IF actual IS DISTINCT FROM source_dates THEN RAISE EXCEPTION 'A sandbox must retain every original approved holiday occurrence exactly once.'; END IF;
  RETURN NULL;
 END IF;
 IF actual IS DISTINCT FROM obligation.evidence->'instruction'->'holidayDates' THEN
  RAISE EXCEPTION 'Record every approved holiday occurrence exactly once before completing the entitlement.';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_opening_employer_authority_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE retained jsonb;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
  OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Qualified opening employer authority and original evidence are immutable' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id::text||':'||NEW.employee_party_id::text||':'||NEW.tax_year::text,0));
 SELECT to_jsonb(b) INTO retained FROM public.payroll_opening_balances b
  WHERE b.org_id=NEW.org_id AND b.id=NEW.opening_balance_id AND b.employee_party_id=NEW.employee_party_id AND b.tax_year=NEW.tax_year FOR SHARE;
 IF retained IS NULL OR retained IS DISTINCT FROM NEW.opening_snapshot
  OR encode(public.digest(retained::text,'sha256'),'hex')<>NEW.opening_sha256 THEN
  RAISE EXCEPTION 'Opening employer authority must retain the exact original employee/year amounts' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.worker_employments e WHERE e.org_id=NEW.org_id
  AND e.worker_party_id=NEW.employee_party_id AND e.employer_subsidiary_id=NEW.subsidiary_id) THEN
  RAISE EXCEPTION 'Opening employer authority requires the employee native legal employer' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
  WHERE f.org_id=NEW.org_id AND f.id=NEW.source_file_id AND NOT f.is_inactive AND v.id=NEW.source_version_id
   AND v.content_hash=NEW.source_sha256 AND v.created_by=NEW.created_by) THEN
  RAISE EXCEPTION 'Opening employer authority needs the importing operator exact retained source version and hash' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_opening_levy_opening_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  row_org uuid;
  row_employee uuid;
  row_year integer;
  opening_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME = 'payroll_opening_balance_components' THEN
      IF (NEW.org_id,NEW.opening_balance_id,NEW.component_id) IS DISTINCT FROM (OLD.org_id,OLD.opening_balance_id,OLD.component_id) THEN
        RAISE EXCEPTION 'Payroll opening component source identity is immutable' USING ERRCODE = '23514';
      END IF;
    ELSIF TG_TABLE_NAME = 'payroll_opening_program_bases' THEN
      IF (NEW.org_id,NEW.employee_party_id,NEW.tax_year,NEW.program_key) IS DISTINCT FROM (OLD.org_id,OLD.employee_party_id,OLD.tax_year,OLD.program_key) THEN
        RAISE EXCEPTION 'Payroll opening programme source identity is immutable' USING ERRCODE = '23514';
      END IF;
    ELSIF TG_TABLE_NAME = 'payroll_opening_sui_wages' THEN
      IF (NEW.org_id, NEW.opening_balance_id, NEW.state)
          IS DISTINCT FROM (OLD.org_id, OLD.opening_balance_id, OLD.state) THEN
        RAISE EXCEPTION 'Payroll opening SUI source identity is immutable' USING ERRCODE = '23514';
      END IF;
    ELSIF (NEW.org_id, NEW.employee_party_id, NEW.tax_year, NEW.program_key, NEW.filing_account_id, NEW.region)
        IS DISTINCT FROM (OLD.org_id, OLD.employee_party_id, OLD.tax_year, OLD.program_key, OLD.filing_account_id, OLD.region) THEN
      RAISE EXCEPTION 'Payroll opening filing-account source identity is immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_TABLE_NAME IN ('payroll_opening_sui_wages','payroll_opening_balance_components') THEN
    IF TG_OP = 'DELETE' THEN
      row_org := OLD.org_id; opening_id := OLD.opening_balance_id;
    ELSE
      row_org := NEW.org_id; opening_id := NEW.opening_balance_id;
    END IF;
    SELECT b.employee_party_id, b.tax_year INTO row_employee, row_year
      FROM public.payroll_opening_balances b WHERE b.org_id = row_org AND b.id = opening_id;
  ELSE
    IF TG_OP = 'DELETE' THEN
      row_org := OLD.org_id; row_employee := OLD.employee_party_id; row_year := OLD.tax_year;
    ELSE
      row_org := NEW.org_id; row_employee := NEW.employee_party_id; row_year := NEW.tax_year;
    END IF;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'payroll-run-ytd:' || row_org::text || ':' || row_employee::text || ':' || row_year::text, 0));
  IF EXISTS (SELECT 1 FROM public.payroll_opening_levy_source_authorities h
      WHERE h.org_id = row_org AND h.employee_party_id = row_employee AND h.tax_year = row_year AND h.sealed) THEN
    RAISE EXCEPTION 'Source-qualified statutory opening amounts must be preserved; a replacement source certificate cannot change annual or child opening amounts' USING ERRCODE = '23514';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_opening_levy_source_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  authority public.payroll_opening_levy_source_authorities%ROWTYPE;
  account_type text;
  account_state text;
  account_subsidiary uuid;
  federal_type text;
  federal_subsidiary uuid;
BEGIN
  IF TG_OP = 'DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Payroll opening levy allocation rows are immutable' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO authority FROM public.payroll_opening_levy_source_authorities h
   WHERE h.org_id = NEW.org_id AND h.id = NEW.authority_id FOR UPDATE;
  IF authority.id IS NULL OR authority.sealed THEN
    RAISE EXCEPTION 'Payroll opening levy allocations can only be written before their source authority is sealed' USING ERRCODE = '23514';
  END IF;
  IF authority.original_country NOT IN ('CA','US') OR (authority.original_country = 'CA' AND NEW.program_key NOT IN ('ca_wcb','ca_eht','ca_cnt'))
    OR (authority.original_country = 'US' AND NEW.program_key NOT IN ('us_futa','us_sui','us_pa_lst')) THEN
    RAISE EXCEPTION 'Opening allocation country must match its authored original source country' USING ERRCODE = '23514';
  END IF;
  IF NEW.federal_account_id IS NOT NULL THEN
    SELECT program_type, subsidiary_id INTO federal_type, federal_subsidiary
      FROM public.payroll_filing_accounts
     WHERE org_id = NEW.org_id AND id = NEW.federal_account_id AND country = 'US' FOR SHARE;
    IF federal_type IS DISTINCT FROM 'us_ein'
      OR (federal_subsidiary IS NOT NULL AND federal_subsidiary <> authority.subsidiary_id) THEN
      RAISE EXCEPTION 'Bind each US original opening allocation to its native original employer EIN' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF NEW.filing_account_id IS NOT NULL THEN
    SELECT program_type, state_code, subsidiary_id INTO account_type, account_state, account_subsidiary
      FROM public.payroll_filing_accounts
     WHERE org_id = NEW.org_id AND id = NEW.filing_account_id FOR SHARE;
    IF NEW.program_key = 'us_futa' AND account_type IS DISTINCT FROM 'us_ein'
      OR NEW.program_key = 'us_sui' AND (account_type IS DISTINCT FROM 'us_state_sui' OR account_state IS DISTINCT FROM NEW.region)
      OR NEW.program_key NOT IN ('us_futa','us_sui')
      OR (account_subsidiary IS NOT NULL AND account_subsidiary <> authority.subsidiary_id) THEN
      RAISE EXCEPTION 'US opening allocations must use the original legal employer EIN or matching state SUI account' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_opening_levy_source_authority_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  retained jsonb;
  source_authority public.payroll_opening_employer_authorities%ROWTYPE;
  actual_snapshot jsonb;
  original_file uuid;
  predecessor public.payroll_opening_levy_source_authorities%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Payroll opening levy source authority preserves its original allocation' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.sealed OR NOT NEW.sealed
      OR (to_jsonb(NEW) - ARRAY['sealed','allocation_sha256','allocation_snapshot'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['sealed','allocation_sha256','allocation_snapshot']) THEN
      RAISE EXCEPTION 'Payroll opening levy source authority and allocations are immutable once sealed' USING ERRCODE = '23514';
    END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'programKey', a.program_key, 'region', a.region, 'subRegion', a.sub_region,
      'filingAccountId', a.filing_account_id, 'federalAccountId', a.federal_account_id, 'amount', a.amount::text
    ) ORDER BY a.program_key, a.region, a.sub_region, a.filing_account_id NULLS FIRST, a.federal_account_id NULLS FIRST), '[]'::jsonb)
      INTO actual_snapshot
      FROM public.payroll_opening_levy_source_allocations a
     WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id;
    IF NEW.opening_children_snapshot IS DISTINCT FROM public.payroll_opening_source_children(NEW.org_id,NEW.opening_balance_id,NEW.employee_party_id,NEW.tax_year)
      OR NEW.opening_children_sha256 <> encode(public.digest(NEW.opening_children_snapshot::text,'sha256'),'hex')
      OR actual_snapshot IS DISTINCT FROM NEW.allocation_snapshot
      OR encode(public.digest(actual_snapshot::text, 'sha256'), 'hex') <> NEW.allocation_sha256
      OR (NEW.original_country IN ('CA','US') AND jsonb_array_length(actual_snapshot) = 0) THEN
      RAISE EXCEPTION 'Payroll opening levy allocation set must exactly match its sealed source snapshot' USING ERRCODE = '23514';
    END IF;
    SELECT to_jsonb(b) INTO retained FROM public.payroll_opening_balances b
      WHERE b.org_id = NEW.org_id AND b.id = NEW.opening_balance_id FOR SHARE;
    IF NEW.original_country = 'CA' THEN
      IF jsonb_array_length(actual_snapshot) <> 18
        OR (SELECT sum(a.amount) FROM public.payroll_opening_levy_source_allocations a
          WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'ca_wcb')
            IS DISTINCT FROM (retained->>'wcb_assessable_ytd')::numeric
        OR (SELECT sum(a.amount) FROM public.payroll_opening_levy_source_allocations a
          WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'ca_eht')
            IS DISTINCT FROM (retained->>'eht_remuneration_ytd')::numeric THEN
        RAISE EXCEPTION 'Declare all Canadian levy jurisdictions and preserve the exact original WCB and EHT aggregate amounts' USING ERRCODE = '23514';
      END IF;
    ELSIF NEW.original_country = 'US' THEN
      IF NOT EXISTS (SELECT 1 FROM public.payroll_opening_levy_source_allocations a
          WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_futa')
        OR EXISTS (SELECT 1 FROM public.payroll_opening_levy_source_allocations a
          WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND NOT EXISTS (
            SELECT 1 FROM public.payroll_opening_levy_source_allocations f
             WHERE f.org_id = a.org_id AND f.authority_id = a.authority_id
               AND f.program_key = 'us_futa' AND f.filing_account_id = a.federal_account_id)) THEN
        RAISE EXCEPTION 'Declare an exact FUTA opening for every original EIN named by the allocation set' USING ERRCODE = '23514';
      END IF;
      IF EXISTS (SELECT 1 FROM public.payroll_opening_account_bases b
          WHERE b.org_id = NEW.org_id AND b.employee_party_id = NEW.employee_party_id
            AND b.tax_year = NEW.tax_year AND b.program_key = 'us_futa') THEN
        IF (retained->>'insurable_ytd')::numeric <> 0
          OR EXISTS (SELECT 1 FROM public.payroll_opening_account_bases b
              WHERE b.org_id = NEW.org_id AND b.employee_party_id = NEW.employee_party_id
                AND b.tax_year = NEW.tax_year AND b.program_key = 'us_futa' AND NOT EXISTS (
                  SELECT 1 FROM public.payroll_opening_levy_source_allocations a
                   WHERE a.org_id = b.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_futa'
                     AND a.filing_account_id = b.filing_account_id AND a.amount = b.insurable_ytd))
          OR EXISTS (SELECT 1 FROM public.payroll_opening_levy_source_allocations a
              WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_futa'
                AND a.amount <> 0 AND NOT EXISTS (
                  SELECT 1 FROM public.payroll_opening_account_bases b
                   WHERE b.org_id = a.org_id AND b.employee_party_id = NEW.employee_party_id
                     AND b.tax_year = NEW.tax_year AND b.program_key = 'us_futa' AND b.filing_account_id = a.filing_account_id)) THEN
          RAISE EXCEPTION 'FUTA source allocations must preserve every exact EIN-specific opening wage base' USING ERRCODE = '23514';
        END IF;
      ELSIF (SELECT sum(a.amount) FROM public.payroll_opening_levy_source_allocations a
          WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_futa')
            IS DISTINCT FROM (retained->>'insurable_ytd')::numeric THEN
        RAISE EXCEPTION 'FUTA source allocations must equal the exact original employee-only insurable opening' USING ERRCODE = '23514';
      END IF;
      IF (retained->>'insurable_ytd')::numeric > 0 AND NOT EXISTS (
          SELECT 1 FROM public.payroll_opening_levy_source_allocations a
           WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_sui')
        OR EXISTS (SELECT 1 FROM public.payroll_opening_account_bases b
          WHERE b.org_id = NEW.org_id AND b.employee_party_id = NEW.employee_party_id AND b.tax_year = NEW.tax_year
            AND b.program_key = 'us_sui' AND (SELECT sum(a.amount) FROM public.payroll_opening_levy_source_allocations a
              WHERE a.org_id = b.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_sui'
                AND a.region = b.region AND a.filing_account_id = b.filing_account_id) IS DISTINCT FROM b.insurable_ytd)
        OR EXISTS (
          SELECT 1 FROM (
            SELECT sw.state AS region, sw.insurable_ytd AS amount
              FROM public.payroll_opening_sui_wages sw WHERE sw.org_id = NEW.org_id AND sw.opening_balance_id = NEW.opening_balance_id
            UNION ALL
            SELECT b.region,b.insurable_ytd FROM public.payroll_opening_account_bases b
              WHERE b.org_id = NEW.org_id AND b.employee_party_id = NEW.employee_party_id AND b.tax_year = NEW.tax_year
                AND b.program_key = 'us_sui'
          ) prior GROUP BY prior.region HAVING sum(prior.amount) IS DISTINCT FROM (
            SELECT sum(a.amount) FROM public.payroll_opening_levy_source_allocations a
             WHERE a.org_id = NEW.org_id AND a.authority_id = NEW.id AND a.program_key = 'us_sui' AND a.region = prior.region)
        ) THEN
        RAISE EXCEPTION 'SUI source allocations must preserve every exact original state and account aggregate, split only by source-confirmed EIN' USING ERRCODE = '23514';
      END IF;
    ELSIF jsonb_array_length(actual_snapshot) <> 0 THEN
      RAISE EXCEPTION 'The original country has no declared opening levy allocation programmes; preserve its generic opening amounts' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.sealed THEN
    RAISE EXCEPTION 'Payroll opening levy source authority must be sealed after its allocation rows are written' USING ERRCODE = '23514';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'payroll-opening-source:' || NEW.org_id::text || ':' || NEW.tax_year::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'payroll-run-ytd:' || NEW.org_id::text || ':' || NEW.employee_party_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'payroll-run-ytd:' || NEW.org_id::text || ':' || NEW.employee_party_id::text || ':' || NEW.tax_year::text, 0));
  -- The native GB apprenticeship levy shares an organization-wide annual base.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'payroll-levy-ytd:' || NEW.org_id::text || ':' || NEW.tax_year::text || ':GB:apprenticeship_levy',0));
  IF NEW.supersedes_authority_id IS NOT NULL THEN
    SELECT * INTO predecessor FROM public.payroll_opening_levy_source_authorities h
     WHERE h.org_id=NEW.org_id AND h.id=NEW.supersedes_authority_id FOR UPDATE;
    IF predecessor.id IS NULL OR NOT predecessor.sealed
      OR (predecessor.opening_balance_id,predecessor.employer_authority_id,predecessor.employee_party_id,
          predecessor.tax_year,predecessor.subsidiary_id,predecessor.opening_sha256,
          predecessor.opening_children_snapshot,predecessor.opening_children_sha256)
        IS DISTINCT FROM (NEW.opening_balance_id,NEW.employer_authority_id,NEW.employee_party_id,
          NEW.tax_year,NEW.subsidiary_id,NEW.opening_sha256,NEW.opening_children_snapshot,NEW.opening_children_sha256)
      OR EXISTS (SELECT 1 FROM public.payroll_opening_levy_source_authorities h
        WHERE h.org_id=NEW.org_id AND h.supersedes_authority_id=predecessor.id) THEN
      RAISE EXCEPTION 'Source correction must replace the current sealed certificate while preserving its legal payer and every original opening amount' USING ERRCODE='23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.payroll_filing_submissions f WHERE f.org_id=NEW.org_id AND f.tax_year=NEW.tax_year) THEN
      RAISE EXCEPTION 'An issued payroll filing retains history for this tax year; source certificate replacement for an issued year is unavailable' USING ERRCODE='23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.pay_runs r JOIN public.documents d ON d.org_id=r.org_id AND d.id=r.document_id
      WHERE r.org_id=NEW.org_id AND r.tax_year=NEW.tax_year AND r.run_status='committed' AND d.status<>'voided'
        AND (d.subsidiary_id=NEW.subsidiary_id
          OR coalesce(r.calculation_source_snapshot,'{}'::jsonb) @> jsonb_build_object('openingLevySourceAuthorities',
            jsonb_build_array(jsonb_build_object('id',predecessor.id::text)))
          OR coalesce(r.calculation_source_snapshot,'{}'::jsonb) @> jsonb_build_object('openingBalanceSources',
            jsonb_build_array(jsonb_build_object('openingBalanceId',NEW.opening_balance_id::text)))
          OR EXISTS (SELECT 1 FROM public.pay_stubs s WHERE s.org_id=r.org_id AND s.pay_run_document_id=r.document_id
            AND s.employee_party_id=NEW.employee_party_id))) THEN
      RAISE EXCEPTION 'Committed payroll retains this opening source; complete its native governed void before correcting the certificate' USING ERRCODE='23514';
    END IF;
  END IF;
  SELECT to_jsonb(b) INTO retained
    FROM public.payroll_opening_balances b
   WHERE b.org_id = NEW.org_id AND b.id = NEW.opening_balance_id
     AND b.employee_party_id = NEW.employee_party_id AND b.tax_year = NEW.tax_year FOR SHARE;
  SELECT * INTO source_authority
    FROM public.payroll_opening_employer_authorities a
   WHERE a.org_id = NEW.org_id AND a.id = NEW.employer_authority_id
     AND a.opening_balance_id = NEW.opening_balance_id FOR SHARE;
  IF NEW.opening_children_snapshot IS DISTINCT FROM public.payroll_opening_source_children(NEW.org_id,NEW.opening_balance_id,NEW.employee_party_id,NEW.tax_year)
    OR NEW.opening_children_sha256 <> encode(public.digest(NEW.opening_children_snapshot::text,'sha256'),'hex')
    OR retained IS NULL OR source_authority.id IS NULL
    OR source_authority.employee_party_id <> NEW.employee_party_id
    OR source_authority.tax_year <> NEW.tax_year
    OR source_authority.subsidiary_id <> NEW.subsidiary_id
    OR source_authority.opening_sha256 <> NEW.opening_sha256
    OR encode(public.digest(retained::text, 'sha256'), 'hex') <> NEW.opening_sha256 THEN
    RAISE EXCEPTION 'Payroll opening levy allocations must retain the exact qualified legal employer, opening and source file version' USING ERRCODE = '23514';
  END IF;
  SELECT v.id INTO original_file FROM public.files f JOIN public.file_versions v ON v.file_id = f.id
    WHERE f.org_id = NEW.org_id AND f.id = NEW.source_file_id AND NOT f.is_inactive
      AND v.id = NEW.source_version_id AND v.content_hash = NEW.source_sha256 AND v.created_by = NEW.created_by
    FOR SHARE OF f,v;
  IF original_file IS NULL THEN
    RAISE EXCEPTION 'Select the active original Cabinet file and its exact retained version and hash' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_opening_levy_successor_complete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE retained public.payroll_opening_levy_source_authorities%ROWTYPE;
BEGIN
  SELECT * INTO retained FROM public.payroll_opening_levy_source_authorities h WHERE h.org_id=NEW.org_id AND h.id=NEW.id;
  IF retained.id IS NULL AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(NEW))
    OR public.openbooks_sandbox_wipe_allowed(NEW.org_id)) THEN RETURN NULL; END IF;
  IF retained.id IS NULL OR NOT retained.sealed OR NOT EXISTS (
    SELECT 1 FROM public.audit_log a JOIN public.payroll_opening_levy_source_authorities p
      ON p.org_id=retained.org_id AND p.id=retained.supersedes_authority_id
     WHERE a.org_id=retained.org_id AND a.table_name='payroll_opening_levy_source_authorities' AND a.row_id=retained.id
       AND a.actor_id=retained.created_by AND a.changes->'before'=to_jsonb(p) AND a.changes->'after'=to_jsonb(retained)
       AND a.changes->>'reason'=retained.change_reason
  ) THEN
    RAISE EXCEPTION 'Opening source replacement must retain its complete sealed certificate and immutable before/after audit in the same transaction' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_opening_qualified_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
  OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||OLD.org_id::text||':'||OLD.employee_party_id::text||':'||OLD.tax_year::text,0));
 IF EXISTS(SELECT 1 FROM public.payroll_opening_employer_authorities a WHERE a.org_id=OLD.org_id AND a.opening_balance_id=OLD.id)
  AND (TG_OP='DELETE' OR to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)) THEN
  RAISE EXCEPTION 'Source-qualified opening amounts must be preserved; use a governed payroll correction' USING ERRCODE='23514';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_period_opening_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE opening jsonb; amount record; annual_amount numeric; v_org uuid; v_employee uuid; v_year integer;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 v_org:=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
 v_employee:=CASE WHEN TG_OP='DELETE' THEN OLD.employee_party_id ELSE NEW.employee_party_id END;
 v_year:=CASE WHEN TG_OP='DELETE' THEN OLD.tax_year ELSE NEW.tax_year END;
 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(v_org) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Period openings preserve source history; correct an unused opening with an audited revision.'; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' AND NEW.revision<>1 THEN RAISE EXCEPTION 'A new period opening must begin at revision one.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||v_org||':'||v_employee,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||v_org||':'||v_employee||':'||v_year,0));
 IF EXISTS(SELECT 1 FROM public.pay_stubs s JOIN public.pay_runs r ON r.org_id=s.org_id AND r.document_id=s.pay_run_document_id
  WHERE s.org_id=v_org AND s.employee_party_id=v_employee AND s.tax_year=v_year AND r.run_status='committed') THEN
  RAISE EXCEPTION 'A committed payroll already used this employee year; reverse the affected payroll through its controlled void action before correcting opening balances.';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.org_id,NEW.id,NEW.employee_party_id,NEW.tax_year,NEW.annual_opening_balance_id,NEW.created_at,NEW.created_by)
   IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.employee_party_id,OLD.tax_year,OLD.annual_opening_balance_id,OLD.created_at,OLD.created_by) THEN
   RAISE EXCEPTION 'Period opening ownership and creation evidence are immutable.';
  END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'The period opening changed; reload its current revision before saving.'; END IF;
 END IF;
 SELECT to_jsonb(b) INTO opening FROM public.payroll_opening_balances b
  WHERE b.org_id=NEW.org_id AND b.id=NEW.annual_opening_balance_id
   AND b.employee_party_id=NEW.employee_party_id AND b.tax_year=NEW.tax_year FOR SHARE;
 IF opening IS NULL THEN RAISE EXCEPTION 'Record the verified annual payroll opening balances before attributing same-period payments.'; END IF;
 FOR amount IN SELECT key,value FROM jsonb_each_text(NEW.amounts) LOOP
  IF amount.key !~ '^[A-Za-z][A-Za-z0-9_]*$' OR amount.value !~ '^[0-9]{1,15}\.[0-9]{4}$' THEN
   RAISE EXCEPTION 'Period opening amounts must be non-negative exact decimal text.';
  END IF;
 END LOOP;
 FOR amount IN SELECT key,value FROM jsonb_each_text(NEW.annual_bounds) LOOP
  IF amount.value !~ '^[0-9]{1,15}\.[0-9]{4}$' THEN
   RAISE EXCEPTION 'Annual period bounds must use exact non-negative decimal text.';
  END IF;
  IF amount.key ~ '^program:[A-Za-z][A-Za-z0-9_]*$' THEN
   SELECT coalesce(sum(insurable_ytd),0) INTO annual_amount FROM public.payroll_opening_program_bases
    WHERE org_id=NEW.org_id AND employee_party_id=NEW.employee_party_id AND tax_year=NEW.tax_year
     AND program_key=substring(amount.key FROM 9);
  ELSIF amount.key ~ '^[a-z][a-z0-9_]*$' AND jsonb_typeof(opening->amount.key)='number' THEN
   annual_amount:=(opening->>amount.key)::numeric;
  ELSE
   RAISE EXCEPTION 'The period opening names an unavailable annual balance.';
  END IF;
  IF amount.value::numeric>annual_amount THEN
   RAISE EXCEPTION 'Period amounts must already be included in their annual payroll opening balances; review annual and period amounts together.';
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_prior_earnings_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE source_period jsonb; earning jsonb; next_day date; source_keys text[]:=ARRAY[]::text[];
 earning_from date; earning_through date;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Prior earnings preserve source history; correct an unused record through its audited revision.'; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id||':'||NEW.employee_party_id,0));
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.org_id,NEW.id,NEW.employee_party_id,NEW.subsidiary_id,NEW.created_at,NEW.created_by)
   IS DISTINCT FROM ROW(OLD.org_id,OLD.id,OLD.employee_party_id,OLD.subsidiary_id,OLD.created_at,OLD.created_by) THEN
   RAISE EXCEPTION 'Prior earnings ownership and creation evidence are immutable.';
  END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Prior earnings changed; reload the current revision before saving.'; END IF;
 ELSIF NEW.revision<>1 THEN RAISE EXCEPTION 'New prior earnings must start at revision one.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.pay_stubs s JOIN public.pay_runs r ON r.org_id=s.org_id AND r.document_id=s.pay_run_document_id
  JOIN public.documents d ON d.org_id=r.org_id AND d.id=r.document_id
  WHERE s.org_id=NEW.org_id AND s.employee_party_id=NEW.employee_party_id AND d.subsidiary_id=NEW.subsidiary_id
   AND r.run_status='committed' AND r.period_end>=CASE WHEN TG_OP='UPDATE' THEN least(NEW.history_from,OLD.history_from) ELSE NEW.history_from END) THEN
  RAISE EXCEPTION 'Committed payroll overlaps or follows these prior earnings; use the governed payroll void process before correcting its inputs.';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.parties p JOIN public.employee_roles e ON e.org_id=p.org_id AND e.party_id=p.id
  JOIN public.subsidiaries employer ON employer.org_id=p.org_id AND employer.id=p.subsidiary_id
  WHERE p.org_id=NEW.org_id AND p.id=NEW.employee_party_id AND p.subsidiary_id=NEW.subsidiary_id
   AND employer.country=NEW.country AND employer.base_currency=NEW.currency) THEN
  RAISE EXCEPTION 'Prior earnings must belong to the native employee, legal employer and payroll currency.';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.file_versions v JOIN public.files f ON f.id=v.file_id
  WHERE f.org_id=NEW.org_id AND f.id=NEW.source_file_id AND v.id=NEW.source_version_id AND v.content_hash=NEW.source_hash) THEN
  RAISE EXCEPTION 'Prior earnings require the retained tenant source-file version and its exact content hash.';
 END IF;
 next_day:=NEW.history_from;
 FOR source_period IN SELECT value FROM jsonb_array_elements(NEW.periods) LOOP
  IF jsonb_typeof(source_period)<>'object' OR source_period-ARRAY['from','through','sourceReference','lines']<>'{}'::jsonb
   OR coalesce(source_period->>'from','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   OR coalesce(source_period->>'through','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   OR length(trim(coalesce(source_period->>'sourceReference',''))) NOT BETWEEN 1 AND 2000
   OR coalesce(jsonb_typeof(source_period->'lines'),'')<>'array' THEN
   RAISE EXCEPTION 'Every prior-payroll period requires dates, source evidence and an explicit earning-line set.';
  END IF;
  IF (source_period->>'from')::date<>next_day OR (source_period->>'through')::date<next_day
   OR (source_period->>'through')::date>NEW.history_through OR jsonb_array_length(source_period->'lines')>2000 THEN
   RAISE EXCEPTION 'Prior earnings periods must cover the entire history interval exactly once without gaps or overlaps.';
  END IF;
  FOR earning IN SELECT value FROM jsonb_array_elements(source_period->'lines') LOOP
   IF jsonb_typeof(earning)<>'object' OR earning-ARRAY['sourceKey','sourceLabel','earnedFrom','earnedThrough','bucket','amount']<>'{}'::jsonb
    OR length(trim(coalesce(earning->>'sourceKey',''))) NOT BETWEEN 1 AND 300
    OR length(trim(coalesce(earning->>'sourceLabel',''))) NOT BETWEEN 1 AND 160
    OR coalesce(earning->>'bucket','') NOT IN('regular','overtime','vacationPay','holidayPay')
    OR coalesce(jsonb_typeof(earning->'amount'),'')<>'string'
    OR coalesce(earning->>'amount','') !~ '^-?[0-9]{1,15}\.[0-9]{4}$'
    OR coalesce(earning->>'earnedFrom','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    OR coalesce(earning->>'earnedThrough','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION 'Prior earning lines require a unique source key, original category, dated classification and exact decimal amount.';
   END IF;
   IF earning->>'sourceKey'=ANY(source_keys) THEN RAISE EXCEPTION 'A prior earning source is repeated; duplicate copies must not count twice.'; END IF;
   source_keys:=array_append(source_keys,earning->>'sourceKey');
   earning_from:=(earning->>'earnedFrom')::date; earning_through:=(earning->>'earnedThrough')::date;
   IF earning_from<(source_period->>'from')::date OR earning_through>(source_period->>'through')::date OR earning_through<earning_from THEN
    RAISE EXCEPTION 'Prior earning dates must lie wholly within the source period; payment dates do not establish earned dates.';
   END IF;
  END LOOP;
  next_day:=(source_period->>'through')::date+1;
 END LOOP;
 IF next_day<>NEW.history_through+1 THEN RAISE EXCEPTION 'Prior earnings do not reach the declared end of history.'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_program_period_bounds_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE subjects jsonb; subject record; bound numeric; annual_amount numeric;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 subjects:=CASE WHEN TG_OP='INSERT' THEN jsonb_build_array(to_jsonb(NEW))
  WHEN TG_OP='DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END;
 IF TG_WHEN='BEFORE' THEN
  -- Direct program corrections use the same ordering as annual entry and
  -- payroll commit, before the changed amounts become visible.
  FOR subject IN SELECT DISTINCT org_id,employee_party_id FROM jsonb_to_recordset(subjects)
   AS r(org_id uuid,employee_party_id uuid) ORDER BY org_id,employee_party_id LOOP
   IF NOT public.openbooks_sandbox_wipe_allowed(subject.org_id) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||subject.org_id||':'||subject.employee_party_id,0));
   END IF;
  END LOOP;
  FOR subject IN SELECT DISTINCT org_id,employee_party_id,tax_year FROM jsonb_to_recordset(subjects)
   AS r(org_id uuid,employee_party_id uuid,tax_year integer) ORDER BY org_id,employee_party_id,tax_year LOOP
   IF NOT public.openbooks_sandbox_wipe_allowed(subject.org_id) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||subject.org_id||':'||subject.employee_party_id||':'||subject.tax_year,0));
   END IF;
  END LOOP;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END IF;
 -- A reassignment must also preserve the old subject's admitted share.
 FOR subject IN SELECT DISTINCT org_id,employee_party_id,tax_year,program_key FROM jsonb_to_recordset(subjects)
  AS r(org_id uuid,employee_party_id uuid,tax_year integer,program_key text) LOOP
  IF public.openbooks_sandbox_wipe_allowed(subject.org_id) THEN CONTINUE; END IF;
  SELECT (annual_bounds->>('program:'||subject.program_key))::numeric INTO bound FROM public.payroll_period_openings
   WHERE org_id=subject.org_id AND employee_party_id=subject.employee_party_id AND tax_year=subject.tax_year;
  IF bound IS NOT NULL THEN
   SELECT coalesce(sum(insurable_ytd),0) INTO annual_amount FROM public.payroll_opening_program_bases
    WHERE org_id=subject.org_id AND employee_party_id=subject.employee_party_id AND tax_year=subject.tax_year AND program_key=subject.program_key;
   IF annual_amount<bound THEN RAISE EXCEPTION 'Annual contribution-program balances cannot be reduced below their admitted period payments; correct the unused period amounts first.'; END IF;
  END IF;
 END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_roe_issued_event_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE snapshot jsonb;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Issued ROE event source bindings and snapshots are immutable' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id::text||':'||NEW.employee_party_id::text,0));
 IF NOT EXISTS(SELECT 1 FROM public.payroll_roe_separation_events e
   JOIN public.payroll_filing_submission_slips sl ON sl.id=NEW.issued_slip_id AND sl.org_id=e.org_id
   JOIN public.payroll_filing_submissions f ON f.org_id=sl.org_id AND f.id=sl.submission_id
   WHERE e.org_id=NEW.org_id AND e.id=NEW.event_id AND e.employee_party_id=NEW.employee_party_id
     AND e.status='confirmed' AND e.first_day_worked IS NOT NULL AND e.employment_id IS NOT NULL AND e.subsidiary_id IS NOT NULL
     AND sl.row_id=e.employee_party_id::text||'~'||e.id::text AND f.country='CA' AND f.filing_key='roe') THEN
   RAISE EXCEPTION 'Issued ROE binding requires the exact confirmed employee event and native issued slip' USING ERRCODE='23514';
 END IF;
 IF cardinality(NEW.historical_period_ids)<>(SELECT count(DISTINCT p) FROM unnest(NEW.historical_period_ids) p)
   OR cardinality(NEW.line_evidence_ids)<>(SELECT count(DISTINCT l) FROM unnest(NEW.line_evidence_ids) l)
   OR cardinality(NEW.excluded_stub_ids)<>(SELECT count(DISTINCT s) FROM unnest(NEW.excluded_stub_ids) s) THEN
   RAISE EXCEPTION 'Issued ROE source identities must be unique' USING ERRCODE='23514';
 END IF;
 snapshot:=public.payroll_roe_issued_source_snapshot_with_returns(NEW.org_id,NEW.event_id,NEW.historical_period_ids,NEW.line_evidence_ids,NEW.excluded_stub_ids);
 IF snapshot IS NULL OR snapshot IS DISTINCT FROM NEW.source_snapshot
   OR jsonb_array_length(snapshot->'historicalPeriods')<>cardinality(NEW.historical_period_ids)
   OR jsonb_array_length(snapshot->'lineEvidence')<>cardinality(NEW.line_evidence_ids)
   OR encode(public.digest(snapshot::text,'sha256'),'hex')<>NEW.source_sha256 THEN
   RAISE EXCEPTION 'Issued ROE binding must retain the exact selected event and used reporting evidence snapshot' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_issued_source_snapshot_with_returns(tenant uuid, event uuid, period_ids uuid[], line_ids uuid[], excluded_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE body jsonb; excluded jsonb; line_count bigint;
BEGIN
 IF cardinality(excluded_ids)>5000 THEN RAISE EXCEPTION 'ROE service evidence exceeds the bounded retained-stub window' USING ERRCODE='23514'; END IF;
 body:=public.payroll_roe_issued_source_snapshot(tenant,event,period_ids,line_ids);
 SELECT count(*) INTO line_count FROM (
   SELECT l.id FROM public.pay_stub_lines l WHERE l.org_id=tenant AND l.stub_id=ANY(excluded_ids)
     AND l.kind='earning' AND (l.amount<>0 OR l.hours<>0) LIMIT 50001
 ) bounded;
 IF line_count>50000 THEN RAISE EXCEPTION 'ROE service evidence exceeds the bounded retained-line window' USING ERRCODE='23514'; END IF;
 SELECT jsonb_agg(q.proof ORDER BY q.stub_id) INTO excluded FROM (
   SELECT s.id AS stub_id,public.payroll_roe_later_stub_source(tenant,event,s.id) AS proof
   FROM public.pay_stubs s WHERE s.org_id=tenant AND s.id=ANY(excluded_ids)
 ) q WHERE q.proof IS NOT NULL;
 IF jsonb_array_length(coalesce(excluded,'[]'::jsonb))<>cardinality(excluded_ids) THEN
   RAISE EXCEPTION 'Issued ROE exclusions need every exact source-qualified later stub identity' USING ERRCODE='23514';
 END IF;
 IF excluded IS NOT NULL THEN body:=body||jsonb_build_object('excludedLaterService',excluded); END IF;
 RETURN body;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_reporting_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE snapshot jsonb; employee uuid; tenant uuid;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 employee:=CASE WHEN TG_OP='DELETE' THEN OLD.employee_party_id ELSE NEW.employee_party_id END;
 tenant:=CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||tenant::text||':'||employee::text,0));
 IF TG_OP='UPDATE' AND (NEW.org_id,NEW.employee_party_id,NEW.employment_id,NEW.subsidiary_id)
   IS DISTINCT FROM (OLD.org_id,OLD.employee_party_id,OLD.employment_id,OLD.subsidiary_id) THEN
   RAISE EXCEPTION 'ROE reporting evidence cannot change its employee, employment or legal employer' USING ERRCODE='23514';
 END IF;
 IF public.payroll_roe_has_unbound_issued_source(tenant,employee) OR
   (TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM public.payroll_roe_issued_event_sources b
     WHERE b.org_id=tenant AND ((TG_TABLE_NAME='payroll_roe_historical_periods' AND OLD.id=ANY(b.historical_period_ids))
       OR (TG_TABLE_NAME='payroll_roe_line_evidence' AND OLD.id=ANY(b.line_evidence_ids))))) THEN
   RAISE EXCEPTION 'Issued ROE reporting evidence must be retained; its used source cannot be changed' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.worker_employments e WHERE e.org_id=NEW.org_id AND e.id=NEW.employment_id
   AND e.worker_party_id=NEW.employee_party_id AND e.employer_subsidiary_id=NEW.subsidiary_id) THEN
   RAISE EXCEPTION 'ROE reporting evidence must identify the native employee, employment and employer' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
   WHERE f.org_id=NEW.org_id AND f.id=NEW.source_file_id AND v.id=NEW.source_version_id AND v.content_hash=NEW.source_sha256) THEN
   RAISE EXCEPTION 'ROE reporting evidence needs the exact retained native file version and content hash' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='payroll_roe_historical_periods' THEN
   IF NOT EXISTS(SELECT 1 FROM public.pay_schedules s WHERE s.org_id=NEW.org_id AND s.id=NEW.pay_schedule_id AND s.frequency=NEW.frequency AND (s.subsidiary_id IS NULL OR s.subsidiary_id=NEW.subsidiary_id))
     OR (NEW.frequency='weekly' AND NEW.period_end-NEW.period_start<>6)
     OR (NEW.frequency='biweekly' AND NEW.period_end-NEW.period_start<>13) THEN
     RAISE EXCEPTION 'Historical ROE periods need their native schedule and complete reporting interval' USING ERRCODE='23514';
   END IF;
   IF NOT EXISTS(SELECT 1 FROM public.payroll_filing_accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.filing_account_id
     AND a.subsidiary_id=NEW.subsidiary_id AND a.country='CA' AND a.program_type='ca_rp') THEN
     RAISE EXCEPTION 'The historical ROE period needs its native Canadian payroll filing account' USING ERRCODE='23514';
   END IF;
   IF EXISTS(SELECT 1 FROM public.payroll_roe_historical_periods p WHERE p.org_id=NEW.org_id AND p.employment_id=NEW.employment_id
     AND p.id<>NEW.id AND p.period_start<=NEW.period_end AND p.period_end>=NEW.period_start) THEN
     RAISE EXCEPTION 'Historical ROE reporting periods cannot overlap' USING ERRCODE='23514';
   END IF;
   IF EXISTS(SELECT 1 FROM public.pay_runs r JOIN public.documents d ON d.org_id=r.org_id AND d.id=r.document_id
     WHERE r.org_id=NEW.org_id AND d.subsidiary_id=NEW.subsidiary_id AND r.pay_schedule_id=NEW.pay_schedule_id
       AND r.run_status='committed' AND r.period_start<=NEW.period_end AND r.period_end>=NEW.period_start
       AND (r.run_type='regular' OR EXISTS(SELECT 1 FROM public.pay_stubs s WHERE s.org_id=r.org_id
         AND s.pay_run_document_id=r.document_id AND s.employee_party_id=NEW.employee_party_id))) THEN
     RAISE EXCEPTION 'Historical ROE evidence cannot replace or duplicate retained committed payroll periods' USING ERRCODE='23514';
   END IF;
 ELSE
   IF TG_OP='UPDATE' AND NEW.pay_stub_line_id IS DISTINCT FROM OLD.pay_stub_line_id THEN
     RAISE EXCEPTION 'ROE reporting evidence cannot be moved to a different committed earning line' USING ERRCODE='23514';
   END IF;
   snapshot:=public.payroll_roe_reporting_line_snapshot(NEW.pay_stub_line_id,NEW.org_id);
   IF snapshot IS NULL OR snapshot IS DISTINCT FROM NEW.line_snapshot
     OR snapshot->>'employmentId' IS DISTINCT FROM NEW.employment_id::text
     OR snapshot->>'subsidiaryId' IS DISTINCT FROM NEW.subsidiary_id::text
     OR snapshot->>'currency'<>'CAD'
     OR NOT EXISTS(SELECT 1 FROM public.pay_stubs s JOIN public.pay_stub_lines l ON l.org_id=s.org_id AND l.stub_id=s.id
       WHERE l.org_id=NEW.org_id AND l.id=NEW.pay_stub_line_id AND s.employee_party_id=NEW.employee_party_id) THEN
     RAISE EXCEPTION 'ROE line evidence must match the exact committed Canadian payroll source' USING ERRCODE='23514';
   END IF;
   IF (snapshot->>'earnedFrom' IS NOT NULL AND NEW.earned_from<(snapshot->>'earnedFrom')::date)
     OR (snapshot->>'earnedTo' IS NOT NULL AND NEW.earned_to>(snapshot->>'earnedTo')::date) THEN
     RAISE EXCEPTION 'Qualified earned evidence cannot expand the retained payroll span; correct its native source first' USING ERRCODE='23514';
   END IF;
   IF NEW.is_insurable AND snapshot->>'hours' IS NOT NULL AND (snapshot->>'hours')::numeric<>NEW.insurable_hours THEN
     RAISE EXCEPTION 'Qualified insurable hours must preserve the retained paid-hour source' USING ERRCODE='23514';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_separation_basis_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE proof jsonb; retained jsonb;
BEGIN
 IF NEW.reporting_basis='service' THEN RETURN NEW; END IF;
 -- Lock every mutable referenced declaration before taking its protected proof.
 PERFORM 1 FROM public.payroll_roe_separation_events WHERE org_id=NEW.org_id AND id=NEW.separation_event_id FOR SHARE;
 PERFORM 1 FROM public.payroll_roe_separation_payments WHERE org_id=NEW.org_id AND id=NEW.separation_payment_id FOR SHARE;

 proof:=public.payroll_roe_separation_reporting_basis(NEW.org_id,NEW.separation_event_id,NEW.pay_stub_line_id,NEW.separation_payment_id,NEW.report_period_start,NEW.report_period_end);
 retained:=public.payroll_roe_reporting_line_snapshot(NEW.pay_stub_line_id,NEW.org_id);
 IF proof IS NULL OR proof IS DISTINCT FROM NEW.separation_basis_snapshot OR retained IS DISTINCT FROM NEW.line_snapshot
   OR proof->'event'->>'employee_party_id' IS DISTINCT FROM NEW.employee_party_id::text
   OR proof->'event'->>'employment_id' IS DISTINCT FROM NEW.employment_id::text
   OR proof->'event'->>'subsidiary_id' IS DISTINCT FROM NEW.subsidiary_id::text
   OR NEW.earned_from IS DISTINCT FROM (retained->>'earnedFrom')::date
   OR NEW.earned_to IS DISTINCT FROM (retained->>'earnedTo')::date THEN
   RAISE EXCEPTION 'Separation reporting needs the exact paid line, selected event, effective category and final period; retain its true earned and payment dates' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_separation_basis_reference_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE subject jsonb; selected_event uuid; tenant uuid;
BEGIN
 subject:=CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END;
 tenant:=(subject->>'org_id')::uuid;selected_event:=(subject->>'separation_event_id')::uuid;
 IF TG_OP='UPDATE' AND (NEW.org_id,NEW.id,NEW.separation_event_id) IS DISTINCT FROM (OLD.org_id,OLD.id,OLD.separation_event_id) THEN
   RAISE EXCEPTION 'A separation payment declaration retains its organization, identity and selected event' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,subject)
   OR public.openbooks_sandbox_wipe_allowed(tenant)) THEN RETURN OLD; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||tenant::text||':'||
   (SELECT employee_party_id::text FROM public.payroll_roe_separation_events WHERE org_id=tenant AND id=selected_event),0));
 IF EXISTS(SELECT 1 FROM public.payroll_roe_separation_events e WHERE e.org_id=tenant AND e.id=selected_event AND e.status='issued')
   OR EXISTS(SELECT 1 FROM public.payroll_roe_issued_event_sources b WHERE b.org_id=tenant AND b.event_id=selected_event) THEN
   RAISE EXCEPTION 'Issued ROE separation payment declarations are immutable; retain the original statutory source' USING ERRCODE='23514';
 END IF;
 IF TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM public.payroll_roe_line_evidence evidence
   WHERE evidence.org_id=tenant AND evidence.reporting_basis='separation_payment' AND evidence.separation_payment_id=OLD.id) THEN
   RAISE EXCEPTION 'Qualified ROE separation reporting retains this payment; withdraw unissued attribution before correcting its declaration' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NEW.source_line_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.pay_stub_lines l JOIN public.pay_stubs s ON s.org_id=l.org_id AND s.id=l.stub_id
   JOIN public.pay_runs r ON r.org_id=s.org_id AND r.document_id=s.pay_run_document_id AND r.run_status='committed'
   JOIN public.documents d ON d.org_id=r.org_id AND d.id=r.document_id
   JOIN public.payroll_roe_separation_events e ON e.org_id=s.org_id AND e.id=NEW.separation_event_id
   WHERE l.org_id=NEW.org_id AND l.id=NEW.source_line_id AND l.kind='earning' AND l.component_id=NEW.pay_component_id
     AND l.amount=NEW.amount AND l.amount>0 AND l.amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) AND (l.hours IS NULL OR l.hours=0) AND s.pay_date=NEW.expected_payment_on
     AND s.employee_party_id=e.employee_party_id AND s.employment_id=e.employment_id AND d.subsidiary_id=e.subsidiary_id AND d.status<>'voided'
     AND s.currency_code='CAD' AND NEW.payment_status='paid') THEN
   RAISE EXCEPTION 'A paid separation declaration must retain its exact committed employee line and payment facts' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_separation_facts_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE recorded boolean;
BEGIN
  IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
    OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT EXISTS(SELECT 1 FROM public.payroll_roe_issued_event_sources b
      WHERE b.org_id=OLD.org_id AND b.event_id=OLD.id)
      OR public.payroll_roe_has_unbound_issued_source(OLD.org_id,OLD.employee_party_id) INTO recorded;
    IF OLD.status='issued' OR recorded THEN
      IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'Issued Record of Employment separation facts must be retained; use the Service Canada correction workflow'
          USING ERRCODE='23514',CONSTRAINT='payroll_roe_separation_facts_issued';
      END IF;
      IF ROW(NEW.org_id,NEW.employee_party_id,NEW.employment_id,NEW.subsidiary_id,NEW.first_day_worked,
          NEW.interruption_on,NEW.last_insurable_earnings_on,NEW.salary_continuance_end_on,NEW.source_reference,NEW.change_reason)
        IS DISTINCT FROM ROW(OLD.org_id,OLD.employee_party_id,OLD.employment_id,OLD.subsidiary_id,OLD.first_day_worked,
          OLD.interruption_on,OLD.last_insurable_earnings_on,OLD.salary_continuance_end_on,OLD.source_reference,OLD.change_reason)
        OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status <> 'issued') THEN
        RAISE EXCEPTION 'Issued Record of Employment separation facts are immutable; use the Service Canada correction workflow'
          USING ERRCODE='23514',CONSTRAINT='payroll_roe_separation_facts_issued';
      END IF;
    END IF;
  END IF;
  IF TG_OP='INSERT' AND public.payroll_roe_has_unbound_issued_source(NEW.org_id,NEW.employee_party_id) THEN
    RAISE EXCEPTION 'A legacy issued ROE has no qualified event source binding; preserve its artifact and resolve the original event evidence'
      USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id::text||':'||NEW.employee_party_id::text,0));
  IF NEW.status='issued' AND NOT EXISTS(SELECT 1 FROM public.payroll_roe_issued_event_sources b WHERE b.org_id=NEW.org_id AND b.event_id=NEW.id)
    AND NOT(TG_OP='UPDATE' AND OLD.status='issued') THEN
    RAISE EXCEPTION 'Record the exact native issued event source binding before marking ROE facts issued' USING ERRCODE='23514';
  END IF;

  IF NEW.status IN ('confirmed','issued') AND NEW.first_day_worked IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.payroll_roe_separation_events e WHERE e.org_id=NEW.org_id
      AND e.employee_party_id=NEW.employee_party_id AND e.employment_id=NEW.employment_id
      AND e.id<>NEW.id AND e.status IN ('confirmed','issued')
      AND e.first_day_worked<=coalesce(NEW.salary_continuance_end_on,NEW.last_insurable_earnings_on)
      AND coalesce(e.salary_continuance_end_on,e.last_insurable_earnings_on)>=NEW.first_day_worked) THEN
    RAISE EXCEPTION 'Employment-spell dates overlap another confirmed separation event; reconcile the original spell evidence' USING ERRCODE='23514';
  END IF;

  IF NEW.employment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.worker_employments e
    WHERE e.org_id=NEW.org_id AND e.id=NEW.employment_id
      AND e.worker_party_id=NEW.employee_party_id AND e.employer_subsidiary_id=NEW.subsidiary_id
  ) THEN
    RAISE EXCEPTION 'Record of Employment facts must identify the selected employee, native employment and legal employer'
      USING ERRCODE='23514',CONSTRAINT='payroll_roe_separation_facts_identity';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_subsequent_service_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'Retain return-to-service certificates and their audit history; correct unused evidence through the native command' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.org_id,NEW.preceding_event_id,NEW.employee_party_id,NEW.employment_id,NEW.subsidiary_id,NEW.created_by,NEW.created_at)
   IS DISTINCT FROM ROW(OLD.org_id,OLD.preceding_event_id,OLD.employee_party_id,OLD.employment_id,OLD.subsidiary_id,OLD.created_by,OLD.created_at) THEN
   RAISE EXCEPTION 'Return-to-service evidence cannot change its original event or subject identity' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||NEW.org_id::text||':'||NEW.employee_party_id::text,0));
 IF public.payroll_roe_has_unbound_issued_source(NEW.org_id,NEW.employee_party_id) OR EXISTS(
   SELECT 1 FROM public.payroll_roe_issued_event_sources b WHERE b.org_id=NEW.org_id AND b.event_id=NEW.preceding_event_id) THEN
   RAISE EXCEPTION 'An issued ROE retains its service scope; preserve its source and use the statutory correction workflow' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.payroll_roe_separation_events e
   JOIN public.worker_employments w ON w.org_id=e.org_id AND w.id=e.employment_id
   WHERE e.org_id=NEW.org_id AND e.id=NEW.preceding_event_id AND e.status='confirmed'
     AND e.employee_party_id=NEW.employee_party_id AND e.employment_id=NEW.employment_id
     AND e.subsidiary_id=NEW.subsidiary_id AND w.worker_party_id=NEW.employee_party_id
     AND w.employer_subsidiary_id=NEW.subsidiary_id AND e.first_day_worked IS NOT NULL
     AND NEW.first_day_worked>e.interruption_on
     AND NEW.first_day_worked>coalesce(e.salary_continuance_end_on,e.last_insurable_earnings_on)) THEN
   RAISE EXCEPTION 'Return-to-service evidence needs the exact earlier confirmed event, native employment and employer, and a later first day worked'
     USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.files f JOIN public.file_versions v ON v.file_id=f.id
   WHERE f.org_id=NEW.org_id AND f.id=NEW.source_file_id AND v.id=NEW.source_version_id
     AND v.content_hash=NEW.source_sha256 AND v.created_by=NEW.updated_by) THEN
   RAISE EXCEPTION 'Return-to-service evidence needs the importing operator retained source file version and content hash' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_roe_used_exclusion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE tenant uuid; employee uuid; identity uuid;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 tenant:=CASE WHEN TG_OP='INSERT' THEN NEW.org_id ELSE OLD.org_id END;
 employee:=CASE WHEN TG_OP='INSERT' THEN NEW.employee_party_id ELSE OLD.employee_party_id END;
 identity:=CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END;
 IF TG_TABLE_NAME='payroll_roe_separation_events' AND TG_OP='UPDATE'
   AND to_jsonb(NEW)->>'status'='issued' AND to_jsonb(OLD)->>'status'='confirmed'
   AND (to_jsonb(NEW)-ARRAY['status','updated_at','updated_by'])=(to_jsonb(OLD)-ARRAY['status','updated_at','updated_by']) THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('payroll-run-ytd:'||tenant::text||':'||employee::text,0));
 IF EXISTS(SELECT 1 FROM public.payroll_roe_issued_event_sources b,
   LATERAL jsonb_array_elements(coalesce(b.source_snapshot->'excludedLaterService','[]'::jsonb)) proof
   WHERE b.org_id=tenant AND b.employee_party_id=employee AND (
     TG_TABLE_NAME='payroll_roe_separation_events' AND proof->'laterEvent'->>'id'=identity::text
     OR TG_TABLE_NAME='payroll_roe_line_evidence' AND EXISTS(
       SELECT 1 FROM jsonb_array_elements(proof->'lines') line WHERE line->'attribution'->>'id'=identity::text
         OR TG_OP='INSERT' AND line->'retained'->>'lineId'=to_jsonb(NEW)->>'pay_stub_line_id'))) THEN
   RAISE EXCEPTION 'Issued ROE used exclusion evidence cannot be changed; retain the original and use the statutory correction workflow'
     USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.payroll_service_configuration_audit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE row_value jsonb;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP = 'DELETE' THEN row_value := to_jsonb(OLD); ELSE row_value := to_jsonb(NEW); END IF;
 INSERT INTO public.audit_log(org_id,table_name,row_id,action,changes,actor_id)
 VALUES ((row_value->>'org_id')::uuid,TG_TABLE_NAME,(row_value->>'id')::uuid,lower(TG_OP),
 jsonb_build_object('before',CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,'after',CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END),
 coalesce((row_value->>'updated_by')::uuid,(row_value->>'created_by')::uuid));
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_service_configuration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE last_period_end date; target_org uuid; configurations jsonb;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='INSERT' AND public.payroll_service_historical_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
 target_org := CASE WHEN TG_OP = 'INSERT' THEN NEW.org_id ELSE OLD.org_id END;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:payroll-service:' || target_org::text,0));
 IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 configurations := CASE WHEN TG_OP = 'INSERT' THEN jsonb_build_array(to_jsonb(NEW))
  WHEN TG_OP = 'DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END;
 SELECT max(r.period_end) INTO last_period_end FROM public.pay_runs r JOIN public.pay_stubs s
  ON s.org_id = r.org_id AND s.pay_run_document_id = r.document_id
 LEFT JOIN public.worker_employments e ON e.org_id=s.org_id AND e.id=s.employment_id
 WHERE r.org_id = target_org AND r.run_status IN ('committed','voided') AND EXISTS (
  SELECT 1 FROM jsonb_array_elements(configurations) cfg
  WHERE (cfg->>'employment_id' IS NULL OR s.employment_id=(cfg->>'employment_id')::uuid)
    AND (cfg->>'employer_subsidiary_id' IS NULL OR e.employer_subsidiary_id IS NULL OR e.employer_subsidiary_id=(cfg->>'employer_subsidiary_id')::uuid)
    AND r.period_end >= (cfg->>'effective_from')::date
    AND (cfg->>'effective_to' IS NULL OR r.period_end <= (cfg->>'effective_to')::date)
 );
 IF last_period_end IS NOT NULL THEN
  IF TG_OP IN ('INSERT','DELETE') THEN
   RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'This service configuration affects committed payroll evidence. Preserve its terms and add a replacement effective after the last committed period end.';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['effective_to','updated_at','updated_by']) IS DISTINCT FROM
     (to_jsonb(OLD) - ARRAY['effective_to','updated_at','updated_by']) OR NEW.effective_to IS NULL OR NEW.effective_to < last_period_end THEN
   RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'This service configuration has committed payroll evidence. Preserve its terms, close its window on or after the last committed period end, and add an effective-dated replacement.';
  END IF;
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_service_historical_clone_matches(relation regclass, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target record; original jsonb; expected jsonb; column_row record; removed jsonb;
BEGIN
 IF NOT public.openbooks_clone_authority() OR relation NOT IN ('public.payroll_vacation_terms'::regclass,
  'public.payroll_service_credits'::regclass,'public.entitlement_service_tiers'::regclass) THEN RETURN false; END IF;
 SELECT o.id,o.sandbox_of,o.sandbox_seed,s.masked INTO target FROM public.orgs o
 JOIN public.sandboxes s ON s.org_id=o.id AND s.production_org_id=o.sandbox_of
 WHERE o.id=(candidate->>'org_id')::uuid AND o.env_kind='sandbox' AND o.sandbox_seed IS NOT NULL;
 IF NOT FOUND THEN RETURN false; END IF;
 EXECUTE format('SELECT to_jsonb(source) FROM %s source WHERE source.org_id=$1 AND public.ob_rebase(source.id,$2)=$3',relation)
 INTO original USING target.sandbox_of,target.sandbox_seed,(candidate->>'id')::uuid;
 IF original IS NULL THEN RETURN false; END IF;
 expected:=original;
 FOR column_row IN SELECT attname,atttypid,attnotnull FROM pg_catalog.pg_attribute WHERE attrelid=relation AND attnum>0 AND NOT attisdropped LOOP
  IF column_row.attname='org_id' THEN expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(target.id));
  ELSIF column_row.atttypid='uuid'::regtype AND jsonb_typeof(original->column_row.attname)='string' THEN
   expected:=jsonb_set(expected,ARRAY[column_row.attname],to_jsonb(public.ob_rebase((original->>column_row.attname)::uuid,target.sandbox_seed)));
  END IF;
  IF target.masked AND column_row.attname IN('source_snapshot','reason') AND EXISTS(
   SELECT 1 FROM public.masking_policies p WHERE p.org_id=target.sandbox_of AND p.table_name=(SELECT relname FROM pg_class WHERE oid=relation)
    AND p.column_name=column_row.attname AND p.is_active AND
      ((column_row.attname='source_snapshot' AND p.transform='null_out') OR (column_row.attname='reason' AND p.transform='redact'))) THEN
   removed:=CASE WHEN column_row.attname='reason' AND original->column_row.attname<>'null'::jsonb THEN to_jsonb('REDACTED'::text)
    WHEN column_row.attnotnull AND column_row.atttypid='jsonb'::regtype THEN '{}'::jsonb ELSE 'null'::jsonb END;
   expected:=jsonb_set(expected,ARRAY[column_row.attname],removed);
  END IF;
 END LOOP;
 RETURN candidate=expected;
END $function$

CREATE OR REPLACE FUNCTION public.payroll_us_filing_account_lineage_clone_matches(candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target record;
  original jsonb;
  expected jsonb;
  column_row record;
BEGIN
  IF NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
  SELECT org.sandbox_of, org.sandbox_seed, sandbox.masked
    INTO target
    FROM public.orgs org
    JOIN public.sandboxes sandbox
      ON sandbox.org_id = org.id AND sandbox.production_org_id = org.sandbox_of
    JOIN public.orgs production ON production.id = org.sandbox_of AND production.id <> org.id
   WHERE org.id = (candidate->>'org_id')::uuid
     AND org.env_kind = 'sandbox'
     AND org.sandbox_seed IS NOT NULL
     AND sandbox.status IN ('provisioning', 'refreshing');
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT to_jsonb(source)
    INTO original
    FROM public.payroll_us_filing_account_employer_lineage source
   WHERE source.org_id = target.sandbox_of
     AND public.ob_rebase(source.id, target.sandbox_seed) = (candidate->>'id')::uuid;
  IF original IS NULL THEN RETURN false; END IF;

  expected := original;
  FOR column_row IN
    SELECT attribute.attname, attribute.atttypid
      FROM pg_catalog.pg_attribute attribute
     WHERE attribute.attrelid = 'public.payroll_us_filing_account_employer_lineage'::regclass
       AND attribute.attnum > 0 AND NOT attribute.attisdropped
  LOOP
    IF column_row.attname = 'org_id' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb((candidate->>'org_id')::uuid));
    ELSIF column_row.atttypid = 'uuid'::regtype
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb(public.ob_rebase(
        (original->>column_row.attname)::uuid, target.sandbox_seed
      )));
    END IF;
    IF target.masked AND column_row.attname IN ('source_reference', 'change_reason')
      AND jsonb_typeof(original->column_row.attname) = 'string' THEN
      expected := jsonb_set(expected, ARRAY[column_row.attname], to_jsonb('REDACTED'::text));
    END IF;
  END LOOP;
  RETURN candidate = expected;
END
$function$

CREATE OR REPLACE FUNCTION public.payroll_work_location_allocation_audit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_row public.payroll_work_location_allocations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    v_row := OLD;
  ELSE
    v_row := NEW;
  END IF;
  INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id)
  VALUES (
    v_row.org_id,
    'payroll_work_location_allocations',
    v_row.id,
    lower(TG_OP),
    jsonb_build_object(
      'before', CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
      'after', CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END,
      'reason', v_row.change_reason
    ),
    coalesce(v_row.updated_by, v_row.created_by)
  );
  RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.payroll_work_location_allocation_lock_committed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_org uuid := coalesce(NEW.org_id, OLD.org_id);
  v_employment uuid := coalesce(NEW.employment_id, OLD.employment_id);
  v_start date := coalesce(NEW.period_start, OLD.period_start);
  v_end date := coalesce(NEW.period_end, OLD.period_end);
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pay_stubs s
    JOIN public.pay_runs r ON r.org_id = s.org_id AND r.document_id = s.pay_run_document_id
    JOIN public.documents d ON d.org_id = r.org_id AND d.id = r.document_id
    WHERE s.org_id = v_org AND s.employment_id = v_employment
      AND r.period_start = v_start AND r.period_end = v_end
      AND r.run_status = 'committed' AND d.status <> 'voided'
  ) THEN
    RAISE EXCEPTION 'Payroll work allocation is locked because a payroll run for this employment period is committed'
      USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.period_end_journal_entry_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_set record;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Period-end journal links are retained history.' USING ERRCODE = '23514';
  END IF;
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT s.book_id, s.subsidiary_id, s.status INTO v_set
      FROM public.period_end_journal_sets s
     WHERE s.org_id = NEW.org_id AND s.id = NEW.set_id;
    IF NOT FOUND OR v_set.status <> 'posted' OR NEW.reversal_entry_id IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM public.journal_entries e
       WHERE e.org_id = NEW.org_id AND e.id = NEW.entry_id AND e.status = 'posted'
         AND e.book_id = v_set.book_id AND e.subsidiary_id = v_set.subsidiary_id
         AND e.reverses_entry_id IS NULL
         AND e.origin = CASE WHEN NEW.kind = 'opening' THEN 'opening' ELSE 'closing' END
    ) THEN
      RAISE EXCEPTION 'A period-end journal link names a posted period-end entry of its live generation''s book and legal entity.'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.reversal_entry_id IS NULL AND NEW.reversal_entry_id IS NOT NULL
     AND NEW.id = OLD.id AND NEW.org_id = OLD.org_id AND NEW.set_id = OLD.set_id
     AND NEW.kind = OLD.kind AND NEW.entry_id = OLD.entry_id AND NEW.created_at = OLD.created_at
     AND EXISTS (
       SELECT 1 FROM public.journal_entries r
        WHERE r.org_id = NEW.org_id AND r.id = NEW.reversal_entry_id
          AND r.status = 'posted' AND r.reverses_entry_id = NEW.entry_id
     ) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'A period-end journal link changes only once, to name the posted reversal of its entry.'
    USING ERRCODE = '23514';
END;
$function$

CREATE OR REPLACE FUNCTION public.period_end_journal_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
      RETURN NEW;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.accounts a
       WHERE a.org_id = NEW.org_id AND a.id = NEW.retained_earnings_account_id
         AND a.type = 'equity' AND NOT a.is_summary AND a.is_active
    ) THEN
      RAISE EXCEPTION 'The retained earnings account of a period-end journal policy must be an active, postable equity account.'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.income_summary_account_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.accounts a
       WHERE a.org_id = NEW.org_id AND a.id = NEW.income_summary_account_id
         AND a.type = 'equity' AND NOT a.is_summary AND a.is_active
    ) THEN
      RAISE EXCEPTION 'The income summary account of a period-end journal policy must be an active, postable equity account.'
        USING ERRCODE = '23514';
    END IF;
    -- A new version cannot reach back into a year already closed by journal.
    IF EXISTS (
      SELECT 1 FROM public.period_end_journal_sets s
       WHERE s.org_id = NEW.org_id AND s.status = 'posted' AND s.year_ends_on >= NEW.effective_from
    ) THEN
      RAISE EXCEPTION 'A period-end journal policy cannot take effect on or before the end of a fiscal year closed by period-end journals; choose a later effective date.'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Period-end journal policy history is preserved; record a new policy with its effective date in Setup → Accounting → Period-End Journals.'
    USING ERRCODE = '23514';
END;
$function$

CREATE OR REPLACE FUNCTION public.period_end_journal_posting_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_subsidiaries uuid[];
  v_seal record;
BEGIN
  IF NEW.status <> 'posted' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM 'draft' THEN
    RETURN NEW;
  END IF;
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.period_end_journal_sets s
     WHERE s.org_id = NEW.org_id AND s.book_id = NEW.book_id AND s.status = 'posted'
  ) THEN
    RETURN NEW;
  END IF;
  SELECT array_agg(DISTINCT l.subsidiary_id) INTO v_subsidiaries
    FROM public.journal_lines l
   WHERE l.org_id = NEW.org_id AND l.entry_id = NEW.id;
  v_subsidiaries := array_append(coalesce(v_subsidiaries, ARRAY[]::uuid[]), NEW.subsidiary_id);
  SELECT * INTO v_seal
    FROM public.period_end_journal_seal(NEW.org_id, NEW.book_id, NEW.period_id, v_subsidiaries, NEW.reverses_entry_id);
  IF FOUND THEN
    RAISE EXCEPTION 'Fiscal year % of this accounting book is closed by its period-end journals; request a controlled reopen of the year-end period, which reverses them, before posting into it.', v_seal.fiscal_year
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.period_end_journal_set_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Period-end journal generations are retained history; reverse the generation instead.'
      USING ERRCODE = '23514';
  END IF;
  IF public.app_bypass_rls_active() AND coalesce(current_setting('openbooks.migration', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'posted' THEN
      RAISE EXCEPTION 'A period-end journal generation is recorded as posted.' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.accounting_periods p
       WHERE p.org_id = NEW.org_id AND p.id = NEW.closing_period_id
         AND p.fiscal_calendar_id = NEW.fiscal_calendar_id AND p.fiscal_year = NEW.fiscal_year
         AND p.ends_on = NEW.year_ends_on
    ) THEN
      RAISE EXCEPTION 'The closing period of a period-end journal generation must be a period of its fiscal year ending on the year end.'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.opening_period_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.accounting_periods p
       WHERE p.org_id = NEW.org_id AND p.id = NEW.opening_period_id
         AND p.fiscal_calendar_id = NEW.fiscal_calendar_id AND p.starts_on > NEW.year_ends_on
         AND NOT p.is_adjustment
    ) THEN
      RAISE EXCEPTION 'The opening period of a period-end journal generation must be a regular period after the closed year.'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status = 'posted' AND NEW.status = 'reversed'
     AND NEW.id = OLD.id AND NEW.org_id = OLD.org_id AND NEW.book_id = OLD.book_id
     AND NEW.subsidiary_id = OLD.subsidiary_id AND NEW.fiscal_calendar_id = OLD.fiscal_calendar_id
     AND NEW.fiscal_year = OLD.fiscal_year AND NEW.year_starts_on = OLD.year_starts_on
     AND NEW.year_ends_on = OLD.year_ends_on AND NEW.closing_period_id = OLD.closing_period_id
     AND NEW.opening_period_id IS NOT DISTINCT FROM OLD.opening_period_id
     AND NEW.generation = OLD.generation AND NEW.policy_id = OLD.policy_id
     AND NEW.policy_snapshot = OLD.policy_snapshot AND NEW.content_hash = OLD.content_hash
     AND NEW.currency = OLD.currency AND NEW.fiscal_year_earnings = OLD.fiscal_year_earnings
     AND NEW.prior_unclosed_earnings = OLD.prior_unclosed_earnings AND NEW.reason = OLD.reason
     AND NEW.generated_at = OLD.generated_at AND NEW.generated_by IS NOT DISTINCT FROM OLD.generated_by
     AND NEW.created_at = OLD.created_at AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
     AND (NEW.reopen_request_id IS NULL OR EXISTS (
       SELECT 1 FROM public.close_reopen_requests r WHERE r.org_id = NEW.org_id AND r.id = NEW.reopen_request_id
     ))
     AND NOT EXISTS (
       SELECT 1 FROM public.period_end_journal_entries pe
        WHERE pe.org_id = NEW.org_id AND pe.set_id = NEW.id AND pe.reversal_entry_id IS NULL
     ) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'A period-end journal generation changes only from posted to reversed, after every journal in it has been reversed, with the reversal evidence.'
    USING ERRCODE = '23514';
END;
$function$

CREATE OR REPLACE FUNCTION public.pick_execution_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
