 END IF;
 IF (to_jsonb(NEW)-'current_stock_location_id') IS DISTINCT FROM (to_jsonb(OLD)-'current_stock_location_id') THEN
  RAISE EXCEPTION 'Pick confirmation and short-pick release are immutable';
 END IF;
