CREATE OR REPLACE FUNCTION public.rate_adjustment_target_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT version.status, adjustment.org_id
    INTO v_status, v_org_id
    FROM labor_rate_adjustments adjustment
    JOIN item_rate_versions version
      ON version.id = adjustment.version_id
     AND version.org_id = adjustment.org_id
   WHERE adjustment.id = coalesce(NEW.adjustment_id, OLD.adjustment_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'adjustment target must reference a tenant-owned rate version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.rate_book_currency_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    IF EXISTS (
      SELECT 1 FROM item_rate_versions version
       WHERE version.rate_book_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'a rate book with version history cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'rate book organization is immutable';
  END IF;
  IF NEW.currency IS DISTINCT FROM OLD.currency
     AND EXISTS (
       SELECT 1 FROM item_rate_versions version
        WHERE version.rate_book_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'rate book currency cannot change after version history exists';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.rate_version_child_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  SELECT status, org_id
    INTO v_status, v_org_id
    FROM public.item_rate_versions
   WHERE id = coalesce(NEW.version_id, OLD.version_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'rate-version child must reference a tenant-owned version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    -- The native clone copies the immutable source snapshot into a sandbox.
    -- Its privileged, transaction-local authority permits INSERT only.
    IF TG_OP = 'INSERT' AND public.openbooks_clone_authority()
       AND EXISTS (SELECT 1 FROM public.orgs
                    WHERE id = NEW.org_id AND env_kind = 'sandbox'
                      AND sandbox_of IS NOT NULL) THEN
      RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE'
       AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'children of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.rate_version_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'activated and retired rate versions cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;

  IF OLD.status = 'active' AND NEW.status = 'active'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom
     AND NEW.effective_to IS NOT NULL
     AND NEW.effective_to >= OLD.effective_from
     AND (OLD.effective_to IS NULL OR NEW.effective_to <= OLD.effective_to) THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'active' AND NEW.status = 'retired'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.effective_to IS NOT DISTINCT FROM OLD.effective_to
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'activated and retired rate versions are immutable';
END
$function$

CREATE OR REPLACE FUNCTION public.rebate_agreement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE tier jsonb; last_threshold numeric; threshold numeric; rate numeric;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Rebate agreements are retained for audit'; END IF;
 IF TG_OP='UPDATE' AND OLD.status='approved' THEN RAISE EXCEPTION 'Approved rebate terms are immutable; create a successor dated agreement'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.org_id,NEW.created_by) IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.created_by) THEN RAISE EXCEPTION 'Rebate agreement identity is immutable'; END IF;
 IF jsonb_array_length(NEW.tiers)>100 OR (NEW.method IN ('percent','per_unit') AND jsonb_array_length(NEW.tiers)=0) THEN RAISE EXCEPTION 'Configure one through one hundred rebate tiers'; END IF;
 FOR tier IN SELECT value FROM jsonb_array_elements(NEW.tiers) LOOP
  IF jsonb_typeof(tier->'threshold') IS DISTINCT FROM 'string' OR jsonb_typeof(tier->'rate') IS DISTINCT FROM 'string'
    OR (tier->>'threshold') !~ '^[0-9]+(\.[0-9]{1,4})?$' OR (tier->>'rate') !~ '^[0-9]+(\.[0-9]{1,4})?$' THEN RAISE EXCEPTION 'Rebate tiers require exact non-negative threshold and rate strings'; END IF;
  threshold:=(tier->>'threshold')::numeric; rate:=(tier->>'rate')::numeric;
  IF (last_threshold IS NOT NULL AND threshold<=last_threshold) OR (NEW.method='percent' AND rate>100) THEN RAISE EXCEPTION 'Rebate thresholds must increase and percentages cannot exceed one hundred'; END IF;
  last_threshold:=threshold;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.accounts a WHERE a.org_id=NEW.org_id AND a.id=NEW.accrual_account_id AND a.is_active AND NOT a.is_summary AND a.type=CASE NEW.side WHEN 'customer' THEN 'liability_current_other' ELSE 'asset_current_other' END)
  THEN RAISE EXCEPTION 'Select a postable rebate liability or receivable account for this side'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[NEW.offset_account_id,NEW.fx_account_id]) target(id) WHERE NOT EXISTS(SELECT 1 FROM public.accounts a WHERE a.org_id=NEW.org_id AND a.id=target.id AND a.is_active AND NOT a.is_summary AND a.type IN ('expense','expense_other','cogs','income','income_other')))
  THEN RAISE EXCEPTION 'Select postable income or expense offset and FX accounts'; END IF;
 IF NEW.party_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.parties p WHERE p.org_id=NEW.org_id AND p.id=NEW.party_id AND p.is_active AND (p.subsidiary_id IS NULL OR p.subsidiary_id=NEW.subsidiary_id)
  AND CASE NEW.side WHEN 'customer' THEN EXISTS(SELECT 1 FROM public.customer_roles r WHERE r.org_id=p.org_id AND r.party_id=p.id AND r.is_active) ELSE EXISTS(SELECT 1 FROM public.vendor_roles r WHERE r.org_id=p.org_id AND r.party_id=p.id AND r.is_active) END)
  THEN RAISE EXCEPTION 'Agreement counterparty must hold the active customer or vendor role in this legal entity'; END IF;
 IF NEW.status='approved' AND EXISTS(SELECT 1 FROM public.rebate_agreements a WHERE a.org_id=NEW.org_id AND a.id<>NEW.id AND a.status='approved' AND a.subsidiary_id=NEW.subsidiary_id AND a.side=NEW.side
  AND a.party_id IS NOT DISTINCT FROM NEW.party_id AND a.selection_group=NEW.selection_group AND a.stacking='best' AND NEW.stacking='best'
  AND daterange(a.effective_from,a.effective_to,'[]') && daterange(NEW.effective_from,NEW.effective_to,'[]') AND a.currency<>NEW.currency)
  THEN RAISE EXCEPTION 'Competing best-deal agreements must use the same currency'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rebate_claim_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Rebate claim evidence is retained'; END IF;
 IF ROW(NEW.id,NEW.org_id,NEW.agreement_id,NEW.party_id,NEW.amount,NEW.base_amount,NEW.cutoff_on,NEW.basis,NEW.created_by,NEW.reason)
  IS DISTINCT FROM ROW(OLD.id,OLD.org_id,OLD.agreement_id,OLD.party_id,OLD.amount,OLD.base_amount,OLD.cutoff_on,OLD.basis,OLD.created_by,OLD.reason) THEN RAISE EXCEPTION 'Rebate claim terms are immutable'; END IF;
 IF NOT ((OLD.status='draft' AND NEW.status IN ('approved','cancelled')) OR (OLD.status='approved' AND NEW.status IN ('document_pending','settled','cancelled')) OR (OLD.status='document_pending' AND NEW.status IN ('settled','approved')) OR (OLD.status='settled' AND NEW.status='approved'))
  THEN RAISE EXCEPTION 'Invalid rebate claim transition'; END IF;
 IF OLD.approved_by IS NOT NULL AND ROW(NEW.approved_by,NEW.approved_at) IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at) THEN RAISE EXCEPTION 'Claim approval evidence is immutable'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.recognition_revision_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN
  IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
 END IF;
 IF OLD.superseded_by_change_id IS NOT NULL THEN RAISE EXCEPTION 'superseded revenue plans are immutable evidence'; END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.journal_entry_id IS NOT NULL THEN RAISE EXCEPTION 'posted revenue history cannot be deleted'; END IF;
  RETURN OLD;
 END IF;
 IF OLD.journal_entry_id IS NOT NULL AND
    (to_jsonb(NEW)-ARRAY['reversal_journal_entry_id','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['reversal_journal_entry_id','updated_at','updated_by']) THEN
   RAISE EXCEPTION 'posted revenue measurements are immutable; append an adjustment';
 END IF;
 IF OLD.reversal_journal_entry_id IS NOT NULL AND NEW.reversal_journal_entry_id IS DISTINCT FROM OLD.reversal_journal_entry_id THEN
   RAISE EXCEPTION 'revenue reversal lineage is immutable';
 END IF;
 IF NEW.superseded_by_change_id IS DISTINCT FROM OLD.superseded_by_change_id AND
   (OLD.journal_entry_id IS NOT NULL OR NOT EXISTS (
     SELECT 1 FROM financial_changes f JOIN recognition_schedules s ON s.id=OLD.schedule_id AND s.org_id=OLD.org_id
     JOIN performance_obligations o ON o.id=s.obligation_id AND o.org_id=s.org_id
     WHERE f.id=NEW.superseded_by_change_id AND f.org_id=OLD.org_id AND f.domain='revenue' AND f.subject_id=o.contract_id AND f.status='approved')) THEN
   RAISE EXCEPTION 'only unposted plans may be superseded by an approved modification of this contract';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.recon_matches_single_group_per_journal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Serialize concurrent match writers on the claimed journal: without this,
  -- two transactions could both pass the check below on uncommitted rows.
  PERFORM pg_advisory_xact_lock(hashtextextended('recon-match-journal:' || NEW.org_id::text || ':' || NEW.journal_line_id::text, 0));
  IF EXISTS (
    SELECT 1 FROM reconciliation_matches
     WHERE org_id = NEW.org_id
       AND journal_line_id = NEW.journal_line_id
       AND group_id IS DISTINCT FROM NEW.group_id
  ) THEN
    RAISE EXCEPTION 'journal line % is already matched in another group (reconciliation_matches one-journal-one-group)', NEW.journal_line_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.recruiting_offer_flow_admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE fingerprint text;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.approval_status<>'none' OR NEW.submission_policy IS NOT NULL THEN
   RAISE EXCEPTION 'Create draft offer terms before submission through Flows.';
  END IF;
  RETURN NEW;
 END IF;
 fingerprint:=public.offer_approval_fingerprint(NEW);
 IF NEW.approval_status='none' AND OLD.approval_status<>'none' THEN
  IF NEW.status<>'draft' OR NEW.submission_policy IS NOT NULL OR NEW.approval_version IS NOT NULL
   OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='recruiting_offer'
    AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Cancel outstanding offer gates before replacing submitted terms.';
  END IF;
 ELSIF NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
  IF NEW.submitted_by IS NULL OR OLD.approval_status NOT IN('none','rejected')
    OR NEW.status<>'draft' OR NEW.approval_version IS DISTINCT FROM NEW.version
    OR NOT public.flow_submission_policy_valid(NEW.org_id,'recruiting_offer',NEW.id,NEW.submitted_by,NEW.submission_policy)
    OR NOT EXISTS(SELECT 1 FROM public.flow_submissions f WHERE f.org_id=NEW.org_id AND f.subject_kind='recruiting_offer'
      AND f.subject_id=NEW.id AND f.actor_id=NEW.submitted_by AND f.policy=NEW.submission_policy
      AND f.context->>'approvalFingerprint'=fingerprint) THEN
   RAISE EXCEPTION 'Submit the exact current offer version through native Flow routing.';
  END IF;
 END IF;
 IF OLD.approval_status IN('pending','approved') AND NEW.approval_status<>'none'
   AND public.offer_approval_fingerprint(OLD) IS DISTINCT FROM fingerprint THEN
  RAISE EXCEPTION 'Submitted offer terms are immutable; render and submit a new version.';
 END IF;
 IF NEW.approval_status IN('approved','rejected') AND NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
  IF NEW.approval_version IS DISTINCT FROM NEW.version OR NEW.submission_policy IS NULL THEN
   RAISE EXCEPTION 'The decision must name the submitted offer version.';
  END IF;
  IF NEW.approval_status='approved' AND NEW.submission_policy->>'kind'='ungated'
   AND public.flow_ungated_submission_authorized(NEW.org_id,'recruiting_offer',NEW.id,NEW.updated_by,
     jsonb_build_object('approvalFingerprint',fingerprint)) THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind='recruiting_offer' AND g.subject_id=NEW.id
      AND NEW.submission_policy->'runIds' ? r.id::text AND g.status=NEW.approval_status AND g.decided_by=NEW.updated_by
      AND r.context->>'approvalFingerprint'=fingerprint
      AND (NEW.updated_by IS DISTINCT FROM NEW.submitted_by OR EXISTS(
        SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
         WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
          AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
    OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='recruiting_offer'
      AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete the configured offer Flow gates before releasing these terms.';
  END IF;
 END IF;
 IF NEW.status='sent' AND OLD.status='draft' AND (NEW.approval_status<>'approved' OR NEW.approval_version IS DISTINCT FROM NEW.version) THEN
  RAISE EXCEPTION 'Release this offer version through Flows before issuance.';
 END IF;
 IF NEW.signature_status='sent' AND OLD.signature_status IS DISTINCT FROM 'sent' AND NEW.status<>'sent' THEN
  RAISE EXCEPTION 'Release the offer before issuing its signing link.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.recurring_occurrence_document_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'recurring occurrence lineage is immutable';
END $function$

CREATE OR REPLACE FUNCTION public.refresh_document_totals_from_lines(p_document_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_kind text;
    v_line_count integer;
    v_amount_sum numeric;
    v_tax_sum numeric;
    v_debit_sum numeric;
    v_want_subtotal numeric;
    v_want_total numeric;
BEGIN
    SELECT kind INTO v_kind
      FROM public.documents
     WHERE id = p_document_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT count(*)::int,
           coalesce(sum(l.amount), 0),
           coalesce(sum(l.tax_amount), 0),
           coalesce(sum(l.amount) FILTER (WHERE l.amount > 0), 0)
      INTO v_line_count, v_amount_sum, v_tax_sum, v_debit_sum
      FROM public.document_lines l
     WHERE l.document_id = p_document_id AND l.org_id = p_org_id;
    IF v_kind IN ('journal', 'pay_run') THEN
        v_want_total := v_debit_sum;
        v_want_subtotal := v_debit_sum - v_tax_sum;
    ELSE
        v_want_subtotal := v_amount_sum;
        v_want_total := v_amount_sum + v_tax_sum;
    END IF;
    UPDATE public.documents d
       SET subtotal = v_want_subtotal,
           tax_total = v_tax_sum,
           total = v_want_total,
           updated_at = greatest(clock_timestamp(), d.updated_at + interval '1 microsecond')
     WHERE d.id = p_document_id
       AND d.org_id = p_org_id
       AND (d.subtotal, d.tax_total, d.total) IS DISTINCT FROM
           (v_want_subtotal, v_tax_sum, v_want_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.refuse_merged_account_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_column text;
  v_new text;
  v_survivor uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.accounts
     WHERE org_id = NEW.org_id AND merged_into_id IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;
  IF public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  FOREACH v_column IN ARRAY TG_ARGV LOOP
    v_new := to_jsonb(NEW) ->> v_column;
    CONTINUE WHEN v_new IS NULL;
    CONTINUE WHEN TG_OP = 'UPDATE' AND (to_jsonb(OLD) ->> v_column) IS NOT DISTINCT FROM v_new;
    SELECT merged_into_id INTO v_survivor
      FROM public.accounts
     WHERE org_id = NEW.org_id AND id = v_new::uuid;
    IF v_survivor IS NOT NULL THEN
      RAISE EXCEPTION '%.% names account %, which was merged into account % — choose the surviving account', TG_TABLE_NAME, v_column, v_new, v_survivor
        USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.renewal_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE day jsonb;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Renewal policy and occurrence evidence is immutable; create a new dated policy'; END IF;
 IF TG_TABLE_NAME='subscription_renewal_policies' THEN
  IF jsonb_array_length(NEW.reminder_days)>20 THEN RAISE EXCEPTION 'At most twenty renewal reminder offsets are allowed'; END IF;
  FOR day IN SELECT value FROM jsonb_array_elements(NEW.reminder_days) LOOP
   IF jsonb_typeof(day)<>'object' OR jsonb_typeof(day->'days') IS DISTINCT FROM 'number' OR (day->>'days') !~ '^[0-9]+$' OR (day->>'days')::numeric>3660 THEN
    RAISE EXCEPTION 'Renewal reminder days must be whole numbers from zero through 3660';
   END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM public.subscriptions s JOIN public.parties p ON p.org_id=s.org_id AND p.id=s.customer_id
    JOIN public.subsidiaries sub ON sub.org_id=p.org_id AND sub.id=NEW.subsidiary_id
    WHERE s.org_id=NEW.org_id AND s.id=NEW.subscription_id AND coalesce(p.subsidiary_id,(SELECT id FROM public.subsidiaries WHERE org_id=NEW.org_id AND parent_id IS NULL))=NEW.subsidiary_id)
   THEN RAISE EXCEPTION 'Renewal policy must use the subscription customer legal entity'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.reopen_submission_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.submission_policy IS NOT NULL THEN RAISE EXCEPTION 'Submit the saved reopen through Flows.'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
  IF OLD.status<>'requested' OR NEW.status<>'requested' OR OLD.submission_policy IS NOT NULL
    OR NOT public.flow_submission_policy_valid(NEW.org_id,'close_reopen_request',NEW.id,NEW.requested_by,NEW.submission_policy) THEN
   RAISE EXCEPTION 'Reopen routing evidence must be complete and freezes on submission.';
  END IF;
 END IF;
 IF OLD.status='requested' AND NEW.status='approved' AND NEW.submission_policy IS NULL THEN
  RAISE EXCEPTION 'Submit the reopen through Flows before releasing it.';
 END IF;
 IF OLD.status='requested' AND NEW.status IN('approved','rejected') THEN
  IF NEW.submission_policy->>'kind'='ungated' THEN
   IF NEW.status<>'approved' OR NEW.approved_by IS DISTINCT FROM NEW.requested_by THEN
    RAISE EXCEPTION 'An ungated reopen is released by its requester, without a human decision.';
   END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind='close_reopen_request' AND g.subject_id=NEW.id
      AND g.status=NEW.status AND g.decided_by=NEW.approved_by AND g.decided_at IS NOT NULL
      AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
      AND (NEW.approved_by<>NEW.requested_by OR EXISTS(
        SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
          WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
            AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
    OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id
      AND g.subject_kind='close_reopen_request' AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete the configured reopen gates before releasing the request.';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.reporting_book_ids(p_org uuid, p_book uuid)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE selected accounting_books%ROWTYPE;
BEGIN
 SELECT * INTO selected FROM accounting_books WHERE org_id=p_org AND id=p_book;
 IF NOT FOUND THEN RAISE EXCEPTION 'The selected reporting book is unavailable.' USING ERRCODE='23514'; END IF;
 IF NOT selected.is_primary AND selected.posts_gl AND selected.replication_mode='adjustment_only' THEN
  IF EXISTS(SELECT 1 FROM subsidiaries s WHERE s.org_id=p_org AND s.is_active
    AND public.accounting_book_currency(p_org,p_book,s.id)<>s.base_currency) THEN
   RAISE EXCEPTION 'Primary plus adjustments requires the same measurement currency in both books. Use a full translated book for another currency.' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM accounting_books WHERE org_id=p_org AND is_primary AND is_active AND posts_gl) THEN
   RAISE EXCEPTION 'Primary plus adjustments requires an active primary posting book.' USING ERRCODE='23514'; END IF;
  RETURN QUERY SELECT id FROM accounting_books WHERE org_id=p_org AND is_primary AND is_active AND posts_gl;
 END IF;
 RETURN NEXT selected.id;
END $function$

CREATE OR REPLACE FUNCTION public.revenue_approved_terms_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE subject uuid; changed boolean; amendment uuid;
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF NEW.org_id<>OLD.org_id OR NEW.id<>OLD.id THEN RAISE EXCEPTION 'revenue identity and organization are immutable'; END IF;
 IF TG_TABLE_NAME='revenue_contracts' THEN
  IF OLD.subsidiary_id IS NOT NULL AND NEW.subsidiary_id IS DISTINCT FROM OLD.subsidiary_id THEN RAISE EXCEPTION 'revenue legal entity cannot be changed'; END IF;
  subject:=OLD.id; amendment:=NEW.last_change_id;
  changed:=(NEW.total_transaction_price,NEW.currency,NEW.customer_id,NEW.starts_on,NEW.ends_on) IS DISTINCT FROM
           (OLD.total_transaction_price,OLD.currency,OLD.customer_id,OLD.starts_on,OLD.ends_on);
 ELSE
  IF NEW.contract_id<>OLD.contract_id THEN RAISE EXCEPTION 'a performance obligation cannot move contracts'; END IF;
  subject:=OLD.contract_id; amendment:=NEW.last_change_id;
  changed:=(NEW.allocated_price,NEW.standalone_selling_price,NEW.recognition_rule_id,NEW.recognition_starts_on,NEW.recognition_ends_on,NEW.deferred_account_id,NEW.recognized_account_id) IS DISTINCT FROM
           (OLD.allocated_price,OLD.standalone_selling_price,OLD.recognition_rule_id,OLD.recognition_starts_on,OLD.recognition_ends_on,OLD.deferred_account_id,OLD.recognized_account_id);
 END IF;
 IF (OLD.last_change_id IS NOT NULL AND changed) OR NEW.last_change_id IS DISTINCT FROM OLD.last_change_id THEN
  IF amendment IS NULL OR NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=amendment AND f.org_id=OLD.org_id AND f.domain='revenue' AND f.subject_id=subject AND f.status='approved') THEN
   RAISE EXCEPTION 'approved revenue terms require a new independently approved contract modification';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.revenue_schedule_basis_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE subject uuid; parent uuid;
BEGIN
 IF coalesce(current_setting('openbooks.amend',true),'off')='on' THEN RETURN NEW; END IF;
 IF NEW.change_basis IS NOT NULL AND (TG_OP='INSERT' OR NEW.change_basis IS DISTINCT FROM OLD.change_basis) THEN
  SELECT c.id,c.parent_contract_id INTO subject,parent FROM performance_obligations o JOIN revenue_contracts c ON c.id=o.contract_id AND c.org_id=o.org_id WHERE o.id=NEW.obligation_id AND o.org_id=NEW.org_id;
  IF NOT EXISTS(SELECT 1 FROM financial_changes f WHERE f.id=(NEW.change_basis->>'changeId')::uuid AND f.org_id=NEW.org_id AND f.domain='revenue' AND f.subject_id IN(subject,parent) AND f.status='approved') THEN
   RAISE EXCEPTION 'amended recognition basis requires the approved contract modification';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND OLD.change_basis IS NOT NULL AND NEW.change_basis IS NULL THEN RAISE EXCEPTION 'an approved recognition basis cannot be erased'; END IF;
 IF NEW.change_basis IS NOT NULL AND NEW.total_amount IS DISTINCT FROM (NEW.change_basis->>'totalAmount')::numeric THEN RAISE EXCEPTION 'recognition total must match its approved basis'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rma_document_kind_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  record_org uuid;
  record_kind text;
BEGIN
  SELECT org_id, kind INTO record_org, record_kind
    FROM public.documents WHERE id = NEW.document_id;
  IF record_org IS DISTINCT FROM NEW.org_id OR record_kind IS DISTINCT FROM 'rma' THEN
    RAISE EXCEPTION 'RMA details require a return authorization document in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT org_id, kind INTO record_org, record_kind
    FROM public.documents WHERE id = NEW.source_document_id;
  IF record_org IS DISTINCT FROM NEW.org_id OR record_kind NOT IN ('customer_invoice', 'sales_fulfillment') THEN
    RAISE EXCEPTION 'RMA source must be a customer invoice or sales fulfillment in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.customer_credit_id IS NOT NULL THEN
    SELECT org_id, kind INTO record_org, record_kind
      FROM public.documents WHERE id = NEW.customer_credit_id;
    IF record_org IS DISTINCT FROM NEW.org_id OR record_kind IS DISTINCT FROM 'customer_credit' THEN
      RAISE EXCEPTION 'RMA customer credit must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.rma_line_kind_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  rma_org uuid;
  document_kind text;
  line_document uuid;
  source_org uuid;
  location_org uuid;
  credit_org uuid;
  credit_kind text;
  scrap_org uuid;
BEGIN
  SELECT org_id INTO rma_org FROM public.rma_documents
   WHERE document_id = NEW.document_id AND org_id = NEW.org_id;
  SELECT d.kind, l.document_id INTO document_kind, line_document
    FROM public.document_lines l JOIN public.documents d ON d.id = l.document_id AND d.org_id = l.org_id
   WHERE l.id = NEW.line_id AND l.org_id = NEW.org_id;
  IF rma_org IS NULL OR document_kind IS DISTINCT FROM 'rma' OR line_document IS DISTINCT FROM NEW.document_id THEN
    RAISE EXCEPTION 'RMA line must belong to an RMA document in the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT org_id INTO source_org FROM public.inventory_movements WHERE id = NEW.source_issue_movement_id;
  IF source_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'RMA source movement must belong to the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.disposition_location_id IS NOT NULL THEN
    SELECT org_id INTO location_org FROM public.stock_locations WHERE id = NEW.disposition_location_id;
    IF location_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'RMA disposition location must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.vendor_credit_id IS NOT NULL THEN
    SELECT org_id, kind INTO credit_org, credit_kind FROM public.documents WHERE id = NEW.vendor_credit_id;
    IF credit_org IS DISTINCT FROM NEW.org_id OR credit_kind IS DISTINCT FROM 'vendor_credit' THEN
      RAISE EXCEPTION 'RMA vendor credit must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.scrap_movement_id IS NOT NULL THEN
    SELECT org_id INTO scrap_org FROM public.inventory_movements WHERE id = NEW.scrap_movement_id;
    IF scrap_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'RMA scrap movement must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.row_extra_dims_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_subsidiary uuid;
begin
  v_subsidiary := new.subsidiary_id;
  if tg_table_name = 'document_lines' and v_subsidiary is null then
    select subsidiary_id into v_subsidiary from documents where id = new.document_id;
  end if;
  if v_subsidiary is null then
    select id into v_subsidiary from subsidiaries where org_id = new.org_id and parent_id is null;
  end if;
  perform validate_extra_dims(new.org_id, new.extra_dims, v_subsidiary);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.saas_metrics_fx_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'saas FX evidence is append-only and cannot be deleted; record a superseding observation instead'
      USING ERRCODE = 'check_violation';
  END IF;
  RAISE EXCEPTION 'saas FX evidence is immutable and cannot be updated; record a new observation instead'
    USING ERRCODE = 'check_violation';
END
$function$

CREATE OR REPLACE FUNCTION public.saas_metrics_normalization_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  actor_org uuid;
  live boolean;
  prior_digest text;
  new_digest text;
BEGIN
  IF TG_OP='DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN RETURN OLD; END IF;
  IF TG_OP = 'DELETE' THEN
    IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'saas normalization requests are durable audit and cannot be deleted; cancel the request instead'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Actor identities are validated against the subject: the requester and
  -- the approver must belong to the requesting organization.
  IF NEW.requested_by IS NOT NULL THEN
    SELECT org_id INTO actor_org FROM public.users WHERE id = NEW.requested_by;
    IF actor_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'saas normalization requester must be a user of the requesting organization; choose a requester in this organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW.approved_by IS NOT NULL THEN
    SELECT org_id INTO actor_org FROM public.users WHERE id = NEW.approved_by;
    IF actor_org IS DISTINCT FROM NEW.org_id THEN
      RAISE EXCEPTION 'saas normalization approver must be a user of the requesting organization; choose an approver in this organization'
        USING ERRCODE = 'check_violation';
    END IF;

  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'pending' THEN
      RAISE EXCEPTION 'new saas normalization requests start as pending; claim the pending request to begin work'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION 'saas normalization approval is recorded by updating the pending request, not at insert; insert without approver, then record approval'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_heartbeat_at IS NOT NULL THEN
      RAISE EXCEPTION 'new saas normalization requests hold no lease; claim the pending request to take a lease token'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> 0 THEN
      RAISE EXCEPTION 'new saas normalization requests start at attempt zero; claims pending attempts'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'new saas normalization requests carry no outcome; finalize a running claim to record one'
        USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_requested',
      jsonb_build_object('event', 'saas_normalization_requested', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', 0,
        'statusBefore', NULL, 'statusAfter', NEW.status,
        'priorLeaseDigest', NULL, 'newLeaseDigest', NULL,
        'actor', NEW.requested_by, 'reason', NEW.reason),
      NEW.requested_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Request identity is immutable; a new month or idempotency key is a new request.
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.month IS DISTINCT FROM OLD.month
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
     OR NEW.requested_by IS DISTINCT FROM OLD.requested_by THEN
    RAISE EXCEPTION 'saas normalization request identity (organization, month, idempotency key, request hash, requester) is immutable; file a new request instead'
      USING ERRCODE = 'check_violation';
  END IF;
  -- The approver is immutable once recorded; the approval timestamp follows it.
  IF OLD.approved_by IS NOT NULL AND NEW.approved_by IS DISTINCT FROM OLD.approved_by THEN
    RAISE EXCEPTION 'saas normalization approver is immutable once recorded; the recorded approval stands'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_at IS NOT NULL AND NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
    RAISE EXCEPTION 'saas normalization approval time is immutable once recorded; the recorded approval stands'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.approved_by IS NULL) <> (NEW.approved_at IS NULL) THEN
    RAISE EXCEPTION 'saas normalization approval needs both approver and approval time; record them together on the pending request'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Terminal rows are immutable; further work is a new request.
  IF OLD.status IN ('succeeded', 'cancelled') THEN
    RAISE EXCEPTION 'saas normalization requests in terminal state % are immutable; file a new request for further work', OLD.status
      USING ERRCODE = 'check_violation';
  END IF;

  -- Liveness: the presented token must equal the stored live token and the
  -- stored lease must not have expired. Every later mutation and
  -- finalization funnels through this flag.
  live := OLD.lease_token IS NOT NULL
          AND NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token
          AND OLD.lease_expires_at IS NOT NULL
          AND OLD.lease_expires_at > now();
  prior_digest := CASE WHEN OLD.lease_token IS NULL THEN NULL
    ELSE 'sha256:' || encode(public.digest(convert_to(OLD.lease_token::text, 'UTF8'), 'sha256'), 'hex') END;
  new_digest := CASE WHEN NEW.lease_token IS NULL THEN NULL
    ELSE 'sha256:' || encode(public.digest(convert_to(NEW.lease_token::text, 'UTF8'), 'sha256'), 'hex') END;

  IF OLD.approved_by IS NULL AND NEW.approved_by IS NOT NULL
    AND NOT public.normalization_request_flow_authorized(NEW.org_id,NEW.id,NEW.approved_by,'approved') THEN
   RAISE EXCEPTION 'Complete native tenant Flow routing before releasing the correction.' USING ERRCODE='23514';
  END IF;

  -- Pending rows change only by recording approval, claiming, or cancelling.
  IF OLD.status = 'pending' AND NEW.status = 'pending' THEN
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token
       OR NEW.lease_expires_at IS DISTINCT FROM OLD.lease_expires_at
       OR NEW.last_heartbeat_at IS DISTINCT FROM OLD.last_heartbeat_at
       OR NEW.attempt_count <> OLD.attempt_count
       OR NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL
       OR NEW.progress IS DISTINCT FROM OLD.progress THEN
      RAISE EXCEPTION 'pending saas normalization requests change only by recording approval, claiming to running, or cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    IF OLD.approved_by IS NULL AND NEW.approved_by IS NOT NULL THEN
      INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
      VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_approved',
        jsonb_build_object('event', 'saas_normalization_approved', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', NEW.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'actor', NEW.approved_by, 'reason', NEW.reason),
        NEW.approved_by, NEW.idempotency_key::text);
    END IF;
    RETURN NEW;
  END IF;

  -- First claim: pending to running opens attempt one with a fresh live lease.
  -- Execution requires a recorded approval and a presented transition actor.
  IF OLD.status = 'pending' AND NEW.status = 'running' THEN
    IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN
      RAISE EXCEPTION 'claiming a saas normalization request requires a recorded approval; record approver and approval time on the pending request, then claim'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM NEW.approved_by THEN
      RAISE EXCEPTION 'claiming a saas normalization request requires the approver as the acting user; record the approver as updated_by when claiming'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'claiming a saas normalization request needs a fresh lease token with a future expiry; generate a token and claim again'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'claiming a saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a claimed saas normalization request carries no outcome yet; finalize after work completes'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_claimed',
      jsonb_build_object('event', 'saas_normalization_claimed', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'pending' AND NEW.status = 'cancelled' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.requested_by AND NOT public.normalization_request_flow_authorized(NEW.org_id,NEW.id,NEW.updated_by,'rejected') THEN
      RAISE EXCEPTION 'cancelling a pending saas normalization request requires the requester as the acting user; record the requester as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL THEN
      RAISE EXCEPTION 'cancelling an unclaimed saas normalization request takes no lease; cancel without lease fields'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Running to running: either a live heartbeat under the live token, or a
  -- stale reacquisition after expiry. Heartbeats manufacture no audit event.
  IF OLD.status = 'running' AND NEW.status = 'running' THEN
    IF NEW.lease_token IS DISTINCT FROM OLD.lease_token THEN
      IF OLD.lease_expires_at IS NULL OR OLD.lease_expires_at > now() THEN
        RAISE EXCEPTION 'saas normalization lease is still live; heartbeat with the live token, or wait for expiry and reacquire'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request requires the approver as the acting user; record the approver as updated_by when reacquiring'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request needs a fresh lease token with a future expiry; generate a token and reacquire'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
        RAISE EXCEPTION 'reacquiring a saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
        RAISE EXCEPTION 'a reacquired saas normalization request carries no outcome yet; finalize after work completes'
          USING ERRCODE = 'check_violation';
      END IF;
      NEW.last_heartbeat_at := now();
      NEW.updated_at := now();
      INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
      VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_abandoned',
        jsonb_build_object('event', 'saas_normalization_abandoned', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', OLD.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
          'actor', NEW.updated_by, 'reason', NEW.reason),
        NEW.updated_by, NEW.idempotency_key::text),
        (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_reacquired',
        jsonb_build_object('event', 'saas_normalization_reacquired', 'requestId', NEW.id,
          'month', NEW.month, 'attempt', NEW.attempt_count,
          'statusBefore', OLD.status, 'statusAfter', NEW.status,
          'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
          'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
          'actor', NEW.updated_by, 'reason', NEW.reason),
        NEW.updated_by, NEW.idempotency_key::text);
      RETURN NEW;
    END IF;
    IF OLD.lease_expires_at IS NULL OR OLD.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'saas normalization lease has expired; reacquire with a fresh token before further heartbeats'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'saas normalization heartbeat requires the approver as the acting user; record the approver as updated_by when heartbeating'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count THEN
      RAISE EXCEPTION 'heartbeats open no new attempts; keep attempt_count at % or reacquire after expiry', OLD.attempt_count
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_expires_at < OLD.lease_expires_at THEN
      RAISE EXCEPTION 'heartbeats may extend the saas normalization lease expiry, never shorten it'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'running saas normalization requests carry progress only; finalize to record an outcome'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- Finalization under the live lease token: exactly one terminal event.
  IF OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed') THEN
    IF NOT live THEN
      RAISE EXCEPTION 'finalizing a saas normalization request requires the live lease token; heartbeat or reacquire first, then finalize'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'finalizing a saas normalization request requires the approver as the acting user; record the approver as updated_by when finalizing'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count THEN
      RAISE EXCEPTION 'finalization closes the current attempt; keep attempt_count at %', OLD.attempt_count
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'succeeded' THEN
      IF NEW.result IS NULL THEN
        RAISE EXCEPTION 'a succeeded saas normalization must store its result; include the result document'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
        RAISE EXCEPTION 'a succeeded saas normalization carries a result, not a failure; clear failure and remedy'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.failure IS NULL OR btrim(NEW.failure) = '' THEN
        RAISE EXCEPTION 'a failed saas normalization must name the failure; describe what went wrong'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.remedy IS NULL OR btrim(NEW.remedy) = '' THEN
        RAISE EXCEPTION 'a failed saas normalization must name the remedy; record how the operator recovers'
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW.result IS NOT NULL THEN
        RAISE EXCEPTION 'a failed saas normalization carries failure and remedy, not a result; clear the result'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    NEW.lease_token := NULL;
    NEW.lease_expires_at := NULL;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id,
      CASE WHEN NEW.status = 'succeeded' THEN 'saas_normalization_succeeded' ELSE 'saas_normalization_failed' END,
      jsonb_build_object('event', CASE WHEN NEW.status = 'succeeded' THEN 'saas_normalization_succeeded' ELSE 'saas_normalization_failed' END,
        'requestId', NEW.id, 'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'running' AND NEW.status = 'cancelled' THEN
    IF NOT live THEN
      RAISE EXCEPTION 'cancelling a running saas normalization request requires the live lease token; heartbeat or reacquire first'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'cancelling a running saas normalization request requires the approver as the acting user; record the approver as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.lease_token := NULL;
    NEW.lease_expires_at := NULL;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  -- Retry from failure re-enters the lifecycle with a fresh live lease.
  IF OLD.status = 'failed' AND NEW.status = 'running' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request requires the approver as the acting user; record the approver as updated_by when retrying'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.lease_token IS NULL OR NEW.lease_expires_at IS NULL OR NEW.lease_expires_at <= now() THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request needs a fresh lease token with a future expiry; generate a token and retry'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt_count <> OLD.attempt_count + 1 THEN
      RAISE EXCEPTION 'retrying a failed saas normalization request opens attempt %; set attempt_count accordingly', OLD.attempt_count + 1
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a retried saas normalization request starts clear; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.last_heartbeat_at := now();
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_retried',
      jsonb_build_object('event', 'saas_normalization_retried', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'progressBefore', OLD.progress, 'progressAfter', NEW.progress,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  IF OLD.status = 'failed' AND NEW.status = 'cancelled' THEN
    IF NEW.updated_by IS DISTINCT FROM OLD.approved_by THEN
      RAISE EXCEPTION 'cancelling a failed saas normalization request requires the approver as the acting user; record the approver as updated_by when cancelling'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.result IS NOT NULL OR NEW.failure IS NOT NULL OR NEW.remedy IS NOT NULL THEN
      RAISE EXCEPTION 'a cancelled saas normalization request carries no outcome; clear result, failure and remedy'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
    INSERT INTO public.audit_log (org_id, table_name, row_id, action, changes, actor_id, request_id)
    VALUES (NEW.org_id, 'saas_metrics_normalization_requests', NEW.id, 'saas_normalization_cancelled',
      jsonb_build_object('event', 'saas_normalization_cancelled', 'requestId', NEW.id,
        'month', NEW.month, 'attempt', NEW.attempt_count,
        'statusBefore', OLD.status, 'statusAfter', NEW.status,
        'priorLeaseDigest', prior_digest, 'newLeaseDigest', new_digest,
        'actor', NEW.updated_by, 'reason', NEW.reason),
      NEW.updated_by, NEW.idempotency_key::text);
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'saas normalization requests move pending to running to succeeded, failed or cancelled, and failed may retry to running; % to % is not a legal transition', OLD.status, NEW.status
    USING ERRCODE = 'check_violation';
END
$function$

CREATE OR REPLACE FUNCTION public.sales_capture_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE is_credit boolean:=false; is_reversal boolean:=false; old_won boolean:=false; new_won boolean:=false; prior public.crm_sales_evidence; metric_name text; source_name text; source_number_value text; value numeric; event_date date; clone_target record;
BEGIN
 IF TG_TABLE_NAME='documents' THEN
  IF NEW.kind NOT IN ('customer_invoice','customer_credit') THEN RETURN NEW; END IF;
 END IF;

 -- Copying a sales source is not a new sale. Its immutable credit and reversal
 -- rows are copied separately, including records made before this trigger
 -- existed. Recapturing would duplicate a credit or invent historical evidence.
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  SELECT target.sandbox_of,target.sandbox_seed INTO clone_target
   FROM public.orgs target
   JOIN public.sandboxes control ON control.org_id=target.id
    AND control.production_org_id=target.sandbox_of
   JOIN public.orgs source ON source.id=target.sandbox_of
   WHERE target.id=NEW.org_id AND target.env_kind='sandbox'
    AND target.sandbox_seed IS NOT NULL;
  IF FOUND THEN
   IF TG_TABLE_NAME='documents' THEN
    IF public.sales_document_clone_matches(NEW) THEN RETURN NEW; END IF;
    RAISE EXCEPTION 'Sandbox sales sources must retain the original identity, revision, state, attribution, amount and dates; refresh from the recorded source instead of manufacturing historical sales evidence.' USING ERRCODE='23514';
   ELSE
    PERFORM 1 FROM public.crm_opportunities original
     WHERE original.org_id=clone_target.sandbox_of
      AND original.opportunity_number=NEW.opportunity_number
      AND public.ob_rebase(original.id,clone_target.sandbox_seed)=NEW.id
      AND (original.opportunity_number,original.revision_seq,
           public.ob_rebase(original.status_id,clone_target.sandbox_seed),
           original.projected_amount,original.currency,original.closed_at,original.updated_at,original.updated_by,
           public.ob_rebase(original.sales_rep_id,clone_target.sandbox_seed),
           public.ob_rebase(original.sales_team_id,clone_target.sandbox_seed),
           public.ob_rebase(original.subsidiary_id,clone_target.sandbox_seed))
       IS NOT DISTINCT FROM
          (NEW.opportunity_number,NEW.revision_seq,NEW.status_id,
           NEW.projected_amount,NEW.currency,NEW.closed_at,NEW.updated_at,NEW.updated_by,
           NEW.sales_rep_id,NEW.sales_team_id,NEW.subsidiary_id);
   END IF;
   IF FOUND THEN RETURN NEW; END IF;
   RAISE EXCEPTION 'Sandbox sales sources must retain the original identity, revision, state, attribution, amount and dates; refresh from the recorded source instead of manufacturing historical sales evidence.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_TABLE_NAME='documents' THEN
  metric_name:='net_invoiced'; source_name:='document'; source_number_value:=NEW.document_number;
  is_credit:=NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted');
  is_reversal:=TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status='voided';
  value:=CASE WHEN NEW.kind='customer_credit' THEN -NEW.subtotal ELSE NEW.subtotal END;
  event_date:=COALESCE(NEW.posting_date,NEW.document_date);
  IF is_reversal THEN
   -- Finalized voids clear request fields. The posted reversal is the
   -- authoritative effective date for both accounting and sales evidence.
   SELECT reversal.posting_date INTO event_date
     FROM public.journal_entries reversal
    WHERE reversal.org_id=NEW.org_id
      AND reversal.id=NEW.reversal_entry_id
      AND reversal.reverses_entry_id=NEW.posted_entry_id
      AND reversal.status='posted';
  END IF;
 ELSE
  metric_name:='closed_won'; source_name:='opportunity'; source_number_value:=NEW.opportunity_number;
  SELECT is_won INTO new_won FROM public.crm_opportunity_statuses WHERE org_id=NEW.org_id AND id=NEW.status_id;
  IF TG_OP='UPDATE' THEN SELECT is_won INTO old_won FROM public.crm_opportunity_statuses WHERE org_id=OLD.org_id AND id=OLD.status_id; END IF;
  is_credit:=COALESCE(new_won,false) AND NOT COALESCE(old_won,false);
  is_reversal:=COALESCE(old_won,false) AND NOT COALESCE(new_won,false);
  IF TG_OP='UPDATE' AND old_won AND new_won AND
    (OLD.sales_rep_id IS DISTINCT FROM NEW.sales_rep_id OR OLD.sales_team_id IS DISTINCT FROM NEW.sales_team_id OR OLD.projected_amount IS DISTINCT FROM NEW.projected_amount OR OLD.currency IS DISTINCT FROM NEW.currency) THEN
   RAISE EXCEPTION 'Closed-won sales evidence is immutable; reopen the opportunity with a reason before adjusting it.' USING ERRCODE='23514';
  END IF;
  value:=NEW.projected_amount; event_date:=(NEW.closed_at AT TIME ZONE COALESCE((SELECT NULLIF(settings->>'timeZone','') FROM public.orgs WHERE id=NEW.org_id),'UTC'))::date;
  IF is_reversal AND NULLIF(trim(NEW.win_loss_reason),'') IS NULL THEN RAISE EXCEPTION 'Enter the reason for reopening this opportunity.' USING ERRCODE='23514'; END IF;
 END IF;
 IF is_credit THEN
  IF event_date IS NULL THEN RAISE EXCEPTION 'Sales evidence requires an effective date.' USING ERRCODE='23514'; END IF;
  INSERT INTO public.crm_sales_evidence(org_id,source_kind,source_id,source_number,source_revision,event_kind,metric,employee_id,sales_team_id,subsidiary_id,currency,amount,effective_date,created_by)
   VALUES(NEW.org_id,source_name,NEW.id,source_number_value,NEW.revision_seq,'credit',metric_name,NEW.sales_rep_id,NEW.sales_team_id,NEW.subsidiary_id,NEW.currency,value,event_date,NEW.updated_by);
 ELSIF is_reversal THEN
  SELECT e.* INTO prior FROM public.crm_sales_evidence e WHERE e.org_id=NEW.org_id AND e.source_kind=source_name AND e.source_id=NEW.id AND e.event_kind='credit' AND NOT EXISTS (SELECT 1 FROM public.crm_sales_evidence r WHERE r.org_id=e.org_id AND r.reverses_id=e.id) ORDER BY e.created_at DESC LIMIT 1;
  IF FOUND THEN
   IF source_name='opportunity' THEN event_date:=(NEW.updated_at AT TIME ZONE COALESCE((SELECT NULLIF(settings->>'timeZone','') FROM public.orgs WHERE id=NEW.org_id),'UTC'))::date; END IF;
   IF event_date IS NULL THEN RAISE EXCEPTION 'A sales reversal requires its controlled effective date.' USING ERRCODE='23514'; END IF;
   INSERT INTO public.crm_sales_evidence(org_id,source_kind,source_id,source_number,source_revision,event_kind,metric,employee_id,sales_team_id,subsidiary_id,currency,amount,effective_date,reverses_id,created_by)
    VALUES(prior.org_id,prior.source_kind,prior.source_id,prior.source_number,NEW.revision_seq,'reversal',prior.metric,prior.employee_id,prior.sales_team_id,prior.subsidiary_id,prior.currency,-prior.amount,event_date,prior.id,NEW.updated_by);
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_customer_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE account public.crm_account_profiles;
BEGIN
 IF TG_OP='UPDATE' AND OLD.sales_rep_id IS NOT DISTINCT FROM NEW.sales_rep_id THEN RETURN NEW; END IF;
 SELECT * INTO account FROM public.crm_account_profiles WHERE org_id=NEW.org_id AND party_id=NEW.party_id FOR UPDATE;
 IF NOT FOUND OR account.sales_rep_id IS NOT DISTINCT FROM NEW.sales_rep_id THEN RETURN NEW; END IF;
 UPDATE public.crm_account_profiles SET sales_rep_id=NEW.sales_rep_id,updated_at=clock_timestamp(),updated_by=NEW.updated_by WHERE org_id=NEW.org_id AND id=account.id;
 INSERT INTO public.crm_account_assignment_events(org_id,account_profile_id,from_employee_id,to_employee_id,from_owner_user_id,to_owner_user_id,from_territory_id,to_territory_id,source,reason,created_by,updated_by)
 VALUES(NEW.org_id,account.id,account.sales_rep_id,NEW.sales_rep_id,account.owner_user_id,account.owner_user_id,account.territory_id,account.territory_id,'manual','Customer sales representative changed',NEW.updated_by,NEW.updated_by);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_document_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND NEW.kind IN ('customer_invoice','customer_credit')
    AND public.sales_document_clone_matches(NEW) THEN
  RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' AND OLD.status IN ('posted','voided') AND (OLD.sales_rep_id IS DISTINCT FROM NEW.sales_rep_id OR OLD.sales_team_id IS DISTINCT FROM NEW.sales_team_id) THEN
  RAISE EXCEPTION 'Posted sales attribution is immutable.' USING ERRCODE='23514';
 END IF;
 IF NEW.status='posted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'posted') AND NEW.kind IN ('customer_invoice','customer_credit') AND NEW.sales_rep_id IS NULL THEN
  SELECT c.sales_rep_id INTO NEW.sales_rep_id FROM public.customer_roles c WHERE c.org_id=NEW.org_id AND c.party_id=NEW.party_id;
  IF NEW.sales_team_id IS NULL THEN
   SELECT (v.definition->>'sales_team_id')::uuid INTO NEW.sales_team_id FROM public.crm_account_profiles cp
    JOIN LATERAL(SELECT definition FROM public.crm_sales_territory_versions v WHERE v.org_id=cp.org_id AND v.territory_id=cp.territory_id AND v.effective_from<=COALESCE(NEW.posting_date,NEW.document_date) ORDER BY effective_from DESC,revision DESC LIMIT 1)v ON true
    WHERE cp.org_id=NEW.org_id AND cp.party_id=NEW.party_id AND cp.sales_rep_id=NEW.sales_rep_id;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_employee_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
 field_name text; employee uuid; before_value jsonb; after_value jsonb;
 source_org uuid; clone_seed uuid; source_value jsonb; identity_field text;
BEGIN
 after_value:=to_jsonb(NEW);
 IF TG_OP='UPDATE' THEN before_value:=to_jsonb(OLD); ELSE before_value:='{}'::jsonb; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  SELECT target.sandbox_of,target.sandbox_seed INTO source_org,clone_seed
   FROM public.orgs target
   JOIN public.sandboxes control ON control.org_id=target.id
     AND control.production_org_id=target.sandbox_of
   JOIN public.orgs source ON source.id=target.sandbox_of
   WHERE target.id=NEW.org_id AND target.env_kind='sandbox';
  IF source_org IS NOT NULL AND clone_seed IS NOT NULL THEN
   -- Customer role identities use party_id; the other guarded records use id.
   identity_field:=CASE WHEN TG_TABLE_NAME='customer_roles' THEN 'party_id' ELSE 'id' END;
   EXECUTE format(
    'SELECT to_jsonb(original) FROM %I.%I original WHERE original.org_id=$1
     AND public.ob_rebase(original.%I,$2)=$3 FOR SHARE',
    TG_TABLE_SCHEMA,TG_TABLE_NAME,identity_field)
    INTO source_value USING source_org,clone_seed,(after_value->>identity_field)::uuid;
  END IF;
 END IF;
 FOREACH field_name IN ARRAY TG_ARGV LOOP
  employee:=NULLIF(after_value->>field_name,'')::uuid;
  IF employee IS NOT NULL AND (TG_OP='INSERT' OR before_value->field_name IS DISTINCT FROM after_value->field_name) THEN
   IF source_value->>field_name IS NOT NULL
      AND public.ob_rebase((source_value->>field_name)::uuid,clone_seed)=employee THEN
    CONTINUE;
   END IF;
   PERFORM 1 FROM public.employee_roles e JOIN public.parties p ON p.org_id=e.org_id AND p.id=e.party_id
    WHERE e.org_id=NEW.org_id AND e.party_id=employee AND e.is_active AND e.is_sales_rep AND p.is_active
    AND (e.sales_rep_since IS NULL OR e.sales_rep_since<=COALESCE((after_value->>'period_start')::date,(after_value->>'valid_from')::date,(after_value->>'effective_from')::date,CURRENT_DATE)) FOR SHARE OF e,p;
   IF NOT FOUND THEN RAISE EXCEPTION 'Select an active employee designated as a sales representative in Sales → Representatives.' USING ERRCODE='23514'; END IF;
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_legacy_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE field_name text; before_value jsonb; after_value jsonb;
BEGIN
 after_value:=to_jsonb(NEW);before_value:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
 FOREACH field_name IN ARRAY TG_ARGV LOOP
  IF after_value->>field_name IS NOT NULL AND (TG_OP='INSERT' OR before_value->field_name IS DISTINCT FROM after_value->field_name) THEN
   RAISE EXCEPTION 'Sales responsibility must reference a native employee. Manage assignments in Sales.' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_quota_flow_admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.lifecycle NOT IN('draft') OR NEW.submission_policy IS NOT NULL THEN
   RAISE EXCEPTION 'Create a draft quota before submitting it through Flows.';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.lifecycle='draft' AND NEW.lifecycle='pending_approval' THEN
  IF NEW.submitted_by IS NULL OR NOT public.flow_submission_policy_valid(NEW.org_id,'sales_quota',NEW.id,NEW.submitted_by,NEW.submission_policy)
   OR NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind='sales_quota'
    AND s.subject_id=NEW.id AND s.actor_id=NEW.submitted_by AND s.policy=NEW.submission_policy
    AND s.context @> jsonb_build_object('revision',OLD.revision)
    AND NOT EXISTS(SELECT 1 FROM public.flow_submissions newer WHERE newer.org_id=s.org_id AND newer.subject_kind=s.subject_kind
      AND newer.subject_id=s.subject_id AND (newer.created_at,newer.id)>(s.created_at,s.id))) THEN
   RAISE EXCEPTION 'Submit the current quota revision through native Flow routing.';
  END IF;
 ELSIF OLD.lifecycle='pending_approval' AND NEW.lifecycle='draft' THEN
  IF NEW.submission_policy IS NOT NULL OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id
    AND g.subject_kind='sales_quota' AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Reject through the Flow gate or withdraw the submitted quota before editing it.';
  END IF;
 ELSIF NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
  RAISE EXCEPTION 'Budget submission routing is immutable until the quota returns to draft.';
 END IF;
 IF OLD.lifecycle='pending_approval' AND NEW.lifecycle<>'draft' AND
  (to_jsonb(NEW)-ARRAY['lifecycle','revision','updated_at','updated_by','reason','approved_at','approved_by']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['lifecycle','revision','updated_at','updated_by','reason','approved_at','approved_by']) THEN
  RAISE EXCEPTION 'Submitted quota terms are immutable; withdraw before editing.';
 END IF;
 IF NEW.lifecycle='approved' AND OLD.lifecycle<>'approved' THEN
  IF OLD.lifecycle<>'pending_approval' OR NEW.submission_policy IS NULL THEN
   RAISE EXCEPTION 'Submit the quota through Flows before release.';
  END IF;
  IF NEW.submission_policy->>'kind'='ungated' THEN
   IF NEW.approved_by IS DISTINCT FROM NEW.submitted_by
    OR NOT public.flow_ungated_submission_authorized(NEW.org_id,'sales_quota',NEW.id,NEW.submitted_by,
      jsonb_build_object('revision',OLD.revision-1)) THEN
    RAISE EXCEPTION 'An ungated quota requires its current submission receipt.';
   END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind='sales_quota' AND g.subject_id=NEW.id
      AND NEW.submission_policy->'runIds' ? r.id::text AND g.status='approved' AND g.decided_by=NEW.approved_by
      AND r.context->'submissionPolicy'->>'flowId'=r.flow_id::text
      AND (NEW.approved_by IS DISTINCT FROM NEW.submitted_by OR EXISTS(
        SELECT 1 FROM jsonb_array_elements(r.context->'submissionPolicy'->'graph'->'nodes') node
         WHERE node->>'id'=g.node_id AND node->'data'->>'kind'='gate'
          AND node->'data'->'gate'->'preventSelfApproval'='false'::jsonb)))
    OR EXISTS(SELECT 1 FROM public.flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='sales_quota'
      AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete every configured quota approval gate before release.';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sales_quota_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id)
    AND current_setting('openbooks.migration',true)='on'
    AND current_setting('openbooks.amend',true)='on'
    AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=SESSION_USER AND (rolsuper OR rolbypassrls))
 THEN RETURN OLD; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Quota history cannot be deleted; close the quota instead.' USING ERRCODE='23514'; END IF;
 IF OLD.lifecycle IN ('approved','superseded','closed') AND
  (to_jsonb(NEW)-ARRAY['lifecycle','updated_at','updated_by','revision']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['lifecycle','updated_at','updated_by','revision']) THEN
  RAISE EXCEPTION 'Approved quotas are immutable; create a revised quota with a reason and approval.' USING ERRCODE='23514';
 END IF;
 IF NEW.lifecycle IS DISTINCT FROM OLD.lifecycle AND NOT (
  (OLD.lifecycle='draft' AND NEW.lifecycle='pending_approval') OR
  (OLD.lifecycle='pending_approval' AND NEW.lifecycle IN ('draft','approved')) OR
  (OLD.lifecycle='approved' AND NEW.lifecycle IN ('superseded','closed'))) THEN
  RAISE EXCEPTION 'Invalid quota lifecycle transition.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_attendance_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE batch_row public.schedule_attendance_batches; observation_row public.schedule_attendance_observations;
 entry_row public.schedule_entries; policy_row public.schedule_attendance_policies; event_row record;
 device_count integer; incomplete_count integer; effective_through timestamptz; capture_from timestamptz; capture_to timestamptz;
 expected_ids uuid[]; linked_ids uuid[]; state text := 'out'; opened_at timestamptz; break_at timestamptz;
 first_at timestamptz; last_at timestamptz; previous_at timestamptz; presence bigint := 0; breaks bigint := 0;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME = 'schedule_attendance_batches' THEN
  SELECT * INTO batch_row FROM public.schedule_attendance_batches WHERE org_id = NEW.org_id AND id = NEW.id;
  IF batch_row.event_count <> (SELECT count(*) FROM public.schedule_attendance_events WHERE org_id = NEW.org_id AND batch_id = NEW.id) THEN
   RAISE EXCEPTION 'The check-in batch is incomplete; import every declared event and its completeness in one command.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_events' THEN
  IF NEW.supersedes_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.schedule_attendance_event_claims WHERE org_id = NEW.org_id
     AND event_id = NEW.supersedes_id AND released_at IS NULL) THEN
   RAISE EXCEPTION 'The corrected check-in is still attributed to a booking; release its attribution with the correction and process attendance again.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_observations' THEN
  SELECT * INTO observation_row FROM public.schedule_attendance_observations WHERE org_id = NEW.org_id AND id = NEW.id;
  IF observation_row.status = 'voided' THEN RETURN NULL; END IF;
  SELECT * INTO entry_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = observation_row.entry_id;
  SELECT * INTO policy_row FROM public.schedule_attendance_policies WHERE org_id = NEW.org_id AND id = observation_row.policy_id;
  capture_from := entry_row.starts_at - make_interval(mins => policy_row.capture_before_minutes);
  capture_to := entry_row.ends_at + make_interval(mins => policy_row.capture_after_minutes);
  IF EXISTS (SELECT 1 FROM public.schedule_attendance_identities i JOIN public.schedule_attendance_devices d ON d.org_id = i.org_id AND d.id = i.device_id
    WHERE i.org_id = NEW.org_id AND i.worker_party_id = entry_row.worker_party_id
     AND daterange(i.effective_from, i.effective_to, '[)') && daterange((capture_from AT TIME ZONE d.time_zone)::date, (capture_to AT TIME ZONE d.time_zone)::date, '[]')
     AND NOT daterange(i.effective_from, i.effective_to, '[)') @> daterange((capture_from AT TIME ZONE d.time_zone)::date, (capture_to AT TIME ZONE d.time_zone)::date, '[]')) THEN
   RAISE EXCEPTION 'A device mapping changes inside the booking''s capture window; reconcile the dated mapping before processing attendance.' USING ERRCODE = '23514';
  END IF;
  SELECT count(DISTINCT i.device_id), count(*) FILTER (WHERE w.complete_through IS NULL), min(w.complete_through)
   INTO device_count, incomplete_count, effective_through
   FROM public.schedule_attendance_identities i JOIN public.schedule_attendance_devices d ON d.org_id = i.org_id AND d.id = i.device_id
   LEFT JOIN public.schedule_attendance_watermarks w ON w.org_id = i.org_id AND w.device_id = i.device_id
   WHERE i.org_id = NEW.org_id AND i.worker_party_id = entry_row.worker_party_id
    AND i.effective_from <= (capture_from AT TIME ZONE d.time_zone)::date AND (i.effective_to IS NULL OR i.effective_to > (capture_to AT TIME ZONE d.time_zone)::date);
  IF device_count = 0 THEN
   RAISE EXCEPTION 'No dated device mapping covers this booking''s capture window; map the person''s device identifier before processing attendance.' USING ERRCODE = '23514';
  END IF;
  IF incomplete_count > 0 THEN effective_through := NULL; END IF;
  IF observation_row.complete_through IS DISTINCT FROM effective_through THEN
   RAISE EXCEPTION 'Device completeness changed; reload and process attendance again.' USING ERRCODE = '23514';
  END IF;
  SELECT coalesce(array_agg(e.id ORDER BY e.id), ARRAY[]::uuid[]) INTO expected_ids FROM public.schedule_attendance_events e
   WHERE e.org_id = NEW.org_id AND e.worker_party_id = entry_row.worker_party_id AND e.occurred_at BETWEEN capture_from AND capture_to AND e.kind <> 'void'
    AND NOT EXISTS (SELECT 1 FROM public.schedule_attendance_events n WHERE n.org_id = e.org_id AND n.supersedes_id = e.id);
  SELECT coalesce(array_agg(c.event_id ORDER BY c.event_id), ARRAY[]::uuid[]) INTO linked_ids FROM public.schedule_attendance_observation_events oe
   JOIN public.schedule_attendance_event_claims c ON c.org_id = oe.org_id AND c.id = oe.event_claim_id
   WHERE oe.org_id = NEW.org_id AND oe.observation_id = NEW.id AND c.released_at IS NULL;
  IF expected_ids IS DISTINCT FROM linked_ids THEN
   RAISE EXCEPTION 'Attendance must retain every current check-in in the capture window; reconcile overlapping attribution and process the complete source set.' USING ERRCODE = '23514';
  END IF;
  IF effective_through IS NULL OR effective_through < capture_to THEN
   IF observation_row.status <> 'waiting_for_sync' THEN
    RAISE EXCEPTION 'The mapped devices have not declared the capture window complete; wait for synchronization before finalizing attendance.' USING ERRCODE = '23514';
   END IF;
   RETURN NULL;
  END IF;
  IF cardinality(expected_ids) = 0 THEN
   IF observation_row.status <> 'absent' THEN
    RAISE EXCEPTION 'Complete sources hold no check-ins for this booking; record the absence without a presence interval.' USING ERRCODE = '23514';
   END IF;
   RETURN NULL;
  END IF;
  FOR event_row IN SELECT id, kind, occurred_at FROM public.schedule_attendance_events WHERE org_id = NEW.org_id AND id = ANY (expected_ids) ORDER BY occurred_at, id LOOP
   IF previous_at IS NOT NULL AND event_row.occurred_at <= previous_at THEN
    RAISE EXCEPTION 'Check-ins have indistinguishable times; reconcile the source instants before processing attendance.' USING ERRCODE = '23514';
   END IF;
   IF state = 'out' AND event_row.kind = 'clock_in' THEN opened_at := event_row.occurred_at; first_at := coalesce(first_at, event_row.occurred_at); state := 'in';
   ELSIF state = 'in' AND event_row.kind = 'break_start' THEN break_at := event_row.occurred_at; state := 'break';
   ELSIF state = 'break' AND event_row.kind = 'break_end' THEN breaks := breaks + (extract(epoch FROM event_row.occurred_at - break_at) * 1000)::bigint; state := 'in';
   ELSIF state = 'in' AND event_row.kind = 'clock_out' THEN presence := presence + (extract(epoch FROM event_row.occurred_at - opened_at) * 1000)::bigint; last_at := event_row.occurred_at; state := 'out';
   ELSE
    RAISE EXCEPTION 'Finalized check-ins contain an inconsistent clock pair; reconcile the missing or contradictory source event.' USING ERRCODE = '23514';
   END IF;
   previous_at := event_row.occurred_at;
  END LOOP;
  IF state <> 'out' THEN
   RAISE EXCEPTION 'Finalized check-ins leave an unfinished clock or break; reconcile the missing source event.' USING ERRCODE = '23514';
  END IF;
  IF observation_row.status <> 'present' OR observation_row.first_in IS DISTINCT FROM first_at OR observation_row.last_out IS DISTINCT FROM last_at
     OR observation_row.presence_milliseconds IS DISTINCT FROM presence - breaks OR observation_row.break_milliseconds IS DISTINCT FROM breaks
     OR observation_row.late IS DISTINCT FROM (first_at > entry_row.starts_at + make_interval(mins => policy_row.late_grace_minutes))
     OR observation_row.left_early IS DISTINCT FROM (last_at < entry_row.ends_at - make_interval(mins => policy_row.early_grace_minutes))
     OR observation_row.over_break IS DISTINCT FROM (breaks > (entry_row.break_minutes + policy_row.break_grace_minutes)::bigint * 60000) THEN
   RAISE EXCEPTION 'Attendance differs from its clock and break evidence; process the source sequence again.' USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_attendance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE device_row public.schedule_attendance_devices; identity_row public.schedule_attendance_identities;
 batch_row public.schedule_attendance_batches; event_row public.schedule_attendance_events; entry_row public.schedule_entries;
 observation_row public.schedule_attendance_observations; claim_row public.schedule_attendance_event_claims;
 policy_row public.schedule_attendance_policies; prior_through timestamptz;
BEGIN
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Attendance history cannot be deleted; end a mapping, deactivate a device or append a reasoned correction.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' THEN
  IF TG_TABLE_NAME IN ('schedule_attendance_devices','schedule_attendance_identities','schedule_attendance_watermarks') THEN
   IF ROW(NEW.id, NEW.org_id, NEW.created_at, NEW.created_by) IS DISTINCT FROM ROW(OLD.id, OLD.org_id, OLD.created_at, OLD.created_by) THEN
    RAISE EXCEPTION 'Attendance creation evidence is immutable; create a new record.' USING ERRCODE = '23514';
   END IF;
   IF NEW.revision <> OLD.revision + 1 OR NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'The attendance record changed since it was loaded; reload it and try again.' USING ERRCODE = '40001';
   END IF;
  ELSIF TG_TABLE_NAME <> 'schedule_attendance_event_claims' THEN
   RAISE EXCEPTION 'Attendance source and observation evidence is immutable; append a reasoned correction with the previous record as its predecessor.' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF TG_TABLE_NAME = 'schedule_attendance_devices' THEN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = NEW.time_zone) THEN
   RAISE EXCEPTION 'The device time zone is unknown; select its named source time zone.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND to_jsonb(NEW) - ARRAY['name','is_active','reason','revision','updated_at','updated_by']
     IS DISTINCT FROM to_jsonb(OLD) - ARRAY['name','is_active','reason','revision','updated_at','updated_by'] THEN
   RAISE EXCEPTION 'A device keeps its code, legal entity and time zone; register a new device for a changed source.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_identities' THEN
  SELECT * INTO device_row FROM public.schedule_attendance_devices WHERE org_id = NEW.org_id AND id = NEW.device_id FOR UPDATE;
  IF TG_OP = 'INSERT' THEN
   IF NOT device_row.is_active OR device_row.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id THEN
    RAISE EXCEPTION 'The device is unavailable for this legal entity; choose an active device.' USING ERRCODE = '23514';
   END IF;
   IF NEW.employment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.worker_employments e WHERE e.org_id = NEW.org_id AND e.id = NEW.employment_id
      AND e.worker_party_id = NEW.worker_party_id AND e.employer_subsidiary_id = NEW.subsidiary_id) THEN
    RAISE EXCEPTION 'The employment belongs to another person or employer; select the person''s employment with the device''s legal entity.' USING ERRCODE = '23514';
   END IF;
  ELSE
   IF to_jsonb(NEW) - ARRAY['effective_to','reason','revision','updated_at','updated_by'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['effective_to','reason','revision','updated_at','updated_by']
      OR NEW.effective_to IS NULL OR (OLD.effective_to IS NOT NULL AND NEW.effective_to > OLD.effective_to) THEN
    RAISE EXCEPTION 'A device mapping is immutable; end its window and create a new mapping.' USING ERRCODE = '23514';
   END IF;
   IF EXISTS (SELECT 1 FROM public.schedule_attendance_events WHERE org_id = NEW.org_id AND identity_id = NEW.id AND source_local_date >= NEW.effective_to) THEN
    RAISE EXCEPTION 'Recorded check-ins extend beyond this mapping end; choose a later end date.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_policies' THEN
  SELECT * INTO policy_row FROM public.schedule_attendance_policies WHERE org_id = NEW.org_id AND board_id = NEW.board_id
   AND effective_from > NEW.effective_from LIMIT 1;
  IF FOUND THEN
   RAISE EXCEPTION 'A later attendance policy version exists; add versions in date order.' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.schedule_attendance_observations o JOIN public.schedule_entries e ON e.org_id = o.org_id AND e.id = o.entry_id
     WHERE o.org_id = NEW.org_id AND o.board_id = NEW.board_id AND e.starts_on >= NEW.effective_from) THEN
   RAISE EXCEPTION 'Attendance was already observed on or after this date; choose a later effective date so recorded observations keep their policy.' USING ERRCODE = '23514';
  END IF;
  IF NOT public.schedule_board_has_capability(NEW.org_id, NEW.board_id, 'attendance') THEN
   RAISE EXCEPTION 'Attendance policies apply to shift roster boards.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_batches' THEN
  SELECT * INTO device_row FROM public.schedule_attendance_devices WHERE org_id = NEW.org_id AND id = NEW.device_id FOR UPDATE;
  IF NOT FOUND OR NOT device_row.is_active THEN
   RAISE EXCEPTION 'The attendance device is inactive; reactivate it before importing check-ins.' USING ERRCODE = '23514';
  END IF;
  IF NEW.source_evidence->>'source' IS NULL OR length(btrim(NEW.source_evidence->>'source')) = 0 THEN
   RAISE EXCEPTION 'Check-in batches need source evidence; identify the source connection or import file.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_events' THEN
  SELECT * INTO device_row FROM public.schedule_attendance_devices WHERE org_id = NEW.org_id AND id = NEW.device_id FOR UPDATE;
  SELECT * INTO batch_row FROM public.schedule_attendance_batches WHERE org_id = NEW.org_id AND id = NEW.batch_id;
  SELECT * INTO identity_row FROM public.schedule_attendance_identities WHERE org_id = NEW.org_id AND id = NEW.identity_id FOR SHARE;
  IF ROW(NEW.subsidiary_id, NEW.worker_party_id, NEW.employment_id) IS DISTINCT FROM ROW(identity_row.subsidiary_id, identity_row.worker_party_id, identity_row.employment_id)
     OR NEW.source_local_date <> (NEW.occurred_at AT TIME ZONE device_row.time_zone)::date
     OR NEW.source_local_date < identity_row.effective_from OR (identity_row.effective_to IS NOT NULL AND NEW.source_local_date >= identity_row.effective_to) THEN
   RAISE EXCEPTION 'The check-in does not match its dated device mapping; reconcile the source worker mapping and local date before importing.' USING ERRCODE = '23514';
  END IF;
  SELECT complete_through INTO prior_through FROM public.schedule_attendance_watermarks WHERE org_id = NEW.org_id AND device_id = NEW.device_id FOR SHARE;
  IF (NEW.occurred_at <= prior_through OR NEW.supersedes_id IS NOT NULL) AND NOT batch_row.is_correction THEN
   RAISE EXCEPTION 'This check-in changes source records already declared complete; import it in a reasoned correction batch and process attendance again.' USING ERRCODE = '23514';
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN
   SELECT * INTO event_row FROM public.schedule_attendance_events WHERE org_id = NEW.org_id AND id = NEW.supersedes_id FOR SHARE;
   IF NEW.source_version IS DISTINCT FROM event_row.source_version + 1 OR NEW.source_event_id IS DISTINCT FROM event_row.source_event_id
      OR NEW.device_id IS DISTINCT FROM event_row.device_id THEN
    RAISE EXCEPTION 'The correction does not name the next source version; append it to the latest version of the same source event.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_watermarks' THEN
  SELECT * INTO device_row FROM public.schedule_attendance_devices WHERE org_id = NEW.org_id AND id = NEW.device_id FOR UPDATE;
  SELECT * INTO batch_row FROM public.schedule_attendance_batches WHERE org_id = NEW.org_id AND id = NEW.batch_id;
  IF NEW.complete_through IS DISTINCT FROM batch_row.complete_through THEN
   RAISE EXCEPTION 'The completeness watermark must equal its batch''s declared completeness.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.device_id IS DISTINCT FROM OLD.device_id OR NEW.complete_through < OLD.complete_through) THEN
   RAISE EXCEPTION 'Device completeness never moves backwards; import a reasoned correction batch instead.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_observations' THEN
  SELECT * INTO entry_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.entry_id FOR UPDATE;
  IF entry_row.status NOT IN ('published','cancelled') OR entry_row.worker_party_id IS NULL
     OR ROW(NEW.board_id, NEW.worker_party_id, NEW.employment_id, NEW.subsidiary_id)
      IS DISTINCT FROM ROW(entry_row.board_id, entry_row.worker_party_id, entry_row.employment_id, entry_row.subsidiary_id) THEN
   RAISE EXCEPTION 'Attendance is observed for a person''s published booking and its exact subject; reload the board.' USING ERRCODE = '23514';
  END IF;
  IF (entry_row.status = 'cancelled') <> (NEW.status = 'voided') THEN
   RAISE EXCEPTION 'A cancelled booking records voided attendance; process its current state without deleting earlier observations.' USING ERRCODE = '23514';
  END IF;
  IF entry_row.closed_at IS NOT NULL THEN
   RAISE EXCEPTION 'A closed shift keeps its attendance; closing is final.' USING ERRCODE = '23514';
  END IF;
  IF NOT public.schedule_board_has_capability(NEW.org_id, NEW.board_id, 'attendance') THEN
   RAISE EXCEPTION 'Attendance is observed for shifts on shift roster boards.' USING ERRCODE = '23514';
  END IF;
  IF NEW.status <> 'voided' THEN
   SELECT * INTO policy_row FROM public.schedule_attendance_policies WHERE org_id = NEW.org_id AND board_id = entry_row.board_id
    AND effective_from <= entry_row.starts_on ORDER BY effective_from DESC LIMIT 1;
   IF policy_row.id IS DISTINCT FROM NEW.policy_id THEN
    RAISE EXCEPTION 'Attendance uses the board policy effective on the booking date; reload and process again.' USING ERRCODE = '23514';
   END IF;
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN
   SELECT * INTO observation_row FROM public.schedule_attendance_observations WHERE org_id = NEW.org_id AND id = NEW.supersedes_id FOR SHARE;
   IF observation_row.entry_id IS DISTINCT FROM NEW.entry_id THEN
    RAISE EXCEPTION 'An attendance correction supersedes the latest observation of the same booking.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_event_claims' THEN
  SELECT * INTO event_row FROM public.schedule_attendance_events WHERE org_id = NEW.org_id AND id = NEW.event_id FOR UPDATE;
  SELECT * INTO entry_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.entry_id FOR SHARE;
  IF TG_OP = 'UPDATE' THEN
   IF to_jsonb(NEW) - ARRAY['released_at','released_by','release_reason'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['released_at','released_by','release_reason']
      OR OLD.released_at IS NOT NULL OR NEW.released_at IS NULL THEN
    RAISE EXCEPTION 'A check-in attribution is released once with its actor and reason.' USING ERRCODE = '23514';
   END IF;
  ELSE
   SELECT * INTO policy_row FROM public.schedule_attendance_policies WHERE org_id = NEW.org_id AND board_id = entry_row.board_id
    AND effective_from <= entry_row.starts_on ORDER BY effective_from DESC LIMIT 1;
   IF NEW.released_at IS NOT NULL OR event_row.kind = 'void' OR policy_row.id IS NULL
      OR event_row.worker_party_id IS DISTINCT FROM entry_row.worker_party_id OR entry_row.status <> 'published'
      OR EXISTS (SELECT 1 FROM public.schedule_attendance_events WHERE org_id = NEW.org_id AND supersedes_id = NEW.event_id)
      OR event_row.occurred_at < entry_row.starts_at - make_interval(mins => policy_row.capture_before_minutes)
      OR event_row.occurred_at > entry_row.ends_at + make_interval(mins => policy_row.capture_after_minutes) THEN
    RAISE EXCEPTION 'The check-in cannot be attributed to this booking; reconcile its current source version, person and capture window.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_attendance_observation_events' THEN
  SELECT * INTO observation_row FROM public.schedule_attendance_observations WHERE org_id = NEW.org_id AND id = NEW.observation_id FOR SHARE;
  SELECT * INTO claim_row FROM public.schedule_attendance_event_claims WHERE org_id = NEW.org_id AND id = NEW.event_claim_id FOR SHARE;
  IF claim_row.entry_id IS DISTINCT FROM observation_row.entry_id OR claim_row.released_at IS NOT NULL OR NEW.created_by IS DISTINCT FROM observation_row.created_by THEN
   RAISE EXCEPTION 'Observation evidence must match its active booking attribution; process the booking''s check-ins together.' USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_boards_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP = 'DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  IF EXISTS (SELECT 1 FROM public.schedule_entries WHERE org_id = OLD.org_id AND board_id = OLD.id) THEN
   RAISE EXCEPTION 'This board has booking history; archive it instead of deleting it.' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = NEW.time_zone) THEN
  RAISE EXCEPTION 'The board time zone is unknown; select a named time zone such as America/Toronto.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'UPDATE' AND ROW(NEW.row_kind, NEW.resource_kind) IS DISTINCT FROM ROW(OLD.row_kind, OLD.resource_kind) THEN
  RAISE EXCEPTION 'A board keeps its row type; create a new board for a different kind of schedule.' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_boards_type_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE board_type public.openbooks_schedule_board_types;
BEGIN
 IF TG_OP = 'INSERT' AND NEW.board_type IS NULL THEN NEW.board_type := NEW.row_kind; END IF;
 IF TG_OP = 'UPDATE' AND NEW.board_type IS DISTINCT FROM OLD.board_type THEN
  RAISE EXCEPTION 'A board keeps its type; create a new board for a different kind of schedule.' USING ERRCODE = '23514';
 END IF;
 SELECT * INTO board_type FROM public.openbooks_schedule_board_types WHERE key = NEW.board_type;
 IF NOT FOUND OR board_type.row_kind <> NEW.row_kind THEN
  RAISE EXCEPTION 'The board type does not schedule this kind of row; choose a type for people, tasks or resources.' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_codes_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP = 'DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  IF EXISTS (SELECT 1 FROM public.schedule_entries WHERE org_id = OLD.org_id AND schedule_code_id = OLD.id) THEN
   RAISE EXCEPTION 'This schedule code is used by bookings; deactivate it instead of deleting it.' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP = 'UPDATE' AND NEW.category IS DISTINCT FROM OLD.category
    AND EXISTS (SELECT 1 FROM public.schedule_entries WHERE org_id = OLD.org_id AND schedule_code_id = OLD.id AND status <> 'cancelled') THEN
  RAISE EXCEPTION 'The category of a code in use is fixed, because it decides whether booked days count as work; create a new code instead.' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_delivery_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE operator uuid;
BEGIN
 IF NEW.automatic_delivery_policy IS NULL THEN RETURN NEW; END IF;
 IF NEW.row_kind NOT IN ('people','resources') THEN RAISE EXCEPTION 'Automatic schedule delivery requires a people or resource board.' USING ERRCODE='23514'; END IF;
 IF public.openbooks_clone_authority() THEN RAISE EXCEPTION 'Automatic delivery policies must be cleared when copying an environment.' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND OLD.automatic_delivery_policy IS NOT DISTINCT FROM NEW.automatic_delivery_policy THEN RETURN NEW; END IF;
 operator:=(NEW.automatic_delivery_policy->>'operatorId')::uuid;
 IF operator IS NULL OR operator IS DISTINCT FROM NEW.updated_by OR NOT EXISTS(SELECT 1 FROM public.users u WHERE u.org_id=NEW.org_id AND u.id=operator AND u.is_active) THEN
  RAISE EXCEPTION 'The active operator must configure their own automatic schedule delivery policy.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_distribution_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='schedule_distributions' AND TG_OP='UPDATE' THEN
  IF OLD.status='previewed' AND NEW.status='queued' AND (to_jsonb(OLD)-ARRAY['status','flow_run_id','queued_at'])=(to_jsonb(NEW)-ARRAY['status','flow_run_id','queued_at'])
   AND EXISTS(SELECT 1 FROM public.flow_runs r WHERE r.org_id=NEW.org_id AND r.id=NEW.flow_run_id AND r.created_by=NEW.created_by AND ((r.subject_kind='schedule_distribution' AND r.subject_id=NEW.id) OR (r.subject_kind='schedule_board' AND r.subject_id=NEW.board_id AND r.trigger='scheduled' AND NEW.replay_key LIKE 'automatic:%' AND NEW.reason='Automatic schedule occurrence '||r.occurrence_key))) THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'Reviewed schedule snapshots are immutable; create a new review to change the report or audience.' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entries_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE board public.schedule_boards; prior public.schedule_entries; successor public.schedule_entries;
 request_row public.schedule_entry_requests; assignment_row public.schedule_pattern_assignments; last_date date; editable text[];
BEGIN
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Booking history cannot be deleted; cancel the booking instead.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 -- A governed project merge re-points project references only; every other
 -- booking fact, including its revision, is preserved.
 IF TG_OP = 'UPDATE' AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND to_jsonb(NEW) - ARRAY['project_id','project_task_id'] = to_jsonb(OLD) - ARRAY['project_id','project_task_id'] THEN
  RETURN NEW;
 END IF;
 IF TG_OP = 'UPDATE' THEN
  IF ROW(NEW.id, NEW.org_id, NEW.board_id, NEW.created_at, NEW.created_by, NEW.request_hash, NEW.supersedes_id,
         NEW.pattern_assignment_id, NEW.pattern_occurs_on, NEW.pattern_slot, NEW.origin_request_id, NEW.removes_predecessor)
     IS DISTINCT FROM ROW(OLD.id, OLD.org_id, OLD.board_id, OLD.created_at, OLD.created_by, OLD.request_hash, OLD.supersedes_id,
         OLD.pattern_assignment_id, OLD.pattern_occurs_on, OLD.pattern_slot, OLD.origin_request_id, OLD.removes_predecessor) THEN
   RAISE EXCEPTION 'A booking keeps its board, creation evidence, predecessor and origin; create a new booking instead.' USING ERRCODE = '23514';
  END IF;
  IF NEW.revision <> OLD.revision + 1 OR NEW.updated_at < OLD.updated_at THEN
   RAISE EXCEPTION 'The booking changed since it was loaded; reload the board and try again.' USING ERRCODE = '40001';
  END IF;
  IF OLD.closed_at IS NOT NULL THEN
   RAISE EXCEPTION 'A closed shift is final history; record attendance corrections as new evidence instead.' USING ERRCODE = '23514';
  END IF;
 END IF;
 SELECT * INTO board FROM public.schedule_boards WHERE org_id = NEW.org_id AND id = NEW.board_id FOR SHARE;
 IF NOT FOUND OR board.row_kind NOT IN ('people','resources') THEN
  RAISE EXCEPTION 'Bookings belong to a people or resource board; select a booking board.' USING ERRCODE = '23514';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = NEW.time_zone)
    OR NEW.starts_on <> (NEW.starts_at AT TIME ZONE NEW.time_zone)::date
    OR NEW.ends_on <> (NEW.ends_at AT TIME ZONE NEW.time_zone)::date THEN
  RAISE EXCEPTION 'Booking dates do not match their time zone; select the booking times again.' USING ERRCODE = '23514';
 END IF;
 last_date := ((NEW.ends_at - interval '1 millisecond') AT TIME ZONE NEW.time_zone)::date;
 -- Manual booking changes use native publication; service visit projections retain their source lifecycle.
 IF TG_OP = 'INSERT' OR OLD.status = 'draft' THEN
  NEW.governed := NEW.service_visit_id IS NULL;
 ELSIF NEW.governed IS DISTINCT FROM OLD.governed THEN
  RAISE EXCEPTION 'A published booking keeps its governance.' USING ERRCODE = '23514';
 END IF;

 IF TG_OP = 'INSERT' THEN
  IF NOT board.is_active THEN
   RAISE EXCEPTION 'This board is archived; reactivate it in Setup before booking.' USING ERRCODE = '23514';
  END IF;
  IF NEW.closed_at IS NOT NULL THEN
   RAISE EXCEPTION 'A booking is closed only after its attendance is complete.' USING ERRCODE = '23514';
  END IF;
  IF NEW.removes_predecessor AND NEW.status <> 'draft' THEN
   RAISE EXCEPTION 'A removal revision starts as a draft that names the published booking it removes.' USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'published' THEN
   IF NEW.origin_request_id IS NOT NULL THEN
    SELECT * INTO request_row FROM public.schedule_entry_requests WHERE org_id = NEW.org_id AND id = NEW.origin_request_id FOR SHARE;
    IF NOT FOUND OR request_row.status <> 'approved' OR request_row.board_id <> NEW.board_id
       OR coalesce(request_row.decided_by, request_row.updated_by) IS DISTINCT FROM NEW.published_by OR NEW.published_by IS DISTINCT FROM NEW.created_by
       OR NEW.supersedes_id IS NULL OR NEW.supersedes_id NOT IN (request_row.entry_id, coalesce(request_row.counterpart_entry_id, request_row.entry_id)) THEN
     RAISE EXCEPTION 'A shift request outcome is published by its approver in the approval command; reload the request.' USING ERRCODE = '23514';
    END IF;
   ELSE
    IF NEW.service_visit_id IS NULL THEN
     RAISE EXCEPTION 'Submit booking changes through the board publication and complete its tenant Flow gates.' USING ERRCODE = '23514';
    END IF;
    IF NEW.published_by IS DISTINCT FROM NEW.created_by THEN
     RAISE EXCEPTION 'Publication evidence must name the person who booked it.' USING ERRCODE = '23514';
    END IF;
   END IF;
  ELSIF NEW.status <> 'draft' OR NEW.published_by IS NOT NULL THEN
   RAISE EXCEPTION 'New bookings start as drafts or, on live boards, as published bookings.' USING ERRCODE = '23514';
  END IF;
  IF NEW.supersedes_id IS NOT NULL THEN
   SELECT * INTO prior FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.supersedes_id FOR SHARE;
   IF prior.board_id IS DISTINCT FROM NEW.board_id OR prior.status = 'draft'
      OR (NEW.status = 'published' AND prior.status <> 'cancelled') THEN
    RAISE EXCEPTION 'A replacement booking supersedes a published or cancelled booking on the same board; reload the board.' USING ERRCODE = '23514';
   END IF;
   IF prior.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'A closed shift is final history; book a new shift instead.' USING ERRCODE = '23514';
   END IF;
   IF NEW.removes_predecessor AND (prior.status <> 'published' OR ROW(NEW.worker_party_id, NEW.equipment_unit_id, NEW.resource_location_id, NEW.starts_at, NEW.ends_at)
      IS DISTINCT FROM ROW(prior.worker_party_id, prior.equipment_unit_id, prior.resource_location_id, prior.starts_at, prior.ends_at)) THEN
    RAISE EXCEPTION 'A removal revision names the published booking it removes, with the same subject and times.' USING ERRCODE = '23514';
   END IF;
  END IF;
  IF NEW.pattern_assignment_id IS NOT NULL THEN
   SELECT * INTO assignment_row FROM public.schedule_pattern_assignments WHERE org_id = NEW.org_id AND id = NEW.pattern_assignment_id FOR SHARE;
   IF NOT FOUND OR assignment_row.board_id <> NEW.board_id OR assignment_row.worker_party_id IS DISTINCT FROM NEW.worker_party_id
      OR assignment_row.employment_id IS DISTINCT FROM NEW.employment_id
      OR NEW.pattern_occurs_on < assignment_row.effective_from
      OR (assignment_row.effective_to IS NOT NULL AND NEW.pattern_occurs_on >= assignment_row.effective_to)
      OR (assignment_row.status = 'cancelled' AND NOT NEW.pattern_override) THEN
    RAISE EXCEPTION 'A pattern booking belongs to its assignment''s board, person and effective window; reload the assignment.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF OLD.status = 'draft' THEN
  -- A draft awaiting a publication decision keeps the content being decided.
  IF EXISTS (SELECT 1 FROM public.schedule_publications p WHERE p.org_id = NEW.org_id AND p.board_id = NEW.board_id
      AND p.status = 'pending' AND OLD.id = ANY (p.entry_ids)) THEN
   RAISE EXCEPTION 'This change is awaiting its publication decision; wait for the decision or have the publication declined.' USING ERRCODE = '23514';
  END IF;
  IF NEW.status = 'published' THEN
   IF NEW.removes_predecessor THEN
    RAISE EXCEPTION 'A removal revision is applied by cancelling the booking it removes, not published.' USING ERRCODE = '23514';
   END IF;
   IF NEW.published_by IS DISTINCT FROM NEW.updated_by OR NEW.published_at IS NULL THEN
    RAISE EXCEPTION 'Publication evidence must name the publisher.' USING ERRCODE = '23514';
   END IF;
   IF NEW.supersedes_id IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.supersedes_id AND status = 'cancelled') THEN
    RAISE EXCEPTION 'Publishing a replacement cancels the booking it replaces in the same command.' USING ERRCODE = '23514';
   END IF;
   IF NOT EXISTS (SELECT 1 FROM public.schedule_publications p WHERE p.org_id = NEW.org_id AND p.board_id = NEW.board_id
      AND p.status = 'approved' AND NEW.id = ANY (p.entry_ids) AND coalesce(p.decided_by, p.updated_by) = NEW.published_by) THEN
    RAISE EXCEPTION 'A booking is published through its board''s publication, which routes through any configured approval Flow; publish the board.' USING ERRCODE = '23514';
   END IF;
  ELSIF NEW.status NOT IN ('draft','cancelled') OR NEW.published_by IS NOT NULL THEN
   RAISE EXCEPTION 'A draft booking can be edited, published or cancelled.' USING ERRCODE = '23514';
  END IF;
  IF NEW.removes_predecessor AND NEW.status = 'draft' THEN
   RAISE EXCEPTION 'A removal revision cannot be edited; discard it and record another change.' USING ERRCODE = '23514';
  END IF;
  IF NEW.closed_at IS NOT NULL THEN
   RAISE EXCEPTION 'A booking is closed only after it is published and its attendance is complete.' USING ERRCODE = '23514';
  END IF;
 ELSIF OLD.status = 'published' THEN
  editable := ARRAY['status','notes','reason','revision','updated_at','updated_by','closed_at','closed_by','close_reason'];
  IF to_jsonb(NEW) - editable IS DISTINCT FROM to_jsonb(OLD) - editable OR NEW.status NOT IN ('published','cancelled') THEN
   RAISE EXCEPTION 'A published booking keeps its person or resource, target and times; change it on the board, which records a replacement.' USING ERRCODE = '23514';
  END IF;
  IF NEW.closed_at IS NOT NULL THEN
   IF NEW.status <> 'published' OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.closed_by IS DISTINCT FROM NEW.updated_by THEN
    RAISE EXCEPTION 'Closing records only the closer, the time and the reason.' USING ERRCODE = '23514';
   END IF;
   PERFORM public.schedule_entry_assert_closable(NEW);
  ELSIF NEW.service_visit_id IS NULL THEN
   IF NEW.status = 'published' THEN
    RAISE EXCEPTION 'A published booking is immutable history; record the change on the board and publish it, or approve a shift request.' USING ERRCODE = '23514';
   END IF;
   IF NOT EXISTS (SELECT 1 FROM public.schedule_entry_requests r WHERE r.org_id = NEW.org_id AND r.status = 'approved'
       AND coalesce(r.decided_by, r.updated_by) = NEW.updated_by AND OLD.id IN (r.entry_id, r.counterpart_entry_id)) THEN
    SELECT * INTO successor FROM public.schedule_entries WHERE org_id = NEW.org_id AND supersedes_id = OLD.id AND status = 'draft' FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM public.schedule_publications p WHERE p.org_id = NEW.org_id AND p.board_id = NEW.board_id
       AND p.status = 'approved' AND successor.id = ANY (p.entry_ids) AND coalesce(p.decided_by, p.updated_by) = NEW.updated_by) THEN
     RAISE EXCEPTION 'A published booking is changed or removed through a published revision; record the change on the board and publish it.' USING ERRCODE = '23514';
    END IF;
   END IF;
  END IF;
 ELSE
  RAISE EXCEPTION 'Cancelled bookings are history; create a new booking.' USING ERRCODE = '23514';
 END IF;

 IF NEW.status IN ('draft','published') AND (TG_OP = 'INSERT' OR OLD.status = 'draft') AND NOT NEW.removes_predecessor THEN
  IF board.row_kind = 'people' THEN
   IF NEW.worker_party_id IS NULL THEN RAISE EXCEPTION 'People boards book active employees.' USING ERRCODE = '23514'; END IF;
   PERFORM public.schedule_entry_assert_worker(NEW.org_id, NEW.worker_party_id, NEW.employment_id, NEW.starts_on, last_date);
  ELSIF board.resource_kind = 'equipment' THEN
   IF NEW.equipment_unit_id IS NULL THEN RAISE EXCEPTION 'This board books native equipment units.' USING ERRCODE = '23514'; END IF;
   PERFORM 1 FROM public.equipment_units u WHERE u.org_id = NEW.org_id AND u.id = NEW.equipment_unit_id
     AND u.status = 'active' AND (u.in_service_on IS NULL OR u.in_service_on <= NEW.starts_on) FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Choose an active equipment unit in service on the booking date.' USING ERRCODE = '23514'; END IF;
  ELSIF board.resource_kind = 'location' THEN
   IF NEW.resource_location_id IS NULL THEN RAISE EXCEPTION 'This board books native locations.' USING ERRCODE = '23514'; END IF;
   PERFORM 1 FROM public.locations l WHERE l.org_id = NEW.org_id AND l.id = NEW.resource_location_id AND l.is_active FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Choose an active location.' USING ERRCODE = '23514'; END IF;
  ELSE RAISE EXCEPTION 'Choose the resource kind in board settings.' USING ERRCODE = '23514';
  END IF;
  IF NEW.worker_party_id IS NULL AND coalesce(array_length(NEW.required_qualification_type_ids, 1), 0) > 0 THEN
   RAISE EXCEPTION 'Qualification requirements apply to people bookings.' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF NEW.worker_party_id IS NOT NULL AND NEW.status = 'published' AND (TG_OP = 'INSERT' OR OLD.status = 'draft') THEN
  PERFORM public.schedule_entry_assert_available(NEW);
  PERFORM public.schedule_entry_assert_qualified(NEW);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entries_service_visit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE prior_visit uuid;
BEGIN
 IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND NEW.service_visit_id IS DISTINCT FROM OLD.service_visit_id THEN
  RAISE EXCEPTION 'A booking keeps the service visit it serves; book the visit again instead.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'INSERT' THEN
  IF NEW.supersedes_id IS NOT NULL THEN
   SELECT service_visit_id INTO prior_visit FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.supersedes_id;
   IF prior_visit IS DISTINCT FROM NEW.service_visit_id THEN
    RAISE EXCEPTION 'A replacement booking serves the same service visit as the booking it replaces.' USING ERRCODE = '23514';
   END IF;
  END IF;
  IF NEW.service_visit_id IS NOT NULL THEN
   IF NOT public.schedule_board_has_capability(NEW.org_id, NEW.board_id, 'dispatch') THEN
    RAISE EXCEPTION 'Service visits are booked on dispatch boards; open a dispatch board to assign the visit.' USING ERRCODE = '23514';
   END IF;
   IF NEW.worker_party_id IS NULL THEN
    RAISE EXCEPTION 'A service visit is booked on a technician.' USING ERRCODE = '23514';
   END IF;
   IF NOT public.service_dispatch_enabled(NEW.org_id) THEN
    RAISE EXCEPTION 'Service dispatch is switched off; enable it on Company Settings → Features before booking visits.' USING ERRCODE = '23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entry_assert_available(entry schedule_entries)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE blocked date; last_date date;
BEGIN
 last_date := ((entry.ends_at - interval '1 millisecond') AT TIME ZONE entry.time_zone)::date;
 SELECT a.on_date INTO blocked FROM public.hrm_absences a
  JOIN public.worker_employments e ON e.org_id = a.org_id AND e.id = a.employment_id
  WHERE a.org_id = entry.org_id AND e.worker_party_id = entry.worker_party_id AND a.on_date BETWEEN entry.starts_on AND last_date
  GROUP BY a.on_date, a.employment_id, a.leave_type_id HAVING sum(a.hours) <> 0 ORDER BY a.on_date LIMIT 1;
 IF FOUND THEN
  RAISE EXCEPTION 'Recorded leave covers %; choose another date or correct the leave through its request.', blocked USING ERRCODE = '23514';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entry_assert_closable(entry schedule_entries)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE features jsonb; observation_row public.schedule_attendance_observations; policy_row public.schedule_attendance_policies;
 capture_from timestamptz; capture_to timestamptz; mapped integer; pending integer; expected_ids uuid[]; linked_ids uuid[];
BEGIN
 IF NOT public.schedule_board_has_capability(entry.org_id, entry.board_id, 'closing') THEN
  RAISE EXCEPTION 'Formal closing applies to shifts on shift roster boards.' USING ERRCODE = '23514';
 END IF;
 SELECT settings->'features' INTO features FROM public.orgs WHERE id = entry.org_id FOR SHARE;
 IF features->'hrm' IS DISTINCT FROM 'true'::jsonb OR features->'hrmShiftPlanning' IS DISTINCT FROM 'true'::jsonb
    OR features->'hrmAttendance' IS DISTINCT FROM 'true'::jsonb OR features->'hrmShiftClosing' IS DISTINCT FROM 'true'::jsonb THEN
  RAISE EXCEPTION 'Formal shift closing is disabled; enable it and Device attendance on Company Settings → Features. Published bookings do not require closing.' USING ERRCODE = '23514';
 END IF;
 IF entry.worker_party_id IS NULL OR entry.ends_at > now() THEN
  RAISE EXCEPTION 'Only a person''s ended booking can be closed; wait until the shift ends.' USING ERRCODE = '23514';
 END IF;
 SELECT * INTO observation_row FROM public.schedule_attendance_observations o WHERE o.org_id = entry.org_id AND o.entry_id = entry.id
  AND NOT EXISTS (SELECT 1 FROM public.schedule_attendance_observations n WHERE n.org_id = o.org_id AND n.supersedes_id = o.id) FOR SHARE;
 IF observation_row.id IS NULL OR observation_row.status NOT IN ('absent','present') THEN
  RAISE EXCEPTION 'Attendance has no current completed observation; synchronize the mapped devices and process attendance before closing.' USING ERRCODE = '23514';
 END IF;
 SELECT * INTO policy_row FROM public.schedule_attendance_policies WHERE org_id = entry.org_id AND id = observation_row.policy_id;
 capture_from := entry.starts_at - make_interval(mins => policy_row.capture_before_minutes);
 capture_to := entry.ends_at + make_interval(mins => policy_row.capture_after_minutes);
 SELECT count(*), count(*) FILTER (WHERE w.complete_through IS NULL OR w.complete_through < capture_to) INTO mapped, pending
  FROM public.schedule_attendance_identities i
  JOIN public.schedule_attendance_devices d ON d.org_id = i.org_id AND d.id = i.device_id
  LEFT JOIN public.schedule_attendance_watermarks w ON w.org_id = i.org_id AND w.device_id = i.device_id
  WHERE i.org_id = entry.org_id AND i.worker_party_id = entry.worker_party_id
    AND daterange(i.effective_from, i.effective_to, '[)') @> daterange((capture_from AT TIME ZONE d.time_zone)::date, (capture_to AT TIME ZONE d.time_zone)::date, '[]');
 IF mapped = 0 OR pending > 0 THEN
  RAISE EXCEPTION 'Attendance sources are not complete for this booking; synchronize every mapped device and process attendance before closing.' USING ERRCODE = '23514';
 END IF;
 SELECT coalesce(array_agg(e.id ORDER BY e.id), ARRAY[]::uuid[]) INTO expected_ids FROM public.schedule_attendance_events e
  WHERE e.org_id = entry.org_id AND e.worker_party_id = entry.worker_party_id AND e.occurred_at BETWEEN capture_from AND capture_to AND e.kind <> 'void'
    AND NOT EXISTS (SELECT 1 FROM public.schedule_attendance_events n WHERE n.org_id = e.org_id AND n.supersedes_id = e.id);
 SELECT coalesce(array_agg(c.event_id ORDER BY c.event_id), ARRAY[]::uuid[]) INTO linked_ids FROM public.schedule_attendance_observation_events oe
  JOIN public.schedule_attendance_event_claims c ON c.org_id = oe.org_id AND c.id = oe.event_claim_id
  WHERE oe.org_id = entry.org_id AND oe.observation_id = observation_row.id AND c.released_at IS NULL;
 IF expected_ids IS DISTINCT FROM linked_ids THEN
  RAISE EXCEPTION 'Attendance evidence changed after it was processed; process attendance again before closing.' USING ERRCODE = '23514';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entry_assert_qualified(entry schedule_entries)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE type_row public.hrm_qualification_types; required uuid; last_date date;
BEGIN
 IF coalesce(array_length(entry.required_qualification_type_ids, 1), 0) = 0 THEN RETURN; END IF;
 last_date := ((entry.ends_at - interval '1 millisecond') AT TIME ZONE entry.time_zone)::date;
 FOREACH required IN ARRAY entry.required_qualification_type_ids LOOP
  SELECT * INTO type_row FROM public.hrm_qualification_types WHERE org_id = entry.org_id AND id = required AND is_active FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'A required qualification type is unavailable; reactivate it or remove the requirement from the pattern slot.' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.hrm_worker_qualifications q JOIN public.worker_employments e ON e.org_id = q.org_id AND e.id = q.employment_id
   WHERE q.org_id = entry.org_id AND e.worker_party_id = entry.worker_party_id
     AND (entry.employment_id IS NULL OR q.employment_id = entry.employment_id)
     AND q.type_id = required AND q.status = 'valid' AND q.verified_by IS NOT NULL AND q.verified_at IS NOT NULL
     AND q.issued_on <= entry.starts_on AND (q.expires_on IS NULL OR q.expires_on >= last_date)
   FOR SHARE OF q;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Qualification % (%) is not verified for the whole booking; record, renew or verify the person''s qualification before publishing.', type_row.name, type_row.code USING ERRCODE = '23514';
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entry_assert_worker(tenant uuid, worker uuid, employment uuid, from_on date, through_on date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 PERFORM 1 FROM public.employee_roles r
  WHERE r.org_id = tenant AND r.party_id = worker AND r.is_active
    AND (r.hired_on IS NULL OR r.hired_on <= from_on)
    AND (r.terminated_on IS NULL OR r.terminated_on >= through_on)
  FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'This person has no active employee role covering %; book an active employee or correct their hire and termination dates.', from_on USING ERRCODE = '23514';
 END IF;
 IF employment IS NOT NULL THEN
  PERFORM 1 FROM public.worker_employments e WHERE e.org_id = tenant AND e.id = employment AND e.worker_party_id = worker FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'The employment does not belong to this person; select the person again.' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT employment_id FROM public.worker_employment_versions
   WHERE org_id = tenant AND employment_id = employment AND recorded_until IS NULL AND status = 'active'
   GROUP BY employment_id HAVING range_agg(daterange(effective_from, effective_to, '[)')) @> daterange(from_on, through_on, '[]')) THEN
   RAISE EXCEPTION 'Active employment history does not cover %; choose a covered date or record the employment change first.', from_on USING ERRCODE = '23514';
  END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_entry_requests_outcome_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE request_row public.schedule_entry_requests; entry_row public.schedule_entries; counterpart_row public.schedule_entries;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NULL; END IF;
 SELECT * INTO request_row FROM public.schedule_entry_requests WHERE org_id = NEW.org_id AND id = NEW.id;
 IF request_row.status <> 'approved' THEN RETURN NULL; END IF;
 SELECT * INTO entry_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = request_row.entry_id;
 IF entry_row.status <> 'cancelled' THEN
  RAISE EXCEPTION 'An approved shift request replaces or releases its booking in the same command.' USING ERRCODE = '23514';
 END IF;
 IF request_row.kind = 'change' AND NOT EXISTS (SELECT 1 FROM public.schedule_entries s WHERE s.org_id = NEW.org_id
    AND s.origin_request_id = request_row.id AND s.supersedes_id = request_row.entry_id AND s.status = 'published'
    AND s.starts_at = request_row.proposed_starts_at AND s.ends_at = request_row.proposed_ends_at
    AND s.break_minutes = request_row.proposed_break_minutes AND s.worker_party_id = request_row.worker_party_id) THEN
  RAISE EXCEPTION 'An approved change publishes the requested times in the same command.' USING ERRCODE = '23514';
 END IF;
 IF request_row.kind = 'swap' THEN
  SELECT * INTO counterpart_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = request_row.counterpart_entry_id;
  IF counterpart_row.status <> 'cancelled'
     OR NOT EXISTS (SELECT 1 FROM public.schedule_entries s WHERE s.org_id = NEW.org_id AND s.origin_request_id = request_row.id
       AND s.supersedes_id = request_row.entry_id AND s.status = 'published' AND s.worker_party_id = request_row.counterpart_party_id
       AND s.starts_at = entry_row.starts_at AND s.ends_at = entry_row.ends_at)
     OR NOT EXISTS (SELECT 1 FROM public.schedule_entries s WHERE s.org_id = NEW.org_id AND s.origin_request_id = request_row.id
       AND s.supersedes_id = request_row.counterpart_entry_id AND s.status = 'published' AND s.worker_party_id = request_row.worker_party_id
       AND s.starts_at = counterpart_row.starts_at AND s.ends_at = counterpart_row.ends_at) THEN
   RAISE EXCEPTION 'An approved swap exchanges both bookings in the same command.' USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_flow_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE kind text:=TG_ARGV[0]; receipt public.flow_submissions; actor uuid;
BEGIN
 IF OLD.status<>'pending' OR NEW.status NOT IN('approved','declined') THEN RETURN NEW; END IF;
 SELECT * INTO receipt FROM public.flow_submissions s WHERE s.org_id=NEW.org_id AND s.subject_kind=kind
  AND s.subject_id=NEW.id ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
 actor:=NEW.updated_by;
 IF NOT FOUND THEN RAISE EXCEPTION 'Submit this schedule record through native tenant Flows before release.'; END IF;
 IF NEW.released_without_approval THEN
  IF NEW.status<>'approved' OR NEW.decided_by IS NOT NULL OR NOT public.flow_ungated_submission_authorized(NEW.org_id,kind,NEW.id,actor) THEN
   RAISE EXCEPTION 'This schedule record has no complete zero-gate Flow submission.';
  END IF;
 ELSIF NEW.decided_by IS DISTINCT FROM actor OR NOT EXISTS(
   SELECT 1 FROM public.flow_gates g JOIN public.flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE g.org_id=NEW.org_id AND g.subject_kind=kind AND g.subject_id=NEW.id
      AND receipt.policy->'runIds' ? r.id::text AND g.decided_by=actor AND g.decided_at IS NOT NULL
      AND g.status=CASE WHEN NEW.status='approved' THEN 'approved' ELSE 'rejected' END
      AND r.status IN('waiting','completed') AND r.error IS NULL)
   OR (NEW.status='approved' AND NOT public.flow_submission_approved(NEW.org_id,kind,NEW.id,receipt.id))
   OR EXISTS(SELECT 1 FROM flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind=kind AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
  RAISE EXCEPTION 'Complete the configured schedule Flow gates before releasing this record.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_pattern_slots_valid(slots jsonb, cycle_days integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE slot jsonb; qualification jsonb; seen text[]; slot_day integer; starts integer; ends integer; pause integer;
 cycle_minutes integer; from_minute integer; to_minute integer;
 intervals int4range[] := ARRAY[]::int4range[]; segment int4range; existing int4range;
BEGIN
 IF cycle_days IS NULL OR cycle_days NOT BETWEEN 1 AND 366 THEN RETURN false; END IF;
 IF jsonb_typeof(slots) IS DISTINCT FROM 'array' OR jsonb_array_length(slots) NOT BETWEEN 1 AND 1000 THEN RETURN false; END IF;
 cycle_minutes := cycle_days * 1440;
 FOR slot IN SELECT value FROM jsonb_array_elements(slots) LOOP
  IF jsonb_typeof(slot) IS DISTINCT FROM 'object'
   OR NOT slot ?& ARRAY['position','starts','ends','breakMinutes','qualificationTypeIds']
   OR slot - ARRAY['position','starts','ends','breakMinutes','qualificationTypeIds'] <> '{}'::jsonb
   OR jsonb_typeof(slot->'position') IS DISTINCT FROM 'number' OR (slot->>'position') !~ '^[0-9]{1,3}$'
   OR jsonb_typeof(slot->'breakMinutes') IS DISTINCT FROM 'number' OR (slot->>'breakMinutes') !~ '^[0-9]{1,3}$'
   OR jsonb_typeof(slot->'starts') IS DISTINCT FROM 'string' OR (slot->>'starts') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
   OR jsonb_typeof(slot->'ends') IS DISTINCT FROM 'string' OR (slot->>'ends') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
   OR jsonb_typeof(slot->'qualificationTypeIds') IS DISTINCT FROM 'array' OR jsonb_array_length(slot->'qualificationTypeIds') > 100 THEN
   RETURN false;
  END IF;
  slot_day := (slot->>'position')::integer;
  pause := (slot->>'breakMinutes')::integer;
  starts := split_part(slot->>'starts', ':', 1)::integer * 60 + split_part(slot->>'starts', ':', 2)::integer;
  ends := split_part(slot->>'ends', ':', 1)::integer * 60 + split_part(slot->>'ends', ':', 2)::integer;
  IF ends <= starts THEN ends := ends + 1440; END IF;
  IF slot_day >= cycle_days OR pause > 240 OR pause >= ends - starts THEN RETURN false; END IF;
  seen := ARRAY[]::text[];
  FOR qualification IN SELECT value FROM jsonb_array_elements(slot->'qualificationTypeIds') LOOP
   IF jsonb_typeof(qualification) IS DISTINCT FROM 'string'
    OR (qualification#>>'{}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR (qualification#>>'{}') = ANY (seen) THEN
    RETURN false;
   END IF;
   seen := array_append(seen, qualification#>>'{}');
  END LOOP;
  from_minute := slot_day * 1440 + starts;
  to_minute := slot_day * 1440 + ends;
  FOR segment IN SELECT unnest(CASE WHEN to_minute > cycle_minutes
    THEN ARRAY[int4range(from_minute, cycle_minutes, '[)'), int4range(0, to_minute - cycle_minutes, '[)')]
    ELSE ARRAY[int4range(from_minute, to_minute, '[)')] END) LOOP
   FOREACH existing IN ARRAY intervals LOOP
    IF existing && segment THEN RETURN false; END IF;
   END LOOP;
   intervals := array_append(intervals, segment);
  END LOOP;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_resource_recipients_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE b public.schedule_boards;p public.parties;owner uuid;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF (OLD.org_id,OLD.board_id,OLD.equipment_unit_id,OLD.resource_location_id,OLD.subsidiary_id,OLD.created_by,OLD.created_at) IS DISTINCT FROM (NEW.org_id,NEW.board_id,NEW.equipment_unit_id,NEW.resource_location_id,NEW.subsidiary_id,NEW.created_by,NEW.created_at) OR NEW.revision<>OLD.revision+1 THEN
   RAISE EXCEPTION 'Resource recipient identity is immutable and edits need the next native revision.' USING ERRCODE='23514';
  END IF;
 END IF;
 SELECT * INTO b FROM public.schedule_boards WHERE org_id=NEW.org_id AND id=NEW.board_id FOR SHARE;
 SELECT * INTO p FROM public.parties WHERE org_id=NEW.org_id AND id=NEW.party_id FOR SHARE;
 IF b.row_kind IS DISTINCT FROM 'resources' OR (NEW.is_active AND NOT p.is_active) OR p.id IS NULL OR p.kind <> 'person' THEN RAISE EXCEPTION 'Choose a resource board and an active native person/contact.' USING ERRCODE='23514'; END IF;
 IF NEW.equipment_unit_id IS NOT NULL AND b.resource_kind='equipment' THEN SELECT subsidiary_id INTO owner FROM public.equipment_units WHERE org_id=NEW.org_id AND id=NEW.equipment_unit_id FOR SHARE;
 ELSIF NEW.resource_location_id IS NOT NULL AND b.resource_kind='location' THEN SELECT subsidiary_id INTO owner FROM public.locations WHERE org_id=NEW.org_id AND id=NEW.resource_location_id FOR SHARE;
 ELSE RAISE EXCEPTION 'The recipient resource must match the board resource kind.' USING ERRCODE='23514'; END IF;
 IF NOT FOUND OR owner IS DISTINCT FROM NEW.subsidiary_id OR (b.subsidiary_id IS NOT NULL AND owner IS DISTINCT FROM b.subsidiary_id) OR p.subsidiary_id IS DISTINCT FROM owner THEN RAISE EXCEPTION 'The resource, contact and board must share their authorized legal entity.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_roster_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE entry_row public.schedule_entries; counterpart_row public.schedule_entries; board public.schedule_boards;
 pattern_row public.schedule_patterns; author_party uuid; allowed text[]; listed integer;
BEGIN
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Roster history cannot be deleted; deactivate a pattern, end an assignment, revoke an exception or withdraw a request.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND TG_TABLE_NAME <> 'schedule_pattern_exceptions' THEN
  IF ROW(NEW.id, NEW.org_id, NEW.created_at, NEW.created_by) IS DISTINCT FROM ROW(OLD.id, OLD.org_id, OLD.created_at, OLD.created_by) THEN
   RAISE EXCEPTION 'Roster creation evidence is immutable; create a new record.' USING ERRCODE = '23514';
  END IF;
  IF NEW.revision <> OLD.revision + 1 OR NEW.updated_at < OLD.updated_at THEN
   RAISE EXCEPTION 'The roster record changed since it was loaded; reload it and try again.' USING ERRCODE = '40001';
  END IF;
 END IF;
 IF TG_TABLE_NAME = 'schedule_publications' THEN
  SELECT * INTO board FROM public.schedule_boards WHERE org_id = NEW.org_id AND id = NEW.board_id FOR SHARE;
  IF TG_OP = 'INSERT' THEN
   IF board.id IS NULL OR board.row_kind NOT IN ('people','resources') THEN
    RAISE EXCEPTION 'Publications belong to a native booking board.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status <> 'pending' OR NEW.decided_by IS NOT NULL OR NEW.decided_at IS NOT NULL OR NEW.released_without_approval OR NEW.flow_run_id IS NOT NULL THEN
    RAISE EXCEPTION 'A new publication awaits its decision.' USING ERRCODE = '23514';
   END IF;
   SELECT count(*) INTO listed FROM public.schedule_entries x WHERE x.org_id = NEW.org_id AND x.board_id = NEW.board_id AND x.status = 'draft'
    AND x.id = ANY (NEW.entry_ids);
   IF listed <> cardinality(NEW.entry_ids) THEN
    RAISE EXCEPTION 'A publication names the board''s unpublished changes; reload the board.' USING ERRCODE = '23514';
   END IF;
  ELSE
   allowed := ARRAY['status','flow_run_id','released_without_approval','decided_by','decided_at','decision_reason','revision','updated_at','updated_by'];
   IF to_jsonb(NEW) - allowed IS DISTINCT FROM to_jsonb(OLD) - allowed THEN
    RAISE EXCEPTION 'A publication keeps the changes it was submitted with; submit a new publication.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status = OLD.status THEN
    IF NEW.status <> 'pending' OR OLD.flow_run_id IS NOT NULL OR NEW.decided_by IS NOT NULL OR NEW.released_without_approval THEN
     RAISE EXCEPTION 'Publication evidence is immutable.' USING ERRCODE = '23514';
    END IF;
   ELSIF OLD.status = 'pending' AND NEW.status = 'approved' THEN
    IF NOT ((NEW.decided_by = NEW.updated_by AND NOT NEW.released_without_approval)
       OR (NEW.released_without_approval AND NEW.decided_by IS NULL AND OLD.flow_run_id IS NULL AND NEW.updated_by = OLD.created_by)) THEN
     RAISE EXCEPTION 'A publication is approved by its Flow decider, or released by its submitter when no approval Flow applies.' USING ERRCODE = '23514';
    END IF;
   ELSIF OLD.status = 'pending' AND NEW.status = 'declined' THEN
    IF NEW.decided_by IS DISTINCT FROM NEW.updated_by OR NEW.released_without_approval THEN
     RAISE EXCEPTION 'Decision evidence must name the decider.' USING ERRCODE = '23514';
    END IF;
   ELSIF OLD.status = 'pending' AND NEW.status = 'withdrawn' THEN
    IF NEW.updated_by <> OLD.created_by OR NEW.decided_by IS NOT NULL
      OR EXISTS(SELECT 1 FROM flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='schedule_publication' AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
     RAISE EXCEPTION 'Only the submitter withdraws a publication that no approval Flow owns.' USING ERRCODE = '23514';
    END IF;
   ELSE
    RAISE EXCEPTION 'This publication transition is unavailable; reload the board.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_patterns' THEN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name = NEW.time_zone) THEN
   RAISE EXCEPTION 'The pattern time zone is unknown; select a named time zone such as America/Toronto.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND ROW(NEW.code, NEW.subsidiary_id) IS DISTINCT FROM ROW(OLD.code, OLD.subsidiary_id) THEN
   RAISE EXCEPTION 'A pattern keeps its code and legal entity; create a new pattern instead.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_pattern_assignments' THEN
  SELECT * INTO board FROM public.schedule_boards WHERE org_id = NEW.org_id AND id = NEW.board_id FOR SHARE;
  SELECT * INTO pattern_row FROM public.schedule_patterns WHERE org_id = NEW.org_id AND id = NEW.pattern_id FOR SHARE;
  IF TG_OP = 'INSERT' THEN
   IF NOT public.schedule_board_has_capability(NEW.org_id, NEW.board_id, 'patterns') OR NOT board.is_active OR NEW.status <> 'active' THEN
    RAISE EXCEPTION 'Assign recurring patterns on an active shift roster board.' USING ERRCODE = '23514';
   END IF;
   IF NOT pattern_row.is_active THEN
    RAISE EXCEPTION 'The pattern is inactive; reactivate it in Setup before assigning it.' USING ERRCODE = '23514';
   END IF;
   IF pattern_row.subsidiary_id IS NOT NULL AND NEW.subsidiary_id IS DISTINCT FROM pattern_row.subsidiary_id THEN
    RAISE EXCEPTION 'The pattern belongs to another legal entity; choose a pattern of the person''s legal entity.' USING ERRCODE = '23514';
   END IF;
   IF NEW.employment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.worker_employments e WHERE e.org_id = NEW.org_id
      AND e.id = NEW.employment_id AND e.worker_party_id = NEW.worker_party_id) THEN
    RAISE EXCEPTION 'The employment does not belong to this person; select the person again.' USING ERRCODE = '23514';
   END IF;
   IF NEW.generated_through IS NOT NULL THEN
    RAISE EXCEPTION 'A new assignment has not generated bookings yet.' USING ERRCODE = '23514';
   END IF;
  ELSE
   allowed := ARRAY['status','effective_to','generated_through','last_generation','reason','revision','updated_at','updated_by'];
   IF to_jsonb(NEW) - allowed IS DISTINCT FROM to_jsonb(OLD) - allowed THEN
    RAISE EXCEPTION 'An assignment keeps its board, pattern, person and start; end it and create a new assignment.' USING ERRCODE = '23514';
   END IF;
   IF OLD.status <> 'active' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.effective_to IS DISTINCT FROM OLD.effective_to) THEN
    RAISE EXCEPTION 'An ended or cancelled assignment is history; create a new assignment.' USING ERRCODE = '23514';
   END IF;
   IF OLD.status = 'active' AND NEW.status = 'active' AND NEW.effective_to IS DISTINCT FROM OLD.effective_to THEN
    RAISE EXCEPTION 'End the assignment to change its end date.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status = 'ended' AND OLD.effective_to IS NOT NULL AND NEW.effective_to > OLD.effective_to THEN
    RAISE EXCEPTION 'An assignment can end earlier than planned, never later; create a new assignment to extend it.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status = 'cancelled' AND NEW.effective_to IS DISTINCT FROM OLD.effective_to THEN
    RAISE EXCEPTION 'Cancelling keeps the assignment''s dates.' USING ERRCODE = '23514';
   END IF;
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_pattern_exceptions' THEN
  IF TG_OP = 'UPDATE' THEN
   IF to_jsonb(NEW) - ARRAY['revoked_at','revoked_by','revoke_reason'] IS DISTINCT FROM to_jsonb(OLD) - ARRAY['revoked_at','revoked_by','revoke_reason']
      OR OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL THEN
    RAISE EXCEPTION 'A pattern exception is revoked once with its actor and reason; record a new exception instead.' USING ERRCODE = '23514';
   END IF;
  ELSIF NEW.revoked_at IS NOT NULL THEN
   RAISE EXCEPTION 'A new pattern exception is active.' USING ERRCODE = '23514';
  END IF;
 ELSIF TG_TABLE_NAME = 'schedule_entry_requests' THEN
  SELECT * INTO entry_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.entry_id FOR SHARE;
  IF NEW.counterpart_entry_id IS NOT NULL THEN
   SELECT * INTO counterpart_row FROM public.schedule_entries WHERE org_id = NEW.org_id AND id = NEW.counterpart_entry_id FOR SHARE;
  END IF;
  IF TG_OP = 'INSERT' THEN
   SELECT party_id INTO author_party FROM public.users WHERE org_id = NEW.org_id AND id = NEW.created_by AND is_active FOR SHARE;
   IF author_party IS NULL OR author_party <> NEW.worker_party_id THEN
    RAISE EXCEPTION 'A shift request is made by the scheduled person from their own schedule.' USING ERRCODE = '23514';
   END IF;
   IF NOT public.schedule_board_has_capability(NEW.org_id, NEW.board_id, 'shift_requests') THEN
    RAISE EXCEPTION 'Shift requests are made for shifts on shift roster boards; ask the scheduler to change this booking.' USING ERRCODE = '23514';
   END IF;
   IF entry_row.status <> 'published' OR entry_row.closed_at IS NOT NULL OR entry_row.revision <> NEW.entry_revision
      OR entry_row.worker_party_id IS DISTINCT FROM NEW.worker_party_id OR entry_row.board_id <> NEW.board_id OR entry_row.starts_at <= now() THEN
    RAISE EXCEPTION 'A shift request names a current published future booking of the requester; reload the schedule.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status <> (CASE WHEN NEW.kind = 'swap' THEN 'awaiting_counterpart' ELSE 'pending' END)
      OR NEW.decided_by IS NOT NULL OR NEW.counterpart_responded_by IS NOT NULL THEN
    RAISE EXCEPTION 'A new swap awaits the colleague''s answer; other requests await a decision.' USING ERRCODE = '23514';
   END IF;
   IF NEW.kind = 'swap' AND (counterpart_row.status <> 'published' OR counterpart_row.closed_at IS NOT NULL OR counterpart_row.revision <> NEW.counterpart_entry_revision
      OR counterpart_row.worker_party_id IS DISTINCT FROM NEW.counterpart_party_id OR counterpart_row.board_id <> NEW.board_id OR counterpart_row.starts_at <= now()) THEN
    RAISE EXCEPTION 'A swap names a colleague''s current published future booking on the same board; reload the schedule.' USING ERRCODE = '23514';
   END IF;
  ELSE
   allowed := ARRAY['status','counterpart_responded_by','counterpart_responded_at','flow_run_id','released_without_approval','decided_by','decided_at','decision_reason','revision','updated_at','updated_by'];
   IF to_jsonb(NEW) - allowed IS DISTINCT FROM to_jsonb(OLD) - allowed THEN
    RAISE EXCEPTION 'Shift request details are immutable; withdraw it and make a new request.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status = OLD.status THEN
    IF ROW(NEW.counterpart_responded_by, NEW.decided_by, NEW.released_without_approval) IS DISTINCT FROM ROW(OLD.counterpart_responded_by, OLD.decided_by, OLD.released_without_approval)
       OR (OLD.flow_run_id IS NOT NULL AND NEW.flow_run_id IS DISTINCT FROM OLD.flow_run_id) THEN
     RAISE EXCEPTION 'Shift request evidence is immutable.' USING ERRCODE = '23514';
    END IF;
   ELSIF OLD.status = 'awaiting_counterpart' AND NEW.status IN ('pending','declined') AND NEW.updated_by <> OLD.created_by THEN
    SELECT party_id INTO author_party FROM public.users WHERE org_id = NEW.org_id AND id = NEW.updated_by AND is_active FOR SHARE;
    IF author_party IS DISTINCT FROM NEW.counterpart_party_id THEN
     RAISE EXCEPTION 'Only the colleague named in a swap can accept or decline it.' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'pending' AND (NEW.counterpart_responded_by IS DISTINCT FROM NEW.updated_by OR NEW.decided_by IS NOT NULL) THEN
     RAISE EXCEPTION 'Accepting a swap records the colleague''s answer and awaits a decision.' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'declined' AND NEW.decided_by IS DISTINCT FROM NEW.updated_by THEN
     RAISE EXCEPTION 'Declining a swap records the colleague as the decider.' USING ERRCODE = '23514';
    END IF;
   ELSIF OLD.status IN ('awaiting_counterpart','pending') AND NEW.status = 'withdrawn' THEN
    IF NEW.updated_by <> OLD.created_by OR NEW.decided_by IS NOT NULL THEN
     RAISE EXCEPTION 'Only the request author can withdraw it; a decider declines it instead.' USING ERRCODE = '23514';
    END IF;
   ELSIF OLD.status = 'pending' AND NEW.status IN ('approved','declined') THEN
    IF NOT ((NEW.decided_by = NEW.updated_by AND NOT NEW.released_without_approval)
       OR (NEW.status = 'approved' AND NEW.released_without_approval AND NEW.decided_by IS NULL AND OLD.flow_run_id IS NULL
           AND NEW.updated_by IN (OLD.created_by, coalesce(OLD.counterpart_responded_by, OLD.created_by)))) THEN
     RAISE EXCEPTION 'A shift request is decided through its approval Flow, or released by its submitter when no approval Flow applies.' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'approved' AND (entry_row.status <> 'published' OR entry_row.revision <> OLD.entry_revision
       OR (OLD.kind = 'swap' AND (counterpart_row.status <> 'published' OR counterpart_row.revision <> OLD.counterpart_entry_revision))) THEN
     RAISE EXCEPTION 'The booking changed after the request was made; decline this request and ask for a new one.' USING ERRCODE = '23514';
    END IF;
   ELSE
    RAISE EXCEPTION 'This shift request transition is unavailable; reload the request.' USING ERRCODE = '23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_source_records_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE prior public.schedule_source_records; board public.schedule_boards; person public.parties;
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'Source scheduling evidence is immutable; record a reviewed successor instead.' USING ERRCODE='23514';
 END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.users WHERE org_id=NEW.org_id AND id=NEW.created_by AND is_active) THEN
  RAISE EXCEPTION 'Source evidence must identify an active organization actor.' USING ERRCODE='23514';
 END IF;
 IF NEW.supersedes_id IS NOT NULL THEN
  SELECT * INTO prior FROM public.schedule_source_records WHERE org_id=NEW.org_id AND id=NEW.supersedes_id FOR UPDATE;
  IF NOT FOUND OR ROW(prior.source_system,prior.source_dataset,prior.source_key)
   IS DISTINCT FROM ROW(NEW.source_system,NEW.source_dataset,NEW.source_key) THEN
   RAISE EXCEPTION 'The source successor must name the same source identity.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.board_id IS NOT NULL THEN
  SELECT * INTO board FROM public.schedule_boards WHERE org_id=NEW.org_id AND id=NEW.board_id FOR SHARE;
  IF NOT FOUND OR board.row_kind <> 'people' THEN
   RAISE EXCEPTION 'Source people scheduling belongs to a native people board.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.worker_party_id IS NOT NULL THEN
  SELECT * INTO person FROM public.parties WHERE org_id=NEW.org_id AND id=NEW.worker_party_id FOR SHARE;
  IF NOT FOUND OR person.kind <> 'person'
   OR NOT EXISTS(SELECT 1 FROM public.employee_roles er WHERE er.org_id=NEW.org_id AND er.party_id=NEW.worker_party_id)
   OR person.subsidiary_id IS DISTINCT FROM NEW.subsidiary_id
   OR (NEW.board_id IS NOT NULL AND board.subsidiary_id IS NOT NULL AND board.subsidiary_id IS DISTINCT FROM person.subsidiary_id) THEN
   RAISE EXCEPTION 'The source person and board must belong to the same authorized legal entity.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.disposition='linked' AND NOT EXISTS (SELECT 1 FROM public.schedule_entries e
   WHERE e.org_id=NEW.org_id AND e.id=NEW.linked_entry_id AND e.board_id=NEW.board_id
    AND e.worker_party_id=NEW.worker_party_id AND e.starts_on=NEW.on_date) THEN
  RAISE EXCEPTION 'The native booking does not match this source person, board and date.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.scheduler_outbox_terminal_audit_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'scheduler_outbox_terminal_audit is append-only';
END $function$

CREATE OR REPLACE FUNCTION public.scheduler_outbox_terminal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_generation integer;
BEGIN
  IF OLD.terminal_failed_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.kind IS DISTINCT FROM OLD.kind
     OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
     OR NEW.occurrence_key IS DISTINCT FROM OLD.occurrence_key
     OR NEW.payload IS DISTINCT FROM OLD.payload THEN
    RAISE EXCEPTION 'scheduler_outbox terminal-failure evidence is immutable; authorize a replay to reset it';
  END IF;
  IF NEW.terminal_failed_at IS NOT DISTINCT FROM OLD.terminal_failed_at
     AND NEW.terminal_failed_by IS NOT DISTINCT FROM OLD.terminal_failed_by THEN
    IF NEW.status <> 'failed' THEN
      RAISE EXCEPTION 'terminal scheduler delivery requires an authorized replay';
    END IF;
    RETURN NEW;
  END IF;
  SELECT failure.failure_generation INTO v_generation
    FROM public.scheduler_outbox_terminal_audit failure
   WHERE failure.outbox_row_id = OLD.id AND failure.event <> 'replay_authorized'
     AND failure.at = OLD.terminal_failed_at AND failure.marked_by = OLD.terminal_failed_by
   ORDER BY failure.failure_generation DESC LIMIT 1;
  IF v_generation IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.scheduler_outbox_terminal_audit replay
     WHERE replay.outbox_row_id = OLD.id AND replay.event = 'replay_authorized'
       AND replay.failure_generation = v_generation
  ) THEN
    RAISE EXCEPTION 'a scheduler_outbox replay reset requires its replay_authorized audit evidence first';
  END IF;
  IF public.openbooks_scheduler_outbox_replay_allowed(OLD.org_id) IS NOT TRUE THEN
    RAISE EXCEPTION 'a scheduler_outbox replay reset requires its organization''s authorization pin';
  END IF;
  IF NEW.terminal_failed_at IS NOT NULL OR NEW.terminal_failed_by IS NOT NULL
     OR NEW.status <> 'pending' OR NEW.attempt_count <> 0
     OR NEW.locked_at IS NOT NULL OR NEW.lease_token IS NOT NULL THEN
    RAISE EXCEPTION 'an authorized scheduler replay must reset the current failure to pending delivery';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.segment_balancing_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.financial_history_native_clone_matches(TG_RELID,to_jsonb(NEW)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Financial history clone admission requires the exact registered source row, seed and destination parents.' USING ERRCODE='23514';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('openbooks:ledger-setup:'||NEW.org_id,0));
 IF NOT EXISTS(SELECT 1 FROM segment_definitions WHERE org_id=NEW.org_id AND key=NEW.segment_key AND is_active AND is_balancing) THEN
  RAISE EXCEPTION 'Choose an active balancing segment.' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE org_id=NEW.org_id AND id=NEW.clearing_account_id AND is_active AND NOT is_summary
   AND currency_restriction IS NULL AND type IN('asset_current_other','asset_other','liability_current_other','liability_long_term')) THEN
  RAISE EXCEPTION 'Choose an unrestricted active balance-sheet clearing account.' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM journal_entries WHERE org_id=NEW.org_id AND status IN('posted','reversed') AND posting_date>=NEW.effective_from) THEN
  RAISE EXCEPTION 'Start the balancing policy after the latest posting date; posted entries retain their original balancing policy.' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.segment_definition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if tg_op = 'DELETE' and old.source_kind = 'builtin'
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'built-in segment definitions cannot be deleted' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and old.source_kind = 'builtin' and
     (new.key <> old.key or new.source_kind <> old.source_kind or new.storage_column is distinct from old.storage_column) then
    raise exception 'built-in segment identity cannot be changed' using errcode = '23514';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION public.segment_definition_has_value(p_org uuid, p_segment uuid, p_value uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_kind text;
  v_storage text;
BEGIN
  SELECT source_kind, storage_column INTO v_kind, v_storage
    FROM public.segment_definitions WHERE org_id = p_org AND id = p_segment;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF v_kind = 'custom' THEN
    RETURN EXISTS (SELECT 1 FROM public.segment_values WHERE org_id = p_org AND segment_id = p_segment AND id = p_value);
  END IF;
  RETURN CASE v_storage
    WHEN 'department_id' THEN EXISTS (SELECT 1 FROM public.departments WHERE org_id = p_org AND id = p_value)
    WHEN 'class_id' THEN EXISTS (SELECT 1 FROM public.classes WHERE org_id = p_org AND id = p_value)
    WHEN 'location_id' THEN EXISTS (SELECT 1 FROM public.locations WHERE org_id = p_org AND id = p_value)
    WHEN 'project_id' THEN EXISTS (SELECT 1 FROM public.projects WHERE org_id = p_org AND id = p_value)
    WHEN 'subsidiary_id' THEN EXISTS (SELECT 1 FROM public.subsidiaries WHERE org_id = p_org AND id = p_value)
    ELSE false
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.segment_definitions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_value_segment uuid;
  v_line_count bigint;
begin
  if new.default_value_id is not null then
    select segment_id into v_value_segment
      from public.segment_values
     where org_id = new.org_id and id = new.default_value_id;
    if not found or v_value_segment is distinct from new.id then
      raise exception 'default value % does not belong to segment %', new.default_value_id, new.key
        using errcode = '23514';
    end if;
  end if;

  if tg_op = 'UPDATE' and old.is_balancing and not new.is_balancing then
    select count(*) into v_line_count
      from public.journal_lines l
      join public.journal_entries e on e.org_id = l.org_id and e.id = l.entry_id
     where l.org_id = old.org_id
       and l.extra_dims ? old.key
       and e.status is distinct from 'draft';
    if v_line_count > 0 then
      raise exception 'segment % cannot stop balancing while % posted journal lines carry it',
        old.key, v_line_count using errcode = '23514';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.segment_value_dependency_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN
    RETURN NEW;
  END IF;
  IF NOT public.segment_definition_has_value(NEW.org_id, NEW.segment_id, NEW.value_id) THEN
    RAISE EXCEPTION 'segment value dependency names value % that does not belong to its segment', NEW.value_id
      USING ERRCODE = '23514';
  END IF;
  IF NOT public.segment_definition_has_value(NEW.org_id, NEW.controlling_segment_id, NEW.allowed_value_id) THEN
    RAISE EXCEPTION 'segment value dependency allows value % that does not belong to the controlling segment', NEW.allowed_value_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.segment_value_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_hierarchical boolean;
  old_scope text;
  new_scope text;
  first_scope text;
  second_scope text;
  tree_scope text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (OLD.org_id, OLD.segment_id) IS DISTINCT FROM (NEW.org_id, NEW.segment_id) THEN
    old_scope := OLD.org_id::text || ':' || OLD.segment_id::text;
    new_scope := NEW.org_id::text || ':' || NEW.segment_id::text;
    first_scope := LEAST(old_scope, new_scope);
    second_scope := GREATEST(old_scope, new_scope);
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || first_scope, 0)
    );
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || second_scope, 0)
    );
  ELSE
    tree_scope := NEW.org_id::text || ':' || NEW.segment_id::text;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('segment-value-tree:' || tree_scope, 0)
    );
  END IF;

  SELECT is_hierarchical INTO v_hierarchical
    FROM public.segment_definitions
   WHERE id = NEW.segment_id
     AND org_id = NEW.org_id
     AND source_kind = 'custom'
   FOR KEY SHARE;
  IF v_hierarchical IS NULL THEN
    RAISE EXCEPTION 'segment value must belong to a custom segment in this organization'
      USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE'
     AND (OLD.org_id, OLD.segment_id) IS DISTINCT FROM (NEW.org_id, NEW.segment_id)
     AND EXISTS (
       SELECT 1 FROM public.segment_values child
        WHERE child.parent_id = OLD.id
          AND child.org_id = OLD.org_id
          AND child.segment_id = OLD.segment_id
     ) THEN
    RAISE EXCEPTION 'a segment value with children cannot change organization or segment'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.subsidiary_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.subsidiaries subsidiary
     WHERE subsidiary.id = NEW.subsidiary_id AND subsidiary.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'segment value subsidiary belongs to another organization'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.parent_id IS NOT NULL THEN
    IF NOT v_hierarchical THEN
      RAISE EXCEPTION 'this segment is not hierarchical' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.segment_values parent
       WHERE parent.id = NEW.parent_id
         AND parent.org_id = NEW.org_id
         AND parent.segment_id = NEW.segment_id
    ) THEN
      RAISE EXCEPTION 'segment value parent is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.parent_id = NEW.id OR EXISTS (
      WITH RECURSIVE descendants AS (
        SELECT id
          FROM public.segment_values
         WHERE org_id = NEW.org_id
           AND segment_id = NEW.segment_id
           AND parent_id = NEW.id
        UNION
        SELECT value.id
          FROM public.segment_values value
          JOIN descendants descendant ON value.parent_id = descendant.id
         WHERE value.org_id = NEW.org_id
           AND value.segment_id = NEW.segment_id
      )
      SELECT 1 FROM descendants WHERE id = NEW.parent_id
    ) THEN
      RAISE EXCEPTION 'segment value hierarchy contains a cycle' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.segment_values_clear_default_for_wipe()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  if public.openbooks_sandbox_wipe_allowed(old.org_id) then
    update public.segment_definitions
       set default_value_id = null, updated_at = now()
     where org_id = old.org_id and default_value_id = old.id;
  end if;
  return old;
end $function$

CREATE OR REPLACE FUNCTION public.service_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) OR public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Service history cannot be deleted.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'UPDATE' THEN
  RAISE EXCEPTION 'Service history is append-only; record a new version or event instead.' USING ERRCODE = '23514';
 END IF;
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME = 'service_agreement_lines' AND EXISTS (SELECT 1 FROM public.service_visits v
   WHERE v.org_id = NEW.org_id AND v.agreement_version_id = (to_jsonb(NEW)->>'version_id')::uuid) THEN
  RAISE EXCEPTION 'An agreement version that generated visits keeps its lines; add a new version instead.' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.service_record_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE immutable text[]; visit_status text; job_open boolean; o jsonb; n jsonb; tenant uuid; job uuid;
BEGIN
 -- Table-specific columns are read through jsonb so one guard serves every service table.
 o := CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END;
 n := CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END;
 tenant := coalesce(n->>'org_id', o->>'org_id')::uuid;
 IF TG_OP = 'DELETE' THEN
  IF tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, o) OR public.openbooks_sandbox_wipe_allowed(tenant) THEN RETURN OLD; END IF;
  IF TG_TABLE_NAME = 'service_visit_parts' AND o->>'inventory_movement_id' IS NULL THEN
   SELECT status INTO visit_status FROM public.service_visits WHERE org_id = tenant AND id = (o->>'visit_id')::uuid FOR SHARE;
   IF visit_status IN ('completed','unable_to_complete','cancelled') THEN
    RAISE EXCEPTION 'Parts on a finished visit are its history; record a correction on a new visit instead.' USING ERRCODE = '23514';
   END IF;
   RETURN OLD;
  END IF;
  -- Discarding a draft invoice releases the work it billed; discarding a
  -- draft estimate drops its unsent service terms.
  IF TG_TABLE_NAME = 'service_billings' AND o->>'released_at' IS NULL AND EXISTS (SELECT 1 FROM public.documents d
    WHERE d.org_id = tenant AND d.id = (o->>'invoice_document_id')::uuid AND d.status = 'draft') THEN
   RETURN OLD;
  END IF;
  IF TG_TABLE_NAME = 'service_quotes' AND o->>'status' = 'draft' THEN
   RETURN OLD;
  END IF;
  IF TG_TABLE_NAME = 'service_quote_lines' THEN
   IF o->>'selected' IS NOT NULL THEN
    RAISE EXCEPTION 'The customer''s add-on selection is final.' USING ERRCODE = '23514';
   END IF;
   RETURN OLD;
  END IF;
  IF TG_TABLE_NAME = 'service_job_lines' THEN
   job := (o->>'job_id')::uuid;
   SELECT status = 'open' AND NOT EXISTS (SELECT 1 FROM public.service_billings b WHERE b.org_id = tenant AND b.job_id = job AND b.released_at IS NULL)
    INTO job_open FROM public.service_jobs WHERE org_id = tenant AND id = job FOR SHARE;
   IF NOT coalesce(job_open, false) THEN
    RAISE EXCEPTION 'Job lines change only while the job is open and not yet invoiced.' USING ERRCODE = '23514';
   END IF;
   RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Service history cannot be deleted; cancel or close the record instead.' USING ERRCODE = '23514';
 END IF;
 IF TG_OP = 'INSERT' THEN
  IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
  IF NOT public.service_dispatch_enabled(tenant) THEN
   RAISE EXCEPTION 'Service dispatch is switched off; enable it on Company Settings → Features. Existing service records are preserved.' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'service_job_lines' THEN
   job := (n->>'job_id')::uuid;
   SELECT status = 'open' AND NOT EXISTS (SELECT 1 FROM public.service_billings b WHERE b.org_id = tenant AND b.job_id = job AND b.released_at IS NULL)
    INTO job_open FROM public.service_jobs WHERE org_id = tenant AND id = job FOR SHARE;
   IF NOT coalesce(job_open, false) THEN
    RAISE EXCEPTION 'Job lines change only while the job is open and not yet invoiced.' USING ERRCODE = '23514';
   END IF;
  END IF;
  IF TG_TABLE_NAME = 'service_visit_parts' THEN
   SELECT status INTO visit_status FROM public.service_visits WHERE org_id = tenant AND id = (n->>'visit_id')::uuid FOR SHARE;
   IF visit_status IS NULL OR visit_status NOT IN ('scheduled','dispatched','en_route','on_site') THEN
    RAISE EXCEPTION 'Parts are recorded on a scheduled or active visit.' USING ERRCODE = '23514';
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 -- UPDATE
 -- A governed party merge re-points the customer only; every other fact,
 -- including the revision, is preserved.
 IF TG_TABLE_NAME IN ('service_requests','service_jobs','service_agreements')
    AND coalesce(current_setting('openbooks.amend', true), 'off') = 'on'
    AND coalesce(current_setting('openbooks.migration', true), 'off') = 'on'
    AND n - 'customer_party_id' = o - 'customer_party_id' THEN
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME IN ('service_requests','service_jobs','service_visits','service_agreements','service_quotes')
    AND ((n->>'revision')::integer <> (o->>'revision')::integer + 1 OR (n->>'updated_at')::timestamptz < (o->>'updated_at')::timestamptz) THEN
  RAISE EXCEPTION 'The record changed since it was loaded; reload it and try again.' USING ERRCODE = '40001';
 END IF;
 immutable := CASE TG_TABLE_NAME
  WHEN 'service_requests' THEN ARRAY['id','org_id','request_number','source','portal_link_id','created_at','created_by']
  WHEN 'service_jobs' THEN ARRAY['id','org_id','job_number','request_id','agreement_id','currency','created_at','created_by']
  WHEN 'service_visits' THEN ARRAY['id','org_id','kind','request_id','job_id','sequence','agreement_id','agreement_version_id','occurs_on','created_at','created_by']
  WHEN 'service_agreements' THEN ARRAY['id','org_id','agreement_number','customer_party_id','subsidiary_id','created_at','created_by']
  WHEN 'service_quotes' THEN ARRAY['id','org_id','quote_document_id','created_at','created_by']
  WHEN 'service_visit_parts' THEN ARRAY['id','org_id','visit_id','item_id','stock_location_id','quantity','lot_id','serial_id','created_at','created_by']
  WHEN 'service_billings' THEN ARRAY['id','org_id','job_id','visit_id','invoice_document_id','created_at','created_by']
  WHEN 'service_visit_signature_requests' THEN ARRAY['id','org_id','visit_id','recipient','token_digest','expires_at','created_at','created_by']
  WHEN 'service_quote_lines' THEN ARRAY['org_id','quote_document_id','document_line_id']
  WHEN 'service_customer_notices' THEN ARRAY['id','org_id','visit_id','kind','occurrence_key','recipient','created_at','created_by']
  ELSE ARRAY['id','org_id'] END;
 IF EXISTS (SELECT 1 FROM unnest(immutable) column_name WHERE n->column_name IS DISTINCT FROM o->column_name) THEN
  RAISE EXCEPTION 'This service record keeps its identity, parent and creation evidence; create a new record instead.' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME = 'service_visit_parts' AND o->>'inventory_movement_id' IS NOT NULL THEN
  RAISE EXCEPTION 'An issued part is inventory history.' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME = 'service_job_lines' THEN
  job := (n->>'job_id')::uuid;
  SELECT status = 'open' AND NOT EXISTS (SELECT 1 FROM public.service_billings b WHERE b.org_id = tenant AND b.job_id = job AND b.released_at IS NULL)
   INTO job_open FROM public.service_jobs WHERE org_id = tenant AND id = job FOR SHARE;
  IF NOT coalesce(job_open, false) THEN
   RAISE EXCEPTION 'Job lines change only while the job is open and not yet invoiced.' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF TG_TABLE_NAME = 'service_billings' THEN
  IF o->>'released_at' IS NOT NULL OR n->>'released_at' IS NULL THEN
   RAISE EXCEPTION 'A billing link changes only when its voided invoice releases it.' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.documents d WHERE d.org_id = tenant AND d.id = (n->>'invoice_document_id')::uuid AND d.status = 'voided') THEN
   RAISE EXCEPTION 'A billing link is released only after its invoice is voided; void the invoice first.' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF TG_TABLE_NAME = 'service_visit_signature_requests' AND (o->>'responded_at' IS NOT NULL OR o->>'revoked_at' IS NOT NULL) THEN
  RAISE EXCEPTION 'A used or revoked signing link is final.' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME = 'service_customer_notices' AND (o->>'status' <> 'queued' OR n->>'status' = 'queued') THEN
  RAISE EXCEPTION 'A customer notice records its delivery outcome once.' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME = 'service_quote_lines' AND o->>'selected' IS NOT NULL THEN
  RAISE EXCEPTION 'The customer''s add-on selection is final; revise the quote and send it again.' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.service_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE live_bookings integer;
BEGIN
 IF TG_OP = 'INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME = 'service_requests' THEN
  IF TG_OP = 'INSERT' AND NEW.status <> 'new' THEN
   RAISE EXCEPTION 'A service request starts as new.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NOT (
   (OLD.status = 'new' AND NEW.status IN ('assessment_scheduled','assessed','quoted','converted','declined','cancelled'))
   OR (OLD.status = 'assessment_scheduled' AND NEW.status IN ('new','assessed','quoted','converted','declined','cancelled'))
   OR (OLD.status = 'assessed' AND NEW.status IN ('quoted','converted','declined','cancelled'))
   OR (OLD.status = 'quoted' AND NEW.status IN ('assessed','converted','declined','cancelled'))) THEN
   RAISE EXCEPTION 'A service request cannot move from % to %.', OLD.status, NEW.status USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status = 'converted' AND OLD.status <> 'converted'
     AND NOT EXISTS (SELECT 1 FROM public.service_jobs j WHERE j.org_id = NEW.org_id AND j.request_id = NEW.id) THEN
   RAISE EXCEPTION 'A request is converted by creating its service job.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME = 'service_jobs' THEN
  IF TG_OP = 'INSERT' AND NEW.status <> 'open' THEN
   RAISE EXCEPTION 'A service job starts open.' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
   IF NOT ((OLD.status = 'open' AND NEW.status IN ('completed','cancelled')) OR (OLD.status = 'completed' AND NEW.status = 'open')) THEN
    RAISE EXCEPTION 'A service job cannot move from % to %.', OLD.status, NEW.status USING ERRCODE = '23514';
   END IF;
   IF NEW.status = 'completed' AND EXISTS (SELECT 1 FROM public.service_visits v WHERE v.org_id = NEW.org_id AND v.job_id = NEW.id
     AND v.status IN ('scheduled','dispatched','en_route','on_site')) THEN
    RAISE EXCEPTION 'The job still has visits in progress; complete, reschedule or cancel them first.' USING ERRCODE = '23514';
   END IF;
   IF NEW.status = 'cancelled' AND EXISTS (SELECT 1 FROM public.service_visits v WHERE v.org_id = NEW.org_id AND v.job_id = NEW.id
     AND v.status NOT IN ('unscheduled','cancelled')) THEN
    RAISE EXCEPTION 'A job with booked or worked visits is completed, not cancelled; cancel its open visits first.' USING ERRCODE = '23514';
   END IF;
   IF OLD.status = 'completed' AND NEW.status = 'open' AND EXISTS (SELECT 1 FROM public.service_billings b WHERE b.org_id = NEW.org_id
     AND b.job_id = NEW.id AND b.visit_id IS NULL AND b.released_at IS NULL) THEN
    RAISE EXCEPTION 'An invoiced job stays completed; void its invoice before reopening it.' USING ERRCODE = '23514';
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 -- service_visits
 IF TG_OP = 'INSERT' THEN
  IF NEW.status NOT IN ('unscheduled') THEN
   RAISE EXCEPTION 'A visit starts unscheduled; assign it on a dispatch board.' USING ERRCODE = '23514';
  END IF;
  IF NEW.kind = 'service' AND NOT EXISTS (SELECT 1 FROM public.service_jobs j WHERE j.org_id = NEW.org_id AND j.id = NEW.job_id AND j.status = 'open') THEN
   RAISE EXCEPTION 'Visits are added to open jobs.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
  (OLD.status = 'unscheduled' AND NEW.status IN ('scheduled','cancelled'))
  OR (OLD.status = 'scheduled' AND NEW.status IN ('unscheduled','dispatched','en_route','cancelled'))
  OR (OLD.status = 'dispatched' AND NEW.status IN ('unscheduled','scheduled','en_route','cancelled'))
  OR (OLD.status = 'en_route' AND NEW.status IN ('on_site','unable_to_complete'))
  OR (OLD.status = 'on_site' AND NEW.status IN ('completed','unable_to_complete'))
  OR (OLD.status = 'completed' AND NEW.status = 'on_site' AND NEW.review_status IS NULL AND OLD.review_status = 'rejected')) THEN
  RAISE EXCEPTION 'A visit cannot move from % to %.', OLD.status, NEW.status USING ERRCODE = '23514';
 END IF;
 IF NEW.status IN ('scheduled','dispatched','en_route','on_site','unscheduled') AND NEW.status IS DISTINCT FROM OLD.status THEN
  SELECT count(*) INTO live_bookings FROM public.schedule_entries e
   WHERE e.org_id = NEW.org_id AND e.service_visit_id = NEW.id AND e.status = 'published';
  IF NEW.status = 'unscheduled' AND live_bookings > 0 THEN
   RAISE EXCEPTION 'An unscheduled visit holds no bookings; remove its technicians first.' USING ERRCODE = '23514';
  END IF;
  IF NEW.status <> 'unscheduled' AND live_bookings = 0 THEN
   RAISE EXCEPTION 'A scheduled visit is booked on at least one technician.' USING ERRCODE = '23514';
  END IF;
 END IF;
 IF OLD.status IN ('completed','unable_to_complete','cancelled') AND NEW.status = OLD.status
    AND to_jsonb(NEW) - ARRAY['review_status','review_flow_run_id','review_decided_by','review_decided_at','review_reason','revision','updated_at','updated_by']
     IS DISTINCT FROM to_jsonb(OLD) - ARRAY['review_status','review_flow_run_id','review_decided_by','review_decided_at','review_reason','revision','updated_at','updated_by'] THEN
  RAISE EXCEPTION 'A finished visit is history; only its completion review is recorded.' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.statistical_document_quantity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE statistical boolean;
BEGIN
 IF TG_TABLE_NAME='document_lines' THEN
  IF NEW.quantity<>trunc(NEW.quantity,4) THEN
   SELECT d.kind='journal' AND d.journal_mode='statistical' INTO statistical FROM documents d
    WHERE d.org_id=NEW.org_id AND d.id=NEW.document_id FOR SHARE;
   IF statistical THEN
    RAISE EXCEPTION 'Statistical quantities require at most four exact decimal places; finer quantities cannot be rounded into the ledger.' USING ERRCODE='23514';
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF EXISTS(SELECT 1 FROM documents d JOIN document_lines l ON l.org_id=d.org_id AND l.document_id=d.id
   WHERE d.org_id=NEW.org_id AND d.id=NEW.id AND d.kind='journal' AND d.journal_mode='statistical'
    AND l.quantity<>trunc(l.quantity,4)) THEN
  RAISE EXCEPTION 'Statistical quantities require at most four exact decimal places; correct the journal quantities before changing its mode.' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.stock_count_flow_admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.submission_policy IS NOT NULL OR NEW.review_released THEN RAISE EXCEPTION 'Stock counts start without review admission.'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='review' AND NEW.status IN('counting','cancelled') THEN
  IF EXISTS(SELECT 1 FROM flow_gates WHERE org_id=NEW.org_id AND subject_kind='stock_count'
    AND subject_id=NEW.id AND status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Withdraw the native count approval gates before changing the count.';
  END IF;
  NEW.submission_policy:=NULL; NEW.review_released:=false; NEW.submitted_by:=NULL;
  RETURN NEW;
 END IF;
 IF OLD.status='counting' AND NEW.status='review' THEN
  IF NEW.submitted_by IS NULL OR NOT public.flow_submission_policy_valid(NEW.org_id,'stock_count',NEW.id,NEW.submitted_by,NEW.submission_policy)
    OR NEW.review_released IS DISTINCT FROM (NEW.submission_policy->>'kind'='ungated') THEN
   RAISE EXCEPTION 'Submit the counted observations through their native Flow routing.';
  END IF;
 ELSIF NEW.submission_policy IS DISTINCT FROM OLD.submission_policy THEN
  RAISE EXCEPTION 'Count review policy freezes on submission; return to counting for a new review.';
 END IF;
 IF OLD.status='review' AND NEW.status='review' AND NOT OLD.review_released AND NEW.review_released THEN
  IF NEW.submission_policy->>'kind' IS DISTINCT FROM 'gated'
    OR NOT EXISTS(SELECT 1 FROM public.flow_submissions s WHERE s.org_id=NEW.org_id
      AND s.subject_kind='stock_count' AND s.subject_id=NEW.id AND s.policy=NEW.submission_policy
      AND public.flow_submission_approved(s.org_id,s.subject_kind,s.subject_id,s.id))
    OR NOT EXISTS(SELECT 1 FROM flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='stock_count'
      AND g.subject_id=NEW.id AND NEW.submission_policy->'runIds' ? g.run_id::text
      AND g.status='approved' AND g.decided_by=NEW.updated_by)
    OR EXISTS(SELECT 1 FROM flow_gates g WHERE g.org_id=NEW.org_id AND g.subject_kind='stock_count'
      AND g.subject_id=NEW.id AND g.status IN('pending','escalated')) THEN
   RAISE EXCEPTION 'Complete all configured count review gates before releasing it.';
  END IF;
 END IF;
 IF OLD.status='review' AND NEW.status='posted' AND NOT OLD.review_released THEN
  RAISE EXCEPTION 'The stock count has not been released by its Flow submission policy.';
 END IF;
 IF OLD.status='review' AND NEW.counted_on IS DISTINCT FROM OLD.counted_on THEN
  RAISE EXCEPTION 'Return the count to counting before changing its date.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.stock_location_custody_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE parent_kind text; parent_vendor uuid;
BEGIN
 IF public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND (NEW.kind,NEW.custodian_party_id,NEW.location_id,NEW.parent_id) IS DISTINCT FROM (OLD.kind,OLD.custodian_party_id,OLD.location_id,OLD.parent_id)
   AND (NEW.kind='subcontract' OR OLD.kind='subcontract') THEN
  IF EXISTS(SELECT 1 FROM public.inventory_movements WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.cost_layers WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.inventory_provisional_costs WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.consignment_stock WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.stock_locations WHERE org_id=OLD.org_id AND parent_id=OLD.id) THEN
   RAISE EXCEPTION 'Vendor custody identity is fixed after stock history or children; configure another location.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.kind='subcontract' THEN
  PERFORM id FROM public.parties WHERE org_id=NEW.org_id AND id=NEW.custodian_party_id FOR SHARE;
  IF NOT EXISTS(SELECT 1 FROM public.parties p WHERE p.org_id=NEW.org_id AND p.id=NEW.custodian_party_id AND p.is_active
    AND (p.kind='vendor' OR EXISTS(SELECT 1 FROM public.vendor_roles v WHERE v.org_id=p.org_id AND v.party_id=p.id))) THEN
   RAISE EXCEPTION 'Choose an active vendor for company-owned custody.' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.parent_id IS NOT NULL THEN
  SELECT kind,custodian_party_id INTO parent_kind,parent_vendor FROM public.stock_locations WHERE org_id=NEW.org_id AND id=NEW.parent_id FOR SHARE;
  IF parent_kind='subcontract' AND (NEW.kind<>'subcontract' OR NEW.custodian_party_id IS DISTINCT FROM parent_vendor) THEN
   RAISE EXCEPTION 'Children of vendor custody must preserve the same vendor and custody kind.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.stock_location_ownership_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.inventory_ownership,NEW.owner_party_id) IS DISTINCT FROM (OLD.inventory_ownership,OLD.owner_party_id) THEN
  IF EXISTS(SELECT 1 FROM public.cost_layers WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.inventory_provisional_costs WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.consignment_stock WHERE org_id=OLD.org_id AND stock_location_id=OLD.id)
    OR EXISTS(SELECT 1 FROM public.stock_locations WHERE org_id=OLD.org_id AND parent_id=OLD.id) THEN
   RAISE EXCEPTION 'Location ownership is fixed once stock history exists; use a new location for a different owner';
  END IF;
 END IF;
 IF NEW.parent_id IS NOT NULL THEN
  PERFORM id FROM public.stock_locations WHERE org_id=NEW.org_id AND id=NEW.parent_id FOR SHARE;
  IF NOT EXISTS(SELECT 1 FROM public.stock_locations p WHERE p.org_id=NEW.org_id AND p.id=NEW.parent_id
    AND p.inventory_ownership=NEW.inventory_ownership AND p.owner_party_id IS NOT DISTINCT FROM NEW.owner_party_id) THEN
   RAISE EXCEPTION 'Child locations must preserve their parent ownership';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.stock_location_warehouse(p_org_id uuid, p_stock_location_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  current_id uuid := p_stock_location_id;
  current_kind text;
  next_id uuid;
  depth integer := 0;
BEGIN
  WHILE current_id IS NOT NULL LOOP
    SELECT sl.kind, sl.parent_id INTO current_kind, next_id
      FROM public.stock_locations sl
     WHERE sl.id = current_id AND sl.org_id = p_org_id;
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
    IF current_kind = 'warehouse' THEN
      RETURN current_id;
    END IF;
    depth := depth + 1;
    IF depth > 64 THEN
      RAISE EXCEPTION 'stock location % has a parent chain deeper than 64 levels or a cycle', p_stock_location_id;
    END IF;
    current_id := next_id;
  END LOOP;
  RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.stock_locations_warehouse_nesting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  enclosing uuid;
  enclosing_code text;
  nested_code text;
BEGIN
  enclosing := public.stock_location_warehouse(NEW.org_id, NEW.parent_id);
  IF NEW.kind = 'warehouse' AND enclosing IS NOT NULL THEN
    SELECT code INTO enclosing_code FROM public.stock_locations WHERE id = enclosing AND org_id = NEW.org_id;
    RAISE EXCEPTION 'warehouse % cannot sit inside warehouse %; make it a zone or move it out', NEW.code, enclosing_code
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.kind = 'warehouse' OR enclosing IS NOT NULL) THEN
    WITH RECURSIVE below AS (
      SELECT c.id, c.code, c.kind, 1 AS depth
        FROM public.stock_locations c
       WHERE c.parent_id = NEW.id AND c.org_id = NEW.org_id
      UNION ALL
      SELECT c.id, c.code, c.kind, b.depth + 1
        FROM below b
        JOIN public.stock_locations c ON c.parent_id = b.id AND c.org_id = NEW.org_id
       WHERE b.depth < 64
    )
    SELECT code INTO nested_code FROM below WHERE kind = 'warehouse' LIMIT 1;
    IF nested_code IS NOT NULL THEN
      RAISE EXCEPTION 'warehouse % cannot sit inside another warehouse; make it a zone or move it out', nested_code
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.stored_value_entries_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF current_setting('openbooks.teardown_org', true) = OLD.org_id::text THEN
  RETURN OLD;
 END IF;
 RAISE EXCEPTION 'Stored-value entries are immutable; record a reversal entry instead.' USING ERRCODE='23514';
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.subcontract_change_pending_terms_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE candidate jsonb; parent_id uuid; organization uuid;
BEGIN
 IF TG_OP='DELETE' AND (tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD))
   OR public.openbooks_sandbox_wipe_allowed(OLD.org_id)) THEN RETURN OLD; END IF;
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN RETURN NEW; END IF;
 FOR candidate IN SELECT value FROM jsonb_array_elements(jsonb_build_array(
   CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) ELSE NULL END,
   CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) ELSE NULL END)) WHERE value<>'null'::jsonb LOOP
  organization:=(candidate->>'org_id')::uuid;
  IF TG_TABLE_NAME='subcontracts' THEN parent_id:=(candidate->>'id')::uuid;
  ELSIF TG_TABLE_NAME='vendor_pay_application_lines' THEN
   SELECT subcontract_id INTO parent_id FROM vendor_pay_applications WHERE org_id=organization AND id=(candidate->>'pay_application_id')::uuid;
  ELSE parent_id:=(candidate->>'subcontract_id')::uuid; END IF;
  IF EXISTS(SELECT 1 FROM subcontract_change_orders c JOIN flow_gates g ON g.org_id=c.org_id AND g.subject_id=c.id
    JOIN flow_runs r ON r.org_id=g.org_id AND r.id=g.run_id
    WHERE c.org_id=organization AND c.subcontract_id=parent_id AND g.subject_kind='subcontract_change_order'
      AND g.status IN('pending','escalated') AND r.context ? 'command') THEN
   RAISE EXCEPTION 'Recall the pending subcontract change order before changing its schedule or billed progress.';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.subscription_amendment_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
  IF OLD.status = 'applied' THEN
    RAISE EXCEPTION 'applied subscription amendments are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.subscription_period_invoice_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;
