CREATE OR REPLACE FUNCTION public.validate_document_posted_period_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  current_status text;
  current_entry_id uuid;
  current_period_id uuid;
  current_org_id uuid;
  entry_period_id uuid;
  entry_org_id uuid;
BEGIN
  SELECT status, posted_entry_id, posting_period_id, org_id
    INTO current_status, current_entry_id, current_period_id, current_org_id
    FROM documents
   WHERE id = NEW.id;

  -- The document may have been deleted later in the same transaction.
  IF NOT FOUND OR current_status <> 'posted' THEN
    RETURN NULL;
  END IF;
  IF current_entry_id IS NULL OR current_period_id IS NULL THEN
    RAISE EXCEPTION 'posted document requires exact journal and accounting-period identity';
  END IF;
  SELECT period_id, org_id
    INTO entry_period_id, entry_org_id
    FROM journal_entries
   WHERE id = current_entry_id;
  IF entry_period_id IS NULL
     OR entry_org_id <> current_org_id
     OR entry_period_id <> current_period_id THEN
    RAISE EXCEPTION 'document posting period must equal its posted journal period';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_extra_dims(p_org_id uuid, p_dims jsonb, p_subsidiary_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
AS $function$
declare d record;
begin
  if jsonb_typeof(coalesce(p_dims, '{}'::jsonb)) <> 'object' then
    raise exception 'custom segment assignments must be an object' using errcode = '23514';
  end if;
  for d in
    select pair.key, pair.value, sd.id as segment_id, sv.id as value_id, sv.subsidiary_id, sv.subsidiary_include_children
      from jsonb_each(coalesce(p_dims, '{}'::jsonb)) pair
      left join segment_definitions sd on sd.org_id = p_org_id and sd.key = pair.key
       and sd.source_kind = 'custom' and sd.is_active
      left join segment_values sv on sv.segment_id = sd.id and sv.org_id = sd.org_id
       and sv.id::text = (pair.value #>> '{}') and sv.is_active
  loop
    if d.segment_id is null then
      raise exception 'unknown or inactive custom segment %', d.key using errcode = '23514';
    end if;
    -- A known optional segment may be explicitly blank. Keeping its key
    -- prevents a line from inheriting a header value the operator cleared.
    if d.value = 'null'::jsonb then continue; end if;
    if jsonb_typeof(d.value) <> 'string' or d.value_id is null then
      raise exception 'invalid custom segment assignment for %', d.key using errcode = '23514';
    end if;
    if d.subsidiary_id is not null and p_subsidiary_id is not null and not (
      p_subsidiary_id = d.subsidiary_id or (
        d.subsidiary_include_children and exists (
          with recursive descendants as (
            select id from subsidiaries where id = d.subsidiary_id and org_id = p_org_id
            union all
            select s.id from subsidiaries s join descendants x on s.parent_id = x.id
             where s.org_id = p_org_id
          ) select 1 from descendants where id = p_subsidiary_id
        )
      )
    ) then
      raise exception 'custom segment value % is restricted to another subsidiary', d.value using errcode = '23514';
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_clone_json(payload jsonb, seed uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE field text; element jsonb; result jsonb;
BEGIN
 IF payload IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(payload)='array' THEN
  result='[]'::jsonb;
  FOR element IN SELECT value FROM jsonb_array_elements(payload) LOOP
   result=result||jsonb_build_array(public.warehouse_execution_clone_json(element,seed));
  END LOOP;
  RETURN result;
 END IF;
 IF jsonb_typeof(payload)<>'object' THEN RETURN payload; END IF;
 result=payload;
 FOREACH field IN ARRAY ARRAY['fromMovementId','toMovementId','entryId','toBinId','shipmentLineId'] LOOP
  IF payload->>field IS NOT NULL THEN result=jsonb_set(result,ARRAY[field],to_jsonb(public.ob_rebase((payload->>field)::uuid,seed)::text)); END IF;
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_clone_row_matches(relation text, candidate jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE target public.orgs%ROWTYPE; source jsonb; expected jsonb; field record; key_column text;
BEGIN
 IF relation NOT IN('pick_execution_lines','handling_units','handling_unit_contents','handling_unit_moves')
   OR NOT public.openbooks_clone_authority() THEN RETURN false; END IF;
 SELECT * INTO target FROM public.orgs org WHERE org.id=(candidate->>'org_id')::uuid AND org.env_kind='sandbox'
   AND org.sandbox_seed IS NOT NULL AND EXISTS(SELECT 1 FROM public.sandboxes control
     WHERE control.org_id=org.id AND control.production_org_id=org.sandbox_of);
 IF NOT FOUND THEN RETURN false; END IF;
 key_column=CASE relation WHEN 'pick_execution_lines' THEN 'line_id' WHEN 'handling_unit_contents' THEN 'shipment_line_id' ELSE 'id' END;
 EXECUTE format('SELECT to_jsonb(source) FROM public.%I source WHERE source.org_id=$1 AND public.ob_rebase(source.%I,$2)=($3->>%L)::uuid',relation,key_column,key_column)
   INTO source USING target.sandbox_of,target.sandbox_seed,candidate;
 IF source IS NULL THEN RETURN false; END IF;
 expected=source;
 FOR field IN SELECT attname FROM pg_attribute WHERE attrelid=to_regclass('public.'||relation)
    AND atttypid='uuid'::regtype AND attnum>0 AND NOT attisdropped LOOP
  expected=jsonb_set(expected,ARRAY[field.attname],CASE WHEN field.attname='org_id' THEN to_jsonb(target.id::text)
    WHEN field.attname='confirmation_task_id' THEN 'null'::jsonb
    ELSE coalesce(to_jsonb(public.ob_rebase((source->>field.attname)::uuid,target.sandbox_seed)::text),'null'::jsonb) END);
 END LOOP;
 IF relation='handling_unit_moves' THEN
  expected=jsonb_set(expected,'{request}',public.warehouse_execution_clone_json(source->'request',target.sandbox_seed));
  expected=jsonb_set(expected,'{movements}',public.warehouse_execution_clone_json(source->'movements',target.sandbox_seed));
 END IF;
 IF EXISTS(SELECT 1 FROM public.sandboxes control WHERE control.org_id=target.id AND control.masked) THEN
  IF relation='handling_units' THEN
   expected=jsonb_set(expected,'{code}',to_jsonb(md5(source->>'code')));
  ELSIF relation='pick_execution_lines' THEN
   expected=jsonb_set(expected,'{reason}',CASE WHEN source->>'reason' IS NULL THEN 'null'::jsonb ELSE to_jsonb('REDACTED'::text) END);
  ELSIF relation='handling_unit_moves' THEN
   expected=jsonb_set(expected,'{command_key}',to_jsonb(md5(source->>'command_key')));
   expected=jsonb_set(expected,'{reason}',to_jsonb('REDACTED'::text));
   expected=jsonb_set(expected,'{request}',public.warehouse_execution_mask_json(source->'request',target.sandbox_seed,'request'));
   expected=jsonb_set(expected,'{movements}',public.warehouse_execution_mask_json(source->'movements',target.sandbox_seed,'movements'));
  END IF;
 END IF;
 RETURN expected=candidate;
END $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_confirmation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE task public.warehouse_execution_tasks%ROWTYPE; subject uuid;
BEGIN
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() AND public.warehouse_execution_clone_row_matches(TG_TABLE_NAME,to_jsonb(NEW)) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='handling_unit_contents' AND to_jsonb(NEW)->>'confirmed_at' IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO task FROM public.warehouse_execution_tasks WHERE org_id=NEW.org_id AND id=NEW.confirmation_task_id;
 subject=(to_jsonb(NEW)->>CASE TG_TABLE_NAME WHEN 'pick_execution_lines' THEN 'line_id' ELSE 'shipment_line_id' END)::uuid;
 IF NOT FOUND OR task.status<>'done' OR task.document_line_id<>subject
    OR task.stage<>(CASE TG_TABLE_NAME WHEN 'pick_execution_lines' THEN 'pick' ELSE 'pack' END)
    OR NOT EXISTS(SELECT 1 FROM public.warehouse_scan_events event WHERE event.org_id=task.org_id AND event.task_id=task.id
      AND event.outcome='confirmed' AND event.xmin=(txid_current()%4294967296)::text::xid) THEN
  RAISE EXCEPTION 'Physical confirmation requires its exact current native execution evidence'; END IF;
 IF TG_TABLE_NAME='pick_execution_lines' THEN
  IF NOT EXISTS(SELECT 1 FROM public.document_lines line JOIN public.documents pick ON pick.org_id=line.org_id AND pick.id=line.document_id
    WHERE line.org_id=NEW.org_id AND line.id=NEW.line_id AND line.document_id=NEW.document_id AND pick.kind='pick_list'
      AND pick.status='approved' AND line.quantity=NEW.requested_quantity AND task.document_quantity=NEW.picked_quantity
      AND task.item_id=line.item_id AND task.subsidiary_id=pick.subsidiary_id AND task.from_stock_location_id=line.stock_location_id) THEN
   RAISE EXCEPTION 'Pick confirmation must preserve its released pick line and quantity'; END IF;
 ELSIF task.item_id<>NEW.item_id OR task.lot_id IS DISTINCT FROM NEW.lot_id OR task.serial_id IS DISTINCT FROM NEW.serial_id
    OR task.quantity<>NEW.quantity OR task.document_quantity<>NEW.document_quantity OR (task.basis->>'unitId')::uuid<>NEW.handling_unit_id THEN
  RAISE EXCEPTION 'Pack confirmation must match its exact assigned carton contents';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'Warehouse execution evidence is immutable; record a new warehouse operation';
END $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_mask_json(payload jsonb, seed uuid, kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE rebased jsonb; element jsonb; result jsonb;
BEGIN
 IF payload IS NULL THEN RETURN NULL; END IF;
 rebased:=public.warehouse_execution_clone_json(payload,seed);
 IF kind='request' THEN
  RETURN jsonb_build_object('toBinId',(rebased->>'toBinId')::uuid::text,
   'date',(rebased->>'date')::date::text,'reason','REDACTED');
 ELSIF kind='movements' THEN
  result:='[]'::jsonb;
  FOR element IN SELECT value FROM jsonb_array_elements(rebased) LOOP
   IF element->'value' IS NULL OR jsonb_typeof(element->'value') NOT IN ('string','number') OR
      (element->>'value')!~'^[+-]?[0-9]+([.][0-9]+)?$' THEN
    RAISE EXCEPTION 'Warehouse movement value requires exact numeric evidence before masking';
   END IF;
   result:=result||jsonb_build_array(jsonb_build_object(
    'shipmentLineId',(element->>'shipmentLineId')::uuid::text,
    'fromMovementId',(element->>'fromMovementId')::uuid::text,
    'toMovementId',(element->>'toMovementId')::uuid::text,
    'entryId',(element->>'entryId')::uuid::text,'value',element->'value'));
  END LOOP;
  RETURN result;
 END IF;
 RAISE EXCEPTION 'Unsupported warehouse evidence masking shape';
END $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_subject_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE candidate jsonb; actor uuid; entity uuid; item uuid; lot uuid; serial uuid; line_org uuid; header record;
BEGIN
 candidate=to_jsonb(NEW);
 IF TG_OP='INSERT' AND public.openbooks_clone_authority() THEN
  IF public.warehouse_execution_clone_row_matches(TG_TABLE_NAME,candidate) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'Warehouse copy must preserve its exact registered source evidence';
 END IF;
 FOREACH actor IN ARRAY ARRAY[(candidate->>'created_by')::uuid,(candidate->>'updated_by')::uuid,(candidate->>'confirmed_by')::uuid] LOOP
  IF actor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.users WHERE id=actor AND org_id=NEW.org_id) THEN
   RAISE EXCEPTION 'Warehouse operation actor must belong to its organization';
  END IF;
 END LOOP;
 entity=(candidate->>'subsidiary_id')::uuid;item=(candidate->>'item_id')::uuid;
 lot=(candidate->>'lot_id')::uuid;serial=(candidate->>'serial_id')::uuid;
 IF lot IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.lots WHERE org_id=NEW.org_id AND id=lot AND item_id=item) THEN
  RAISE EXCEPTION 'Suggested lot must belong to the suggested item and organization'; END IF;
 IF serial IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.serials WHERE org_id=NEW.org_id AND id=serial AND item_id=item AND lot_id IS NOT DISTINCT FROM lot) THEN
  RAISE EXCEPTION 'Suggested serial and lot must belong to the suggested item and organization'; END IF;
 IF TG_TABLE_NAME='warehouse_execution_tasks' THEN
  IF NEW.document_line_id IS NOT NULL THEN
   SELECT doc.org_id,doc.subsidiary_id,line.item_id INTO header FROM public.document_lines line
     JOIN public.documents doc ON doc.org_id=line.org_id AND doc.id=line.document_id WHERE line.id=NEW.document_line_id;
   IF NOT FOUND OR (header.org_id,header.subsidiary_id,header.item_id) IS DISTINCT FROM (NEW.org_id,entity,item) THEN
    RAISE EXCEPTION 'Warehouse suggestion must retain the source document item and legal entity'; END IF;
  END IF;
  IF NEW.count_line_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.stock_count_lines line
   JOIN public.stock_counts count ON count.org_id=line.org_id AND count.id=line.stock_count_id
   WHERE line.org_id=NEW.org_id AND line.id=NEW.count_line_id AND count.subsidiary_id=entity AND line.item_id=item
     AND line.stock_location_id=NEW.to_stock_location_id AND line.lot_id IS NOT DISTINCT FROM lot AND line.serial_id IS NOT DISTINCT FROM serial) THEN
   RAISE EXCEPTION 'Count suggestion must retain its exact count line and identifiers'; END IF;
 ELSIF TG_TABLE_NAME='handling_units' THEN
  SELECT doc.org_id,doc.subsidiary_id,doc.kind,doc.status,fd.warehouse_id,fd.stage INTO header FROM public.documents doc
   JOIN public.fulfillment_documents fd ON fd.org_id=doc.org_id AND fd.document_id=doc.id WHERE doc.id=NEW.shipment_document_id;
  IF NOT FOUND OR header.org_id<>NEW.org_id OR header.subsidiary_id IS DISTINCT FROM entity OR header.kind<>'shipment'
    OR header.warehouse_id<>NEW.warehouse_id THEN RAISE EXCEPTION 'Handling unit must retain its shipment warehouse and legal entity'; END IF;
  IF TG_OP='INSERT' AND (header.status<>'draft' OR header.stage<>'open' OR NEW.status<>'open' OR NEW.content_version<>0
    OR NEW.current_stock_location_id<>NEW.initial_stock_location_id) THEN RAISE EXCEPTION 'Create an open handling unit on a draft shipment'; END IF;
  IF public.stock_location_warehouse(NEW.org_id,NEW.current_stock_location_id) IS DISTINCT FROM NEW.warehouse_id THEN
   RAISE EXCEPTION 'Handling unit must stay in its shipment warehouse'; END IF;
 ELSIF TG_TABLE_NAME='handling_unit_contents' THEN
  IF NOT EXISTS(SELECT 1 FROM public.handling_units unit JOIN public.document_lines line
    ON line.org_id=unit.org_id AND line.document_id=unit.shipment_document_id
    JOIN public.fulfillment_lines fl ON fl.org_id=line.org_id AND fl.line_id=line.id
    WHERE unit.org_id=NEW.org_id AND unit.id=NEW.handling_unit_id AND unit.status='open'
      AND line.id=NEW.shipment_line_id AND line.item_id=NEW.item_id AND line.quantity=NEW.document_quantity
      AND fl.pick_line_id=NEW.pick_line_id AND fl.lot_id IS NOT DISTINCT FROM NEW.lot_id AND fl.serial_id IS NOT DISTINCT FROM NEW.serial_id) THEN
   RAISE EXCEPTION 'Carton contents must match their assigned draft shipment lines'; END IF;
 ELSIF TG_TABLE_NAME='pick_wave_members' THEN
  IF NOT EXISTS(SELECT 1 FROM public.pick_waves wave JOIN public.documents pick
    ON pick.org_id=wave.org_id AND pick.subsidiary_id=wave.subsidiary_id
    JOIN public.fulfillment_documents fd ON fd.org_id=pick.org_id AND fd.document_id=pick.id
    WHERE wave.org_id=NEW.org_id AND wave.id=NEW.wave_id AND pick.id=NEW.pick_list_id AND pick.kind='pick_list'
      AND fd.warehouse_id=wave.warehouse_id AND pick.status=NEW.release_status) THEN
   RAISE EXCEPTION 'Wave membership must retain the released pick warehouse and legal entity'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.warehouse_execution_task_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' THEN
  IF public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Warehouse suggestions and execution history cannot be deleted';
 END IF;
 IF (to_jsonb(NEW)-ARRAY['status','result','updated_at','updated_by']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','result','updated_at','updated_by']) OR OLD.status<>'open' THEN
  RAISE EXCEPTION 'Warehouse suggestion identity is immutable; create a fresh suggestion';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.warehouses_location_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  location_kind text;
  location_code text;
BEGIN
  SELECT kind, code INTO location_kind, location_code
    FROM public.stock_locations
   WHERE id = NEW.stock_location_id AND org_id = NEW.org_id;
  IF location_kind IS DISTINCT FROM 'warehouse' THEN
    RAISE EXCEPTION 'stock location % is a %, not a warehouse; only a warehouse-kind location can be a warehouse',
      coalesce(location_code, NEW.stock_location_id::text), coalesce(location_kind, 'missing location')
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.withholding_deductions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN COALESCE(NEW,OLD); END IF;
 IF TG_OP='UPDATE' AND OLD.status='posted' AND NEW.status='voided'
  AND (to_jsonb(OLD)-ARRAY['status','voided_at','voided_by'])=(to_jsonb(NEW)-ARRAY['status','voided_at','voided_by']) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'A recorded withholding deduction is evidence for a return; void the payment instead of editing it.' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public.withholding_returns_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME, to_jsonb(OLD)) THEN
    RETURN OLD;
  END IF;

 IF TG_OP='DELETE' AND public.openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
 IF public.openbooks_clone_authority() THEN RETURN COALESCE(NEW,OLD); END IF;
 IF TG_OP='DELETE' AND OLD.status='prepared' THEN RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND (to_jsonb(OLD)-ARRAY['status','filed_at','filed_by','filing_reference','remittance_document_id'])=(to_jsonb(NEW)-ARRAY['status','filed_at','filed_by','filing_reference','remittance_document_id'])
  AND ((OLD.status='prepared' AND NEW.status IN('prepared','filed')) OR (OLD.status='filed' AND NEW.status IN('filed','superseded') AND (OLD.filed_at,OLD.filed_by,OLD.filing_reference) IS NOT DISTINCT FROM (NEW.filed_at,NEW.filed_by,NEW.filing_reference))) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'A filed withholding return is frozen; prepare a new revision for the period instead.' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION public.work_operating_profile_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE expected_family text;
BEGIN
 expected_family:=CASE WHEN TG_TABLE_NAME='projects' THEN 'project' ELSE 'production' END;
 IF TG_OP='UPDATE' AND (NEW.operating_profile_version_id,NEW.operating_department_id) IS DISTINCT FROM (OLD.operating_profile_version_id,OLD.operating_department_id) THEN
  RAISE EXCEPTION 'Work keeps its operating profile and department; create new work to use another composition.' USING ERRCODE='23514';
 END IF;
 IF NEW.operating_profile_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.operating_profile_versions v WHERE v.org_id=NEW.org_id AND v.id=NEW.operating_profile_version_id AND v.family=expected_family) THEN
  RAISE EXCEPTION 'Choose an operating profile for this native work family.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.worker_employments_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE survivor uuid;
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'worker_employments: org_id is immutable (composite children reference it)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.employer_subsidiary_id IS DISTINCT FROM OLD.employer_subsidiary_id THEN
    RAISE EXCEPTION 'worker_employments: employer_subsidiary_id is immutable (transfer = terminate + rehire, never an edit)'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.worker_party_id IS DISTINCT FROM OLD.worker_party_id THEN
    -- The marker is the WHOLE contract (merge-owner guarantee): the
    -- absorbed party carries custom.merged_into.survivor, written inside
    -- the merge transaction with the absorbed row deactivated, never
    -- deleted. Deliberately NOT the audit_log row: audit shape is the merge
    -- module's internal detail, and gating a data constraint on a
    -- compliance artifact would couple this table to that shape forever.
    SELECT (custom->'merged_into'->>'survivor')::uuid INTO survivor
      FROM public.parties WHERE id = OLD.worker_party_id AND org_id = OLD.org_id;
    IF survivor IS DISTINCT FROM NEW.worker_party_id THEN
      RAISE EXCEPTION 'worker_employments: worker_party_id changes only through the audited native party merge (engine/src/sync/party-merges.ts)'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_assert_tenant_available(p_tenant uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE status text;
BEGIN
 SELECT state INTO status FROM tenant_retirement.fences WHERE tenant_id=p_tenant FOR SHARE;
 IF status IS DISTINCT FROM 'active' THEN
  RAISE EXCEPTION 'Company % is unavailable for changes because its retirement fence is %',p_tenant,coalesce(status,'missing') USING ERRCODE='55000';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_retirement_begin(p_run uuid, p_tenant uuid, p_plan text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run tenant_retirement.runs; fence tenant_retirement.fences; actual uuid[]; expected uuid[];
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM tenant_retirement.runs WHERE id=p_run;
 IF NOT FOUND OR run.plan_digest IS DISTINCT FROM p_plan OR NOT p_tenant=ANY(run.target_ids) THEN RAISE EXCEPTION 'Unreviewed retirement target or plan'; END IF;
 IF run.catalog_digest IS DISTINCT FROM tenant_retirement.openbooks_retirement_catalog_digest() THEN RAISE EXCEPTION 'Retirement catalog changed; preserve quarantine and review a new native plan'; END IF;
 IF run.database_identity IS DISTINCT FROM jsonb_build_object('database',current_database(),'serverAddress',inet_server_addr()::text,'serverPort',inet_server_port(),'clusterName',current_setting('cluster_name')) THEN RAISE EXCEPTION 'Retirement database identity changed'; END IF;
 SELECT array_agg(id ORDER BY id) INTO actual FROM public.orgs;
 SELECT array_agg(id ORDER BY id) INTO expected FROM (SELECT unnest(run.retain_ids) AS id UNION ALL SELECT tenant_id FROM tenant_retirement.fences WHERE run_id=p_run AND state<>'deleted') remaining;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Retirement company inventory changed'; END IF;
 SELECT * INTO fence FROM tenant_retirement.fences WHERE tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND OR fence.run_id IS DISTINCT FROM p_run THEN RAISE EXCEPTION 'Retirement fence ownership changed'; END IF;
 IF fence.state='deleted' THEN
  IF EXISTS(SELECT 1 FROM public.orgs WHERE id=p_tenant) THEN RAISE EXCEPTION 'Retirement receipt conflicts with surviving company'; END IF;
  RETURN false;
 END IF;
 IF fence.state<>'quarantined' THEN RAISE EXCEPTION 'Retirement target is not quarantined'; END IF;
 IF EXISTS(SELECT 1 FROM public.app_listings WHERE publisher_org_id=p_tenant) THEN RAISE EXCEPTION 'Shared marketplace snapshots retain their publisher; preserve the company' USING ERRCODE='55000'; END IF;
 INSERT INTO tenant_retirement.delete_authorities(transaction_id,backend_pid,tenant_id,run_id,login_name)
 VALUES(txid_current(),pg_backend_pid(),p_tenant,p_run,session_user);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_retirement_finish(p_run uuid, p_tenant uuid, p_receipt jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE relation record; remains boolean;
BEGIN
 IF NOT tenant_retirement.openbooks_tenant_retirement_delete_allowed('orgs',jsonb_build_object('id',p_tenant)) OR NOT EXISTS(SELECT 1 FROM tenant_retirement.fences WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined') THEN RAISE EXCEPTION 'Current retirement authority required'; END IF;
 IF EXISTS(SELECT 1 FROM public.orgs WHERE id=p_tenant) THEN RAISE EXCEPTION 'Company still exists; retirement cannot be certified'; END IF;
 IF NOT EXISTS(SELECT 1 FROM tenant_retirement.storage_manifests WHERE run_id=p_run AND tenant_id=p_tenant) THEN RAISE EXCEPTION 'Storage recovery manifest missing'; END IF;
 FOR relation IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attname='org_id' AND NOT a.attisdropped) LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE org_id=$1)',relation.relname) INTO remains USING p_tenant;
  IF remains THEN RAISE EXCEPTION 'Retirement left tenant rows in %',relation.relname; END IF;
 END LOOP;
 UPDATE tenant_retirement.fences SET state='deleted',receipt=p_receipt,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined';
 IF NOT FOUND THEN RAISE EXCEPTION 'Retirement completion did not update its owned fence'; END IF;
 INSERT INTO tenant_retirement.events(run_id,tenant_id,kind,login_name,detail) VALUES(p_run,p_tenant,'deleted',session_user,p_receipt);
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_retirement_register(p_id uuid, p_plan text, p_catalog text, p_database jsonb, p_retained uuid[], p_targets uuid[], p_actor uuid, p_reason text, p_recovery jsonb, p_state jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target uuid; actual uuid[]; expected uuid[]; prior tenant_retirement.runs;
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Tenant retirement requires the dedicated maintenance login' USING ERRCODE='42501'; END IF;
 IF p_database IS DISTINCT FROM jsonb_build_object('database',current_database(),'serverAddress',inet_server_addr()::text,'serverPort',inet_server_port(),'clusterName',current_setting('cluster_name')) THEN RAISE EXCEPTION 'Retirement database identity changed'; END IF;
 IF p_catalog IS DISTINCT FROM tenant_retirement.openbooks_retirement_catalog_digest() THEN RAISE EXCEPTION 'Retirement schema or guard catalog changed'; END IF;
 IF p_plan IS NULL OR p_plan !~ '^[0-9a-f]{64}$' OR p_catalog IS NULL OR p_catalog !~ '^[0-9a-f]{64}$'
  OR coalesce(cardinality(p_retained),0)<1 OR coalesce(cardinality(p_targets),0)<1
  OR length(btrim(coalesce(p_reason,'')))<12 OR length(p_reason)>2000
  OR jsonb_typeof(p_state) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Reviewed identities, partition, reason and content evidence are required'; END IF;
 IF jsonb_typeof(p_recovery) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Recovery evidence must be an object'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(p_recovery))<>6 OR EXISTS(
  SELECT 1 FROM unnest(ARRAY['backupSha256','restoreReceiptSha256','preservationReceiptSha256','objectRetentionReceiptSha256','verifiedAt','verifier']) key
  WHERE jsonb_typeof(p_recovery->key) IS DISTINCT FROM 'string')
  OR p_recovery->>'backupSha256' !~ '^[0-9a-f]{64}$' OR p_recovery->>'restoreReceiptSha256' !~ '^[0-9a-f]{64}$'
  OR p_recovery->>'preservationReceiptSha256' !~ '^[0-9a-f]{64}$' OR p_recovery->>'objectRetentionReceiptSha256' !~ '^[0-9a-f]{64}$'
  OR length(btrim(coalesce(p_recovery->>'verifier','')))<3 THEN RAISE EXCEPTION 'Verified backup, full restore, preservation and object retention attestations are required'; END IF;
 IF (p_recovery->>'verifiedAt')::timestamptz > clock_timestamp() OR (p_recovery->>'verifiedAt')::timestamptz < clock_timestamp()-interval '24 hours' THEN RAISE EXCEPTION 'Recovery evidence must be verified within 24 hours'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND org_id=ANY(p_retained) AND is_active) THEN RAISE EXCEPTION 'Retirement actor must be an active identity in a retained company'; END IF;
 SELECT * INTO prior FROM tenant_retirement.runs WHERE id=p_id;
 IF FOUND THEN
  IF (prior.plan_digest,prior.catalog_digest,prior.database_identity,prior.retain_ids,prior.target_ids,prior.actor_id,prior.reason,prior.recovery_evidence,prior.reviewed_state)
   IS DISTINCT FROM (p_plan,p_catalog,p_database,p_retained,p_targets,p_actor,p_reason,p_recovery,p_state) THEN RAISE EXCEPTION 'Retirement run identity is already bound to different evidence'; END IF;
  RETURN p_id;
 END IF;
 SELECT array_agg(id ORDER BY id) INTO actual FROM public.orgs;
 SELECT array_agg(x ORDER BY x) INTO expected FROM unnest(p_retained||p_targets) x;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Reviewed retain/retire partition does not match live company identities'; END IF;
 INSERT INTO tenant_retirement.runs(id,plan_digest,catalog_digest,database_identity,retain_ids,target_ids,actor_id,reason,recovery_evidence,reviewed_state)
 VALUES(p_id,p_plan,p_catalog,p_database,p_retained,p_targets,p_actor,p_reason,p_recovery,p_state);
 FOR target IN SELECT unnest(p_targets) ORDER BY 1 LOOP
  UPDATE tenant_retirement.fences SET run_id=p_id,state='quarantined',updated_at=clock_timestamp() WHERE tenant_id=target AND state='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'Company % already belongs to another retirement or lacks a fence',target; END IF;
  IF EXISTS(SELECT 1 FROM public.app_listings WHERE publisher_org_id=target) THEN RAISE EXCEPTION 'Shared marketplace snapshots retain their publisher; preserve the company' USING ERRCODE='55000'; END IF;
 END LOOP;
 INSERT INTO tenant_retirement.events(run_id,kind,login_name,detail) VALUES(p_id,'admitted',session_user,jsonb_build_object('actorId',p_actor,'planDigest',p_plan));
 RETURN p_id;
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_retirement_release(p_run uuid, p_tenant uuid, p_plan text, p_actor uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run tenant_retirement.runs; fence tenant_retirement.fences;
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM tenant_retirement.runs WHERE id=p_run;
 IF NOT FOUND OR run.plan_digest IS DISTINCT FROM p_plan OR NOT p_tenant=ANY(run.target_ids) THEN RAISE EXCEPTION 'Release requires the exact reviewed retirement target'; END IF;
 IF length(coalesce(p_reason,'')) NOT BETWEEN 12 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=p_actor AND org_id=ANY(run.retain_ids) AND is_active) THEN RAISE EXCEPTION 'Release requires a retained active actor and an explicit reason'; END IF;
 SELECT * INTO fence FROM tenant_retirement.fences WHERE tenant_id=p_tenant FOR UPDATE;
 IF NOT FOUND OR fence.run_id IS DISTINCT FROM p_run OR fence.state<>'quarantined' OR NOT EXISTS(SELECT 1 FROM public.orgs WHERE id=p_tenant) THEN RAISE EXCEPTION 'Only an existing quarantined target can be released; deleted history requires backup restoration'; END IF;
 UPDATE tenant_retirement.fences SET run_id=NULL,state='active',receipt=NULL,updated_at=clock_timestamp() WHERE tenant_id=p_tenant AND run_id=p_run AND state='quarantined';
 IF NOT FOUND THEN RAISE EXCEPTION 'Release did not update its owned fence'; END IF;
 INSERT INTO tenant_retirement.events(run_id,tenant_id,kind,login_name,detail) VALUES(p_run,p_tenant,'quarantine_released',session_user,jsonb_build_object('actorId',p_actor,'reason',p_reason,'before',to_jsonb(fence),'afterState','active'));
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_retirement_row_org(p_table text, p_row jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE tenant uuid;
BEGIN
 IF p_row ? 'org_id' THEN RETURN (p_row->>'org_id')::uuid; END IF;
 IF p_table='orgs' THEN RETURN (p_row->>'id')::uuid; END IF;
 IF p_table='app_listings' THEN RETURN (p_row->>'publisher_org_id')::uuid; END IF;
 IF p_table='file_versions' THEN
  SELECT org_id INTO tenant FROM public.files WHERE id=(p_row->>'file_id')::uuid;
 ELSIF p_table='file_blobs' THEN
  SELECT f.org_id INTO tenant FROM public.file_versions v JOIN public.files f ON f.id=v.file_id WHERE v.id=(p_row->>'version_id')::uuid;
 ELSIF p_table='tax_group_members' THEN
  SELECT org_id INTO tenant FROM public.tax_groups WHERE id=(p_row->>'tax_group_id')::uuid;
 ELSIF p_table IN ('auth_login_challenges','auth_login_events','auth_login_state','auth_mfa_factors','auth_oidc_identities','auth_password_resets','auth_sessions') THEN
  SELECT org_id INTO tenant FROM public.users WHERE id=(p_row->>'user_id')::uuid;
 END IF;
 RETURN tenant;
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_retirement_status(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT tenant_retirement.openbooks_retirement_trusted_login() THEN RAISE EXCEPTION 'Dedicated maintenance login required' USING ERRCODE='42501'; END IF;
 SELECT jsonb_build_object('run',to_jsonb(r),'targets',coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.tenant_id) FROM tenant_retirement.fences f WHERE f.tenant_id=ANY(r.target_ids)),'[]'::jsonb),'events',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM tenant_retirement.events e WHERE e.run_id=r.id),'[]'::jsonb)) INTO result
 FROM tenant_retirement.runs r WHERE r.id=p_run;
 IF result IS NULL THEN RAISE EXCEPTION 'Unknown retirement run'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION tenant_retirement.openbooks_tenant_retirement_fence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE old_tenant uuid; new_tenant uuid;
BEGIN
 IF TG_OP='DELETE' AND tenant_retirement.openbooks_tenant_retirement_delete_allowed(TG_TABLE_NAME,to_jsonb(OLD)) THEN RETURN OLD; END IF;
 IF TG_OP IN ('DELETE','UPDATE') THEN old_tenant:=tenant_retirement.openbooks_retirement_row_org(TG_TABLE_NAME,to_jsonb(OLD)); END IF;
 IF TG_OP IN ('INSERT','UPDATE') THEN new_tenant:=tenant_retirement.openbooks_retirement_row_org(TG_TABLE_NAME,to_jsonb(NEW)); END IF;
 IF old_tenant IS NOT NULL THEN PERFORM tenant_retirement.openbooks_assert_tenant_available(old_tenant); END IF;
 IF new_tenant IS NOT NULL AND new_tenant IS DISTINCT FROM old_tenant THEN PERFORM tenant_retirement.openbooks_assert_tenant_available(new_tenant); END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$
